const quotesData = {
            dn: [
                // ĐÃ THÊM TRƯỜNG 'url'
                { text: `“Công đức người bố thí, \nLuôn luôn được tăng trưởng,\nTrừ được tâm hận thù.\nKhông chất chứa, chế ngự,\nKẻ chí thiện từ bỏ.\nMọi ác hạnh bất thiện,\nDiệt trừ tham, sân, si.\nTâm giải thoát thanh tịnh.”`, ref: "DN 16 – Kinh Đại Bát Niết Bàn", url: "../dn/dn16.html#content" },
                { text: `"Hãy tự mình là ngọn đèn cho chính mình, hãy tự mình nương tựa chính mình, chớ nương tựa một gì khác."`, ref: "DN 16 – Kinh Đại Bát Niết Bàn", url: "../dn/dn16.html#content" },
			{ text: `"Này các Tỷ-kheo, nếu có người hủy báng Ta, hủy báng Pháp hay hủy báng Tăng, các ngươi chớ có vì vậy sanh lòng công phẫn, tức tối, tâm sanh phiền muộn. Này các Tỷ-kheo, nếu có người hủy báng Ta, hủy báng Pháp hay hủy báng Tăng, và nếu các ngươi sanh lòng công phẫn, tức tối, tâm sanh phiền muộn, thời như vậy sẽ có hại cho các ngươi. Nếu các ngươi công phẫn và phiền muộn, thời các ngươi có thể biết được lời nói của những kẻ ấy là đúng hay sai lạc chăng?"`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `"Này các Tỷ-kheo, nếu có người tán thán Ta, tán thán Pháp, hay tán thán Tăng, thời các ngươi không nên hoan hỷ, vui mừng, tâm không nên thích thú. Này các Tỷ-kheo, nếu có người tán thán ta, tán thán Pháp hay tán thán Tăng, mà nếu các ngươi hoan hỷ, vui mừng và thích thú thời sẽ có hại cho các ngươi. Này các Tỷ-kheo, nếu có người tán thán Ta... thời các ngươi hãy công nhận những gì đúng sự thật là đúng sự thật."`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `"Sa-môn Gotama từ bỏ sát sanh, tránh xa sát sanh, bỏ trượng, bỏ kiếm, biết tàm quý, có lòng từ, sống thương xót đến hạnh phúc của tất cả chúng sanh và loài hữu tình. Sa-môn Gotama từ bỏ lấy của không cho, tránh xa sự lấy của không cho, chỉ lấy những vật đã cho, chỉ mong những vật đã cho, tự sống thanh tịnh không có trộm cướp. Này các Tỷ-kheo, đó là lời tán thán Như Lai của kẻ phàm phu."`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `"Sa-môn Gotama từ bỏ nói láo, tránh xa nói láo, nói những lời chân thật, y chỉ nơi sự thật, chắc chắn, đáng tin cậy, không lừa gạt, không phản lại lời hứa đối với đời. Sa-môn Gotama từ bỏ nói hai lưỡi, tránh xa nói hai lưỡi; nghe điều gì ở chỗ này, không đi nói đến chỗ kia để sanh chia rẽ ở những người nầy; nghe điều gì ở chỗ kia, không đi nói với những người này để sanh chia rẽ ở những người kia."`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `"Như vậy Sa-môn Gotama sống hòa hợp những kẻ ly gián, tăng trưởng những kẻ đã hòa hợp, hoan hỷ trong hòa hợp, nói những lời đưa đến hòa hợp. Này các Tỷ-kheo, Sa-môn Gotama từ bỏ lời nói độc ác, tránh xa lời nói độc ác, những lời nói không lỗi lầm, đẹp tai, dễ thương, thông cảm đến tâm, tao nhã, đẹp lòng nhiều người, vui lòng nhiều người, Sa-môn Gotama nói những lời như vậy."`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `"Này các Tỷ-kheo, Sa-môn Gotama từ bỏ lời nói phù phiếm, tránh xa lời nói phù phiếm, nói đúng thời, nói những lời chân thật, nói những lời có ý nghĩa, nói những lời về Chánh pháp, nói những lời về Luật, nói những lời đáng được gìn giữ, những lời hợp thời, thuận lý, có mạch lạc hệ thống, có ích lợi. Này các Tỷ-kheo, đó là những lời tán thán Như Lai của kẻ phàm phu."`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `"Này các Tỷ-kheo, thật chỉ thuộc các vấn đề không quan trọng, nhỏ nhặt, chỉ thuộc giới luật mà kẻ phàm phu tán thán Như Lai. [...] Lại có những pháp khác, sâu kín, khó thấu, khó chứng, tịch tịnh, mỹ diệu, vượt ngoài tầm của luận lý suông, tế nhị chỉ những người trí mới nhận hiểu. Những pháp ấy Như Lai đã tự chứng tri, giác ngộ và tuyên thuyết."`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `"Này các Tỷ-kheo, Như Lai tuệ tri như thế này: 'Những sở kiến ấy, chấp trước như vậy, chấp thủ như vậy, sẽ đưa đến những cõi thú như vậy, sẽ tác thành những định mạng như vậy'. Như Lai biết như vậy, Ngài lại biết hơn thế nữa, và Ngài không chấp sở tri ấy. Nhờ không chấp trước sở tri ấy, nội tâm chứng được tịch tịnh."`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `"Ngài như thật biết sự tập khởi, sự diệt trừ của các thọ, vị ngọt, những nguy hiểm và sự xuất ly của chúng. Nhờ biết vậy, này các Tỷ-kheo, Như Lai được giải thoát hoàn toàn, không có chấp thủ. Những chấp pháp ấy, này các Tỷ-kheo, là những pháp sâu kín, khó thấy, khó chứng... và chính những pháp ấy, những ai như thật chân chánh tán thán Như Lai mới nói đến."`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `"Vị hữu tình đầu tiên sanh qua nghĩ rằng: 'Ta là Phạm thiên, Ðại Phạm thiên, Toàn năng... Tổ phụ các chúng sanh đã và sẽ sanh. Những loài hữu tình ấy do chính ta sanh ra. Tại sao vậy? Vì chính do ta khởi niệm: Mong sao các loài hữu tình khác cũng đến tại chỗ này'. Các loài hữu tình đến sau cũng nghĩ như thế này: 'Vị ấy là Phạm thiên... Chúng ta do vị Phạm thiên này hóa sanh'."`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `"Này các Tỷ-kheo, ở đời có Sa-môn hay Bà-la-môn, là nhà suy luận, là nhà thẩm sát. Do sự chia chẻ của suy luận, và sự tùy thuận theo thẩm sát, vị này tuyên bố như thế này: 'Bản ngã và thế giới là thường trú, bất sanh, vững chắc như đảnh núi, như trụ đá, còn những loại hữu tình kia thời lưu chuyển luân hồi, chết đi sanh lại, tuy vậy chúng vẫn thường còn'."`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `"Khi hỏi đến vấn đề này hay vấn đề khác, vị ấy dùng lời ngụy biện trườn uốn như con lươn: 'Tôi không nói là như vậy. Tôi không nói là như kia. Tôi không nói là khác như thế. Tôi không nói là không phải như thế. Tôi không nói là không không phải như thế'. Này các Tỷ-kheo, đó là trường hợp thứ nhất... một số Sa-môn, Bà-la-môn chủ trương Ngụy biện luận."`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `Vị ấy nói: 'Bản ngã và thế giới do vô nhân sanh. Tại sao vậy? Vì rằng tôi trước kia không có, nay tôi có. Từ nơi trạng thái không có, tôi trở thành loài hữu tình'. Này các Tỷ-kheo, đó là trường hợp thứ nhất... một số Sa-môn, Bà-la-môn chủ trương Vô nhân luận, chấp bản ngã và thế giới do vô nhân sanh.`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `Chủ trương ấy là kinh nghiệm cá nhân, là sự không biết, không thấy, sự cảm thọ của những Sa-môn, Bà-la-môn, là sự kích thích, dao động, xuyên tạc của những vị bị tham ái chi phối. [...] Chủ trương ấy phát khởi do sự xúc chạm (của các căn). Những vị này không có thể cảm thọ những chủ trương trên, nếu không có cảm xúc.`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `Tất cả những vị này có những cảm thọ (những chủ trương trên) do sự xúc chạm qua sáu xúc xứ. Do duyên với những cảm thọ mà tham ái phát khởi; do duyên tham ái, thủ phát khởi; do duyên thủ, hữu phát khởi; do duyên hữu, sanh phát khởi, do duyên sanh, già, chết, sầu, bi, khổ, ưu, não phát khởi.`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `Này các Tỷ-kheo, cũng ví như người đánh cá lành nghề hay người học đánh cá vung lưới trên mặt hồ nước nhỏ có mắt sít sao. Người ấy nghĩ: 'Những con cá lớn ở trong hồ nước nhỏ này, tất cả chúng đều bị bao phủ trong tấm lưới này, dầu chúng có nhảy vọt lên, chúng vẫn bị hạn cuộc bao phủ ở nơi đây'.`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `Cũng như vậy này các Tỷ-kheo, những Sa-môn, Bà-la-môn nào, luận bàn về quá khứ tối sơ, hay luận bàn về tương lai... đề xướng nhiều sở kiến sai khác, tất cả những vị này đều bị bao phủ trong lưới của sáu mươi hai luận chấp này; dầu có nhảy vọt lên, những vị này vẫn bị hạn cuộc bao phủ ở nơi đây.`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `Này các Tỷ-kheo, thân của Như Lai còn tồn tại, nhưng cái khiến đưa đến đời sống khác đã bị chấm dứt. [...] Như nhánh có một chùm xoài bị chặt đứt, tất cả trái xoài dính với nhánh ấy đều bị chung một số phận với nhánh kia. Cũng như vậy này các Tỷ-kheo, thân của Như Lai còn tồn tại, nhưng cái khiến đưa đến một đời sống khác đã bị chặt đứt.`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `Khi thân của vị này còn tồn tại thời chư Thiên và loài Người có thể thấy thân ấy. Khi thân hoại mạng chung thời chư Thiên và loài Người không thể thấy được. Này các Tỷ-kheo, thân của Như Lai còn tồn tại, nhưng cái khiến đưa đến một đời sống khác đã bị chặt đứt. Khi thân của vị này còn tồn tại thời chư Thiên và loài Người có thể thấy thân ấy.`, ref: "DN 1 – Kinh Phạm Võng ", url: "../dn/dn1.html#content" },

{ text: `"Như vậy Tỷ-kheo ấy sống hòa hợp những kẻ ly gián, khuyến khích những kẻ hòa hợp, thích thú hòa hợp, hoan hỷ hòa hợp, nói những lời đưa đến hòa hợp. Vị ấy từ bỏ nói lời thô ác, tránh xa lời thô ác, nói những lời nhu hòa, êm tai, khả ái, đi vào lòng người, tao nhã, đẹp lòng nhiều người. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Vị ấy từ bỏ nói láo, tránh xa nói láo, nói những lời chân thật, y chỉ trên sự thật, chắc chắn, đáng tin cậy, không lường gạt, không phản lại lời hứa đối với đời.  Như vậy là giới hạnh của vị ấy trong giới luật."`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Tỷ-kheo từ bỏ nói hai lưỡi, tránh xa nói hai lưỡi, nghe điều gì ở chỗ này, không đến chỗ kia nói để sanh chia rẽ ở những người này; nghe điều gì ở chỗ kia, không đi nói với những người này để sanh chia rẽ ở những người kia."`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Cũng vậy, này Ðại vương, Tỷ-kheo ấy nhờ đầy đủ giới luật, nên không thấy sợ hãi từ một chỗ nào về phương diện hộ trì giới luật. Vị ấy nhờ đầy đủ giới luật cao quý này, nên hưởng lạc thọ, nội tâm không vẩn đục. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Này Ðại vương, khi mắt thấy sắc, Tỷ-kheo không nắm giữ tướng chung, không nắm giữ tướng riêng. Những nguyên nhân gì, khiến nhãn căn không được chế ngự, khiến tham ái, ưu bi, các ác, bất thiện pháp khởi lên, Tỷ-kheo tự chế ngự nguyên nhân ấy, hộ trì nhãn căn, thực hành sự hộ trì nhãn căn. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Những nguyên nhân gì khiến ý căn không được chế ngự, khiến tham ái, ưu bi, các ác, bất thiện pháp khởi lên, Tỷ-kheo chế ngự nguyên nhân ấy, hộ trì ý căn, thực hành sự hộ trì ý căn. Vị ấy, nhờ sự hộ trì cao quý các căn ấy, nên hưởng lạc thọ nội tâm, không vẩn đục. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `Ajàtasattu, con bà Videhi, vua nước Magadha nhìn khắp chúng Tỷ-kheo đang yên lặng an tịnh như một hồ nước trong, cảm hứng nói rằng: "Mong hoàng tử Udàyibhadda cũng được sự trầm lặng như sự trầm lặng của các vị Tỷ-kheo này vậy".`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Ðại vương, cũng như con chim bay đến chỗ nào cũng mang theo hai cánh; cũng vậy, Ðại vương, vị Tỷ-kheo bằng lòng với tấm y để che thân, với đồ ăn khất thực để nuôi bụng, đi tại chỗ nào cũng mang theo. Như vậy, này Ðại vương, là Tỷ-kheo biết đủ. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Vị ấy từ bỏ tham ái ở đời, sống với tâm thoát ly tham ái, gột rửa tâm hết tham ái. Từ bỏ sân hận, vị ấy sống với tâm không sân hận, lòng từ mẫn thương xót tất cả chúng hữu tình, gột rửa tâm hết sân hận. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Từ bỏ hôn trầm, thụy miên, vị ấy sống thoát ly hôn trầm và thụy miên; với tâm tưởng hướng về ánh sáng, chánh niệm tỉnh giác, gột rửa tâm hết hôn trầm, thụy miên. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Từ bỏ trạo cử hối tiếc, vị ấy sống không trạo cử, nội tâm trầm lặng, gột rửa tâm hết trạo cử, hối tiếc. Từ bỏ nghi ngờ, vị ấy sống thoát khỏi nghi ngờ, không phân vân lưỡng lự, gột rửa tâm hết nghi ngờ. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Này Ðại vương, cũng như không mắc nợ, như không bệnh tật, như được khỏi tù tội, như được tự do, như đất lành yên ổn, này Ðại vương, Tỷ-kheo quán năm triền cái khi diệt trừ chúng. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Khi quán tự thân đã xả ly năm triền cái ấy, hân hoan sanh; do hân hoan nên hỷ sanh; do tâm hoan hỷ, thân được khinh an; do thân khinh an, lạc thọ sanh; do lạc thọ, tâm được định tĩnh. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Tỷ-kheo ly dục, ly ác pháp, chứng và trú thiền thứ nhất, một trạng thái hỷ lạc do ly dục sanh, với tầm, với tứ. Tỷ-kheo thấm nhuần, tẩm ướt, làm cho sung mãn, tràn đầy thân mình với hỷ lạc do ly dục sanh, không một chỗ nào trên toàn thân không được hỷ lạc do ly dục sanh ấy thấm nhuần. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Tỷ-kheo thấm nhuần, tẩm ướt, làm cho sung mãn tràn đầy thân mình với hỷ lạc do định sanh, không một chỗ nào trên toàn thân, không được hỷ lạc do định sanh ấy thấm nhuần. Này Ðại vương, đó là quả thiết thực hiện tại của hạnh Sa-môn, còn vi diệu thù thắng hơn những quả thiết thực hiện tại của hạnh Sa-môn trước. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Tỷ-kheo ly hỷ trú xả, chánh niệm tỉnh giác, thân cảm sự lạc thọ mà các bậc Thánh gọi là 'Xả niệm lạc trú', chứng và an trú thiền thứ ba. Tỷ-kheo thấm nhuần... thân mình với lạc thọ không có hỷ ấy, không một chỗ nào trên toàn thân, không được lạc thọ không có hỷ ấy thấm nhuần. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Tỷ-kheo, xả lạc, xả khổ, diệt hỷ ưu đã cảm thọ trước, chứng và trú vào thiền thứ tư, không khổ, không lạc, xả niệm thanh tịnh. Tỷ-kheo ấy thấm nhuần toàn thân mình với tâm thuần tịnh trong sáng, không một chỗ nào trên toàn thân không được tâm thuần tịnh trong sáng ấy thấm nhuần. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Với tâm định tĩnh, thuần tịnh, không cấu nhiễm, không phiền não, nhu nhuyến, dễ sử dụng, vững chắc, bình thản như vậy, Tỷ-kheo dẫn tâm, hướng tâm đến thiên nhĩ thông. Tỷ-kheo với thiên nhĩ thanh tịnh siêu nhân có thể nghe hai loại tiếng, chư Thiên và Người, xa và gần. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Với tâm định tĩnh, thuần tịnh, không cấu nhiễm, không phiền não, nhu nhuyến, dễ sử dụng, vững chắc, bình thản như vậy, Tỷ-kheo dẫn tâm, hướng tâm đến trí huệ về sanh tử của chúng sanh. Vị ấy với thiên nhãn thuần tịnh, siêu nhân, thấy sự sống và chết của chúng sanh. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Vị ấy biết như thật 'đây là khổ', biết như thật 'đây là nguyên nhân của khổ', biết như thật 'đây là khổ diệt', biết như thật 'đây là con đường đưa đến khổ diệt', biết như thật 'đây là những lậu hoặc'... Nhờ hiểu biết như vậy, nhờ nhận thức như vậy, tâm của vị ấy thoát khỏi dục lậu, thoát khỏi hữu lậu, thoát khỏi vô minh lậu. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Ðối với tự thân đã giải thoát, vị ấy biết: Sanh đã tận, phạm hạnh đã thành, việc cần làm đã làm; sau đời hiện tại, không có đời sống nào khác nữa. Này Ðại vương, đó là quả thiết thực, hiện tại của hạnh Sa-môn, còn vi diệu thù thắng hơn những quả thiết thực hiện tại của hạnh Sa-môn trước. "`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Thật khả ái thay, đêm rằm sáng trăng! Nay chúng ta nên đến chiêm bái vị Sa-môn hay Bà-la-môn nào, nhờ sự chiêm bái này tâm chúng ta được tịnh tín?" Jìvaka thưa: "Thế Tôn Gotama có tiếng đồn tốt đẹp: 'Ðây là Thế Tôn, bậc A-la-hán... Phật, Thế Tôn'. Ðại vương hãy đến chiêm bái Thế Tôn này. Rất có thể, nhờ chiêm bái, tâm Ðại vương được tịnh tín."`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Bạch Thế Tôn, con muốn hỏi Thế Tôn một vấn đề này... Chúng hưởng được kết quả thiết thực hiện tại từ công nghiệp chức nghiệp của chúng... Chúng giúp cho tự thân, vợ con, cha mẹ, bạn bè được sống an lạc, hạnh phúc. Chúng dâng các vật cúng dường cho Sa-môn, Bà-la-môn... Bạch Thế Tôn, Ngài có thể chỉ cho rõ ràng kết quả thiết thực, hiện tại của hạnh Sa-môn chăng?"`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Tỷ-kheo từ bỏ nói láo, tránh xa nói láo, nói những lời chân thật, y chỉ trên sự thật, chắc chắn, đáng tin cậy, không lường gạt, không phản lại lời hứa đối với đời. Vị ấy từ bỏ nói hai lưỡi, sống hòa hợp những kẻ ly gián, khuyến khích những kẻ hòa hợp. Như vậy là giới hạnh của vị ấy."`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Trong khi một số Sa-môn, Bà-la-môn... vẫn sống nói những câu chuyện vô ích tầm thường như câu chuyện nói về vua chúa, câu chuyện về ăn trộm, câu chuyện về đại thần, câu chuyện về binh lính, câu chuyện về hãi hùng, câu chuyện về chiến tranh, câu chuyện về đồ ăn, đồ uống, và các câu chuyện vô ích khác." Còn Sa-môn Gotama từ bỏ nói những lời tầm thường vô ích như trên.`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Trong khi một số Sa-môn, Bà-la-môn... vẫn sống dùng các đồ trang sức và mỹ phẩm như thoa dầu, đấm bóp, tắm, gương kem đánh mặt, vòng hoa và phấn son, vòng tay, tóc giả trên đầu, gậy cầm tay... Còn vị ấy thì không dùng các loại trang sức và mỹ phẩm như trên."`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Vị ấy tránh xa các tà mạng như: hỏi gương soi, hỏi phù đồng thiếu nữ, hỏi thiên thần để biết họa phước, thờ mặt trời, thờ đại địa, phun ra lửa, cầu Siri thần tài, dùng bùa chú để giúp người được may mắn, hay khiến người bị rủi ro. Như vậy là giới hạnh của vị ấy trong giới luật."`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Vị ấy tránh xa các tà mạng như: dùng các ảo thuật để được yên ổn, lễ rửa miệng, lễ tắm, lễ hy sinh, làm cho mửa, làm cho xổ, bài tiết các nhơ bẩn... chữa bệnh cho mắt, làm thầy thuốc, mổ xẻ chữa bệnh cho con nít, cho thuốc uống bằng các loại rễ cây, ngăn ngừa công hiệu của thuốc."`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Khi mắt thấy sắc, Tỷ-kheo không nắm giữ tướng chung, không nắm giữ tướng riêng. Những nguyên nhân gì, khiến nhãn căn không được chế ngự, khiến tham ái, ưu bi, các ác, bất thiện pháp khởi lên, Tỷ-kheo tự chế ngự nguyên nhân ấy, hộ trì nhãn căn... Vị ấy nhờ sự hộ trì cao quý các căn ấy, nên hưởng lạc thọ nội tâm, không vẩn đục."`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Tỷ-kheo khi đi tới, đi lui, biết rõ mình đang đi tới, đi lui; khi nhìn tới, nhìn lui, biết rõ mình đang nhìn tới, nhìn lui; khi co tay, duỗi tay, biết rõ mình đang co tay, duỗi tay... Như vậy, Tỷ-kheo sống chánh niệm tỉnh giác, thực hành sự chánh niệm tỉnh giác."`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Tỷ-kheo ly dục, ly ác pháp, chứng và trú thiền thứ nhất, một trạng thái hỷ lạc do ly dục sanh, với tầm, với tứ. Tỷ-kheo thấm nhuần, tẩm ướt, làm cho sung mãn, tràn đầy thân mình với hỷ lạc do ly dục sanh, không một chỗ nào trên toàn thân không được hỷ lạc ấy thấm nhuần."`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Tỷ-kheo, xả lạc, xả khổ, diệt hỷ ưu đã cảm thọ trước, chứng và trú vào thiền thứ tư, không khổ, không lạc, xả niệm thanh tịnh. Tỷ-kheo ấy thấm nhuần toàn thân mình với tâm thuần tịnh trong sáng, không một chỗ nào trên toàn thân không được tâm thuần tịnh trong sáng ấy thấm nhuần."`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Tỷ-kheo, thể hiện nhiều loại thần thông như: một thân biến thành nhiều thân, nhiều thân biến thành một thân; hiện hình biến hình, đi ngang qua vách, qua tường, qua núi, như đi ngang qua hư không; độn thổ trồi lên, ngang qua đất liền như ở trong nước; đi trên nước không chìm như đi trên đất liền... có thể tự thân bay đến cõi Phạm thiên."`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `"Nhờ hiểu biết như vậy, nhận thức như vậy, tâm của vị ấy thoát khỏi dục lậu, thoát khỏi hữu lậu, thoát khỏi vô minh lậu. Ðối với tự thân đã giải thoát, vị ấy biết: Sanh đã tận, phạm hạnh đã thành, việc cần làm đã làm; sau đời hiện tại, không có đời sống nào khác nữa. Này Ðại vương, đó là quả thiết thực hiện tại của hạnh Sa-môn."`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },

{ text: `Ví như một tòa lầu có thượng đài, giữa ngã tư đường, một người có mắt đứng trên ấy, sẽ thấy những người đi vào nhà, đi từ nhà ra, đi qua lại trên đường... Cũng vậy, Tỷ-kheo thấy sự sống và chết của chúng sanh.`, ref: "DN 2 – Kinh Sa-môn Quả ", url: "../dn/dn2.html#content" },
{ text: `"Những tiếng đồn tốt đẹp sau đây được truyền đi về Sa-môn Gotama: 'Ngài là bậc Thế Tôn, A-la-hán, Chánh Ðẳng Giác, Minh Hạnh Túc, Thiện Thệ, Thế Gian Giải, Vô Thượng Sĩ, Ðiều Ngự Trượng Phu, Thiên Nhân Sư, Phật, Thế Tôn.' Ngài thuyết pháp, sơ thiện, trung thiện, hậu thiện, nghĩa văn đầy đủ, trình bày phạm hạnh hoàn toàn đầy đủ, thanh tịnh.`, ref: "DN 3 – Kinh Ambattha ", url: "../dn/dn3.html#content" },

{ text: `"Theo truyền thống của chúng ta về ba mươi hai tướng của vị đại nhân, những ai có ba mươi hai tướng ấy sẽ chọn trong hai con đường, không có đường nào khác. Nếu là tại gia, sẽ thành vị Chuyển luân Thánh vương... Nếu vị này xuất gia... sẽ chứng quả A-la-hán, Chánh Ðẳng Giác, quét sạch mê lầm ở đời. "`, ref: "DN 3 – Kinh Ambattha ", url: "../dn/dn3.html#content" },

{ text: `"Này Ambattha, cũng như con chim cáy, con chim cáy con có thể tự hát thỏa thích trong tổ của nó.  Này Ambattha, Kapilavatthu thuộc dòng họ Thích ca. Thật không xứng để cho Ambattha phải phật lòng vì một vấn đề nhỏ mọn này. "`, ref: "DN 3 – Kinh Ambattha ", url: "../dn/dn3.html#content" },

{ text: `Bài kệ này do Phạm thiên SanamaKumàra thuyết:\n'Ðối với chúng sanh tin tưởng ở giai cấp,\nSát-đế-lỵ chiếm địa vị tối thắng ở nhân gian.\nNhững vị nào giới hạnh và trí tuệ đầy đủ,\nvị này chiếm địa vị tối thắng giữa Người và chư Thiên.'`, ref: "DN 3 – Kinh Ambattha ", url: "../dn/dn3.html#content" },

{ text: `"Những ai còn chấp trước lý thuyết thọ sanh, còn chấp trước lý thuyết giai cấp, còn chấp trước lý thuyết kiêu mạn, hoặc còn chấp trước cưới hỏi rước dâu, những người ấy còn rất xa sự thành tựu vô thượng trí đức. "`, ref: "DN 3 – Kinh Ambattha ", url: "../dn/dn3.html#content" },

{ text: `"Không chấp trước lý thuyết thọ sanh, không chấp trước lý thuyết giai cấp, không chấp trước lý thuyết kiêu mạn, không chấp trước cưới hỏi, đưa dâu, người ấy tức chứng ngộ vô thượng trí đức. Không có sự thành tựu trí đức nào khác siêu việt hơn, cao thượng hơn sự thành tựu trí đức này. "`, ref: "DN 3 – Kinh Ambattha ", url: "../dn/dn3.html#content" },

{ text: `Thật vi diệu thay, Tôn giả Gotama! Thật vi diệu thay, Tôn giả Gotama! Như người dựng đứng lại những gì bị quăng ngã xuống, phơi bày ra những gì bị che kín, chỉ đường cho người bị lạc hướng, đem đèn sáng vào trong bóng tối để những ai có mắt có thể thấy sắc. Cũng vậy, chánh pháp đã được Tôn giả Gotama dùng nhiều phương tiện trình bày, giải thích.`, ref: "DN 3 – Kinh Ambattha ", url: "../dn/dn3.html#content" },

{ text: `Thế Tôn liền thứ lớp giảng pháp cho Bà-la-môn Pokkharasàdi, thuyết về bố thí, thuyết về trì giới, thuyết về các cõi trời, trình bày sự nguy hiểm, sự hạ liệt, sự nhiễm ô của dục lạc và sự lợi ích của xuất ly. Khi Thế Tôn biết tâm của Bà-la-môn Pokkharasàdi đã sẵn sàng, đã nhu thuận, không còn chướng ngại, được phấn khởi, được tín thành, liền thuyết pháp mà chư Phật đã chứng ngộ, tức là khổ, tập, diệt, đạo. Cũng như tấm vải thuần bạch, được gột rửa các vết đen, sẽ rất dễ thấm màu nhuộm, cũng vậy, chính chỗ ngồi này, pháp nhãn xa trần ly cấu khởi lên trong tâm Bà-la-môn Pokkharasàdi: "Phàm pháp gì được tập khởi lên đều bị tiêu diệt".`, ref: "DN 3 – Kinh Ambattha ", url: "../dn/dn3.html#content" },

{ text: `Như vậy, này Ambattha, ngươi và thầy ngươi không phải là một ẩn sĩ, không sống đời sống của nhà ẩn sĩ. Này Ambattha, nếu có gì nghi ngờ, có gì phân vân về Ta, hãy hỏi Ta và Ta sẽ trả lời.`, ref: "DN 3 – Kinh Ambattha ", url: "../dn/dn3.html#content" },

{ text: `Ambattha, ngươi nghĩ thế nào? Ngươi có được nghe những vị Bà-la-môn, trưởng lão, tôn túc, những vị giáo sư và tổ sư nói đến không? Thuở xưa những vị ẩn sĩ, giữa các Bà-la-môn, những tác giả của chú thuật, những nhà tụng tán các chú thuật đã hát, đã nói lên, đã sưu tầm những Thánh cú mà nay những Bà-la-môn, cũng hát lên, nói lên, đọc lên giống như các vị trước đã làm. Những vị ẩn sĩ ấy tên là Atthaka, Vàmaka,..., Kassapa, Bhagu. Những vị ấy có khéo tắm, khéo chải chuốt, tóc và râu khéo sửa soạn, trang điểm với vòng hoa và ngọc, mặc toàn đồ trắng, tận hưởng và tham đắm năm món dục lạc, như người và thầy của ngươi hiện nay không?`, ref: "DN 3 – Kinh Ambattha ", url: "../dn/dn3.html#content" },
{ text: `Này Bà-la-môn, trí tuệ được giới hạnh làm cho thanh tịnh, giới hạnh được trí tuệ làm cho thanh tịnh. Chỗ nào có giới hạnh, chỗ ấy có trí tuệ; chỗ nào có trí tuệ, chỗ ấy có giới hạnh. Người có giới hạnh nhất định có trí tuệ; người có trí tuệ nhất định có giới hạnh. Giới hạnh và trí tuệ được xem là tối thắng ở trên đời.`, ref: "DN 5 – Kinh Kūṭadanta", url: "../dn/dn5.html#content" },


{ text: `Này Kassapa, nếu Tỷ-kheo sống tu tập từ bi tâm, không hận thù, không ác hại, và với sự diệt tận các lậu hoặc, tự giác chứng và an trú ngay hiện tại, tâm giải thoát, tuệ giải thoát vô lậu, này Kassapa, Tỷ-kheo ấy được gọi là Sa-môn, được gọi là Bà-la-môn.`, ref: "DN 8 – Đại Kinh Sử Tử Hống", url: "../dn/dn8.html#content" },

{ text: `Ta đến các vị ấy và nói: “Này các Hiền giả, những điểm bất đồng ý, hãy để chúng yên như vậy. Những điểm đồng ý, các vị có trí hãy hỏi nhau, tìm hiểu và đàm luận với nhau, giáo sư với giáo sư, hay chúng đệ tử với chúng đệ tử: “Những pháp bất thiện hay được xem là bất thiện, những pháp lỗi lầm hay được xem là lỗi lầm, những pháp không nên tuân hành hay được xem là không nên tuân hành, những pháp không xứng bậc Thánh hay được xem là không xứng đáng bậc Thánh, những pháp ô nhiễm hay được xem là ô nhiễm.`, ref: "DN 8 – Đại Kinh Sử Tử Hống", url: "../dn/dn8.html#content" },

{ text: `Này Kassapa, và sự tình này xảy ra. Khi các vị có trí hỏi nhau, tìm hiểu và đàm luận với nhau, các vị này nói: “Những pháp thiện hay được xem là thiện, những pháp không lỗi lầm hay được xem là không lỗi lầm, những pháp nên tuân hành hay được xem là nên tuân hành, những pháp xứng bậc Thánh hay được xem là xứng bậc Thánh, những pháp thanh tịnh hay được xem là thanh tịnh, Sa-môn Gotama đã hoàn toàn thành tựu những pháp này, còn những vị tôn giả, sư trưởng các giáo phái kia chỉ thành tựu một phần”.`, ref: "DN 8 – Đại Kinh Sử Tử Hống", url: "../dn/dn8.html#content" },


{ text: `Du sĩ ngoại đạo Poṭṭhapāda thấy Thế Tôn từ xa đến, liền khuyến cáo chúng của mình: “Các Tôn giả hãy nhỏ tiếng, các Tôn giả hãy đừng làm ồn. Nay Sa-môn Gotama đang đến, Ngài ưa mến sự trầm lặng, vị Ðại đức này tán thán sự trầm lặng. Nếu biết chúng này yên tịnh, Ngài có thể ghé đến đây”. Nghe nói vậy, các du sĩ ngoại đạo liền im lặng.`, ref: "DN 9 – Kinh Poṭṭhapāda", url: "../dn/dn9.html#content" },

{ text: `Cũng vậy, này Poṭṭhapāda, Tỷ-kheo ấy nhờ đầy đủ giới luật nên không thấy sợ hãi từ một chỗ nào về phương diện hộ trì giới luật. Vị ấy nhờ đầy đủ giới luật cao quý này, nên hưởng lạc thọ nội tâm không lỗi lầm. Như vậy, này Poṭṭhapāda, Tỷ-kheo đầy đủ giới luật.`, ref: "DN 9 – Kinh Poṭṭhapāda", url: "../dn/dn9.html#content" },

{ text: `Này Poṭṭhapāda, khi Tỷ-kheo ở đây tự mình khởi tưởng, vị này tiếp tục đi từ tưởng này đến tưởng khác cho đến tưởng tột đỉnh. Và vị này, khi đứng lại tưởng tột đỉnh có thể nghĩ: “Tâm còn suy tưởng, có hại cho ta, tâm không suy tưởng mới tốt cho ta. Nếu ta cứ tiếp tục suy tưởng khi những tưởng này của ta diệt đi, các thô tưởng khác lại khởi lên. Vậy ta hãy đừng có suy tưởng”. Và vị này không có suy tưởng. Do không có suy tưởng, các tưởng kia diệt tận và các thô tưởng khác cũng không khởi lên. Vị ấy cảm thọ sự diệt tận. Như vậy này Poṭṭhapāda là sự chứng đạt trí tuệ diệt trừ dần dần các tăng thượng tưởng.`, ref: "DN 9 – Kinh Poṭṭhapāda", url: "../dn/dn9.html#content" },

{ text: `"- Bạch Thế Tôn, tưởng khởi trước, trí khởi sau; hay trí khởi trước tưởng khởi sau; hay tưởng và trí cùng khởi một lần không trước không sau?" - Này Poṭṭhapāda, tưởng khởi trước trí mới khởi sau, do tưởng sanh, trí mới sanh. Vị ấy tuệ tri: “Do duyên tưởng, trí sanh ra nơi ta”. Này Poṭṭhapāda, với lời dạy này cần phải hiểu tưởng sanh trước trí sanh sau, tưởng sanh trí mới sanh.`, ref: "DN 9 – Kinh Poṭṭhapāda", url: "../dn/dn9.html#content" },

{ text: `—Thật vi diệu thay, bạch Thế Tôn! Thật vi diệu thay, bạch Thế Tôn! Như người dựng lại những gì bị quăng ngã xuống, phơi bày những gì bị che kín, chỉ đường cho những người lạc hướng, đem đèn sáng vào trong bóng tối để những ai có mắt có thể thấy sắc. Cũng vậy chánh pháp đã được Thế Tôn dùng nhiều phương tiện trình bày, giải thích. Bạch Thế Tôn, con xin quy y Thế Tôn, quy y Pháp và quy y chúng Tỷ-kheo. Mong Thế Tôn nhận con làm đệ tử, từ nay trở đi cho đến mạng chung, con trọn đời quy ngưỡng.`, ref: "DN 9 – Kinh Poṭṭhapāda", url: "../dn/dn9.html#content" },

{ text: `Này Poṭṭhapāda, Khi nhiễm pháp được diệt trừ, tịnh pháp được tăng trưởng, ngay hiện tại tự mình giác ngộ, với thắng trí, chứng đạt và an trú trí tuệ sung mãn, quảng đại, thời hân hoan sanh, hoan hỷ, khinh an, chánh niệm, tỉnh giác và lạc trú sanh.`, ref: "DN 9 – Kinh Poṭṭhapāda", url: "../dn/dn9.html#content" },

{ text: `Này Poṭṭhapāda, những pháp gì được Ta tuyên thuyết trình bày một cách dứt khoát? “Ðây là khổ”, này Poṭṭhapāda, đó là pháp được Ta tuyên thuyết trình bày một cách dứt khoát. “Ðây là khổ tập”, này Poṭṭhapāda, đó là pháp được Ta tuyên thuyết trình bày một cách dứt khoát. “Ðây là khổ diệt”, này Poṭṭhapāda, đó là pháp được Ta tuyên thuyết trình bày một cách dứt khoát. “Ðây là con đường đưa đến khổ diệt”, này Poṭṭhapāda, đó là pháp được Ta tuyên thuyết, trình bày một cách dứt khoát.`, ref: "DN 9 – Kinh Poṭṭhapāda", url: "../dn/dn9.html#content" },

{ text: `Này Poṭṭhapāda, những pháp thuộc về đích giải thoát, thuộc về Pháp, thuộc căn bản phạm hạnh, đưa đến yểm ly, đến ly tham, đến tịch diệt, đến tịch tịnh, đến thắng trí, đến giác ngộ, đến Niết-bàn. Vì vậy những pháp ấy được Ta tuyên thuyết trình bày một cách dứt khoát.`, ref: "DN 9 – Kinh Poṭṭhapāda", url: "../dn/dn9.html#content" },

{ text: `Này Kevaddha, thế nào là giáo hóa thần thông? Ở đời có Tỷ-kheo giáo hóa như sau: “Hãy suy tư như thế này, chớ có suy tư như thế kia; hãy tác ý như thế này, chớ có tác ý như thế kia; hãy trừ bỏ điều này, hãy chứng đạt và an trú điều kia”. Này Kevaddha, như vậy gọi là giáo hóa thần thông.`, ref: "DN 10 – Kinh Kevaddha", url: "../dn/dn10.html#content" },

{ text: `“Thức là không thể thấy, vô biên,\nbiến thông hết thảy xứ.\nỞ đây, địa đại, thủy đại,\nhỏa đại, phong đại không có chân đứng.\nỞ đây, cũng vậy dài, ngắn,\ntế, thô, tịnh và bất tịnh.\nỞ đây danh và sắc tiêu diệt hoàn toàn.\nKhi thức diệt, ở đây mọi thứ đều diệt tận”.`, ref: "DN 10 – Kinh Kevaddha", url: "../dn/dn10.html#content" },


{ text: `- Này Vāsaṭṭha, những Bà-la-môn tinh thông ba tập Vedà không biết, không thấy con đường đưa đến cộng trú với Phạm thiên mà thuyết dạy: “Ðây là trực đạo, đây là chánh đạo hướng đến, dẫn đến cộng trú với Phạm thiên cho những ai thực hành theo”, thật không thể có sự kiện ấy. Này Vāsaṭṭha, ví như một chuỗi người mù ôm lưng nhau, người trước không thấy, người giữa cũng không thấy, người cuối cùng cũng không thấy. Như vậy, này Vāsaṭṭha lời nói của những Bà-la-môn tinh thông ba tập Vedà, người đầu không thấy, giữa cũng không thấy, người cuối cùng cũng không thấy, giống như lời nói mù quáng. Lời nói của những Bà-la-môn tinh thông ba tập Vedà như vậy là lời nói đáng chê cười, là lời nói suông, là lời nói không tưởng, là lời nói trống rỗng.`, ref: "DN 13 – Kinh Tam Minh", url: "../dn/dn13.html#content" },

{ text: `Người gia trưởng hay con vị gia trưởng, hay một người sinh ở giai cấp (hạ tiện) nào nghe pháp ấy. Sau khi nghe pháp, người ấy sanh lòng tín ngưỡng Như Lai. Khi có lòng tin ngưỡng ấy, vị này suy nghĩ: “Ðời sống tại gia đầy những triền phược, con đường đầy những bụi đời. Ðời sống xuất gia phóng khoáng như hư không. Thật rất khó cho một người sống tại gia có thể sống theo phạm hạnh hoàn toàn đầy đủ, hoàn toàn thanh tịnh, trắng bạch như vỏ ốc. Vậy ta nên cạo bỏ râu tóc, đắp áo cà sa, xuất gia, từ bỏ gia đình”.`, ref: "DN 13 – Kinh Tam Minh", url: "../dn/dn13.html#content" },

{ text: `Này Vāseṭṭha, năm pháp khiến dục lạc tăng thịnh ấy, các Bà-la-môn tinh thông ba tập Vedā chấp trước, mê đắm, bị trói buộc, không thấy nguy hiểm của chúng, không nhận thức sự không thoát ly của chúng, đã tận hưởng năm pháp ấy. Này Vāseṭṭha, những Bà-la-môn tinh thông ba tập Vedā, loại bỏ những pháp tác thành người Bà-la-môn, tuân theo những pháp không tác thành người Bà-la-môn, chấp trước, mê đắm, bị trói buộc, không thấy nguy hiểm của chúng, không nhận thức sự không thoát ly của chúng, tận hưởng chúng, bị trói buộc bởi sự trói buộc của dục lạc, sau khi thân hoại mạng chung sẽ cộng trú với Phạm thiên, thật không có sự kiện ấy.`, ref: "DN 13 – Kinh Tam Minh", url: "../dn/dn13.html#content" },

{ text: `Này Vàsettha, như một người muốn xây tại ngã tư đường một cái thang để leo lên lầu. Có người hỏi: "Này bạn, Ông muốn xây một cái thang để leo lên lầu, vậy Ông có biết lầu ấy là về hướng Ðông, hay về hướng Tây, hay về hướng Bắc, hay về hướng Nam? Nhà lầu ấy cao hay thấp, hay trung bình?". Ðược hỏi vậy, vị ấy trả lời không biết. Có người hỏi: "Này bạn, như vậy có phải Ông xây một cái thang để leo lên một cái lầu mà Ông không biết, không thấy?". Hỏi vậy, vị ấy trả lời phải. Này Vàsettha, ngươi nghĩ thế nào? Sự kiện là như vậy, thời có phải lời nói người kia không chánh xác, hợp lý?`, ref: "DN 13 – Kinh Tam Minh", url: "../dn/dn13.html#content" },

{ text: `Này Vàsettha, như sông Aciravati này, đầy tràn cho đến bờ khiến con quạ có thể uống được. Có người đến, có sự việc bên bờ bên kia, tìm đến bờ bên kia, hướng đến bờ bên kia và muốn lội qua bờ bên kia. Người đứng bờ bên này kêu bờ bên kia và nói: "Bờ bên kia, hãy lại đây! Bờ bên kia, hãy lại đây". Này Vàsettha, Ngươi nghĩ thế nào? Có phải vì người kia kêu gọi bờ bên kia, vì cầu khẩn, vì hy vọng, vì tán thán mà bờ bên kia của sông Aciravati đến bờ bên này không? "- Tôn giả Gotama, không thể vậy."`, ref: "DN 13 – Kinh Tam Minh", url: "../dn/dn13.html#content" },

{ text: `Cũng vậy, này Vàsettha, có năm triền cái được gọi là chướng ngại, cũng được gọi là triền cái, cũng được gọi là màn che, cũng được gọi là triền phược trong giới luật của bậc Thánh. Thế nào là năm? Dục cái, sân cái, hôn trầm thụy miên cái, trạo hối cái, nghi cái. Này Vàsettha, năm triền cái này được gọi là chướng ngại, cũng được gọi là triền cái, cũng được gọi là màn che, cũng được gọi là triền phược. Này Vàsettha, các Bà-la-môn tinh thông ba tập Vedà, bị chướng ngại, bị triền phược, bị che đậy, bị trói buộc bởi năm triền cái này, Này Vàsettha, thật vậy, những Bà-la-môn tinh thông ba tập Vedà, loại bỏ những pháp tác thành người Bà-la-môn, tuân theo những pháp không tác thành người Bà-la-môn, bị chướng ngại, bị triền phược, bị che đậy, bị trói buộc bởi năm triền cái, sau khi thân hoại mạng chung, sẽ cộng trú với Phạm thiên - Thật không thể có sự kiện ấy.`, ref: "DN 13 – Kinh Tam Minh", url: "../dn/dn13.html#content" },

{ text: `Này Vàsettha, như sông Acivarati này, đầy tràn cho đến bờ khiến con quạ có thể uống được. Có người đến, có sự việc bên bờ bên kia, tìm đến bờ bên kia, hướng đến bờ bên kia và muốn lội qua bờ bên kia. Người này ở bên bờ này trùm đầu và nằm ngủ. Này Vàsettha, nhà Ngươi nghĩ thế nào? Người ấy có thể từ bên này của sông Aciravati đến bờ bên kia không? "- Tôn giả Gotama, không có thể được."`, ref: "DN 13 – Kinh Tam Minh", url: "../dn/dn13.html#content" },

{ text: `"Tỷ-kheo có tự tại, Phạm Thiên có tự tại. Giữa Tỷ-kheo có tự tại với Phạm thiên có tự tại, có thể có một sự cộng hành, cộng trú không? - Tôn giả Gotama, có thể có được. - Lành thay, Vàsettha. Này Vàsettha, Tỷ-kheo sau khi thân hoại mạng chung sẽ cộng trú với Phạm thiên. Sự kiện ấy thật có thể có."`, ref: "DN 13 – Kinh Tam Minh", url: "../dn/dn13.html#content" },

{ text: `Này Vàsettha, như người lực sĩ thổi tù và khiến tiếng được nghe khắp bốn phương, không có gì khó khăn, cũng vậy này Vàsettha, đối với mọi hình thức của sự sống, không có ai là vị ấy bỏ qua hay bỏ sót mà không biến mãn với tâm giải thoát, câu hữu với từ. Này Vàsettha, đó là con đường đưa đến cộng trú với Phạm thiên.`, ref: "DN 13 – Kinh Tam Minh", url: "../dn/dn13.html#content" },

{ text: `Lại nữa, này Vàsettha, vị Tỷ-kheo an trú,  biến mãn một phương với tâm câu hữu với từ... với tâm câu hữu với bi... với tâm câu hữu với hỷ... biến mãn một phương với tâm câu hữu với xả, cũng vậy phương thứ hai, cũng vậy phương thứ ba, cũng vậy phương thứ tư. Như vậy, cùng khắp thế giới, trên, dưới, bề ngang hết thảy phương xứ, cùng khắp vô biên giới, vị ấy an trú biến mãn với tâm câu hữu với xả, quảng đại, vô biên, không hận, không sân.`, ref: "DN 13 – Kinh Tam Minh", url: "../dn/dn13.html#content" },

{ text: `Khi đã xuất gia như vậy, vị ấy sống chế ngự với sự chế ngự của giới bổn Pàtimokkha, đầy đủ oai nghi chánh hạnh, thấy nguy hiểm trong những lỗi nhỏ nhặt, thọ lãnh và tu học trong giới pháp, thân nghiệp, ngữ nghiệp, thanh tịnh. Mạng sống trong sạch, giới hạnh đầy đủ, thủ hộ các căn, chánh niệm, tỉnh giác và biết tri túc.`, ref: "DN 13 – Kinh Tam Minh", url: "../dn/dn13.html#content" },

{ text: `Này Vàsettha, đối với người ấy đã sinh trưởng Manasàkata, còn có thể nghi ngờ và có khó khăn hỏi đến con đường đưa đến Manasàkata nhưng đối với Như Lai thì không có nghi ngờ hay khó khăn gì khi hỏi đến Phạm thiên giới hay con đường đưa đến Phạm thiên giới! Này Vàsettha, Ta biết đến Phạm thiên, Phạm thiên giới và con đường đưa đến Phạm thiên giới.`, ref: "DN 13 – Kinh Tam Minh", url: "../dn/dn13.html#content" },

{ text: `Này Vàsettha, ở đời các Bà-la-môn dầu có tinh thông ba tập Vedà, khi các vị này ngồi với sự tự tín, thật sự đang chìm trong bùn lầy, và khi đang chìm trong bùn lầy, phải sống trong thất vọng, lầm tưởng rằng đã đến cảnh giới an lạc hơn. Do vậy đối với những Bà-la-môn tinh thông Vedà sự tinh thông ấy được gọi là bãi sa mạc không có nước, sự tinh thông ấy cũng được gọi là rừng rậm không có đường lối, sự tinh thông ấy cũng được gọi là sự bất hạnh.`, ref: "DN 13 – Kinh Tam Minh", url: "../dn/dn13.html#content" },

{ text: `"Phạm thiên có dục ái hay không dục ái? - Tôn giả Gotama, không có dục ái. - Có hận tâm hay không hận tâm? - Tôn giả Gotama, không có hận tâm. - Có sân tâm hay không sân tâm? - Tôn giả Gotama, không có sân tâm. - Có nhiễm tâm hay không có nhiễm tâm? - Tôn giả Gotama, không có nhiễm tâm. - Có tự tại hay không có tự tại? - Tôn giả Gotama, có tự tại." "Các Bà-la-môn tinh thông ba tập Vedà có dục ái hay không dục ái? - Tôn giả Gotama, có dục ái. - Có hận tâm hay không hận tâm? - Tôn giả Gotama, có hận tâm. - Có sân tâm hay không có sân tâm? - Tôn giả Gotama, có sân tâm. - Có nhiễm tâm hay không có nhiễm tâm? - Tôn giả Gotama, có nhiễm tâm. - Có tự tại hay không có tự tại? - Tôn giả Gotama, không có tự tại." "Này Vàsettha, Ngươi nói rằng các Bà-la-môn tinh thông ba tập Vedà là có tham ái, Phạm thiên không có tham ái. Giữa các Bà-la-môn tinh thông ba tập Vedà là có tham ái với Phạm thiên không có tham ái, có thể có một sự cộng hành, cộng trú không? - Tôn giả Gotama, không thể có được."`, ref: "DN 13 – Kinh Tam Minh", url: "../dn/dn13.html#content" },
{ text: `Này các Tỷ-kheo, hoàng tử Vipassì trên đường đi đến vườn ngự uyển, thấy một người già nua, lưng còng như nóc nhà, chống gậy, vừa đi vừa run rẩy, khổ não, không còn đâu là tuổi trẻ. Thấy vậy hoàng tử hỏi người đánh xe: “Này khanh, người đó là ai vậy? Sao thân người đó không giống các người khác?”: “Tâu Hoàng tử, người đó là một người được gọi là già vậy”. “Này khanh, sao người ấy được gọi là một người già?”: “Tâu Hoàng tử, người ấy gọi là già vì nay người ấy sống không bao lâu nữa”. “Này khanh, vậy rồi Ta có bị già không, một người chưa qua tuổi già?”: “Tâu Hoàng tử, Hoàng tử và cả con nữa, chúng ta tất cả sẽ bị già nua, dầu chúng ta chưa qua tuổi già!”: “Này khanh, thôi nay thăm vườn ngự uyển như vậy là vừa rồi. Hãy cho đánh xe trở về cung”. “Thưa vâng, Hoàng tử”. Này các Tỷ-kheo, hoàng tử Vipassì về trong cung, đau khổ, sầu muộn và suy nghĩ. “Sỉ nhục thay, cái gọi là sanh. Và ai sanh ra cũng phải già yếu như vậy!”.`, ref: "DN 14 – Kinh Ðại bổn", url: "../dn/dn14.html#content" },

{ text: `Này các Tỷ-kheo, rồi Bồ-tát Vipassì suy nghĩ như sau: “Thức này xoay trở lui lại, từ nơi danh sắc, không vượt khỏi danh sắc. Chỉ như thế này, con người được sanh ra hay trở thành già, hay bị chết, hay từ biệt cõi này, hay sanh lại ở cõi khác, nghĩa là do duyên danh sắc, thức sanh; do duyên thức, danh sắc sanh; do duyên danh sắc, lục nhập sanh; do duyên lục nhập, xúc sanh; do duyên xúc, thọ sanh; do duyên thọ, ái sanh; do duyên ái, thủ sanh; do duyên thủ, hữu sanh; do duyên hữu, sanh sanh; do duyên sanh, lão, tử, sầu bi, khổ ưu não sanh. Như vậy là sự tập khởi của toàn bộ khổ uẩn này”.`, ref: "DN 14 – Kinh Ðại bổn", url: "../dn/dn14.html#content" },

{ text: `Này các Tỷ-kheo, rồi Bồ-tát Vipassì suy nghĩ: “Ôi, Ta đã chứng được con đường đưa đến Bồ-đề, nhờ pháp tu quán. Nghĩa là, do danh sắc diệt, thức diệt; do thức diệt, danh sắc diệt; do danh sắc diệt, lục nhập diệt; do lục nhập diệt, xúc diệt; do xúc diệt, thọ diệt, do thọ diệt, ái diệt; do ái diệt, thủ diệt; do thủ diệt, hữu diệt; do hữu diệt, sanh diệt; do sanh diệt, già, chết, ưu, bi, khổ, sầu, não diệt. Như vậy, toàn bộ khổ uẩn diệt”.`, ref: "DN 14 – Kinh Ðại bổn", url: "../dn/dn14.html#content" },

{ text: `Này các Tỷ-kheo, hoàng tử Vipassì trên đường đi đến ngự uyển thấy một vị xuất gia, đầu trọc, đắp áo cà sa. Thấy vậy, hoàng tử hỏi người đánh xe: “Này khanh, người này đã làm gì, mà đầu người ấy lại khác đầu của những người khác, và áo của người ấy cũng khác áo của những người khác?”: “Tâu Hoàng tử, người ấy được gọi là người xuất gia!”: “Này khanh, sao người ấy được gọi là người xuất gia?”: “Tâu Hoàng tử, xuất gia nghĩa là khéo tu phạm hạnh, khéo tu tịnh hạnh, khéo hành thiện nghiệp, khéo hành công đức nghiệp, khéo giữ không hại chúng sanh, khéo có lòng từ đối với chúng sanh!”: “Này khanh, hãy đánh xe đến gần vị xuất gia”. “Thưa vâng, Hoàng tử”.`, ref: "DN 14 – Kinh Ðại bổn", url: "../dn/dn14.html#content" },

{ text: `Này các Tỷ-kheo, rồi hoàng tử Vipassì hỏi vị xuất gia: “Thưa Hiền giả, Ngài đã làm gì, mà đầu của Ngài không giống những người khác, và áo của Ngài không giống các người khác?”: “Thưa Hoàng tử, tôi là một người xuất gia!”: “Thưa Hiền giả, thế nào gọi là người xuất gia?”: “Thưa Hoàng tử, tôi là người được gọi là xuất gia, vì tôi khéo tu phạm hạnh, khéo tu tịnh hạnh, khéo hành thiện nghiệp, khéo hành công đức nghiệp, khéo giữ không hại chúng sanh, khéo có lòng từ đối với chúng sanh”. “Thưa Hiền giả, lành thay hạnh xuất gia của Ngài, lành thay khéo tu phạm hạnh, khéo tu tịnh hạnh, khéo hành thiện nghiệp, khéo hành công đức nghiệp, khéo giữ không hại chúng sanh, khéo có lòng từ đối với chúng sanh”.`, ref: "DN 14 – Kinh Ðại bổn", url: "../dn/dn14.html#content" },

{ text: `Này các Tỷ-kheo, trong khi yên lặng tịnh cư, Bồ-tát Vipassì suy nghĩ: “Sao Ta lại sống bị bao vây bởi đồ chúng này. Tốt hơn là Ta sống một mình, lánh xa đồ chúng này!”`, ref: "DN 14 – Kinh Ðại bổn", url: "../dn/dn14.html#content" },

{ text: `Này các Tỷ-kheo, rồi Bồ-tát Vipassì, sau một thời gian sống quán sự sanh diệt trong năm uẩn: “Ðây là sắc, đây là sắc tập khởi, đây là sắc diệt. Ðây là thọ, đây là thọ tập khởi, đây là thọ diệt. Ðây là tưởng, đây là tưởng tập khởi, đây là tưởng diệt. Ðây là hành, đây là hành tập khởi, đây là hành diệt! Ðây là thức, đây là thức tập khởi, đây là thức diệt”. Và đối với Ngài, sau khi sống quán pháp sanh diệt trong năm thủ uẩn, chẳng bao lâu các lậu hoặc được tiêu trừ và Ngài được giải thoát.`, ref: "DN 14 – Kinh Ðại bổn", url: "../dn/dn14.html#content" },

{ text: `Này các Tỷ-kheo, Thế Tôn Vipassì, bậc A-la-hán, Chánh Ðẳng Giác suy nghĩ: “Pháp này do Ta chứng được, thật là sâu kín, khó thấy, khó chứng, tịch tịnh, cao thượng, siêu lý luận, vi diệu, chỉ người trí mới hiểu thấu. Còn quần chúng này thì ưa ái dục, khoái ái dục, ham thích ái dục. Ðối với quần chúng ưa ái dục, khoái ái dục, ham thích ái dục, thật khó mà thấy được định lý “Y tánh duyên khởi pháp” (idapaccayatā paṭicca samuppāda); thật khó mà thấy được định lý tất cả hành là tịch tịnh, tất cả sanh y được trừ bỏ, ái được đoạn tận, ly dục, ái diệt, Niết-bàn. Nếu nay Ta thuyết pháp mà các người khác không hiểu Ta, thời như vậy thật khổ não cho Ta!”`, ref: "DN 14 – Kinh Ðại bổn", url: "../dn/dn14.html#content" },

{ text: `Này các Tỷ-kheo, Thế Tôn Vipassì, bậc A-la-hán, Chánh Ðẳng Giác nhìn đời với Phật nhãn, thấy có hạng chúng sanh nhiễm ít bụi đời, nhiễm nhiều bụi đời, có hạng lợi căn độn căn, có hạng tánh thuận tánh nghịch, có hạng dễ dạy khó dạy, và một số ít thấy sự nguy hiểm phải tái sanh thế giới khác và sự nguy hiểm của những hành động lỗi lầm. Như trong hồ sen xanh, sen hồng hay sen trắng, có một số hoa sen xanh, sen hồng hay sen trắng sanh ra dưới nước, lớn lên dưới nước, không vượt lên khỏi mặt nước, được nuôi dưỡng dưới nước; có một số hoa sen xanh, sen hồng hay sen trắng sanh ra dưới nước lớn lên dưới nước, sống vươn lên tới mặt nước, có một số hoa sen xanh, sen hồng hay sen trắng sanh ra dưới nước lớn lên dưới nước vươn lên khỏi mặt nước, không bị nước làm đẫm ướt.`, ref: "DN 14 – Kinh Ðại bổn", url: "../dn/dn14.html#content" },

{ text: `Này các Tỷ-kheo, Thế Tôn Vipassì, bậc A-la-hán, Chánh Ðẳng Giác, giữa chúng Tỷ-kheo, tụng đọc giới bổn này:\n\n“Chư Phật dạy Niết-bàn là đệ nhất.\n“Nhẫn nhục, khổ hạnh, kham nhẫn, là đệ nhất.\n“Người xuất gia hại người xuất gia khác.\n“Hại người khác như vậy không xứng gọi là Sa-môn.\n\n“Mọi điều ác không làm, hướng tâm các thiện nghiệp.\n“Giữ tâm trí thanh tịnh, chính lời chư Phật dạy.\n\n“Không chỉ trích, không đánh đập, giữ mình trong giới bổn.\n“Ăn uống có tiết độ, ngủ nghỉ riêng một mình.\n“Hướng tâm đến cao khiết, chính lời chư Phật dạy”.`, ref: "DN 14 – Kinh Ðại bổn", url: "../dn/dn14.html#content" },
{ text: `Này Ānanda khi nào dân Vajjì, không ban hành những luật lệ không được ban hành, không hủy bỏ những luật lệ đã được ban hành, sống đúng với truyền thống của dân Vajjì như đã ban hành thuở xưa thời, này Ānanda, dân Vajjì sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này Ānanda, khi nào dân Vajjì tôn sùng, kính trọng, đảnh lễ, cúng dường các bậc trưởng lão Vajjì và nghe theo lời dạy của những vị này, thời dân Vajjì sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào chúng Tỷ-kheo tụ họp trong niệm đoàn kết, giải tán trong niệm đoàn kết, và làm việc Tăng sự trong niệm đoàn kết, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào chúng Tỷ-kheo không ban hành những luật lệ không được ban hành, không hủy bỏ những luật lệ đã được ban hành, sống đúng với những học giới được ban hành, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào chúng Tỷ-kheo tôn sùng, kính trọng, đảnh lễ, cúng dường các bậc Tỷ-kheo thượng tọa những vị này là những vị giàu kinh nghiệm, niên cao lạp trưởng, bậc cha của chúng Tăng, bậc thầy của chúng Tăng và nghe theo lời dạy của những vị này, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào chúng Tỷ-kheo không bị chi phối bởi tham ái, tham ái này tác thành một đời sống khác, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào chúng Tỷ-kheo thích sống những chỗ nhàn tịnh, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào chúng Tỷ-kheo tự thân an trú chánh niệm, khiến các bạn đồng tu thiện chí chưa đến muốn đến ở, và các bạn đồng tu thiện chí đã đến ở, được sống an lạc, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào chúng Tỷ-kheo không ưa thích làm thế sự, không hoan hỷ làm thế sự, không đam mê làm thế sự, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào chúng Tỷ-kheo không ưa thích phiếm luận, không hoan hỷ phiếm luận, không đam mê phiếm luận, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào chúng Tỷ-kheo không ưa thích ngủ nghỉ, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào chúng Tỷ-kheo không ưa thích quần tụ, không hoan hỷ quần tụ, không đam mê quần tụ, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào chúng Tỷ-kheo không có ác dục vọng, không bị chi phối bởi ác dục vọng, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào chúng Tỷ-kheo không bạn bè ác dục vọng, không thân tín ác dục vọng, không cộng hành với ác dục vọng, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các, Tỷ-kheo khi nào các vị Tỷ-kheo đối với các vị đồng tu phạm hạnh, tại chỗ đông người và vắng người, gìn giữ thân nghiệp từ hòa, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào các vị Tỷ-kheo đối với các vị đồng tu phạm hạnh, tại chỗ đông người và vắng người gìn giữ khẩu nghiệp từ hòa, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào các vị Tỷ-kheo đối với các vị đồng tu phạm hạnh, tại chỗ đông người và vắng người, gìn giữ ý nghiệp từ hòa, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào các vị Tỷ-kheo phân phối không thiên vị, chung thọ hưởng với các bạn giới đức đồng tu, mọi lợi dưỡng chơn chánh, hợp pháp, cho đến những vật thọ lãnh trong bình bát khất thực, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào các vị Tỷ-kheo sống với các bạn đồng tu, tại chỗ đông người và vắng người, trong sự thọ trì những giới luật đúng với Sa-môn hạnh, những giới luật không bị gẫy vụn, không bị sứt mẻ, không bị tỳ vết, không bị uế trược, những giới luật đưa đến giải thoát, được người có trí tán thán, không bị ô nhiễm bởi mục đích sai lạc, những giới luật hướng đến định tâm, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi nào các vị Tỷ-kheo sống với các bạn đồng tu, tại chỗ đông người và vắng người, trong sự thọ trì những tri kiến đúng với Sa-môn hạnh, những thánh tri kiến đưa đến giải thoát, hướng đến sự diệt tận khổ đau cho những ai thực hành theo, thời này các Tỷ-kheo, chúng Tỷ-kheo sẽ được cường thịnh, không bị suy giảm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Ðây là Giới, đây là Ðịnh, đây là Tuệ, Ðịnh cùng tu với Giới sẽ đưa đến quả vị lớn, lợi ích lớn. Tuệ cùng tu với Ðịnh sẽ đưa đến quả vị lớn, lợi ích lớn. Tâm cùng tu với Tuệ sẽ đưa đến giải thoát hoàn toàn các món lậu hoặc, tức là dục lậu, hữu lậu (tri kiến lậu), vô minh lậu.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Ở đây, này các Gia chủ, người phạm giới, sống trái giới luật sẽ bị tiêu hao tiền của rất nhiều vì sống phóng dật. Ðó là điều nguy hiểm thứ nhất cho những ai phạm giới, sống trái giới luật.\nLại nữa, này các Gia chủ, người phạm giới, sống trái giới luật bị tiếng dữ đồn xa. Ðó là điều nguy hiểm thứ hai cho những ai phạm giới, sống trái giới luật.\nLại nữa, này các Gia chủ, người phạm giới, sống trái giới luật khi vào hội chúng nào, hoặc Sát Ðế Lỵ, hoặc Bà-la-môn, hoặc gia chủ, hoặc Sa-môn, người ấy đi vào với tâm thần sợ hãi, bối rối. Ðó là điều nguy hiểm thứ ba cho những ai phạm giới, sống trái giới luật.\nLại nữa, này các Gia chủ, người phạm giới, sống trái giới luật sẽ chết với tâm hồn rối loạn. Ðó là điều nguy hiểm thứ tư cho những ai phạm giới, sống trái giới luật.\nLại nữa, này các Gia chủ, người phạm giới, sống trái giới luật sau khi thân hoại mạng chung, sẽ bị sanh vào khổ cảnh, ác thú, đọa xứ, địa ngục. Ðó là điều nguy hiểm thứ năm cho những ai phạm giới, sống trái giới luật.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Ở đây, này các Gia chủ, người giữ giới, sống theo giới luật sẽ có tiền của dồi dào rất nhiều vì sống không phóng dật. Ðó là sự lợi ích thứ nhất cho những ai giữ giới, sống theo giới luật.\nLại nữa, này các Gia chủ, người giữ giới, sống theo giới luật được tiếng tốt đồn xa. Ðó là sự lợi ích thứ hai cho những ai giữ giới, sống theo giới luật.\nLại nữa, này các Gia chủ, người giữ giới, sống theo giới luật khi đi vào hội chúng nào, hoặc Sát Ðế Lỵ, hoặc Bà-la-môn, hoặc gia chủ, hoặc Sa-môn, người ấy đi vào với tâm thần không sợ hãi, không bối rối. Ðó là sự lợi ích thứ ba cho những ai giữ giới, sống theo giới luật.\nLại nữa, này các Gia chủ, người giữ giới, sống theo giới luật sẽ chết với tâm hồn không rối loạn. Ðó là sự lợi ích thứ tư cho những ai giữ giới, sống theo giới luật.\nLại nữa, này các Gia chủ, người giữ giới, sống theo giới luật sau khi thân hoại mạng chung, sẽ được sanh vào thiện thú, thiên giới. Ðó là sự lợi ích thứ năm cho những ai giữ giới, sống theo giới luật.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Tại chỗ nào người sáng suốt lấy làm chỗ trú xứ.\nHãy nuôi dưỡng người giữ giới và người phạm hạnh.\nVà san sẽ công đức với Chư Thiên trú tại chỗ ấy.\nÐược tôn kính, chúng sẽ tôn kính lại.\nÐược trọng vọng, chúng sẽ trọng vọng lại.\nChúng sẽ mến thương người ấy như người mẹ thương mến con.\nVà những ai được thiên thần thân mến luôn luôn được thấy may mắn.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Thế Tôn thấy những người kia, người đang đi tìm thuyền, người đang đi tìm phao, người đang đi cột bè để qua bờ bên kia. Thế Tôn hiểu được ý nghĩa của cảnh này, lúc ấy bèn ứng khẩu lời cảm khái:\n“Những ai làm cầu vượt biển trùng dương,\nbỏ lại đất sũng đầm ao, trong khi người phàm phu đang cột bè.\nNhững người ấy thật là những vị trí tuệ được giải thoát”`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, chính vì không giác ngộ, không thông hiểu Bốn Thánh đế mà chúng ta phải lưu chuyển luân hồi lâu năm, Ta và các Ngươi. Bốn Thánh đế ấy là gì?\nNày các Tỷ-kheo, chính vì không giác ngộ, không thông hiểu Khổ Thánh đế,; không giác ngộ, không thông hiểu Khổ Tập Thánh đế,...Khổ Diệt Thánh đế,...Khổ Diệt Ðạo Thánh đế mà chúng ta phải lưu chuyển luân hồi lâu năm, Ta và các Ngươi.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo khi Khổ Thánh đế này được giác ngộ, được thông hiểu; khi Khổ Tập Thánh đế này được giác ngộ, được thông hiểu; khi Khổ Diệt Thánh đế này được giác ngộ, được thông hiểu; khi Khổ Diệt Ðạo Thánh đế này được giác ngộ, được thông hiểu, thời hữu ái được diệt trừ, sự dắt dẫn đến một đời sống được đoạn tuyệt, nay không còn hậu hữu nữa.\nThế Tôn thuyết như vậy. Thiện Thệ lại nói thêm:\n—Chính vì không thấy như thật Bốn Thánh đế nên có sự luân chuyển lâu ngày trong nhiều đời. Khi những sự thực này được nhận thức, nguyên nhân của một đời sống khác được trừ diệt, khi khổ căn được đoạn trừ, sẽ không còn một đời sống khác nữa.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này Ānanda, vì vậy ta sẽ giảng Pháp kính (Gương chánh pháp) để Thánh đệ tử, sau khi chứng đạt pháp nghĩa này, nếu muốn, sẽ tự tuyên bố về mình như sau: “Ðối với ta, sẽ không còn địa ngục, sẽ không còn tái sanh cõi bàng sanh, ngạ quỷ, đọa xứ, ác thú. Ta đã chứng quả Dự lưu, nhứt định không đọa ác đạo, sẽ đạt Chánh giác”.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này Ānanda, vị Thánh đệ tử có chánh tín đối với đức Phật: “Thế Tôn là bậc A-la-hán, Chánh Ðẳng Giác, Minh hạnh Túc, Thiện Thệ, Thế Gian Giải, Vô Thượng Sĩ, Ðiều Ngự Trượng Phu, Thiên Nhân Sư, Phật, Thế Tôn”. Vị ấy có chánh tín đối với chánh pháp: “Chánh pháp được Thế Tôn khéo giảng dạy, thiết thực, vượt ngoài thời gian chi phối, đến để mà thấy, có khả năng giải thoát, được kẻ trí tự mình thâm hiểu”.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Vị ấy có chánh tín đối với chúng Tăng: “Chúng Tăng đệ tử Thế Tôn chân chánh tu hành, chúng Tăng đệ tử Thế Tôn chân trực tu hành, chúng Tăng đệ tử Thế Tôn chân trí tu hành, chúng Tăng đệ tử Thế Tôn chân tịnh tu hành, tức là bốn đôi tám vị. Chúng Tăng đệ tử Thế Tôn đáng được nghênh đón, đáng được cúng dường, đáng được chiêm ngưỡng, đáng được chấp tay, là phước điền vô thượng ở trên đời.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Vị ấy có chánh tín đối với giới hạnh được bậc Thánh mến chuộng, được viên mãn không mảy mún, được vẹn toàn không sứt mẻ, không tỳ vết, không ô nhiễm, những giới hạnh đưa đến giải thoát, được người trí tán thán, không bị ảnh hưởng bởi đời sau, hướng dẫn đến thiền định”.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, các Ngươi phải sống an trú chánh niệm, tỉnh giác. Ðó là lời dạy của Ta cho các Ngươi.\nNày các Tỷ-kheo, thế nào là Tỷ-kheo an trú chánh niệm? Này các Tỷ-kheo, Tỷ-kheo đối với thân, quán thân, tinh tấn, tỉnh giác, chánh niệm nhiếp phục mọi tham ái, ưu bi ở trên đời, đối với các cảm thọ … đối với tâm … đối với các pháp, quán pháp, tinh tấn, tỉnh giác, chánh niệm, nhiếp phục mọi tham ái, ưu bi ở trên đời. Này các Tỷ-kheo, như vậy gọi là chánh niệm.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo thế nào là Tỷ-kheo tỉnh giác? Này các Tỷ-kheo, ở đây Tỷ Kheo tỉnh giác khi đi tới, đi lui, tỉnh giác khi ngó tới, ngó lui; tỉnh giác khi co tay, duỗi tay, tỉnh giác khi mang áo sanghati (tăng-già-lê) mang bát, mang y, tỉnh giác khi ăn, khi uống, khi nhai, khi nếm, tỉnh giác khi đại tiện, tiểu tiện; tỉnh giác khi đi; khi đứng, khi ngồi, khi nằm, khi thức, khi nói, khi im lặng. Này các Tỷ-kheo, như vậy Tỷ-kheo sống tỉnh giác. Này các Tỷ-kheo, Tỷ-kheo phải sống an trú chánh niệm, tỉnh giác. Ðó là lời dạy của Ta cho các Ngươi.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Trong khi Thế Tôn an cư trong mùa mưa, một cơn bệnh trầm trọng khởi lên, rất đau đớn, gần như muốn chết. Nhưng Thế Tôn giữ tâm chánh niệm, tỉnh giác, chịu đựng cơn đau ấy, không một chút ta thán. Thế Tôn tự nghĩ: “Thật không hợp lẽ nếu Ta diệt độ mà không có một lời với các đệ tử hầu cận Ta, không từ biệt chúng Tỷ-kheo. Vậy Ta hãy lấy sức tinh tấn, nhiếp phục cơn bệnh này, duy trì mạng căn và tiếp tục sống”. Và Thế Tôn với sức tinh tấn, nhiếp phục bệnh ấy duy trì mạng căn.\nRồi Thế Tôn lành bệnh. Sau khi lành bệnh không bao lâu, đức Phật rời khỏi tịnh xá và ngồi trên ghế đã soạn sẵn, trong bóng mát của ngôi tịnh xá.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Bạch Thế Tôn, con được thấy Thế Tôn khỏe mạnh. Bạch Thế Tôn, con được thấy Thế Tôn kham nhẫn, bạch Thế Tôn, thấy Thế Tôn bệnh hoạn, thân con cảm thấy yếu ớt như lau sậy, mắt con mờ mịt không thấy rõ phương hướng, dầu cho, bạch Thế Tôn, con được một chút an ủi rằng, Thế Tôn sẽ không diệt độ, nếu Ngài chưa có lời di giáo lại cho chúng Tỷ-kheo.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này Ānanda, chúng Tỷ-kheo còn mong mỏi gì nữa ở Ta! Này Ānanda, Ta đã giảng Chánh pháp, không có phân biệt trong ngoài (mật giáo và không phải mật giáo), vì này Ānanda, đối với các Pháp, Như Lai không bao giờ là vị Ðạo sư còn nắm tay (còn giữ lại một ít mật giáo chưa giảng dạy). Này Ānanda, những ai nghĩ rằng: “Như Lai là vị cầm đầu chúng Tỷ-kheo”; hay “chúng Tỷ-kheo chịu sự giáo huấn của Như Lai” thời này Ānanda, người ấy sẽ có lời di giáo cho chúng Tỷ-kheo. Này Ānanda, Như Lai không nghĩ rằng: “Ta là vị cầm đầu chúng Tỷ-kheo; hay “chúng Tỷ-kheo chịu sự giáo huấn của Ta” thời này Ānanda, làm sao Như Lai lại có lời di giáo cho chúng Tỷ-kheo? Này Ānanda, Ta nay đã già, đã thành bậc trưởng thượng, đã đến tuổi lâm chung, đã đến tám mươi tuổi. Này Ānanda, như cỗ xe đã già mòn, sở dĩ còn chạy được là nhờ dây thắng chằng chịt, cũng vậy thân Như Lai được duy trì sự sống giống như chính nhờ chống đỡ dây chằng. Này Ānanda, chỉ trong khi Như Lai không tác ý đến tất cả tướng, với sự diệt trừ một số cảm thọ, chứng và an trú vô tướng tâm định, chính khi ấy thân Như Lai được thoải mái.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Vậy nên, này Ānanda, hãy tự mình là ngọn đèn cho chính mình, hãy tự mình nương tựa chính mình, chớ nương tựa một gì khác. Dùng Chánh pháp làm ngọn đèn, dùng Chánh pháp làm chỗ nương tựa, chớ nương tựa một gì khác.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này Ānanda, ở đời, vị Tỷ-kheo, đối với thân quán thân, tinh tấn, tỉnh giác, chánh niệm, nhiếp phục mọi tham ái, ưu bi trên đời; đối với các cảm thọ … đối với tâm … đối với các pháp, quán pháp, tinh tấn, tỉnh giác, chánh niệm, nhiếp phục mọi tham ái, ưu bi trên đời. Này Ānanda, như vậy vị Tỷ-kheo tự mình là ngọn đèn cho chính mình, tự mình nương tựa chính mình, không nương tựa một gì khác, dùng Chánh pháp làm ngọn đèn, dùng Chánh pháp làm chỗ nương tựa, không nương tựa một gì khác.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này Ānanda, những ai sau khi Ta diệt độ, tự mình là ngọn đèn cho chính mình, tự mình nương tựa chính mình, không nương tựa một gì khác, dùng Chánh pháp làm ngọn đèn, dùng Chánh pháp làm chỗ nương tựa, không nương tựa vào một pháp gì khác, những vị ấy, này Ānanda, là những vị tối thượng trong hàng Tỷ-kheo của Ta, nếu những vị ấy tha thiết học hỏi.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này Ác ma, Ta sẽ không diệt độ khi nào những Tỷ-kheo của Ta,...những Tỷ-kheo ni,...những nam cư sĩ,...những nữ cư sĩ của ta chưa trở thành những vị đệ tử chân chánh, sáng suốt, có kỷ luật, sẵn sàng, đa văn, duy trì Chánh pháp, thành tựu Chánh pháp và tùy pháp, sống chân chánh, sống theo Chánh pháp, sau khi học hỏi giáo lý, chưa có thể tuyên bố, diễn giảng, trình bày, xác định, khai minh, phân tích, và giải thích rõ ràng Chánh pháp, khi có tà đạo khởi lên chưa có thể chất vấn và hàng phục một cách khéo léo, chưa có thể truyền bá Chánh pháp thần diệu”.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Và tại điện thờ Capala, Thế Tôn chánh niệm, tỉnh giác, từ bỏ thọ, hành (không duy trì mạng sống lâu hơn nữa). Khi Thế Tôn từ bỏ, không duy trì mạng sống thêm nữa, thời đại địa chấn động, ghê rợn, tóc lông dựng ngược, sấm trời vang dậy. Thế Tôn nhận hiểu ý nghĩa của sự kiện ấy, liền thốt câu kệ cảm khái như sau:\nMạng sống có hạn hay vô hạn,\nTu sĩ từ bỏ, không kéo dài.\nNội tâm chuyên nhất trú thiền định.\nNhư tháo áo giáp đang mang mặc.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này Ānanda, có tám nhân, có tám duyên khiến đại địa chấn động. Thế nào là tám? Này Ānanda, đại địa này thiết lập trên nước, nước ở trên gió và gió ở tại hư không. Này Ānanda, đến thời đại phong khởi lên, gió lớn khi thổi làm nổi sóng nước, và khi nước nổi sóng thì quả đất rung động. Ðó là nhân thứ nhất, duyên thứ nhất, đại địa chấn động.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này Ác ma, Ta không diệt độ khi nào phạm hạnh mà Ta giảng dạy chưa được thành tựu, thịnh đạt, phổ biến, quảng bá, biến mãn, nghĩa là được khéo giảng dạy cho loài Người.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này Ānanda, phải chăng ngay từ ban đầu Ta đã từng tuyên bố rằng mọi vật ưu ái, thân hình đều phải bị thay đổi, trở về hư không, biến dịch? Này Ānanda, làm sao có thể được như vầy: Những gì sanh khởi, tồn tại, hữu vi, chịu sự biến hoại mà lại mong khỏi có sự biến diệt? Thật không có sự trạng ấy. Này Ānanda, những gì Như Lai đã từ bỏ, dứt khoát, xả ly, phóng xả, khước từ, chính là thọ, hành. Như Lai đã nói và nói một cách dứt khoát: “Không lâu, Như Lai sẽ diệt độ. Sau ba tháng bắt đầu hôm nay, Như Lai sẽ diệt độ”. Nói rằng Như Lai vì muốn sống mà phản lại lời tuyên bố trên thời thật không có sự trạng ấy.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, nay những pháp do Ta chứng ngộ và giảng dạy cho các Ngươi, các Ngươi phải khéo học hỏi, thực chứng tu tập và truyền rộng để phạm hạnh được trường tồn, vĩnh cửu, vì hạnh phúc cho chúng sanh, vì an lạc cho chúng sanh, vì lòng thương tưởng cho đời, vì lợi ích, vì hạnh phúc, vì an lạc cho loài Trời và loài Người.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, thế nào là các pháp do Ta chứng ngộ và giảng dạy, các Ngươi phải khéo học hỏi, thực chứng, tu tập và truyền rộng để cho phạm hạnh được trường tồn, vĩnh cửu, vì hạnh phúc cho chúng sanh, vì an lạc cho chúng sanh, vì lòng thương tưởng cho đời, vì lợi ích, vì hạnh phúc, vì an lạc cho loài Trời và loài Người? Chính là Bốn Niệm xứ, Bốn Chánh cần, Bốn Thần túc, Năm Căn, Năm Lực, Bảy Bồ-đề phần, Tám Thánh đạo phần. Này các Tỷ-kheo, chính những pháp này do Ta chứng ngộ và giảng dạy, mà các Ngươi phải khéo học hỏi, thực chứng, tu tập và truyền rộng để phạm hạnh được trường tồn, vĩnh cửu, vì hạnh phúc cho chúng sanh, vì lòng thương tưởng cho đời, vì lợi ích, vì hạnh phúc, vì an lạc cho loài Trời và loài Người.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, đây là lời Ta nhắn nhủ các Ngươi. Các hành là vô thường. Hãy tinh tấn lên để tự giải thoát, không lâu Như Lai sẽ diệt độ. Sau ba tháng bắt đầu từ hôm nay, Như Lai sẽ diệt độ.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Ta đã già, dư mạng chẳng còn bao,\nTừ biệt các Ngươi, Ta đi một mình.\nTự mình làm sở y cho chính mình,\nHãy tinh tấn, chánh niệm, giữ giới luật,\nNhiếp thúc ý chí, bảo hộ tự tâm.\nAi tinh tấn trong pháp và luật này\nSẽ diệt sanh tử, chấm dứt khổ đau.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, chính vì không giác ngộ, không chứng đạt bốn Pháp mà Ta và các Ngươi lâu đời phải trôi lăn trong biển sanh tử. Thế nào là bốn? Này các Tỷ-kheo, chính vì không giác ngộ, không chứng đạt Thánh Giới mà Ta và các Ngươi lâu đời phải trôi lăn trong biển sanh tử. Này các Tỷ-kheo, chính vì không giác ngộ, không chứng đạt Thánh Ðịnh mà Ta và các Ngươi lâu đời phải trôi lăn trong biển sanh tử. Này các Tỷ-kheo, chính vì không giác ngộ, không chứng đạt Thánh Tuệ mà Ta và các Ngươi lâu đời phải trôi lăn trong biển sanh tử. Này các Tỷ-kheo, chính vì không giác ngộ, không chứng đạt Thánh giải thoát mà Ta và các Ngươi lâu đời phải trôi lăn trong biển sanh tử.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, khi Thánh Giới được giác ngộ, được chứng đạt; khi Thánh Ðịnh được giác ngộ, được chứng đạt; khi Thánh Tuệ được giác ngộ, được chứng đạt; khi Thánh Giải thoát được giác ngộ, được chứng đạt, thời tham ái một đời sống tương lai được trừ diệt, những gì đưa đến một đời sống mới được dứt sạch, nay không còn một đời sống nào nữa.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Giới, Ðịnh, Tuệ và Giải thoát vô thượng\nGotama danh xưng đã chứng ngộ.\nÐấng Giác Ngộ giảng pháp chúng Tỷ-kheo.\nÐạo Sư diệt khổ, pháp nhãn, tịnh lạc.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, có thể có vị Tỷ-kheo nói: “Tại trú xứ kia có nhiều Tỷ-kheo Thượng tọa ở, những vị này là bậc đa văn, gìn giữ truyền thống, trì pháp, trì luật, trì pháp yếu. Tôi tự thân nghe từ miệng những vị Thượng tọa ấy, tự thân lãnh thọ, như vậy là Pháp, như vậy là Luật, như vậy là lời dạy của vị Ðạo Sư”. Này các Tỷ-kheo, các Ngươi không nên tán thán, không nên hủy báng lời nói của Tỷ-kheo ấy. Không tán thán, không hủy báng, mỗi mỗi chữ, mỗi mỗi câu, phải được học hỏi kỹ lưỡng và đem so sánh với Kinh, đem đối chiếu với Luật. Khi đem so sánh với Kinh, đối chiếu với Luật, và nếu chúng không phù hợp với Kinh, không tương ứng với Luật, thời các Ngươi có thể kết luận: “Chắc chắn những lời này không phải là lời Thế Tôn và Tỷ-kheo ấy đã thọ giáo sai lầm”. Và, này các Tỷ-kheo, các Ngươi hãy từ bỏ chúng. Khi đem so sánh với Kinh, đem đối chiếu với Luật, nếu chúng phù hợp với Kinh, tương ứng với Luật, thời các Ngươi có thể kết luận: “Chắc chắn những lời ấy phải là lời dạy của Thế Tôn và Tỷ-kheo ấy đã thọ giáo chơn chánh”. Này các Tỷ-kheo, như vậy là Ðại giáo pháp thứ ba, các Ngươi hãy thọ trì.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Tôi nghe: Sau khi dùng cơm tại nhà thợ sắt Cunda.\nCơn bệnh khốc liệt bỗng khởi lên, gần như chết đến nơi.\nSau khi cùng món ăn loại mộc nhĩ.\nKịch bệnh khởi lên nơi bậc Ðạo Sư.\nÐiều phục bệnh hoạn, Thế Tôn dạy rằng:\n“Ta đi đến thành Kusināra”.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Tôn giả Ānanda tự nghĩ: “Thật kỳ diệu thay, thật hy hữu thay thần túc và uy lực của Như Lai. Con sông nhỏ đang chảy nông cạn, khuấy động và vẩn đục này, khi ta đến, liền trở thành trong trẻo, sáng lặng và không vẩn đục”.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Bạch Thế Tôn, thật là kỳ diệu, bạch Thế Tôn, thật là hy hữu, trạng thái trầm tĩnh của một vị xuất gia!`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này Pukkusa, người ấy liền tự nghĩ: “Thật là kỳ diệu, thật là hy hữu sự trầm lặng của vị xuất gia, khi thức tỉnh, dầu có mưa tầm tã ào ào, điện quang chói lòa, sấm sét vang động, có hai anh em nông phu và bốn con bò đực bị sét đánh chết mà không thấy gì, không nghe gì hết”. Sau khi nói lên lòng tin tưởng ở nơi Ta, người ấy đảnh lễ Ta, thân phía hữu hướng về phía Ta và từ biệt.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Bạch Thế Tôn, sự tin tưởng của con đối với ngài Alāra Kālāma, nay con đem rải rắc trước luồng gió lớn, nay con đem thả trôi vào dòng nước cuốn. Kỳ diệu thay, bạch Thế Tôn! Hy hữu thay bạch Thế Tôn! Bạch Thế Tôn, như người dựng đứng lại những gì bị quăng ngã xuống, phơi bày ra những gì bị che kín, chỉ đường cho người bị lạc hướng, đem đèn sáng vào trong bóng tối để những ai có mắt có thể thấy sắc. Cũng vậy, Chánh pháp đã được Thế Tôn dùng nhiều phương tiện trình bày. Bạch Thế Tôn, con xin quy y Thế Tôn, quy y Pháp và quy y Tỷ-kheo Tăng. Mong Thế Tôn nhận con làm đệ tử, từ nay trở đi cho đến mạng chung, con trọn đời quy ngưỡng.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Ðức Phật tự đi đến\nCon sông Kakutthà.\nCon sông chảy trong sáng.\nMát lạnh và thanh tịnh.\nVị Ðạo Sư mỏi mệt\nÐi dần xuống mé sông.\nNhư Lai đấng Vô Thượng\nNgự trị ở trên đời\nTắm xong, uống nước xong,\nLội qua bên kia sông.\nBậc Ðạo Sư đi trước,\nGiữa Tăng chúng Tỷ-kheo,\nVừa đi vừa diễn giảng.\nChánh pháp thật vi diệu.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này Hiền giả Cunda, tôi tự thân nghe, tự thân lãnh thọ lời nói này của Thế Tôn: “Có hai sự cúng dường ăn uống đồng một quả báo, đồng một dị thục quả, quả báo lớn hơn, lợi ích hơn các sự cúng dường ăn uống khác? Thế nào là hai? Một là bữa ăn trước khi Như Lai chứng vô thượng Chánh Ðẳng Chánh Giác, hai là bữa ăn trước khi Như Lai diệt độ Niết-bàn giới, không còn di hưởng sanh tử. Hai bữa ăn này đồng một quả báo, đồng một dị thục quả, quả báo lớn hơn, lợi ích hơn các sự cúng dường ăn uống khác. Nhờ hành động này, đại đức Cunda sẽ được hưởng tuổi thọ; nhờ hành động này, đại đức Cunda sẽ được hưởng sắc đẹp; nhờ hành động này, đại đức Cunda sẽ được hưởng an lạc; nhờ hành động này, đại đức Cunda sẽ được hưởng danh tiếng; nhờ hành động này, đại đức Cunda sẽ được hưởng cõi trời, nhờ hành động này, đại đức Cunda sẽ được hưởng uy quyền”.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },
{ text: `Này Ānanda, nếu có Tỷ-kheo, Tỷ-kheo ni, cư sĩ nam hay cư sĩ nữ nào thành tựu Chánh pháp và Tùy pháp, sống chơn chánh trong Chánh pháp, hành trì đúng Chánh pháp, thời người ấy kính trọng, tôn sùng, đảnh lễ, cúng dường Như Lai với sự cúng dường tối thượng. Do vậy, này Ānanda, hãy thành tựu Chánh pháp và Tùy pháp, sống chơn chánh trong Chánh pháp và hành trì đúng Chánh pháp. Này Ānanda, các Người phải học tập như vậy.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này Subhadda, trong pháp luật nào không có Bát Thánh đạo, thời ở đây không có đệ nhất Sa-môn, ở đây cũng không có đệ nhị Sa-môn, cũng không có đệ tam Sa-môn, cũng không có đệ tứ Sa-môn. Này Subhadda trong pháp luật nào có Bát Thánh đạo, thời ở đây có đệ nhất Sa-môn, cũng có đệ nhị Sa-môn, cũng có đệ tam Sa-môn, ở đấy cũng có đệ tứ Sa-môn. Này Subhadda, chính trong pháp luật này có Bát Thánh Ðạo, thời này Subhadda, ở đây có đệ nhất Sa-môn, ở đây cũng có đệ nhị Sa-môn, cũng có đệ tam Sa-môn, cũng có đệ tứ Sa-môn. Những hệ thống ngoại đạo khác đều không có những Sa-môn. Này Subhadda, nếu những vị Tỷ-kheo này sống chơn chánh, thời đời này không vắng những vị A-la-hán.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này Subhadda, năm hai mươi chín,\nTa xuất gia hướng tìm chân thiện đạo.\nTrải năm mươi năm với thêm một năm\nTừ khi xuất gia, này Subhadda,\nTa là du sĩ tu Trí, tu Ðức.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này Ānanda, nếu trong các ngươi có người nghĩ rằng: “Lời nói của bậc Ðạo sư không còn nữa. Chúng ta không có Ðạo sư (giáo chủ)”. Này Ānanda, chớ có những tư tưởng như vậy. Này Ānanda, Pháp và Luật, Ta đã giảng dạy và trình bày, sau khi Ta diệt độ, chính Pháp và Luật ấy sẽ là Ðạo Sư của các Ngươi.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ-kheo, nay Ta khuyên dạy các ngươi: “Các pháp hữu vi là vô thường, hãy tinh tấn, chớ có phóng dật”.\nÐó là lời cuối cùng Như Lai.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Các hành là vô thường,\nCó sanh phải có diệt\nÐã sanh, chúng phải diệt,\nNhiếp chúng là an lạc.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Không phải thở ra vào\nChính tâm trú chánh định\nKhông tham ái tịch tịnh\nTu sĩ hướng diệt độ\nChính tâm tịnh bất động\nNhẫn chịu mọi cảm thọ\nNhư đèn sáng bị tắt\nTâm giải thoát hoàn toàn.`, ref: "DN 16 – Kinh Ðại Bát Niết Bàn", url: "../dn/dn16.html#content" },

{ text: `Này các Tỷ kheo, đây là con đường độc nhất, đưa đến thanh tịnh cho chúng sanh, vượt khỏi sầu bi, diệt trừ khổ ưu, thành tựu chánh lý, chứng ngộ Niết bàn. Ðó là Bốn niệm xứ.\nThế nào là bốn? Này các Tỷ kheo, ở đây vị Tỷ kheo sống quán thân trên thân, nhiệt tâm, tỉnh giác, chánh niệm, để chế ngự tham ưu ở đời; sống quán thọ trên các thọ, nhiệt tâm, tỉnh giác, chánh niệm, để chế ngự tham ưu ở đời; sống quán tâm trên tâm, nhiệt tâm, tỉnh giác, chánh niệm, để chế ngự tham ưu ở đời; sống quán pháp trên các pháp, nhiệt tâm, tỉnh giác, chánh niệm, để chế ngự tham ưu ở đời.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Này các Tỷ kheo, ở đây Tỷ kheo đi đến khu rừng, đi đến gốc cây, hay đi đến ngôi nhà trống, và ngồi kiết già, lưng thẳng và an trú chánh niệm trước mặt. Tỉnh giác, vị ấy thở vô; tỉnh giác, vị ấy thở ra. Thở vô dài, vị ấy tuệ tri: “Tôi thở vô dài”; hay thở ra dài, vị ấy tuệ tri: “Tôi thở ra dài”; hay thở vô ngắn, vị ấy tuệ tri: “Tôi thở vô ngắn”; hay thở ra ngắn, vị ấy tuệ tri: “Tôi thở ra ngắn”; Cảm giác toàn thân, tôi sẽ thở vô”, vị ấy tập; “Cảm giác toàn thân, tôi sẽ thở ra”, vị ấy tập; “An tịnh thân hành, tôi sẽ thở vô”, vị ấy tập; “An tịnh thân hành, tôi sẽ thở ra”, vị ấy tập.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Như vậy, vị ấy sống quán thân trên nội thân; hay sống quán thân trên ngoại thân; hay sống quán thân trên cả nội thân, ngoại thân. Hay vị ấy sống quán tánh sanh khởi trên thân; hay sống quán tánh diệt tận trên thân; hay sống quán tánh sanh diệt trên thân. “Có thân đây”, vị ấy an trú chánh niệm như vậy với hy vọng hướng đến chánh trí, chánh niệm. Và vị ấy sống không nương tựa, không chấp trước một vật gì trên đời. Này các Tỷ kheo, như vậy Tỷ kheo sống quán thân trên thân.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Lại nữa, này các Tỷ kheo, Tỷ kheo, khi bước tới, bước lui, biết rõ việc mình đang làm. Khi ngó tới, ngó lui, biết rõ việc mình đang làm. Khi co tay khi duỗi tay biết rõ việc mình đang làm. Khi mang áo Sanghàti (Tăng-già-lê), mang bát, mang y, biết rõ việc mình đang làm. Khi ăn, uống, nhai, nếm, biết rõ việc mình đang làm. Khi đi đại tiện, tiểu tiện, biết rõ việc mình đang làm. Khi đi, đứng, ngồi, nằm, biết rõ việc mình đang làm.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Này các Tỷ kheo, cũng như một bao đồ, hai đầu trống đựng đầy các loại hột như gạo, lúa, đậu xanh, đậu lớn, mè, gạo đã xay rồi. Một người có mắt, đổ các hột ấy ra và quan sát: “Ðây là hột gạo, đây là hột lúa, đây là đậu xanh, đây là đậu đỏ, đây là mè, đây là hột lúa đã xay rồi.” Cũng vậy, này các Tỷ kheo, một Tỷ kheo quán sát thân này dưới từ bàn chân trở lên, trên cho đến đảnh tóc, bao bọc bởi da và chứa đầy những vật bất tịnh sai biệt: “Trong thân này, đây là tóc, lông, móng, răng, da, thịt, gân, xương, tủy, thận, tim, gan, hoành cách mô, lá lách, phổi, ruột, màng ruột, bụng, phân, mật, đàm, mủ, máu, mồ hôi, mỡ, nước mắt, mỡ da, nước miếng, niêm dịch, nước ở khớp xương, nước tiểu.”`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Này các Tỷ kheo, ở nơi đây Tỷ kheo khi cảm giác lạc thọ, biết rằng: “Tôi cảm giác lạc thọ”; khi cảm giác khổ thọ, biết rằng: “Tôi cảm giác khổ thọ”; khi cảm giác bất khổ bất lạc thọ, biết rằng: “Tôi cảm giác bất khổ bất lạc thọ”. Hay khi cảm giác lạc thọ thuộc vật chất biết rằng: “Tôi cảm giác lạc thọ thuộc vật chất”. Hay khi cảm giác lạc thọ không thuộc vật chất, biết rằng: “Tôi cảm giác lạc thọ không thuộc vật chất”. Hay khi cảm giác khổ thọ thuộc vật chất, biết rằng: “Tôi cảm giác khổ thọ thuộc vật chất”. Hay khi cảm giác khổ thọ không thuộc vật chất, biết rằng: “Tôi cảm giác khổ thọ không thuộc vật chất”. Hay khi cảm giác bất khổ bất lạc thọ thuộc vật chất, biết rằng: “Tôi cảm giác bất khổ bất lạc thọ thuộc vật chất”. Hay khi cảm giác bất khổ bất lạc thọ không thuộc vật chất, biết rằng: “Tôi cảm giác bất khổ bất lạc thọ không thuộc vật chất”.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Này các Tỷ kheo, ở đây vị Tỷ kheo: “Với tâm có tham, biết rằng tâm có tham”; hay “Với tâm không tham, biết rằng tâm không tham”; hay “Với tâm có sân, biết rằng tâm có sân”; hay “Với tâm không sân, biết rằng tâm không sân”; hay “Với tâm có si, biết rằng tâm có si”; hay “Với tâm không si, biết rằng tâm không si”; hay “Với tâm có định, biết rằng tâm có định”; hay “Với tâm không định, biết rằng tâm không định”; hay “Với tâm giải thoát, biết rằng tâm có giải thoát”; hay “Với tâm không giải thoát, biết rằng tâm không giải thoát”.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Này các Tỷ kheo, ở đây Tỷ kheo, nội tâm có tham dục, tuệ tri: “Nội tâm tôi có tham dục”; hay nội tâm không có tham dục, tuệ tri rằng: “Nội tâm tôi không có tham dục”. Và với tham dục chưa sanh nay sanh khởi, vị ấy tuệ tri như vậy. Và với tham dục đã sanh nay được đoạn diệt, vị ấy tuệ tri như vậy. Và với tham dục đã được đoạn diệt, tương lai không sanh khởi nữa, vị ấy tuệ tri như vậy.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Hay nội tâm có sân hận, tuệ tri rằng: “Nội tâm tôi có sân hận”; hay nội tâm không có sân hận, tuệ tri rằng: “Nội tâm tôi không có sân hận.” Và với sân hận chưa sanh nay sanh khởi, vị ấy tuệ tri như vậy. Và với sân hận đã sanh nay được đoạn diệt, vị ấy tuệ tri như vậy. Và với sân hận đã được đoạn diệt, tương lai không sanh khởi nữa, vị ấy tuệ tri như vậy.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Hay nội tâm có hôn trầm thụy miên, tuệ tri rằng: “Nội tâm tôi có hôn trầm thụy miên”; hay nội tâm không có hôn trầm thụy miên, tuệ tri rằng: “Nội tâm tôi không có hôn trầm thụy miên”. Và với hôn trầm thụy miên chưa sanh nay sanh khởi, vị ấy tuệ tri như vậy. Và với hôn trầm thụy miên đã sanh nay được đoạn diệt, vị ấy tuệ tri như vậy. Và với hôn trầm thụy miên đã được đoạn diệt, tương lai không sanh khởi nữa, vị ấy tuệ tri như vậy.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Này các Tỷ kheo, Tỷ kheo suy tư: “Ðây là sắc, đây là sắc sanh, đây là sắc diệt. Ðây là thọ, đây là thọ sanh, đây là thọ diệt. Ðây là tưởng, đây là tưởng sanh, đây là tưởng diệt. Ðây là hành, đây là hành sanh, đây là hành diệt. Ðây là thức, đây là thức sanh, đây là thức diệt”. Như vậy vị ấy sống quán pháp trên các nội pháp; hay sống quán pháp trên các ngoại pháp; hay sống quán pháp trên các nội pháp, ngoại pháp; hay sống quán tánh sanh khởi trên các pháp; hay sống quán tánh diệt tận trên các pháp; hay sống quán tánh sanh diệt trên các pháp. “Có những pháp ở đây”, vị ấy sống an trú chánh niệm như vậy, với hy vọng hướng đến chánh trí, chánh niệm. Và vị ấy sống không nương tựa, không chấp trước một vật gì ở trên đời. Này các Tỷ kheo, như vậy Tỷ kheo sống quán pháp trên các pháp đối với Năm Thủ uẩn.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Và này các Tỷ kheo, thế nào Khổ Thánh đế? Sanh là khổ, già là khổ, chết là khổ, sầu, bi. Khổ, ưu, não là khổ, cầu không được là khổ, tóm lại Năm Thủ uẩn là khổ.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Này các Tỷ kheo, sự tham ái này khi sanh khởi thì sanh khởi ở đâu, khi an trú thì an trú ở đâu? Ở đời, sắc gì thân ái, sắc gì khả ái? Ở đời con mắt là sắc thân ái, là sắc khả ái. Sự tham ái này khi sanh khởi thì sanh khởi ở đấy, khi an trú thì an trú ở đấy. Ở đời cái tai … ở đời mũi … ở đời lưỡi … ở đời thân … ở đời ý là sắc thân ái, là sắc khả ái. Sự tham ái này khi sanh khởi thì sanh khởi ở đấy, khi an trú thì an trú ở đấy.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Này các Tỷ kheo, thế nào là Khổ diệt đạo Thánh đế. Ðó là bát chi Thánh đạo, tức là Chánh tri kiến, Chánh tư duy, Chánh ngữ, Chánh nghiệp, Chánh mạng, Chánh tinh tấn, Chánh niệm, Chánh định.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Này các Tỷ kheo, thế nào là Chánh tri kiến? Này các Tỷ kheo, tri kiến về Khổ, tri kiến về Khổ tập, tri kiến về Khổ diệt, tri kiến về Khổ diệt đạo. Này các Tỷ kheo, như vậy gọi là Chánh tri kiến.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Này các Tỷ kheo, thế nào là Chánh tư duy? Tư duy về ly dục, tư duy về vô sân, tư duy về bất hại. Này các tỷ kheo, như vậy gọi là Chánh tư duy.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Này các Tỷ kheo thế nào là Chánh ngữ? Tự chế không nói láo, tự chế không nói hai lưỡi, tự chế không ác khẩu, tự chế không nói lời phù phiếm. Này các Tỷ kheo, như vậy gọi là Chánh ngữ.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Này các Tỷ kheo, thế nào là Chánh nghiệp? Tự chế không sát sanh, tự chế không trộm cướp, tự chế không tà dâm. Này các Tỷ kheo, như vậy gọi là Chánh nghiệp.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Này các Tỷ kheo, thế nào là Chánh mạng? Này các Tỷ kheo, ở đây vị Thánh đệ tử từ bỏ tà mạng, sinh sống bằng chánh mạng. Này các Tỷ kheo, như vậy gọi là Chánh mạng.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Này các Tỷ kheo, và thế nào là Chánh tinh tấn? Này các Tỷ kheo, ở đây Tỷ kheo, đối với các ác, bất thiện pháp chưa sanh, khởi lên ý muốn không cho sanh khởi; vị này nỗ lực, tinh tấn, quyết tâm, trì chí. Ðối với các ác, bất thiện pháp đã sanh, khởi lên ý muốn trừ diệt, vị này nỗ lực, tinh tấn, quyết tâm, trì chí. Ðối với các thiện pháp chưa sanh, khởi lên ý muốn khiến cho sanh khởi; vị này nỗ lực, tinh tấn, quyết tâm, trì chí. Ðối với các thiện pháp đã sanh, khởi lên ý muốn khiến cho an trú, không cho băng hoại, khiến cho tăng trưởng, phát triển, viên mãn. Vị này nỗ lực, tinh tấn, quyết tâm, trì chí. Này các Tỷ kheo, như vậy gọi là Chánh tinh tấn.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Này các Tỷ kheo, thế nào là Chánh niệm? Này các Tỷ kheo, ở đây vị Tỷ kheo sống quán thân trên thân, nhiệt tâm, tỉnh giác, chánh niệm, để chế ngự tham ưu ở đời; trên các cảm thọ … trên các tâm … quán pháp trên các pháp, tinh cần tỉnh giác, chánh niệm để chế ngự tham ưu ở đời. Này các Tỷ kheo, như vậy gọi là Chánh niệm.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },

{ text: `Này các Tỷ kheo, thế nào là Chánh định? Này các Tỷ kheo, ở đây Tỷ kheo ly dục, ly ác bất thiện pháp, chứng và trú Thiền thứ nhất, một trạng thái hỷ lạc do ly dục sanh, với tầm, với tứ. Tỷ kheo ấy diệt tầm, diệt tứ, chứng và trú Thiền thứ hai, một trạng thái hỷ lạc do định sanh, không tầm, không tứ, nội tĩnh nhất tâm. Tỷ kheo ấy ly hỷ trú xả, chánh niệm tỉnh giác, thân cảm sự lạc thọ mà các bậc Thánh gọi là xả niệm lạc trú, chứng và trú Thiền thứ ba. Tỷ kheo ấy xả lạc, xả khổ, diệt hỷ ưu đã cảm thọ trước, chứng và trú Thiền thứ tư, không khổ, không lạc, xả niệm thanh tịnh. Này các Tỷ kheo, như vậy gọi là Chánh định.`, ref: "DN 22 – Kinh Ðại Niệm xứ", url: "../dn/dn22.html#content" },
{ text: `Này Bhaggava, Ta biết về khởi nguyên thế giới, Ta còn biết hơn thế nữa. Và khi Ta biết như vậy, Ta không có chấp trước. Vì không chấp trước, Ta tự thân thấu hiểu được sự an tịnh ấy. Chính nhờ chứng ngộ sự an tịnh này mà Như Lai không rơi vào lầm lỗi.`, ref: "DN 24 – Kinh Ba-lê", url: "../dn/dn24.html#content" },

{ text: `Nhưng này Bhaggava, Ta không có nói như vậy: “Khi một ai đạt đến thanh tịnh, giải thoát, khi ấy vị ấy biết mọi vật là bất tịnh.” Này Bhaggava, Ta nói như sau: “Khi một ai đạt đến thanh tịnh, giải thoát, khi ấy vị ấy biết mọi vật là thanh tịnh.”`, ref: "DN 24 – Kinh Ba-lê", url: "../dn/dn24.html#content" },

{ text: `- Này Bhaggava, thật khó cho Ngươi khi Ngươi theo các kiến giải sai khác, kham nhẫn các sự việc sai khác, theo dõi những mục tiêu sai khác, đeo đuổi những mục đích sai khác, được huấn luyện theo các phương pháp sai khác để có thể đạt được thanh tịnh, giải thoát. Này Bhaggava, hãy đặt nặng lòng tin ở nơi Ta, hãy khéo gìn giữ lòng tin tưởng ấy.`, ref: "DN 24 – Kinh Ba-lê", url: "../dn/dn24.html#content" },

{ text: `Bạch Thế Tôn, nếu thật khó cho con, khi con theo các kiến giải sai khác, kham nhẫn các sự việc sai khác, theo dõi những mục tiêu sai khác, đeo đuổi những mục đích sai khác, được huấn luyện theo các phương pháp sai khác, để có thể đạt được thanh tịnh giải thoát, thời Bạch Thế Tôn, ít nhất con cũng đặt nặng lòng tin vào Thế Tôn, và con sẽ khéo gìn giữ lòng tin tưởng ấy.`, ref: "DN 24 – Kinh Ba-lê", url: "../dn/dn24.html#content" },
{ text: `Thật sự khác thay, khi các Tôn giả ngoại đạo, các du sĩ này hội họp lại, quy tụ lại, ồn ào, cao giọng lớn tiếng, họ sống bàn cãi về những phiếm luận vô ích như câu chuyện về vua chúa … câu chuyện về sự hiện hữu và sự không hiện hữu. Thật sai khác thay, Thế Tôn an trú các nhàn tịnh xứ, núi rừng tịch mịch, xa vắng, ít tiếng động, có gió đồng thổi, lánh xa mắt người đời, thích hợp cho sự tịnh tu.`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `Vị ấy lựa một chỗ thanh vắng, tịch mịch, như ngôi rừng, gốc cây, trên khe núi, trong hang đá, bãi tha ma, lùm cây, ngoài trời, hay đống rơm. Sau khi ăn xong đi khất thực về, vị ấy ngồi kiết già, lưng thẳng và an trú chánh niệm trước mặt. Vị ấy từ bỏ tham ái ở đời, an trú với tâm thoát ly tham ái, gột sạch tâm hết tham ái. Từ bỏ sân tâm, an trú với tâm thoát ly sân tâm, khởi lòng thương tưởng mọi loài chúng sanh, gột sạch tâm hết sân hận. Từ bỏ hôn trầm thụy miên, an trú với tâm thoát ly hôn trầm thụy miên, tưởng niệm đến ánh sáng, chánh niệm, tỉnh giác, gột sạch tâm hết hôn trầm thụy miên. Từ bỏ trạo hối, an trú tâm thoát ly trạo hối, nội tâm an tịnh, gột sạch tâm hết trạo hối. Từ bỏ nghi hoặc, an trú với tâm thoát ly nghi ngờ, không còn nghi hoặc, gột sạch tâm không còn nghi ngờ đối với các thiện pháp.`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `Này Nigrodha, Ngươi nghĩ thế nào? Ngươi có bao giờ nghe các vị du sĩ niên cao, trưởng thượng, bậc Tổ sư truyền thống nói như sau: “Các vị A la hán, Chánh Ðẳng Giác trong thời quá khứ, các vị Thế Tôn này khi nào hội họp lại, quy tụ lại, ồn ào, cao giọng, lớn tiếng, chung sống bàn cãi về những phiếm luận vô ích, như câu chuyện về vua chúa, câu chuyện về ăn trộm … câu chuyện về hiện hữu và không hiện hữu, như Ngươi và Sư trưởng của Ngươi hiện nay đang làm? Hay là những bậc Thế Tôn ấy an trú các nhàn tịnh xứ, núi rừng tịch mịch, xa vắng, ít tiếng, ít động, có gió đồng thổi, lánh xa mắt của người đời, thích hợp cho sự tĩnh tu, như hiện Ta đang sống chăng?`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `Này Nigrodha, Ngươi là bậc có trí và niên trưởng, có bao giờ Ngươi suy nghĩ như sau: “Ðức Phật, bậc Giác Ngộ, thuyết giảng giáo pháp đưa đến giác ngộ; Thế Tôn là vị đã điều phục, thuyết giảng giáo pháp đưa đến sự điều phục; Thế Tôn bậc An Chỉ, thuyết giảng giáo pháp đưa đến An Chỉ; Thế Tôn là bậc đến bờ bên kia, thuyết giảng giáo pháp đưa đến bờ bên kia; Thế Tôn bậc Tịnh Lạc, thuyết giảng giáo pháp đưa đến sự tịnh lạc.`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `Và này Nigrodha, có những pháp bất thiện không được từ bỏ, làm cho cấu uế, đưa đến tái sanh, đem lại đau khổ, đưa lại quả khổ, đem lại già, bệnh, chết trong tương lai. Những pháp ấy, Ta thuyết giảng để diệt trừ chúng. Nếu các Ngươi thực hành đúng theo lời giảng dạy, thời các pháp cấu uế của ngươi được trừ diệt, các pháp thanh tịnh được tăng trưởng, và các ngươi sẽ tự chứng biết, chứng ngộ, đạt đến an trú ngay trong hiện tại, trí tuệ cụ túc, viên mãn.`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `Này Nigrodha, Ngươi có thể nghĩ rằng: “Sa môn Gotama nói vậy là muốn có đệ tử.” Này Nigrodha, Ngươi chớ có hiểu như vậy. Bổn sư Ngươi là ai, hãy giữ nguyên vị Bổn sư ấy cho Ngươi. Này Nigrodha, Ngươi có thể nghĩ rằng: “Sa môn Gotama nói vậy là muốn chúng tôi từ bỏ kinh tụng của chúng tôi”. Này Nigrodha, Ngươi chớ có hiểu như vậy. Kinh tụng của Ngươi là gì, hãy giữ nguyên kinh tụng ấy cho Ngươi. Này Nigrodha, Ngươi có thể nghĩ rằng: “Sa môn Gotama nói như vậy là muốn chúng tôi từ bỏ nghề sống của chúng tôi.” Này Nigrodha, chớ có hiểu như vậy. Nghề sống của Ngươi là gì, hãy giữ nguyên nghề sống ấy cho Ngươi.`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `Này Nigrodha, Ta nói vậy không phải vì muốn có đệ tử; Ta nói vậy không phải vì mu khiến các Ngươi từ bỏ kinh tụng, Ta nói vậy không phải vì muốn khiến các Ngươi từ bỏ nghề sống; Ta nói vậy không phải vì muốn xác tín cho các Ngươi đối với các pháp bất thiện mà truyền thống Tổ sư đã xem là bất thiện; Ta nói vậy không phải vì muốn cho các Ngươi từ bỏ những thiện pháp mà truyền thống Tổ sư đã xem là thiện pháp. Và này Nigrodha, có những pháp bất thiện không được từ bỏ, làm cho cấu uế, đưa đến tái sanh, đem lại đau khổ, đưa lại quả khổ, đem lại già, bệnh, chết trong tương lai. Những pháp ấy, Ta thuyết giảng để diệt trừ chúng. Nếu các Ngươi thực hành đúng theo lời giảng dạy, thời các pháp cấu uế của ngươi được trừ diệt, các pháp thanh tịnh được tăng trưởng, và các ngươi sẽ tự chứng biết, chứng ngộ, đạt đến an trú ngay trong hiện tại, trí tuệ cụ túc, viên mãn.`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `- Này Nigrodha, ở đây một vị khổ hạnh siêng tu khổ hạnh. Nhờ tu khổ hạnh này, vị ấy hoan hỷ tâm tư thỏa mãn. Này Nigrodha, vị khổ hạnh do siêng tu khổ hạnh, phát sanh hoan hỷ, tâm tư thỏa mãn. Này Nigrodha, như vậy là cấu uế cho người khổ hạnh.\nLại nữa, này Nigrodha, vị khổ hạnh tu hành khổ hạnh, do khổ hạnh này, vị này khen mình chê người. Này Nigrodha, vị khổ hạnh tu hành khổ hạnh nào, do khổ hạnh ấy khen mình chê người. Này Nigrodha, như vậy là cấu uế cho người khổ hạnh.\nLại nữa, này Nigrodha, vị khổ hạnh tu hành khổ hạnh, do khổ hạnh này trở thành mê say, nhiễm trước, phóng dật. Này Nigrodha, vị tu hành khổ hạnh nào, do khổ hạnh ấy mê say, nhiễm trước, phóng dật. Này Nigrodha, như vậy là cấu uế cho người khổ hạnh.`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `Lại nữa, này Nigrodha, vị khổ hạnh tu hành khổ hạnh. Do khổ hạnh này, được thọ lãnh cúng dường, cung kính, danh vọng. Do được cúng dường, cung kính, danh vọng, trở thành hoan hỷ, tâm tư thỏa mãn. Này Nigrodha, vị khổ hạnh tu hành khổ hạnh nào; do khổ hạnh ấy được thọ lãnh cúng dường, cung kính, danh vọng, trở thành hoan hỷ, tâm tư thỏa mãn. Này Nigrodha, như vậy đó là cấu uế cho người khổ hạnh.`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `Lại nữa, này Nigrodha, người khổ hạnh tu hành khổ hạnh. Do khổ hạnh này, được cúng dường, cung kính, danh vọng. Do được cúng dường, cung kính, danh vọng, nên khen mình chê người. Này Nigrodha, người khổ hạnh tu hành khổ hạnh nào, do khổ hạnh ấy được cúng dường, cung kính, danh vọng. Do được cúng dường, cung kính, danh vọng. Do được cúng dường, cung kính, danh vọng này, nên khen mình chê người. Này Nigrodha, như vậy là cấu uế cho người khổ hạnh.`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `Lại nữa, này Nigrodha, người khổ hạnh tu hành khổ hạnh. Do khổ hạnh này, được cúng dường, cung kính, danh vọng. Do được cúng dường, cung kính, danh vọng, trở thành mê say, chấp trước, phóng dật. Này Nigrodha, người khổ hạnh tu hành khổ hạnh nào, do khổ hạnh ấy được cúng dường, cung kính, danh vọng. Do được cúng dường, cung kính, danh vọng này, trở thành mê say, chấp trước, phóng dật. Này Nigrodha, như vậy là cấu uế cho người khổ hạnh.`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `Lại nữa, này Nigrodha, người khổ hạnh tu hành khổ hạnh, phân biệt các thức ăn: “Món này thích hợp với ta, món này không thích hợp với ta.” Ðối với các thức ăn không thích hợp thì cố ý từ bỏ. Ðối với các thức ăn thích hợp thì nắm giữ, tham đắm, chấp trước, không thấy các sự nguy hiểm, không phân biệt chúng là không giải thoát, thọ hưởng chúng … Này Nigrodha, như vậy là cấu uế cho người khổ hạnh.`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `Lại nữa, này Nigrodha, người khổ hạnh tu hành khổ hạnh, nhân vì mong mỏi được cúng dường cung kính danh vọng, nghĩ rằng: “Các vua chúa sẽ cung kính ta, cũng vậy các vị đại thần, các vị Sát đế lỵ, các vị Bà la môn, các vị Gia chủ, các vị Giáo chủ các giáo phái”. Này Nigrodha, như vậy là cấu uế cho người khổ hạnh.`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `Lại nữa, này Nigrodha, người khổ hạnh chống báng một Sa môn hay Bà la môn khác như sau: “Người này sống ăn uống đủ mọi thứ. Như hạt giống từ rễ sanh, hạt giống từ nhánh cây sanh, hạt giống từ đốt sanh, hạt giống từ chiết cây sanh và thứ năm là hạt giống từ hạt giống sanh, nhai nghiền chúng tất cả với tầm sét không bánh xe được gọi là xương quai hàm và người ta gọi vị ấy là một vị Sa môn. Này Nigrodha, như vậy, là cấu uế cho người khổ hạnh.`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `Lại nữa này Nigrodha, người khổ hạnh thấy một Sa môn hay Bà la môn được các gia đình cung kính, kính trọng, lễ bái, cúng dường. Thấy vậy vị ấy nghĩ rằng: “Các gia đình cung kính, kính trọng, lễ bái, cúng dường người sống ăn uống đủ mọi thứ. Các gia đình ấy không cung kính, kính trọng, lễ bái, cúng dường ta, một người tu khổ hạnh. Do vậy sanh tật đố, ganh ghét đối với các gia đình. Này Nigrodha, như vậy là cấu uế cho người khổ hạnh.`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `Lại nữa, này Nigrodha, người khổ hạnh trở thành người ngồi giữa công chúng. Này Nigrodha, như vậy là cấu uế cho người khổ hạnh. Lại nữa, này Nigrodha, người khổ hạnh, khi đi giữa các gia đình (để khất thực) không cho người ta thấy mình: “Như vậy là khổ hạnh của ta, như vậy là khổ hạnh của ta.”. Này Nigrodha, như vậy là cấu uế cho người khổ hạnh.\nLại nữa, này Nigrodha, người khổ hạnh làm bộ có vẻ bí mật. Khi được hỏi: “Có chấp nhận việc này không?”, tuy không chấp nhận nhưng trả lời: “Có chấp nhận”; tuy chấp nhận, nhưng trả lời: “Không chấp nhận.” Như vậy, vị này cố tình nói láo. Này Nigrodha, như vậy là cấu uế cho người khổ hạnh.`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `Lại nữa, này Nigrodha, người khổ hạnh hay tức giận và ôm lòng oán thù. Này Nigrodha, vì người khổ hạnh hay tức giận và ôm lòng oán thù. Này Nigrodha, như vậy là cấu uế cho người khổ hạnh.\nLại nữa, này Nigrodha, người khổ hạnh thường hay giả dối lừa đảo, tật đố và hà tiện, giảo hoạt và ngụy trá, cứng cỏi và quá mạn, có ác ý và bị ác ý chi phối, có tà kiến và tư tưởng cực đoan, chấp trước kinh nghiệm tự thân, cứng đầu và khó giải thoát. Này Nigrodha, vì một người khổ hạnh chấp trước kinh nghiệm tự thân, cứng đầu và khó giải thoát. Này Nigrodha, như vậy là cấu uế cho người khổ hạnh.`, ref: "DN 25 – Kinh Ưu-đàm-bà-la Sư tử hống", url: "../dn/dn25.html#content" },

{ text: `Này các Tỷ kheo, thế nào là một Tỷ kheo sống tự mình là ngọn đèn cho chính mình, tự mình nương tựa mình, không nương tựa một ai khác, lấy Chánh pháp làm ngọn đèn, nương tựa Chánh pháp, không nương tựa một gì khác? Này các Tỷ kheo, ở đây vị Tỷ kheo sống quán thân trên tự thân, nhiệt tâm, tinh cần, chánh niệm, tỉnh giác, để diệt trừ tham ưu ở đời, trên các cảm thọ … trên các tâm … quán pháp trên các pháp, nhiệt tâm, tinh cần, chánh niệm, tỉnh giác, để có thể diệt trừ tham ưu ở đời. Như vậy này các Tỷ kheo, vị Tỷ kheo sống tự mình là ngọn đèn cho chính mình, tự mình nương tựa mình, không nương tựa một ai khác, lấy Chánh pháp làm ngọn đèn, nương tựa Chánh pháp, không nương tựa một gì khác.`, ref: "DN 26 – Kinh Chuyển luân Thánh vương Sư tử hống", url: "../dn/dn26.html#content" },

{ text: `Này các Tỷ kheo, hãy đi lại trong giới hạn được phép của mình, trong giới hạn Tổ phụ các Ngươi truyền lại. Này các Tỷ kheo, nếu các Ngươi đi lại trong giới hạn được phép của mình, trong giới hạn Tổ phụ các Ngươi truyền lại thời tuổi thọ sẽ được tăng thịnh, sắc đẹp sẽ được tăng thịnh, an lạc sẽ được tăng thịnh, tài sản sẽ được tăng thịnh, thế lực sẽ được tăng thịnh.`, ref: "DN 26 – Kinh Chuyển luân Thánh vương Sư tử hống", url: "../dn/dn26.html#content" },

{ text: `Này các Tỷ kheo, như thế nào vị Tỷ kheo tuổi thọ được tăng thịnh? Này các Tỷ kheo, ở đây, vị Tỷ kheo tu tập thần túc, đầy đủ Dục thiền định tinh cần hành; tu tập thần túc, đầy đủ Tinh tấn thiền định tinh cần hành; tu tập thần túc đầy đủ Tâm định tinh cần hành; tu tập thần túc đầy đủ Tư duy thiền định tinh cần hành. Vị này tu tập bốn pháp thần túc này một cách tinh cần, nếu muốn sống kéo dài một kiếp hay năm còn lại của một kiếp. Này các Tỷ kheo, như vậy Ta nói vị Tỷ kheo tuổi thọ được tăng thịnh.`, ref: "DN 26 – Kinh Chuyển luân Thánh vương Sư tử hống", url: "../dn/dn26.html#content" },

{ text: `Này các Tỷ kheo, thế nào là vị Tỷ kheo sắc đẹp được tăng thịnh? Này các Tỷ kheo, ở đây, vị Tỷ kheo sống giữ giới luật, chế ngự với sự chế ngự của giới bổn Pātimokkha, đầy đủ oai nghi chánh hạnh, thấy nguy hiểm trong những lỗi nhỏ nhặt, thọ lãnh và tu học trong giới pháp. Này các Tỷ kheo, như vậy vị Tỷ kheo sắc đẹp được tăng thịnh.`, ref: "DN 26 – Kinh Chuyển luân Thánh vương Sư tử hống", url: "../dn/dn26.html#content" },

{ text: `Này các Tỷ kheo, thế nào là vị Tỷ kheo an lạc được tăng thịnh? Này các Tỷ kheo, ở đây, vị Tỷ kheo ly dục, ly ác pháp, chứng và trú Thiền thứ nhất, một trạng thái hỷ lạc do ly dục sanh với tầm, với tứ; diệt tầm, diệt tứ, chứng và trú Thiền thứ hai, một trạng thái hỷ lạc do định sanh, không tầm, không tứ … chứng và trú Thiền thứ ba … chứng và trú Thiền thứ tư. Này các Tỷ kheo, như vậy vị Tỷ kheo an lạc được tăng thịnh.`, ref: "DN 26 – Kinh Chuyển luân Thánh vương Sư tử hống", url: "../dn/dn26.html#content" },

{ text: `Này các Tỷ kheo, thế nào là vị Tỷ kheo tài sản được tăng thịnh? Này các Tỷ kheo, ở đây, vị Tỷ kheo an trú, biến mãn một phương với tâm câu hữu với từ, cũng vậy phương thứ hai, cũng vậy phương thứ ba, cũng vậy phương thứ tư. Như vậy cùng khắp thế giới, trên, dưới, bề ngang, hết thảy phương xứ, cùng khắp vô biên giới, vị ấy an trú biến mãn với tâm câu hữu với từ, quảng đại vô biên, không hận, không sân, với tâm câu hữu với bi … với tâm câu hữu với hỷ … Vị ấy an trú biến mãn với tâm câu hữu với xả, quảng đại vô biên, không hận, không sân. Này các Tỷ kheo, như vậy vị Tỷ kheo, tài sản được tăng thịnh.`, ref: "DN 26 – Kinh Chuyển luân Thánh vương Sư tử hống", url: "../dn/dn26.html#content" },

{ text: `Này các Tỷ kheo, như thế nào là vị Tỷ kheo thế lực được tăng thịnh? Này các tỷ kheo, ở đây vị Tỷ kheo, với sự diệt tận các lậu hoặc, tự mình biết và chứng, đạt đến an trú ngay trong hiện tại tâm giải thoát, tuệ giải thoát không còn các lậu hoặc. Này các Tỷ kheo, như vậy là vị Tỷ kheo thế lực được tăng thịnh.\nNày các Tỷ kheo, ta quán sát và thấy không có một uy lực nào khác khó nhiếp phục hơn uy lực của Ma vương. Này các Tỷ kheo, chính nhờ chấp nhận và thực hành những thiện pháp ấy mà công đức này được tăng thịnh!`, ref: "DN 26 – Kinh Chuyển luân Thánh vương Sư tử hống", url: "../dn/dn26.html#content" },

{ text: `Ðối với họ, than đỏ được dập tắt, khói được tiêu tan, cối và chầy rơi ngả nghiêng, buổi chiều lo ăn buổi ăn chiều, buổi sáng lo buổi ăn sáng; họ đi vào làng, vào thị xã, vào kinh đô để khất thực. Khi xin được đồ ăn rồi, họ lại vào các chòi lá trong khu rừng để tu thiền. Này Vāsaṭṭha, họ “Jhāyanti”, tu thiền, tức là họ suy tư Jhàyakà. Jhàyakà là danh từ thứ hai được khởi lên.`, ref: "DN 27 – Kinh Khởi thế nhân bổn", url: "../dn/dn27.html#content" },

{ text: `Các vị ấy loại bỏ các ác, bất thiện pháp, tức là Bràhmanà (Bà-la-môn), và chữ Bràhmanà là danh từ đầu tiên được khởi lên. Những vị này lập lên những chòi bằng lá tại các khu rừng và tu thiền trong những nhà chòi bằng lá ấy. Ðối với họ, than đỏ được dập tắt, khói được tiêu tan, cối và chầy rơi ngả nghiêng, buổi chiều lo buổi ăn chiều, buổi sáng lo buổi ăn sáng; họ đi vào làng, vào thị xã, vào kinh đô để khất thực. Khi họ xin được đồ ăn rồi, họ lại vào các chòi lá trong các khu rừng để tu thiền.`, ref: "DN 27 – Kinh Khởi thế nhân bổn", url: "../dn/dn27.html#content" },
{ text: `Bạch Thế Tôn, lại nữa, điểm này thật là vô thượng: Thế Tôn thuyết pháp về các thiện pháp. Ở đây những thiện pháp là Bốn Niệm xứ, Bốn Chánh cần, Bốn Như ý túc, Năm Căn, Năm Lực, Bảy Giác chi, Thánh đạo tám ngành. Bạch Thế Tôn, ở đây vị Tỷ kheo tận diệt các lậu hoặc, có thể tự mình chứng tri và chứng ngộ, đạt đến và an trú ngay trong hiện tại, Tâm giải thoát và Tuệ giải thoát vô lậu này. Bạch Thế Tôn, thật là vô thượng đối với các thiện pháp. Tất cả điểm này, Thế Tôn đã biết và ngoài sự hiểu biết của Ngài, không có gì còn lại để hiểu biết hơn nữa. Không có một ai, một Sa môn hay một Bà-la-môn nào khác có thể chứng biết hơn Thế Tôn về vấn đề các thiện pháp.`, ref: "DN 28 – Kinh Tự hoan hỷ", url: "../dn/dn28.html#content" },

{ text: `Lại nữa, bạch Thế Tôn, điểm này thật là vô thượng: Thế Tôn thuyết pháp về vấn đề chánh hạnh trong ngôn ngữ. Bạch Thế Tôn, ở đây, một người không những không nói những lời liên hệ đến nói láo, mà cũng phải, trong khi tìm cách thắng cuộc, không dùng lời vu khống, lời ác khẩu và lời ly gián; trái lại, người ấy nói lời từ hòa, sáng suốt, đáng được giữ gìn, và nói đúng thời. Bạch Thế Tôn, như vậy là tối thượng về chánh hạnh trong ngôn ngữ.`, ref: "DN 28 – Kinh Tự hoan hỷ", url: "../dn/dn28.html#content" },

{ text: `Lại nữa, bạch Thế Tôn, điểm này thật là vô thượng: Thế Tôn thuyết pháp về vấn đề giới hạnh của con người. Bạch Thế Tôn, ở đây, có người chân thật, thành tín, không dối trá, không lừa gạt, không gợi ý, không chiêm tướng, không lấy lợi câu lợi; hộ trì các căn, ăn uống tiết độ, hành động ôn hòa, luôn luôn cảnh giác, không chán nản, tinh cần, trầm tư, chánh niệm, ngôn từ lanh lợi, hành vi gan dạ, chịu đựng, biết điều, không tham dục, tỉnh giác, cẩn trọng. Bạch Thế Tôn, như vậy là tối thượng về vấn đề giới hạnh của con người.`, ref: "DN 28 – Kinh Tự hoan hỷ", url: "../dn/dn28.html#content" },

{ text: `Bạch Thế Tôn, những gì có thể đạt được bởi một thiện nam tử có lòng tin, có tinh tấn, có kiên trì bởi sự kiên trì của con người, bởi sự tinh tấn của con người, bởi sự tiến bộ của con người, bởi sự nhẫn nhục của con người, đều được Thế Tôn chứng đạt. Bạch Thế Tôn, Thế Tôn không có đam mê các dục lạc, dục lạc này là đê tiện, hèn hạ, thuộc phàm phu, không xứng bậc Thánh, không có lợi ích. Thế Tôn cũng không đam mê tu hành khổ hạnh, khổ hạnh này là khổ, không xứng bậc Thánh, không có lợi ích. Thế Tôn có thể đạt được nếu Ngài muốn, một cách dễ dàng, một cách đầy đủ, sự hạnh phúc ngay trong hiện tại, do bốn Thiền định đem lại.`, ref: "DN 28 – Kinh Tự hoan hỷ", url: "../dn/dn28.html#content" },
{ text: `Do vậy, này Cunda, những pháp do Ta tự chứng tri và tuyên bố cho các Ngươi, tất cả các Ngươi hãy hội họp lại và tụng đọc lại, chớ có cãi lộn nhau, nhưng hãy so sánh các nghĩa với nhau, các câu với nhau để cho phạm hạnh này được tồn tại lâu dài, được an trú lâu dài, vì hạnh phúc cho muôn loài, vì an lạc cho muôn loài, vì lòng thương tưởng cho đời, vì lợi ích, vì an lạc cho chư Thiên và cho loài Người. Những pháp ấy là Bốn Niệm xứ, Bốn Chánh cần, Bốn Như ý túc, Năm Căn, Năm Lực, Bảy Giác chi, Tám Thánh đạo.`, ref: "DN 29 – Kinh Thanh Tịnh", url: "../dn/dn29.html#content" },

{ text: `Này Cunda, các Ngươi hãy hội họp với nhau trong tinh thần hòa đồng và tương kính, không có tranh luận nhau. Có vị đồng phạm hạnh nói pháp giữa Tăng chúng. Nếu các Ngươi nghĩ rằng “Vị Ðại đức này nắm nghĩa sai lạc hay hành văn sai lạc”, các Ngươi không nên tán thán, không nên bác bỏ, các Ngươi phải giải thích cho vị ấy một cách cẩn thận cả nghĩa lẫn hành văn.`, ref: "DN 29 – Kinh Thanh Tịnh", url: "../dn/dn29.html#content" },

{ text: `Này Cunda, các Ngươi hãy hội họp với nhau trong tinh thần hòa đồng và tương kính, không có tranh luận nhau. Này Cunda, có vị đồng phạm hạnh khác nói pháp giữa Tăng chúng. Nếu các Ngươi nghĩ rằng: “Vị Ðại đức ấy nắm nghĩa sai lạc nhưng hành văn đúng đắn”, các Ngươi không nên tán thán, không nên bác bỏ. Không thán thán, không bác bỏ, các ngươi nên nói với vị ấy: “Này Hiền giả, giữa những cách hành văn này, nghĩa này hay nghĩa kia, nghĩa nào thích hợp hơn?” Nếu vị ấy trả lời: “Này Hiền giả, giữa những cách hành văn này, nghĩa này thích hợp hơn nghĩa kia”, các Ngươi không nên bác bỏ, không phỉ báng, các Ngươi phải giải thích một cách cẩn thận ý nghĩa đúng đắn cho vị ấy.`, ref: "DN 29 – Kinh Thanh Tịnh", url: "../dn/dn29.html#content" },

{ text: `Này Cunda Ta không thuyết giảng chỉ để ngăn chận các lậu hoặc ngay trong hiện tại. Này Cunda, Ta không thuyết pháp, chỉ để diệt trừ các lậu hoặc trong tương lai mà thôi. Này Cunda, Ta thuyết pháp vừa để ngăn chận các lậu hoặc ngay trong hiện tại mà cũng để diệt trừ các lậu hoặc trong tương lai nữa.`, ref: "DN 29 – Kinh Thanh Tịnh", url: "../dn/dn29.html#content" },

{ text: `Do vậy, này Cunda, tấm y mà Ta cho phép các Ngươi mặc, như vậy vừa đủ cho các Ngươi ngăn chận lạnh, ngăn chận nóng, ngăn chận sự xúc chạm của các loài ruồi muỗi, của gió, mặt trời và các loài rắn, và các che dấu sự hổ thẹn.\nCác món ăn khất thực mà Ta cho phép các Ngươi dùng, như vậy vừa đủ để nuôi dưỡng thân thể, giúp thân thể sống còn, tránh khỏi nguy hại và giúp đời sống phạm hạnh với hy vọng: “Như vậy ta diệt trừ các cảm thọ cũ và không cho khởi lên các cảm thọ mới. Nhờ vậy đời sống của ta mới khỏi bị lầm lỗi và ta sống an lạc.”`, ref: "DN 29 – Kinh Thanh Tịnh", url: "../dn/dn29.html#content" },

{ text: `Nhà cửa nào mà Ta cho phép các ngươi an trú, như vậy vừa đủ cho các Ngươi ngăn chận lạnh, ngăn chận nóng, ngăn chận sự xúc chạm của ruồi muỗi, gió, mặt trời và các loài rắn, chỉ với mục đích tránh thoát sự nguy hiểm của thời tiết, và an hưởng đời sống tịnh cư.\nCác dược phẩm và thuốc trị bịnh mà Ta cho phép các Ngươi dùng, như vậy vừa đủ để ngăn chận các cảm thọ đau ốm khởi lên và để gìn giữ sức khỏe.`, ref: "DN 29 – Kinh Thanh Tịnh", url: "../dn/dn29.html#content" },

{ text: `Này Cunda, ở đây có người ngu si, sau khi sát sanh, tự mình sung sướng hoan hỷ, đó là hỷ lạc thứ nhất. Lại nữa, này Cunda, ở đây có người sau khi lấy của không cho, tự mình sung sướng, hoan hỷ, đó là hỷ lạc thứ hai. Lại nữa, này Cunda, ở đây có người sau khi nói láo, tự mình sung sướng, hoan hỷ, đó là hỷ lạc thứ ba. Lại nữa này Cunda, ở đây có người say đắm, đam mê sống vây quanh với năm món dục lạc, đó là hỷ lạc thứ tư. Này Cunda, bốn loại hỷ lạc này là thấp kém, hạ liệt, thuộc phàm phu, không xứng Thánh hạnh, không có lợi ích, không hướng đến yểm ly, vô tham, tịch diệt, an tịnh, thắng trí, giác ngộ và Niết-bàn. Này Cunda, sự kiện này có thể xảy ra. Các du sĩ ngoại đạo có thể nói: “Các vị Sa-môn Thích tử đang sống đam mê bốn loại hỷ lạc này”. Họ cần phải được trả lời: “Nói như vậy là không phải; các ông nói như vậy là không đúng đắn. Nói như vậy là các ông xuyên tạc, không đúng sự thật, không thực có”.`, ref: "DN 29 – Kinh Thanh Tịnh", url: "../dn/dn29.html#content" },

{ text: `Này Cunda, có bốn loại hỷ lạc này. Thế nào là bốn? Này Cunda, ở đây vị Tỷ-kheo, ly dục, ly ác pháp, chứng và an trú Sơ thiền, một trạng thái hỷ lạc do ly dục sanh, với tầm, với tứ. Ðó là hỷ lạc thứ nhất. Lại nữa này Cunda, vị Tỷ-kheo diệt tầm và tứ, chứng và trú Thiền thứ hai, một trạng thái hỷ lạc do định sanh, không tầm không tứ, nội tĩnh nhất tâm. Ðó là hỷ lạc thứ hai. Lại nữa này Cunda, vị Tỷ-kheo ly hỷ trú xả … chứng và trú Thiền thứ ba … Ðó là hỷ lạc thứ ba. Lại nữa này Cunda, vị Tỷ-kheo xả lạc, xả khổ … chứng và trú Thiền thứ tư … Ðó là hỷ lạc thứ tư. Này Cunda, bốn loại hỷ lạc nhất định đưa đến yểm ly, vô tham, tịch diệt, an tịnh, thắng trí, giác ngộ, Niết-bàn. Này Cunda, sự kiện này có thể xảy ra. Các du sĩ ngoại đạo có thể nói: “Các vị Sa-môn Thích tử đang sống đam mê bốn loại hỷ lạc này”. Họ cần phải được trả lời: “Nói như vậy là phải; các ông nói như vậy là nói đúng đắn. Nói như vậy là các ông không xuyên tạc, đúng sự thật, và thực có”.`, ref: "DN 29 – Kinh Thanh Tịnh", url: "../dn/dn29.html#content" },

{ text: `Này Cunda, sự kiện này có thể xảy ra. Các du sĩ ngoại đạo có thể nói: “Các Sa-môn Thích tử sống không giữ vững lập trường”. Này Cunda, các vị du sĩ ngoại đạo nói vậy cần phải được trả lời như sau: “Này Hiền giả, Thế Tôn, vị đã biết, đã thấy, là bậc A-la-hán, Chánh Ðẳng Giác đã thuyết, đã trình bày những pháp cho các đệ tử cho đến trọn đời. Này Hiền giả, giống như cột trụ bằng đá hay bằng sắt, chân cột được khéo chôn sâu vào đất, không lắc qua lại, không có rung động. Cũng vậy này Hiền giả, Thế Tôn, vị đã biết, đã thấy là bậc A-la-hán, Chánh Ðẳng Giác đã thuyết, đã trình bày những pháp cho các đệ tử cho đến trọn đời. Này Hiền giả, giống như cột trụ bằng đá hay bằng sắt, chân cột được khéo chôn sâu vào đất, không lắc qua lại, không có rung động. Cũng vậy này Hiền giả, Thế Tôn, vị đã biết, đã thấy là bậc A-la-hán, Chánh Ðẳng Giác đã thuyết, đã trình bày những pháp cho các đệ tử cho đến trọn đời.`, ref: "DN 29 – Kinh Thanh Tịnh", url: "../dn/dn29.html#content" },

{ text: `Này Hiền giả, vị Tỷ-kheo là bậc A-la-hán, đã diệt trừ các lậu hoặc, phạm hạnh đã thành, các việc phải làm đã làm, đã đặt gánh nặng xuống, mục tiêu đã đạt, hữu kiết sử đã diệt trừ, chánh trí giải thoát, không thể làm chín việc sau đây: Này Hiền giả, vị Tỷ-kheo đã diệt trừ các lậu hoặc, không thể cố ý tước đoạt sanh mạng của loài hữu tình; vị Tỷ-kheo đã diệt trừ các lậu hoặc không thể lấy của không cho, tức là ăn trộm; vị Tỷ kheo đã diệt trừ các lậu hoặc không thể hành dâm; vị Tỷ-kheo đã diệt trừ các lậu hoặc, không thể biết mà nói láo; vị Tỷ-kheo đã diệt trừ các lậu hoặc không thể cất chứa tiền của để hưởng thọ dục lạc, như khi còn tại gia; vị Tỷ-kheo đã diệt tận các lậu hoặc không thể đi con đường hành tham; vị Tỷ-kheo đã diệt tận các lậu hoặc không thể đi con đường hành sân; vị Tỷ-kheo đã diệt tận các lậu hoặc, không thể đi con đường hành si; vị Tỷ-kheo đã diệt tận các lậu hoặc, không thể đi con đường hành theo sợ hãi. Này Hiền giả, một vị Tỷ-kheo, là bậc A-la-hán, Chánh Ðẳng Giác, đã diệt tận các lậu hoặc, phạm hạnh đã thành, các việc phải làm đã làm, đã đặt gánh nặng xuống, mục tiêu đã đạt, hữu kiết sử đã diệt trừ, chánh trí giải thoát, không thể làm chín việc như vậy”.`, ref: "DN 29 – Kinh Thanh Tịnh", url: "../dn/dn29.html#content" },

{ text: `Này Cunda, sự kiện này có thể xảy ra. Các du sĩ ngoại đạo có thể nói như sau: “Ðối với quá khứ, Sa-môn Gotama có tri kiến siêu việt. Nhưng đối với tương lai, Sa-môn Gotama không có tri kiến siêu việt; như sự việc xảy ra như thế nào và vì sao lại xảy ra như vậy?” Như vậy, các vị du sĩ ngoại đạo này chủ trương rằng tri kiến về vấn đề này có thể được trình bày nêu rõ bởi tri kiến một vấn đề khác, như những kẻ ngu si, không thông minh khác. Này Cunda, về vấn đề quá khứ, Như Lai có thể nhớ đến đời sống quá khứ. Ngài muốn như thế nào, Ngài có thể nhớ xa được như vậy. Về vấn đề vị lai, Như Lai có trí do tuệ sanh: “Ðây là đời sống cuối cùng, nay không còn đời sống nào khác nữa”.`, ref: "DN 29 – Kinh Thanh Tịnh", url: "../dn/dn29.html#content" },

{ text: `Này Cunda, nếu những gì thuộc quá khứ, vị lai, hay hiện tại là hư vọng, không thật, không lợi ích, Như Lai không trả lời. Này Cunda, nếu những gì thuộc quá khứ, vị lai, hay hiện tại là chơn chánh, như thật, nhưng không lợi ích, Như Lai cũng không trả lời. Này Cunda, nếu những gì thuộc quá khứ, vị lai, hay hiện tại là chơn chánh, như thật, có lợi ích, Như Lai biết thời trả lời câu hỏi ấy. Như vậy, này Cunda, đối với các pháp quá khứ, vị lai, hiện tại, Như Lai là vị nói phải thời nói chơn chánh, nói như thật, nói có lợi ích, nói đúng Pháp, nói đúng Luật. Do vậy mới gọi là Như Lai.`, ref: "DN 29 – Kinh Thanh Tịnh", url: "../dn/dn29.html#content" },

{ text: `Này Cunda, trong thế giới này với chư Thiên, Ma vương, Phạm thiên, với chúng Sa-môn và Bà-la-môn, với chư Thiên và loài Người, những gì được thấy, được nghe, được cảm giác, được phân biệt, được đạt đến, được tìm cầu, được suy đạt với ý, tất cả đều được Như Lai biết rõ. Do vậy mới gọi là Như Lai. Này Cunda, trong thời gian giữa đêm Như Lai chứng ngộ Vô thượng Chánh Ðẳng Giác và đêm Như Lai nhập Vô dư y Niết-bàn giới, trong thời gian ấy, những gì Như Lai nói trong khi thuyết giảng, nói chuyện hay trình bày, tất cả là như vậy, chớ không gì khác. Do vậy mới gọi là Như Lai. Này Cunda, Như Lai nói gì thời làm vậy, làm gì thời nói vậy. Nói gì thời làm vậy, làm gì thời nói vậy nên được gọi là Như Lai. Ðối với thế giới với chư Thiên, Ma vương, Phạm thiên, với chúng Sa-môn và Bà-la-môn, với chư Thiên và loài Người, Như Lai là bậc Toàn Thắng, không ai có thể thắng nổi, bậc Toàn kiến, bậc Tự Tại.`, ref: "DN 29 – Kinh Thanh Tịnh", url: "../dn/dn29.html#content" },

{ text: `Này Cunda, sự kiện này có thể xảy ra. Các du sĩ ngoại đạo có thể nói: “Này Hiền giả, vì sao Sa môn Gotama lại không nói?” Này Cunda, được nói vậy, Ngươi phải trả lời các du sĩ ngoại đạo như sau: “Này Hiền giả, vì không liên hệ đến lợi ích, không liên hệ đến Pháp, không liên hệ đến căn bản phạm hạnh, không hướng đến yểm ly, vô tham, đoạn diệt, an tịnh, thắng trí, giác ngộ và Niết bàn. Do vậy Thế Tôn không trả lời.”`, ref: "DN 29 – Kinh Thanh Tịnh", url: "../dn/dn29.html#content" },

{ text: `Này Cunda, sự kiện này có thể xảy ra. Các du sĩ ngoại đạo có thể nói: “Này Hiền giả, Sa môn Gotama nói điều gì?” Này Cunda, được nói vậy, Ngươi phải trả lời các du sĩ ngoại đạo như sau: “Ðây là Khổ, này Hiền giả, đó là điều Thế Tôn nói. Ðây là Khổ tập, này Hiền giả, đó là điều Thế Tôn nói. Ðây là Khổ diệt, này Hiền giả, đó là điều Thế Tôn nói. Ðây là con đường đưa đến Khổ diệt, này Hiền giả, đó là điều Thế Tôn nói.”\nNày Cunda, sự kiện này có thể xảy ra. Các du sĩ ngoại đạo có thể nói: “Này Hiền giả, vì sao Thế Tôn lại nói vậy?” Này Cunda, được nói như vậy, Ngươi phải trả lời cho các du sĩ ngoại đạo như sau: “Này Hiền giả, vì liên hệ đến lợi ích, liên hệ đến Pháp, liên hệ đến căn bản phạm hạnh, vì nhất định hướng đến yểm ly, vô tham, đoạn diệt, an tịnh, thắng trí, giác ngộ và Niết bàn. Do vậy, Thế Tôn mới nói.”`, ref: "DN 29 – Kinh Thanh Tịnh", url: "../dn/dn29.html#content" },
{ text: `Này Gia chủ tử, quen thói lười biếng có sáu nguy hiểm: “quá lạnh”, không làm việc; “quá nóng”, không làm việc; “quá trễ” không làm việc; “quá sớm”, không làm việc; “tôi đói quá”, không làm việc; “tôi quá no”, không làm việc. Trong khi những công việc phải làm lại không làm. Tài sản chưa có không xây dựng lên, tài sản có rồi bị tiêu thất. Này Gia chủ tử, quen thói lười biếng có sáu nguy hiểm như vậy. Thế Tôn thuyết giảng như vậy.`, ref: "DN 31 – Kinh Giáo Thọ Thi-ca-la-việt", url: "../dn/dn31.html#content" },

{ text: `Này các Hiền giả, Như Lai thanh tịnh thiện hành về thân. Như Lai không có ác về thân mà Như Lai phải gìn giữ: “Chớ để người khác biết việc này về Ta”. Này các Hiền giả, Như Lai thanh tịnh thiện hành về miệng. Như Lai không có ác hạnh về miệng mà Như Lai phải gìn giữ: “Chớ để người khác biết việc này về Ta”. Này các Hiền giả, Như Lai thanh tịnh thiện hành về ý. Như Lai không có ác hạnh về ý mà Như Lai phải gìn giữ: “Chớ để người khác biết việc này về Ta”.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Bốn chánh cần: Ở đây, này các Hiền giả vị Tỷ-kheo, với mục đích khiến cho các ác, bất thiện pháp từ trước chưa sanh không cho sanh khởi, khởi lên ý muốn, cố gắng, tinh tấn, sách tâm, trì tâm. Với mục đích khiến cho các ác bất thiện pháp đã sanh ra được trừ diệt, khởi lên ý muốn, cố gắng, tinh tấn, sách tâm, trì tâm. Với mục đích khiến cho các thiện pháp từ trước chưa sanh nay cho sanh khởi, khởi lên ý muốn, cố gắng, tinh tấn, sách tâm, trì tâm. Với mục đích khiến cho các thiện pháp đã được sanh có thể duy trì, không có mù mờ, được tăng cường, được quảng đại, được tu tập, được viên mãn, khởi lên ý muốn, cố gắng, tinh tấn, sách tâm, trì tâm.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, thế nào là sự tu tập thiền định, nhờ tu tập, nhờ hành trì nhiều lần đưa đến lạc trú ngay trong hiện tại? Ở đây, này các Hiền giả, có vị Tỷ-kheo ly dục, ly ác pháp, và trú thiền thứ nhất … thiền thứ hai … thiền thứ ba … chứng và trú thiền thứ tư. Này các Hiền giả, như vậy là sự tu tập thiền định, nhờ tu tập, nhờ hành trì nhiều lần đưa đến lạc trú ngay trong hiện tại.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, thế nào là sự tu tập thiền định, nhờ tu tập, nhờ hành trì nhiều lần đưa đến chứng đắc tri kiến? Này các Hiền giả, ở đây, vị Tỷ-kheo, tác ý quang minh tưởng, an trú tưởng ban ngày, ban ngày thế nào ban đêm như vậy, ban đêm thế nào ban ngày như vậy. Và như vậy với tâm mở rộng không có đóng kín, tạo ra một tâm có hào quang. Này các Hiền giả, như vậy là tu tập thiền định, nhờ tu tập, nhờ hành trì nhiều lần, đưa đến chứng đắc tri kiến.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, thế nào là sự tu tập thiền định, nhờ tu tập, nhờ hành trì nhiều lần, hướng đến chánh niệm, tỉnh giác? Này các Hiền giả, ở đây, vị Tỷ-kheo biết được thọ khởi, biết được thọ trú, biết được thọ diệt, biết được tưởng khởi, biết được tưởng trú, biết được tưởng diệt, biết được tầm khởi, biết được tầm trú, biết được tầm diệt. Này các Hiền giả, như vậy là sự tu tập thiền định, nhờ tu tập, nhờ hành trì nhiều lần, đưa đến chánh niệm tỉnh giác.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, thế nào là sự tu tập thiền định, nhờ tu tập, nhờ hành trì nhiều lần, đưa đến sự diệt tận các lậu hoặc? Này các Hiền giả, ở đây vị Tỷ-kheo an trú, quán tánh sanh diệt trên Năm Thủ uẩn—Ðây là sắc, đây là sắc tập, đây là sắc diệt. Ðây là thọ … Ðây là tưởng … Ðây là hành … Ðây là thức, đây là thức tập, đây là thức diệt. Này các Tỷ-kheo, như vậy là sự tu tập thiền định, nhờ tu tập, nhờ hành trì nhiều lần, đưa đến sự diệt tận các lậu hoặc.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, lại nữa, vị Tỷ-kheo tự bằng lòng với bất cứ phòng xá nào, tán thán sự bằng lòng với bất cứ phòng xá nào, không cố gắng tìm cầu phòng xá một cách không xứng đáng, không có áo não nếu không được trú xứ. Nhưng khi được phòng xá, vị này không nhiễm trước, không say mê, không có phạm tội. Vị này dùng các phòng xá, thấy các nguy hiểm và biết rõ sự giải thoát. Vì tự bằng lòng với bất cứ phòng xá nào, vị này không khen mình chê người. Ở đây, vị này khéo léo, tinh cần, tỉnh giác, chánh niệm. Này các Hiền giả, vị Tỷ-kheo ấy được gọi là một vị đã trung thành với Thánh chủng, theo truyền thống quá khứ.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, lại nữa, vị Tỷ-kheo ưa thích đoạn trừ, hoan hỷ đoạn trừ, ưa thích tu tập, hoan hỷ tu tập. Nhờ ưa thích đoạn trừ, hoan hỷ đoạn trừ, ưa thích tu tập, hoan hỷ tu tập nên không khen mình chê người. Ở đây, vị Tỷ-kheo này khéo léo, tinh cần, tỉnh giác, chánh niệm. Này các Hiền giả, vị ấy được gọi là một vị đã trung thành với Thánh chủng, theo truyền thống quá khứ.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, thế nào là đoạn trừ tinh cần? Này các Hiền giả, ở đây, vị Tỷ-kheo không chấp nhận dục tầm đã khởi lên, từ bỏ, đoạn trừ, tiêu diệt, không cho hiện hữu; không chấp nhận sân tầm đã khởi lên … không chấp nhận hại tầm đã khởi lên, từ bỏ, đoạn trừ, tiêu diệt, không cho hiện hữu. Này các Hiền giả, như vậy gọi là đoạn trừ tinh cần.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Vị ấy thành tựu giới đức được các bậc Thánh ái mộ, không bị hư hoại, không bị tỳ vết, được thực hành liên tục, không bị khiếm khuyết khiến con người tự tại, được bậc Thánh tán thán, không bị nhiễm ô, hướng đến thiền định.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, do nhân y phục, vị Tỷ-kheo khởi lên lòng tham ái. Này các Hiền giả, do nhân đồ ăn khất thực, vị Tỷ-kheo khởi lên lòng tham ái. Này các Hiền giả, do nhân phòng xá, vị Tỷ-kheo khởi lên lòng tham ái. Này các Hiền giả, do nhân hữu và phi hữu, vị Tỷ-kheo khởi lên lòng tham ái.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, một vị Lậu tận Tỷ kheo không thể cố sát hại đời sống loài hữu tình. Một vị Lậu tận Tỷ kheo không thể cố ý lấy của không cho gọi là trộm cắp. Một vị Lậu tận Tỷ kheo không thể cố ý hành dâm. Một vị Lậu tận Tỷ kheo không thể cố ý tự mình biết mà nói láo. Một vị Lậu tận Tỷ kheo không thể tiêu dùng các vật chứa cất vào các thú vui dục lạc như khi còn là cư sĩ.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, năm pháp nội tâm một vị Tỷ kheo cần phải có nếu muốn chỉ trích một vị khác: “Tôi nói đúng thời, không phải phi thời. Tôi nói đúng sự thật, không sai sự thật. Tôi nói một cách từ tốn, không nói lời ác khẩu. Tôi nói lời có lợi ích, không nói lời không có lợi ích. Tôi nói lời có lòng từ, không phải lời sân hận”. Này các Hiền giả, như vậy là năm pháp nội tâm một vị Tỷ kheo cần phải có, nếu muốn chỉ trích một vị khác.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, ở đây vị Tỷ kheo có lòng tin, tin tưởng sự giác ngộ của Như Lai. Vị ấy thiểu bệnh, thiểu não, sự tiêu hóa được điều hòa, không lạnh quá, không nóng quá, trung bình hợp với sự tinh tấn. Vị ấy không lường đảo, dối gạt, nêu rõ tự mình như chơn đối với bậc Ðạo Sư, đối với các vị sáng suốt hay đối với các vị đồng phạm hạnh. Vị ấy sống siêng năng, tinh tấn, từ bỏ các ác pháp, thành tựu các thiện pháp, cương quyết, kiên trì nỗ lực, không tránh né đối với các thiện pháp. Vị ấy có trí tuệ, thành tựu trí tuệ hướng đến sự sanh diệt của các pháp, thành tựu Thánh quyết trạch, đưa đến sự đoạn diệt chơn chánh các khổ đau.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, lại nữa, vị Tỷ kheo, khi những giới luật của vị này không bị phá hoại, không vi phạm, được kiên trì tuân hành, không có tỳ vết, làm con người được giải thoát, được người trí tán thán, không uế tạp, hướng đến thiền định, vị Tỷ kheo ấy giữ giới hạnh Sa môn như vậy, sống trước mặt hay sau lưng với các vị đồng phạm hạnh như vậy là một pháp hòa kính, tạo ra từ ái, tạo ra cung kính, đưa đến đoàn kết, không tranh luận, hòa hợp, đồng tâm, ý hợp.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, lại nữa, vị Tỷ kheo, đối với các đồ vật được cúng dường một cách hợp pháp cho đến đồ vật nhận trong bình bát, đều đem chia đồng đều giữa các vị Tỷ kheo có giới hạnh, như vậy là một pháp hòa kính, tạo ra từ ái, tạo ra cung kính, đưa đến đoàn kết, không tranh luận, hòa hợp, đồng tâm, ý hợp.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, lại nữa khi vị Tỷ kheo thành tựu từ ý nghiệp trước mặt hay sau lưng, đối với các vị đồng phạm hạnh, như vậy là một pháp hòa kính, tạo ra từ ái, tạo ra cung kính, đưa đến đoàn kết, không tranh luận, hòa hợp, đồng tâm, ý hợp.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, ở đây có việc vị Tỷ kheo phải làm. Vị này nghĩ: “Có công việc ta sẽ phải làm. Nếu ta làm việc, thời thân ta sẽ mệt mỏi. Vậy ta nên nằm xuống”. Vị ấy nằm xuống, không có tinh tấn để đạt được điều chưa đạt được, để thành tựu điều chưa thành tựu, để chứng ngộ điều chưa chứng ngộ được, như vậy là giải đãi sự thứ nhất.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, lại nữa, vị Tỷ kheo bị đau bệnh nhẹ. Vị này nghĩ: “Nay ta bị đau bệnh nhẹ, cần phải nằm nghỉ. Vậy ta nên nằm xuống”. Vị ấy nằm xuống, không có tinh tấn để đạt được điều chưa đạt được, để thành tựu điều chưa thành tựu, để chứng ngộ điều chưa chứng ngộ được, như vậy là giải đãi sự thứ bảy.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, lại nữa, vị Tỷ kheo mới đau bệnh dậy, mới khỏi bệnh không bao lâu. Vị ấy nghĩ: “Ta mới đau bệnh dậy, mới khỏi bệnh không bao lâu. Thân này của ta yếu đuối, không làm được việc gì, vậy ta hãy nằm xuống”. Vị ấy nằm xuống, không có tinh tấn để đạt được điều chưa đạt được, để thành tựu điều chưa thành tựu được, để chứng ngộ điều chưa chứng ngộ được. Như vậy là giải đãi sự thứ tám.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, lại nữa, vị Tỷ kheo bị đau bệnh nhẹ. Vị ấy nghĩ: “Ta nay bị đau bệnh nhẹ, sự kiện này có thể xảy ra, bệnh này có thể trầm trọng hơn. Vậy ta hãy cố gắng tinh tấn để đạt được điều gì chưa đạt được, thành tựu điều gì chưa thành tựu được, chứng ngộ điều gì chưa chứng ngộ được”. Và vị ấy tinh tấn để đạt được điều gì chưa đạt được, thành tựu điều gì chưa thành tựu được, và chứng ngộ điều gì chưa chứng ngộ được. Ðó là tinh tấn sự thứ bảy.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, lại nữa, vị Tỷ kheo nghe nhiều, gìn giữ những gì đã nghe, chất chứa những gì đã nghe, Những pháp ấy, sơ thiện, trung thiện, hậu thiện, nghĩa lý văn cú cụ túc, đề cao đời sống phạm hạnh, hoàn toàn đầy đủ thanh tịnh những pháp ấy, vị đã nghe nhiều, đã nắm giữ, đã ghi nhớ nhờ tụng đọc nhiều lần, chuyên ý quán sát, khéo thành tựu nhờ chánh kiến.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, lại nữa, vị Tỷ kheo là thiện hữu, thiện bạn lữ, là thiện bạn đảng, là hộ trì nhân. Này các Hiền giả, vị Tỷ kheo nào là thiện hữu, là thiện bạn lữ, là thiện bạn đảng. Pháp như vậy là hộ trì nhân.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, lại nữa vị Tỷ kheo thiện ngôn, đầy đủ sự nhu hòa và khiêm nhường, nhẫn nại và nhận sự chỉ trích một cách cung kính. Này các Hiền giả, vị Tỷ kheo nào thiện ngôn … nhận sự chỉ trích một cách cung kính. Pháp như vậy là hộ trì nhân.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, khi nào có những trách nhiệm cần phải làm đối với các vị đồng phạm hạnh niên lạp cao hơn, vị ấy khéo léo, không có biếng nhác, suy tư một cách đầy đủ các phương tiện, vừa đủ để làm, vừa đủ để tổ chức. Này các Hiền giả, một vị Tỷ kheo nào, đối với các vị đồng phạm hạnh … vừa đủ để tổ chức. Pháp như vậy là hộ trì nhân.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, lại nữa có vị Tỷ kheo ưa Pháp, ái luyến nói Pháp, tự mình vô cùng hoan hỷ đối với Thắng pháp, Thắng luật. Này các Hiền giả, vị Tỷ kheo nào ưa Pháp … vô cùng hoan hỷ đối với Thắng pháp, Thắng luật. Pháp như vậy là hộ trì nhân.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, lại nữa, vị Tỷ kheo tự mình bằng lòng với các vật dụng nhận được như y phục, ẩm thực, sàng tọa, bệnh dược. Này các Hiền giả, vị Tỷ kheo nào tự bằng lòng … Pháp như vậy là hộ trì nhân.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, lại nữa vị Tỷ kheo sống tinh tấn siêng năng đoạn trừ các ác pháp, thành tựu các thiện pháp, cương quyết, kiên trì tinh tấn, nhẫn trì không phế bỏ các thiện pháp. Này các Hiền giả, một vị Tỷ kheo nào sống tinh tấn siêng năng … nhẫn trì không phế bỏ các thiện pháp. Pháp như vậy là hộ trì nhân.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, lại nữa, vị Tỷ kheo chánh niệm, đầy đủ tối thượng niệm và tỉnh giác, nhớ đến và ghi nhớ những điều nói và làm từ lâu. Này các Hiền giả, vị Tỷ kheo nào có chánh niệm, ghi nhớ những điều đã nói và làm từ lâu. Pháp như vậy là hộ trì nhân.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Này các Hiền giả, lại nữa, vị Tỷ kheo có huệ trí, đầy đủ sanh diệt trí, hướng đến sự quyết trạch các bậc Thánh, chơn chánh diệt trừ mọi đau khổ. Này các Hiền giả, vị Tỷ kheo nào có huệ trí … chơn chánh diệt trừ mọi đau khổ. Pháp như vậy là hộ trì nhân.`, ref: "DN 33 – Kinh Phúng Tụng", url: "../dn/dn33.html#content" },

{ text: `Tám Suy Nghĩ của bậc Đại Nhân: Pháp này cho người thiểu dục, pháp này không phải cho người đa dục; pháp này cho người tri túc, pháp này không phải cho người không tri túc; pháp này cho người an tịnh độc cư, pháp này không phải cho người ưa tụ hội; pháp này cho người siêng năng tinh tấn, pháp này không phải cho người giải đãi; pháp này cho người có niệm hiền tiền, pháp này không phải cho người thất niệm; pháp này là cho người có định tâm, pháp này không phải cho người không có định tâm; pháp này cho người có trí tuệ, pháp này không phải cho người có ác tuệ; pháp này cho người không ưa thích lý luận, pháp này không phải cho người ưa thích lý luận. Như vậy là tám pháp cần được sanh khởi.`, ref: "DN 34 – Kinh Thập Thượng", url: "../dn/dn34.html#content" },

            ],
            mn: [
             { text: `Này các Tỷ-kheo, Như Lai là bậc A-la-hán, Chánh Ðẳng Giác, thắng tri địa đại là địa đại. Vì thắng tri địa đại là địa đại, Như Lai không nghĩ đến địa đại, không nghĩ đến (tự ngã) đối chiếu với địa đại, không nghĩ đến (tự ngã) như là địa đại, không nghĩ: “Ðịa đại là của ta” —không dục hỷ địa đại. Vì sao vậy? Vì Như Lai biết rằng: “Dục hỷ là căn bản của đau khổ, từ hữu, sanh khởi lên, và già và chết đến với loài sinh vật”. Do vậy, này các Tỷ-kheo, Ta nói vì Như Lai, với sự diệt trừ hoàn toàn các ái, sự ly tham, sự đoạn diệt, sự xả ly, sự từ bỏ hoàn toàn các ái, đã chơn chánh giác ngộ vô thượng chánh đẳng chánh giác.`, ref: "MN 1 – Kinh Pháp Môn Căn Bản", url: "../mn/mn1.html#content" },
			 { text: `“Này các Tỷ-kheo, có những lậu hoặc phải do tri kiến được đoạn trừ, có những lậu hoặc phải do phòng hộ được đoạn trừ, có những lậu hoặc phải do thọ dụng được đoạn trừ, có những lậu hoặc phải do kham nhẫn được đoạn trừ, có những lậu hoặc phải do tránh né được đoạn trừ, có những lậu hoặc phải do trừ diệt được đoạn trừ, có những lậu hoặc phải do tu tập được đoạn trừ.”`, ref: "MN 2 – Kinh Tất Cả Lậu Hoặc", url: "../mn/mn2.html#content" },

{ text: `“Với người không như lý tác ý, một trong sáu tà kiến này khởi lên: ‘Ta có tự ngã’, tà kiến này khởi lên với người ấy như thật, như chơn; ‘Ta không có tự ngã’, tà kiến này khởi lên với người ấy như thật như chơn; ‘Do tự mình, ta tưởng tri ta có tự ngã’...”\n“Này các Tỷ-kheo, như vậy gọi là tà kiến, kiến trù lâm, kiến hoang vu, kiến hý luận, kiến tranh chấp, kiến kiết phược. Này các Tỷ-kheo, trói buộc bởi kiến kiết sử, kẻ phàm phu ít nghe không được giải thoát khỏi sanh, già, chết, sầu, bi, khổ, ưu, não. Ta nói kẻ ấy không thoát khỏi khổ đau.”`, ref: "MN 2 – Kinh Tất Cả Lậu Hoặc", url: "../mn/mn2.html#content" },

{ text: `“Này các Tỷ-kheo, và vị Thánh đệ tử nghe nhiều, được thấy các bậc Thánh, thuần thục pháp các bậc Thánh, tu tập pháp các bậc Thánh; được thấy các bậc Chơn nhơn, thuần thục pháp các bậc Chơn nhơn, tu tập pháp các bậc Chơn nhơn, tuệ tri các pháp cần phải tác ý, tuệ tri các pháp không cần phải tác ý.”\n“Vị ấy như lý tác ý: ‘Ðây là khổ’, như lý tác ý: ‘Ðây là khổ tập’, như lý tác ý: ‘Ðây là khổ diệt’, như lý tác ý: ‘Ðây là con đường đưa đến khổ diệt’. Nhờ vị ấy tác ý như vậy, ba kiết sử được trừ diệt: thân kiến, nghi, giới cấm thủ.”`, ref: "MN 2 – Kinh Tất Cả Lậu Hoặc", url: "../mn/mn2.html#content" },

{ text: `“Này các Tỷ-kheo, thế nào là các lậu hoặc phải do phòng hộ được đoạn trừ? Ở đây, có Tỷ-kheo như lý giác sát, sống phòng hộ với sự phòng hộ mắt. Này các Tỷ-kheo, nếu Tỷ-kheo ấy sống không phòng hộ với sự phòng hộ mắt, các lậu hoặc tàn hại và nhiệt não ấy có thể khởi lên. Nếu sống phòng hộ mắt, các lậu hoặc tàn hại và nhiệt não ấy không còn nữa. Này các Tỷ-kheo, các pháp ấy được gọi là các lậu hoặc phải do phòng hộ được đoạn trừ.`, ref: "MN 2 – Kinh Tất Cả Lậu Hoặc", url: "../mn/mn2.html#content" },

{ text: `Vị ấy như lý giác sát, thọ dụng món ăn khất thực không phải để vui đùa, không phải để đam mê, không phải để trang sức, không phải để tự làm đẹp mình, mà chỉ để thân này được sống lâu và được bảo dưỡng, để thân này khỏi bị thương hại, để hỗ trợ phạm hạnh, nghĩ rằng: “Như vậy, ta diệt trừ các cảm thọ cũ và không cho khởi lên các cảm thọ mới, và ta sẽ không có lỗi lầm, sống được an ổn”.`, ref: "MN 2 – Kinh Tất Cả Lậu Hoặc", url: "../mn/mn2.html#content" },

{ text: `Này các Tỷ-kheo, ở đây, vị Tỷ-kheo như lý giác sát, kham nhẫn lạnh, nóng, đói, khát, sự xúc chạm của ruồi, muỗi, gió, sức nóng mặt trời, các loài bò sát; kham nhẫn những cách nói mạ lị phỉ báng. Vị ấy có tánh kham nhẫn các cảm thọ về thân, những cảm thọ thống khổ, khốc liệt, đau nhói, nhức nhối, không sung sướng, không thích thú, chết điếng người. Này các Tỷ-kheo, nếu vị ấy không kham nhẫn như vậy, các lậu hoặc tàn hại và nhiệt não có thể khởi lên. Nếu vị ấy kham nhẫn như vậy, các lậu hoặc tàn hại và nhiệt não ấy không còn nữa. Này các Tỷ-kheo, các pháp ấy được gọi là các lậu hoặc phải do kham nhẫn được đoạn trừ.`, ref: "MN 2 – Kinh Tất Cả Lậu Hoặc", url: "../mn/mn2.html#content" },

{ text: `Vị ấy như lý giác sát, thọ dụng sàng tọa, chỉ để ngăn ngừa lạnh, ngăn ngừa nóng, ngăn ngừa sự xúc chạm của ruồi, muỗi, gió, sức nóng mặt trời, các loại bò sát, chỉ để giải trừ nguy hiểm của thời tiết, chỉ với mục đích sống độc cư an tịnh.\nVị ấy như lý giác sát thọ dụng dược phẩm trị bệnh, chỉ để ngăn chận các cảm giác khổ thống đã sanh, để được ly khổ hoàn toàn.\nNày các Tỷ-kheo, nếu vị ấy không thọ dụng như vậy, các lậu hoặc tàn hại và nhiệt não có thể khởi lên. Nếu vị ấy thọ dụng như vậy, các lậu hoặc tàn hại và nhiệt não ấy không còn nữa. Này các Tỷ-kheo, các pháp ấy được gọi là các lậu hoặc phải do thọ dụng được đoạn trừ.`, ref: "MN 2 – Kinh Tất Cả Lậu Hoặc", url: "../mn/mn2.html#content" },

{ text: `Này các Tỷ-kheo, ở đây, Tỷ-kheo như lý giác sát tránh né voi dữ, tránh né ngựa dữ, tránh né bò dữ, tránh né chó dữ, rắn, khúc cây, gai góc, hố sâu, vực núi, ao nước nhớp, vũng nước. Có những chỗ ngồi không xứng đáng ngồi, những trú xứ không nên lai vãng, những bạn bè ác độc mà nếu giao du thì bị các vị đồng phạm hạnh có trí nghi ngờ, khinh thường; vị ấy như lý giác sát tránh né chỗ ngồi không xứng đáng ấy, trú xứ không nên lai vãng ấy và các bạn độc ác ấy.`, ref: "MN 2 – Kinh Tất Cả Lậu Hoặc", url: "../mn/mn2.html#content" },

{ text: `Này các Tỷ-kheo, ở đây, Tỷ-kheo như lý giác sát không có chấp nhận dục niệm đã khởi lên, từ bỏ, trừ diệt, diệt tận, không cho tồn tại (dục niệm ấy); không có chấp nhận sân niệm đã khởi lên, từ bỏ, trừ diệt, diệt tận, không cho tồn tại (sân niệm ấy); không có chấp nhận hại niệm đã khởi lên, từ bỏ, trừ diệt, diệt tận, không cho tồn tại (hại niệm ấy); không chấp nhận các ác bất thiện pháp luôn luôn khởi lên, từ bỏ, trừ diệt, diệt tận, không cho tồn tại (các ác bất thiện pháp ấy)`, ref: "MN 2 – Kinh Tất Cả Lậu Hoặc", url: "../mn/mn2.html#content" },
{ text: `“Này các Tỷ-kheo, đối với Tỷ-kheo những lậu hoặc nào phải do tri kiến được đoạn trừ đã được tri kiến đoạn trừ, những lậu hoặc nào phải do phòng hộ được đoạn trừ đã được phòng hộ đoạn trừ... Tỷ-kheo ấy được gọi là đã sống phòng hộ với sự phòng hộ tất cả lậu hoặc, đã đoạn diệt khát ái, đã thoát ly kiết sử, đã chánh quán kiêu mạn, đã diệt tận khổ đau.”`, ref: "MN 2 – Kinh Tất Cả Lậu Hoặc", url: "../mn/mn2.html#content" },
{ text: `Này các Tỷ-kheo, hãy là người thừa tự Pháp của Ta, đừng là những người thừa tự tài vật. Ta có lòng thương tưởng các Ngươi và Ta nghĩ: “Làm sao những đệ tử của Ta là những người thừa tự Pháp của Ta, không phải là những người thừa tự tài vật?”. Và này các Tỷ-kheo, nếu các Ngươi là những người thừa tự tài vật của Ta, không phải là những người thừa tự Pháp, thì không những các Ngươi trở thành những người mà người ta nói: “Cả thầy và trò đều là những người thừa tự tài vật, không phải là những người thừa tự Pháp”, mà cả Ta cũng trở thành người mà người ta nói: “Cả thầy và trò đều là những người thừa tự tài vật, không phải là những người thừa tự Pháp”.`, ref: "MN 3 – Kinh Thừa Tự Pháp", url: "../mn/mn3.html#content" },

{ text: `Này các Tỷ-kheo, dầu cho Tỷ-kheo này, sau khi ăn loại đồ ăn ấy, trừ bỏ đói lả và kiệt sức, và trải qua đêm ngày hôm ấy như vậy, nhưng đối với Ta, Tỷ-kheo đầu tiên đáng được kính nể hơn, và đáng được tán thán hơn. Vì sao vậy? Vì như vậy sẽ đưa đến cho Tỷ-kheo ấy, trong một thời gian lâu ngày, ít dục, biết đủ, khổ hạnh, dễ nuôi dưỡng, tinh cần, tinh tấn. Do vậy, này các Tỷ-kheo, hãy là người thừa tự Pháp của Ta, đừng là người thừa tự tài vật.`, ref: "MN 3 – Kinh Thừa Tự Pháp", url: "../mn/mn3.html#content" },

{ text: `Này chư Hiền, ở đây vị Ðạo Sư sống viễn ly mà các đệ tử không tùy học viễn ly. Những pháp nào vị Ðạo Sư dạy nên từ bỏ, những pháp ấy họ không từ bỏ, và họ sống trong sự đầy đủ, lười biếng, dẫn đầu về đọa lạc, bỏ rơi gánh nặng sống viễn ly.`, ref: "MN 3 – Kinh Thừa Tự Pháp", url: "../mn/mn3.html#content" },

{ text: `Này chư Hiền, các Thượng Tọa Tỷ-kheo có ba trường hợp đáng bị quở trách. Vị Ðạo Sư sống viễn ly, các đệ tử không tùy học viễn ly. Ðó là trường hợp thứ nhất, các Thượng Tọa Tỷ-kheo đáng bị quở trách. Và những pháp nào vị Ðạo Sư dạy nên từ bỏ, những pháp ấy họ không từ bỏ. Ðó là trường hợp thứ hai, các Thượng Tọa Tỷ-kheo đáng bị quở trách. Và họ sống đầy đủ, lười biếng, dẫn đầu về đọa lạc, bỏ rơi gánh nặng sống viễn ly. Ðó là trường hợp thứ ba, các Thượng Tọa Tỷ-kheo đáng bị quở trách. Này chư Hiền, các Thượng tọa Tỷ-kheo do ba trường hợp này đáng bị quở trách.`, ref: "MN 3 – Kinh Thừa Tự Pháp", url: "../mn/mn3.html#content" },

{ text: `Này chư Hiền, các Thượng tọa Tỷ-kheo có ba trường hợp đáng được tán thán. Vị Ðạo Sư sống viễn ly, các đệ tử tùy học viễn ly. Ðó là trường hợp thứ nhất, các Thượng Tọa Tỷ-kheo đáng được tán thán. Và những pháp nào vị Ðạo Sư dạy nên từ bỏ, những pháp ấy họ từ bỏ. Ðó là trường hợp thứ hai, các Thượng tọa Tỷ-kheo đáng được tán thán. Và họ không sống trong sự đầy đủ, không lười biếng, họ bỏ rơi gánh nặng về đọa lạc và dẫn đầu về sống viễn ly. Ðó là trường hợp thứ ba, các Thượng Tọa Tỷ-kheo đáng được tán thán. Này chư Hiền, các Thượng tọa Tỷ-kheo do ba trường hợp này, đáng được tán thán.`, ref: "MN 3 – Kinh Thừa Tự Pháp", url: "../mn/mn3.html#content" },

{ text: `Ở đây, này chư Hiền, tham là ác pháp, và sân cũng là ác pháp, có một con đường Trung đạo diệt trừ tham và diệt trừ sân, khiến (tịnh) nhãn sanh, khiến (chân) trí sanh, hướng đến tịch tịnh, thắng trí, giác ngộ, Niết-bàn. Và này chư Hiền con đường Trung đạo ấy là gì—(con đường) khiến (tịnh) nhãn sanh, khiến (chân) trí sanh, hướng đến tịch tịnh, thắng trí, giác ngộ, Niết-bàn? Ðó là con đường Thánh tám ngành, tức là: Chánh tri kiến, Chánh tư duy, Chánh ngữ, Chánh nghiệp, Chánh mạng, Chánh tinh tấn, Chánh niệm, Chánh định. Này chư Hiền, đó là con đường Trung đạo, khiến (tịnh) nhãn sanh, khiến (chân) trí sanh, hướng đến tịch tịnh, thắng trí, giác ngộ, Niết-bàn.`, ref: "MN 3 – Kinh Thừa Tự Pháp", url: "../mn/mn3.html#content" },

{ text: `Ở đây, này chư Hiền, phẫn nộ là ác pháp và hiềm hận cũng là ác pháp, giả dối là ác pháp và não hại cũng là ác pháp, tật đố là ác pháp và xan lẫn cũng là ác pháp, man trá là ác pháp và phản bội cũng là ác pháp, ngoan cố là ác pháp và bồng bột nông nổi cũng là ác pháp, mạn là ác pháp và tăng thượng mạn cũng là ác pháp, kiêu là ác pháp và phóng dật cũng là ác pháp. Có một con đường Trung đạo diệt trừ kiêu và diệt trừ phóng dật, khiến (tịnh) nhãn sanh, khiến (chân) trí sanh, hướng đến tịch tịnh, thắng trí, giác ngộ, Niết-bàn. Ðó là con đường Thánh tám ngành, tức là: Chánh tri kiến, Chánh tư duy, Chánh ngữ, Chánh nghiệp, Chánh mạng, Chánh tinh tấn, Chánh niệm, Chánh định.`, ref: "MN 3 – Kinh Thừa Tự Pháp", url: "../mn/mn3.html#content" },

{ text: `Và này chư Hiền, con đường Trung đạo ấy là gì—(con đường) khiến (tịnh) nhãn sanh, khiến (chân) trí sanh, hướng đến tịch tịnh, thắng trí, giác ngộ, Niết-bàn? Ðó là con đường Thánh tám ngành, tức là: Chánh tri kiến, Chánh tư duy, Chánh ngữ, Chánh nghiệp, Chánh mạng, Chánh tinh tấn, Chánh niệm, Chánh định. Này chư Hiền, đó là con đường Trung đạo khiến (tịnh) nhãn sanh, khiến (chân) trí sanh, hướng đến tịch tịnh, thắng trí, giác ngộ, Niết-bàn.`, ref: "MN 3 – Kinh Thừa Tự Pháp", url: "../mn/mn3.html#content" },
{ text: `Này Bà-la-môn, rồi Ta suy nghĩ: “Những Sa-môn hay Bà-la-môn nào, thân nghiệp không thanh tịnh, sống tại các trú xứ xa vắng, trong rừng núi hoang vu, do nguyên nhân nhiễm trước, thân nghiệp không thanh tịnh, những Tôn giả Sa-môn hay Bà-la-môn ấy chắc chắn làm cho sợ hãi, khiếp đảm, bất thiện khởi lên. Ta không có thân nghiệp không thanh tịnh, sống tại các trú xứ xa vắng, trong rừng núi hoang vu. Thân nghiệp Ta thanh tịnh. Ta là một trong những bậc Thánh, với thân nghiệp thanh tịnh, sống tại các trú xứ xa vắng, trong rừng núi hoang vu”. Này Bà-la-môn, Ta tự quán sát thân nghiệp hoàn toàn thanh tịnh này, tự cảm thấy lòng tự tin được xác chứng hơn, khi sống trong rừng núi.`, ref: "MN 4 – Kinh Sợ Hãi Khiếp Đảm", url: "../mn/mn4.html#content" },

{ text: `Này Bà-la-môn, tùy thuộc vấn đề này, Ta suy nghĩ như sau: “Những Sa-môn hay Bà-la-môn nào dao động, tâm không an tịnh, sống tại các trú xứ xa vắng, trong rừng núi hoang vu, do nguyên nhân nhiễm trước bị dao động, tâm không an tịnh, những Tôn giả Sa-môn hay Bà-la-môn ấy chắc chắn làm cho sợ hãi, khiếp đảm, bất thiện khởi lên. Ta không có dao động, tâm không phải không an tịnh, sống tại các trú xứ xa vắng, trong rừng núi hoang vu. Ta không có dao động, tâm được an tịnh. Ta là một trong những bậc Thánh không có dao động, tâm được an tịnh, sống tại các trú xứ xa vắng, trong rừng núi hoang vu”. Này Bà-la-môn, Ta tự quán sát tâm Ta được an tịnh như vậy, tự cảm thấy lòng tự tin được xác chứng hơn, khi sống trong rừng núi.`, ref: "MN 4 – Kinh Sợ Hãi Khiếp Đảm", url: "../mn/mn4.html#content" },

{ text: `Này Bà-la-môn, tùy thuộc vấn đề này, Ta suy nghĩ như sau: “Những Sa-môn hay Bà-la-môn nào biếng nhác, kém tinh tấn, sống tại các trú xứ xa vắng, trong rừng núi hoang vu, do nguyên nhân nhiễm trước biếng nhác, kém tinh tấn, những Tôn giả Sa-môn hay Bà-la-môn ấy chắc chắn làm cho sợ hãi, khiếp đảm, bất thiện khởi lên. Ta không có biếng nhác, kém tinh tấn, sống tại các trú xứ xa vắng, trong rừng núi hoang vu. Ta siêng năng, tinh tấn. Ta là một trong những bậc Thánh siêng năng, tinh tấn, sống tại các trú xứ xa vắng, trong rừng núi hoang vu”. Này Bà-la-môn, Ta tự quán sát Ta siêng năng, tinh tấn như vậy, tự cảm thấy lòng tự tin được xác chứng hơn, khi sống trong rừng núi.`, ref: "MN 4 – Kinh Sợ Hãi Khiếp Đảm", url: "../mn/mn4.html#content" },

{ text: `Này Bà-la-môn, tùy thuộc vấn đề này, Ta suy nghĩ như sau: “Những Sa-môn hay Bà-la-môn nào thất niệm, không tỉnh giác, sống tại các trú xứ xa vắng, trong rừng núi hoang vu, do nguyên nhân nhiễm trước thất niệm, không tỉnh giác, những Tôn giả Sa-môn hay Bà-la-môn ấy chắc chắn làm cho sợ hãi, khiếp đảm, bất thiện khởi lên. Ta không có thất niệm, không phải không tỉnh giác, sống tại các trú xứ xa vắng, trong rừng núi hoang vu. Ta an trú niệm. Ta là một trong những bậc Thánh an trú niệm, sống tại các trú xứ xa vắng, trong rừng núi hoang vu”. Này Bà-la-môn, Ta tự quán sát Ta an trú niệm như vậy, tự cảm thấy lòng tự tin được xác chứng hơn, khi sống trong rừng núi.`, ref: "MN 4 – Kinh Sợ Hãi Khiếp Đảm", url: "../mn/mn4.html#content" },

{ text: `Này Bà-la-môn, tùy thuộc vấn đề này, Ta suy nghĩ như sau: “Những Sa-môn hay Bà-la-môn nào không định tĩnh, tâm bị tán loạn, sống tại các trú xứ xa vắng, trong rừng núi hoang vu, do nguyên nhân nhiễm trước không định tĩnh, tâm bị tán loạn, những Tôn giả Sa-môn hay Bà-la-môn ấy chắc chắn làm cho sợ hãi, khiếp đảm, bất thiện khởi lên. Ta được định tĩnh, tâm không bị tán loạn sống tại các trú xứ xa vắng, trong rừng núi hoang vu. Ta thành tựu định tâm. Ta là một trong những bậc Thánh thành tựu định tâm, sống tại các trú xứ xa vắng, trong rừng núi hoang vu”. Này Bà-la-môn, Ta tự quán sát Ta thành tựu định tâm như vậy, từ cảm thấy lòng tự tin được xác chứng hơn, khi sống trong rừng núi.`, ref: "MN 4 – Kinh Sợ Hãi Khiếp Đảm", url: "../mn/mn4.html#content" },

{ text: `Này Bà-la-môn, có một số Sa-môn, Bà-la-môn nghĩ rằng ngày giống như đêm, nghĩ rằng đêm giống như ngày. Như vậy, Ta nói rằng những Sa-môn, Bà-la-môn ấy sống trong si ám. Này Bà-la-môn, Ta nghĩ rằng đêm là đêm, nghĩ rằng ngày là ngày. Này Bà-la-môn, ai nói một cách chơn chánh sẽ nói như sau: “Vị hữu tình nào không có si ám, sinh ra ở đời vì hạnh phúc cho muôn loài, vì an lạc cho muôn loài, vì lòng thương tưởng cho đời, vì lợi ích, vì hạnh phúc, vì an lạc cho loài Trời và loài Người. Vị ấy khi nói một cách chân chánh về Ta sẽ nói như sau: “Là vị hữu tình không có si ám, sinh ra ở đời vì hạnh phúc cho muôn loài, vì an lạc cho muôn loài, vì lòng thương tưởng cho đời, vì lợi ích, vì hạnh phúc, vì an lạc cho loài Trời và loài Người”.`, ref: "MN 4 – Kinh Sợ Hãi Khiếp Đảm", url: "../mn/mn4.html#content" },

{ text: `Này Bà-la-môn, Ta tinh cần, tinh tấn, không lười biếng. Ta an trú chánh niệm, không có loạn, thân được khinh an, không có dao động, tâm được định tĩnh, chuyên nhất.\nNày Bà-la-môn, Ta ly dục, ly các ác pháp, chứng và trú Thiền thứ nhất, một trạng thái hỷ lạc do ly dục sanh, với tầm với tứ.\nDiệt tầm, diệt tứ, Ta chứng và trú Thiền thứ hai, một trạng thái hỷ lạc do định sanh, không tầm, không tứ, nội tĩnh nhất tâm.\nLy hỷ trú xả, chánh niệm tỉnh giác, thân cảm sự lạc thọ mà các bậc Thánh gọi là xả niệm lạc trú, Ta chứng và an trú Thiền thứ ba.\nXả lạc và xả khổ, diệt hỷ ưu đã cảm thọ trước, Ta chứng và an trú Thiền thứ tư, không khổ không lạc, xả niệm thanh tịnh.`, ref: "MN 4 – Kinh Sợ Hãi Khiếp Đảm", url: "../mn/mn4.html#content" },

{ text: `Này Bà-la-môn trong đêm canh ba, Ta chứng được minh thứ ba, vô minh diệt, minh sanh; bóng tối diệt, ánh sáng sanh, trong khi Ta sống không phóng dật, nhiệt tâm, tinh cần.\nNhờ biết như vậy, nhờ thấy như vậy, tâm của Ta thoát khỏi dục lậu, thoát khỏi hữu lậu, thoát khỏi vô minh lậu. Ðối với tự thân đã giải thoát như vậy, khởi lên trí hiểu biết: Ta đã giải thoát. Ta đã thắng tri: “Sanh đã tận, phạm hạnh đã thành, việc cần làm đã làm, không còn trở lui trạng thái này nữa”.`, ref: "MN 4 – Kinh Sợ Hãi Khiếp Đảm", url: "../mn/mn4.html#content" },

{ text: `Này Bà-la-môn, Ông có thể có tư tưởng như sau: “Nay Sa-môn Gotama chưa diệt trừ tham, chưa diệt trừ sân, chưa diệt trừ si, nên sống tại các trú xứ xa vắng, trong rừng núi hoang vu”. Này Bà-la-môn, chớ có hiểu như vậy. Do Ta quán sát hai mục đích mà Ta sống tại các trú xứ xa vắng, trong rừng núi hoang vu. Tự thấy sự hiện tại lạc trú và vì lòng thương tưởng chúng sanh trong tương lai.`, ref: "MN 4 – Kinh Sợ Hãi Khiếp Đảm", url: "../mn/mn4.html#content" },	
{ text: `Ở đây, Hiền giả, hạng người có cấu uế nhưng không như thật tuệ tri: “Nội thân ta có cấu uế”. Với người này, có thể chờ đợi như sau: “Người này sẽ không khởi lên ước muốn, sẽ không cố gắng, sẽ không tinh tấn để diệt trừ cấu uế ấy. Người này sẽ từ trần, trong khi còn có tham, còn có sân, còn có si, trong khi còn cấu uế, trong khi tâm còn ô nhiễm”. Này Hiền giả, giống như một cái bát bằng đồng, mang từ chợ về hay mang từ nhà thợ rèn về, phủ đầy bụi bặm, và người chủ cái bát ấy không dùng đến, không lau chùi và quăng cái bát ấy vào chỗ đầy bụi bặm. Này Hiền giả, như vậy cái bát ấy, sau một thời gian càng ô nhiễm hơn, càng đầy bụi bặm hơn.`, ref: "MN 5 – Kinh Không Uế Nhiễm", url: "../mn/mn5.html#content" },

{ text: `Này Hiền giả, như vậy hạng người có cấu uế nhưng không như thật tuệ tri: “Nội thân ta có cấu uế”. Với người này, có thể chờ đợi như sau: “Người này sẽ không khởi lên ước muốn, sẽ không cố gắng, sẽ không tinh tấn để diệt trừ cấu uế ấy. Người này sẽ từ trần, trong khi còn có tham, còn có sân, còn có si, trong khi còn cấu uế, trong khi tâm còn nhiễm”.`, ref: "MN 5 – Kinh Không Uế Nhiễm", url: "../mn/mn5.html#content" },

{ text: `Ở đây, này Hiền giả, hạng người có cấu uế, và như thật tuệ tri: “Nội thân ta có cấu uế”. Với người này, có thể chờ đợi như sau: “Người này sẽ khởi lên ước muốn, sẽ cố gắng, sẽ tinh tấn để diệt trừ cấu uế ấy. Người này sẽ từ trần, trong khi không còn tham, không còn sân, không còn si, trong khi không còn cấu uế, trong khi tâm không còn ô nhiễm”. Này Hiền giả, giống như cái bát bằng đồng, mang từ chợ về hay mang từ nhà thợ rèn về, phủ đầy bụi bặm, và người chủ cái bát ấy dùng đến, lau chùi và không quăng cái bát ấy vào chỗ đầy bụi bặm. Này Hiền giả, như vậy cái bát ấy, sau một thời gian được thanh tịnh hơn, được sạch sẽ hơn.`, ref: "MN 5 – Kinh Không Uế Nhiễm", url: "../mn/mn5.html#content" },

{ text: `Này Hiền giả, như vậy hạng người có cấu uế và như thật tuệ tri: “Nội thân ta có cấu uế”. Với hạng người này, có thể chờ đợi như sau: “Người này sẽ khởi lên ước muốn, sẽ cố gắng, sẽ tinh tấn, để diệt trừ cấu uế ấy. Người này sẽ từ trần, trong khi không còn tham, không còn sân, không còn si, trong khi không còn cấu uế, trong khi tâm không còn ô nhiễm”.`, ref: "MN 5 – Kinh Không Uế Nhiễm", url: "../mn/mn5.html#content" },

{ text: `Ở đây, này Hiền giả, hạng người không có cấu uế nhưng không như thật tuệ tri: “Nội thân ta không có cấu uế”. Với người này, có thể chờ đợi như sau: “Người này sẽ tư niệm tịnh tướng. Do tư niệm tịnh tướng, tham sẽ làm ô nhiễm tâm của người này. Người này sẽ từ trần, trong khi còn có tham, còn có sân, còn có si, trong khi còn cấu uế, trong khi tâm còn ô nhiễm”. Này Hiền giả, giống như một cái bát bằng đồng, mang từ chợ về hay mang từ nhà thợ rèn về, thanh tịnh và sạch sẽ. Và người chủ cái bát ấy không dùng đến, không lau chùi và quăng cái bát ấy vào chỗ đầy bụi bặm. Này Hiền giả, như vậy cái bát ấy, sau một thời gian, càng ô nhiễm hơn, càng bụi bặm hơn.`, ref: "MN 5 – Kinh Không Uế Nhiễm", url: "../mn/mn5.html#content" },

{ text: `—Này Hiền giả, như vậy hạng người không có cấu uế nhưng không như thật tuệ tri: “Nội thân ta không có cấu uế”. Với người này có thể chờ đợi sau: “Người này sẽ tư niệm tịnh tướng. Do tư niệm tịnh tướng, tham sẽ làm ô nhiễm tâm của người này. Người này sẽ từ trần trong khi còn có tham, còn có sân, còn có si, trong khi còn cấu uế, trong khi tâm còn ô nhiễm”.`, ref: "MN 5 – Kinh Không Uế Nhiễm", url: "../mn/mn5.html#content" },

{ text: `Ở đây, này Hiền giả, hạng người không có cấu uế và như thật tuệ tri: “Nội thân ta không có cấu uế”. Với người này có thể chờ đợi như sau: “Người này sẽ không tư niệm tịnh tướng. Do không tư niệm tịnh tướng, tham sẽ không làm ô nhiễm tâm của người này. Người này sẽ từ trần, trong khi không có tham, không có sân, không có si, trong khi không còn cấu uế, trong khi tâm không còn ô nhiễm”. Này Hiền giả, giống như một cái bát bằng đồng, mang từ chợ về hay mang từ nhà thợ rèn về, thanh tịnh và sạch sẽ và người chủ cái bát ấy dùng đến, lau chùi và không quăng cái bát ấy vào chỗ đầy bụi bặm. Này Hiền giả, như vậy cái bát ấy, sau một thời gian, càng được thanh tịnh hơn, càng được sạch sẽ hơn.`, ref: "MN 5 – Kinh Không Uế Nhiễm", url: "../mn/mn5.html#content" },

{ text: `—Này Hiền giả, như vậy hạng người không có cấu uế, và như thật tuệ tri: “Nội thân ta không có cấu uế”. Với người này có thể chờ đợi như sau: “Người này sẽ không tư niệm tịnh tướng. Do không tư niệm tịnh tướng, tham sẽ không làm ô nhiễm tâm người này. Người này sẽ từ trần, không có tham, không có sân, không có si, không còn cấu uế, tâm không còn ô nhiễm”.`, ref: "MN 5 – Kinh Không Uế Nhiễm", url: "../mn/mn5.html#content" },

{ text: `—Này Hiền giả, cấu uế gọi là cấu uế, danh từ gì là đồng nghĩa cái gọi là cấu uế?\n—Này Hiền giả, các ác bất thiện pháp, cảnh giới của dục là đồng nghĩa cái gọi là cấu uế.`, ref: "MN 5 – Kinh Không Uế Nhiễm", url: "../mn/mn5.html#content" },

{ text: `Này Hiền giả, sự tình này xảy ra, ở đây, một Tỷ-kheo có thể khởi lên ý muốn như sau: “Nếu ta có phạm giới tội, mong rằng các Tỷ-kheo chớ có biết về ta rằng là đã phạm giới tội”. Này Hiền giả, sự tình này có thể xảy ra: các Tỷ-kheo có thể biết được các Tỷ-kheo ấy đã phạm giới tội. Tỷ-kheo này nghĩ rằng: “Các Tỷ-kheo đã biết được ta đã phạm giới tội”. Do đó, vị này trở thành phẫn nộ và bất mãn. Phẫn nộ và bất mãn, cả hai thuộc về cấu uế.`, ref: "MN 5 – Kinh Không Uế Nhiễm", url: "../mn/mn5.html#content" },

{ text: `Những kẻ Thiện nam tử, do lòng tin, xuất gia, từ bỏ gia đình, sống không gia đình; những vị nào không gian ngụy, không xảo trá, không khi cuống, không trạo cử, không kiêu mạn, không dao động, không lắm lời, không tạp thoại, hộ trì các căn, tiết độ trong ăn uống, chú tâm cảnh giác, tha thiết với hạnh Sa-môn, nhiệt thành tôn trọng Phật pháp, không sống trong sung túc, không biếng nhác, bỏ rơi gánh nặng về đọa lạc, dẫn đầu về viễn ly, tinh cần, tinh tấn, nỗ lực, chú tâm cảnh giác, định tâm, nhất tâm, có trí tuệ, không đần độn. Những vị này sau khi nghe pháp môn này của Tôn giả Sāriputta, hình như đang uống, hình như đang nếm với lời nói và tâm ý. Thật lành thay, một vị Tôn giả đồng phạm hạnh đã khiến cho vượt khỏi bất thiện và an trú vào chánh thiện!`, ref: "MN 5 – Kinh Không Uế Nhiễm", url: "../mn/mn5.html#content" },
{ text: `Này các Tỷ-kheo, nếu Tỷ-kheo có ước nguyện: “Mong rằng ta được các đồng phạm hạnh thương mến, yêu quý, cung kính và tôn trọng!”, Tỷ-kheo ấy phải thành tựu viên mãn giới luật, kiên trì, nội tâm tịch tĩnh, không gián đoạn Thiền định, thành tựu quán hạnh, thích sống tại các trú xứ không tịch.`, ref: "MN 6 – Kinh Ước Nguyện", url: "../mn/mn6.html#content" },

{ text: `Này các Tỷ-kheo, nếu Tỷ-kheo có ước nguyện: “Mong rằng những bà con huyết thống với ta, khi họ chết và mệnh chung, nghĩ (đến ta) với tâm hoan hỷ (và nhờ vậy) được quả báo lớn, lợi ích lớn!”, Tỷ-kheo ấy phải thành tựu viên mãn giới luật … (như trên) … trú xứ không tịch.`, ref: "MN 6 – Kinh Ước Nguyện", url: "../mn/mn6.html#content" },

{ text: `Này các Tỷ-kheo, nếu Tỷ-kheo có ước nguyện: “Mong rằng ta nhiếp phục lạc và bất lạc, chớ không phải bất lạc nhiếp phục ta. Mong rằng ta sống luôn luôn nhiếp phục bất lạc được khởi lên!”, Tỷ-kheo ấy phải thành tựu viên mãn giới luật … (như trên) … trú xứ không tịch.\nNày các Tỷ-kheo, nếu Tỷ-kheo có ước nguyện: “Mong rằng ta nhiếp phục khiếp đảm và sợ hãi, chớ không phải khiếp đảm và sợ hãi nhiếp phục ta! Mong rằng ta sống luôn luôn nhiếp phục khiếp đảm và sợ hãi được khởi lên!”, Tỷ-kheo ấy phải thành tựu viên mãn giới luật … (như trên) … trú xứ không tịch.`, ref: "MN 6 – Kinh Ước Nguyện", url: "../mn/mn6.html#content" },

{ text: `Này các Tỷ-kheo, nếu Tỷ-kheo có ước nguyện: “Mong rằng, tùy theo ý muốn, không có khó khăn, không có mệt nhọc, không có phí sức, ta chứng được bốn Thiền, thuộc tăng thượng tâm, hiện tại lạc trú!”, Tỷ-kheo ấy phải thành tựu viên mãn giới luật … (như trên) … trú xứ không tịch.\nNày các Tỷ-kheo, nếu Tỷ-kheo có ước nguyện: “Mong rằng ta trừ diệt ba kiết sử, chứng quả Dự lưu, không còn bị đọa lạc, chắc chắn hướng đến Chánh giác!”, Tỷ-kheo ấy phải thành tựu viên mãn giới luật … (như trên) … trú xứ không tịch.`, ref: "MN 6 – Kinh Ước Nguyện", url: "../mn/mn6.html#content" },
{ text: `Này các Tỷ-kheo, như một tấm vải cấu uế, nhiễm bụi, một người thợ nhuộm nhúng tấm vải ấy vào thuốc nhuộm này hay thuốc nhuộm khác—hoặc xanh, hoặc vàng, hoặc đỏ, hoặc tía—vải ấy sẽ được màu nhuộm không tốt đẹp, sẽ được màu nhuộm không sạch sẽ. Vì sao vậy? Này các Tỷ-kheo, vì tấm vải không được trong sạch. Cũng vậy, này các Tỷ-kheo, cõi ác chờ đợi một tâm cấu uế. Này các Tỷ-kheo, như một tấm vải thanh tịnh, trong sạch, một người thợ nhuộm nhúng tấm vải ấy vào thuốc nhuộm này hay thuốc nhuộm khác—hoặc xanh, hoặc vàng, hoặc đỏ, hoặc tía, vải ấy sẽ được màu nhuộm tốt đẹp, sẽ được màu nhuộm sạch sẽ. Vì sao vậy? Này các Tỷ-kheo, vì tấm vải được trong sạch. Cũng vậy, này các Tỷ-kheo, cõi thiện chờ đợi một tâm không cấu uế.`, ref: "MN 7 – Kinh Ví Dụ Tấm Vải", url: "../mn/mn7.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là những cấu uế của tâm? Tham dục, tà tham là cấu uế của tâm, sân là cấu uế của tâm, phẫn là cấu uế của tâm, hận là cấu uế của tâm, hư ngụy, não hại, tật đố, xan tham, man trá, khi cuống, ngoan cố, cấp tháo, quá mạn, kiêu, phóng dật là cấu uế của tâm.`, ref: "MN 7 – Kinh Ví Dụ Tấm Vải", url: "../mn/mn7.html#content" },

{ text: `Này các Tỷ-kheo, Tỷ-kheo nào nghĩ rằng: “Tham dục, tà tham là cấu uế của tâm” và sau khi biết vậy, vị ấy đoạn trừ tham dục, tà tham cấu uế của tâm; nghĩ rằng: “Sân là cấu uế của tâm”, và sau khi biết vậy, vị ấy đoạn trừ sân, cấu uế của tâm; phẫn … hận … hư ngụy … não hại, tật đố, xan tham, man trá, khi cuống … ngoan cố … cấp tháo … mạn … quá mạn … kiêu; nghĩ rằng: “Phóng dật là cấu uế của tâm” thì sau khi biết vậy, vị ấy đoạn trừ phóng dật, cấu uế của tâm.`, ref: "MN 7 – Kinh Ví Dụ Tấm Vải", url: "../mn/mn7.html#content" },

{ text: `Vị ấy tự nghĩ: “Ta thành tựu lòng tin tuyệt đối đối với Pháp”, và chứng được nghĩa tín thọ, chứng được pháp tín thọ, chứng được hân hoan liên hệ đến pháp; từ hân hoan, hỷ sanh; từ hỷ, thân được khinh an; thân khinh an, cảm giác được lạc thọ; với lạc thọ, tâm được Thiền định.`, ref: "MN 7 – Kinh Ví Dụ Tấm Vải", url: "../mn/mn7.html#content" },

{ text: `Vị ấy tự nghĩ: “Ðến giai đoạn này, đối với Ta, có sự từ bỏ, có sự diệt trừ, có sự giải thoát, có sự đoạn trừ, có sự xả ly”, và chứng được nghĩa tín thọ, chứng được pháp tín thọ, chứng được hân hoan liên hệ đến pháp; từ hân hoan, hỷ sanh; từ hỷ, thân khinh an; thân khinh an, cảm giác được lạc thọ; với lạc thọ, tâm được Thiền định.`, ref: "MN 7 – Kinh Ví Dụ Tấm Vải", url: "../mn/mn7.html#content" },

{ text: `Này các Tỷ-kheo, như một tấm vải cấu uế, nhiễm bụi, nếu bỏ trong nước sạch, trở thành thanh tịnh sạch sẽ, như bỏ vào lò lửa trở thành thanh tịnh sạch sẽ. Cũng vậy, này các Tỷ-kheo, một Tỷ-kheo, giới như vậy, pháp như vậy, tuệ như vậy—nếu có ăn đồ khất thực với gạo thơm, hạt đen được vất đi, với các món canh, với các món ăn khác, cũng không vì vậy trở thành một chướng ngại cho vị ấy.`, ref: "MN 7 – Kinh Ví Dụ Tấm Vải", url: "../mn/mn7.html#content" },

{ text: `Vị ấy an trú, biến mãn một phương với tâm câu hữu với từ, cũng vậy phương thứ hai, cũng vậy phương thứ ba, cũng vậy phương thứ tư. Như vậy, cùng khắp thế giới, trên dưới bề ngang, hết thảy phương xứ, cùng khắp vô biên giới, vị ấy an trú biến mãn với tâm câu hữu với từ, quảng đại, vô biên, không hận, không sân.`, ref: "MN 7 – Kinh Ví Dụ Tấm Vải", url: "../mn/mn7.html#content" },

{ text: `Vị ấy biết: “Có cái này, có cái hạ liệt, có cái cao thượng, có sự giải thoát vượt qua các tưởng”.\nDo vị ấy biết như vậy, thấy như vậy, tâm được giải thoát khỏi dục lậu, tâm được giải thoát khỏi hữu lậu, tâm được giải thoát khỏi vô minh lậu. Ðối với tự thân đã giải thoát, trí khởi lên: “Ta đã giải thoát, sanh đã tận, phạm hạnh đã thành, những việc nên làm đã làm, không còn trở lui trạng thái này nữa”. Này các Tỷ-kheo, Tỷ-kheo ấy được gọi là Tỷ-kheo đã được tắm rửa với sự tắm rửa nội tâm.`, ref: "MN 7 – Kinh Ví Dụ Tấm Vải", url: "../mn/mn7.html#content" },

{ text: `Trong sông Bàhukà\nTại Adhikakkà,\nTại cả sông Gayà\nKẻ ngu dầu thường tắm,\nÁc nghiệp không rửa sạch.\nSông Sundarikà\nCó thể làm được gì?\nPayàga làm gì?\nCả sông Bàhukà?\nKhông thể rửa nghiệp đen\nCủa kẻ ác gây tội.`, ref: "MN 7 – Kinh Ví Dụ Tấm Vải", url: "../mn/mn7.html#content" },

{ text: `Ðối kẻ sống thanh tịnh,\nNgày nào cũng ngày tốt,\nVới kẻ sống thanh tịnh,\nNgày nào cũng ngày lành.`, ref: "MN 7 – Kinh Ví Dụ Tấm Vải", url: "../mn/mn7.html#content" },

{ text: `Các tịnh nghiệp thanh tịnh,\nLuôn thành tựu thiện hạnh.\nNày vị Bà-la-môn,\nChỉ nên tắm ở đây,\nKhiến mọi loài chúng sanh,\nÐược sống trong an ổn.\nNếu không nói dối trá,\nNếu không hại chúng sanh,\nKhông lấy của không cho,\nCó lòng tín, không tham,\nÐi Gayà làm gì,\nGayà một giếng nước?`, ref: "MN 7 – Kinh Ví Dụ Tấm Vải", url: "../mn/mn7.html#content" },

{ text: `\Thật vi diệu thay, Tôn giả Gotama! Thật vi diệu thay, Tôn giả Gotama! Tôn giả Gotama, như người dựng đứng lại những gì bị quăng ngã xuống, phơi bày ra những gì bị che kín, chỉ đường cho kẻ bị lạc hướng, đem đèn sáng vào trong bóng tối, để những ai có mắt có thể thấy sắc. Cũng vậy Chánh pháp đã được Tôn giả Gotama dùng nhiều phương tiện trình bày. Nay con quy y Tôn giả Gotama, quy y Pháp và quy y Tăng. Mong con được xuất gia với Tôn giả Gotama! Mong con được thọ đại giới!`, ref: "MN 7 – Kinh Ví Dụ Tấm Vải", url: "../mn/mn7.html#content" },
{ text: `Này Cunda, giống như một con đường không bằng phẳng, có một con đường bằng phẳng khác đối trị. Này Cunda, giống như một bến nước không bằng phẳng, có một bến nước bằng phẳng khác đối trị. Cũng vậy này Cunda: Đối với con người làm hại, có sự không làm hại đối trị. Ðối với con người sát sanh, có từ bỏ sát sanh đối trị. Ðối với con người lấy của không cho, có từ bỏ lấy của không cho đối trị …, Ðối với con người nhiễm thế tục, cố chấp tư kiến, tánh khó hành xả, có không nhiễm thế tục, không cố chấp tư kiến, tánh dễ hành xả đối trị.`, ref: "MN 8 – Kinh Ðoạn Giảm", url: "../mn/mn8.html#content" },

{ text: `Này Cunda, ví như các bất thiện pháp, tất cả đều hướng hạ, còn các thiện pháp, tất cả đều hướng thượng. Cũng vậy, này Cunda: Con người không làm hại, hướng thượng đối với người làm hại, con người từ bỏ sát sanh, hướng thượng đối với người sát sanh. Con người từ bỏ lấy của không cho, hướng thượng đối với người lấy của không cho. Con người không nhiễm thế tục, không cố chấp tư kiến, tánh dễ hành xả, hướng thượng đối với người nhiễm thế tục, cố chấp tư kiến, tánh khó hành xả.`, ref: "MN 8 – Kinh Ðoạn Giảm", url: "../mn/mn8.html#content" },

{ text: `Này Cunda, con người tự mình bị rơi vào bùn lầy có thể kéo lên một người bị rơi vào bùn lầy, sự tình ấy không thể xảy ra. Này Cunda, con người tự mình không rơi vào bùn lầy, có thể kéo lên một người bị rơi vào bùn lầy, sự tình ấy có thể xảy ra. Này Cunda, con người tự mình không được nhiếp phục, không được huấn luyện, không được hoàn toàn giải thoát, tự mình có thể nhiếp phục, huấn luyện và hoàn toàn giải thoát người khác, sự tình ấy không thể xảy ra. Một người được nhiếp phục, được huấn luyện, được hoàn toàn giải thoát, tự mình có thể nhiếp phục, huấn luyện, hoàn toàn giải thoát người khác, sự tình ấy có thể xảy ra.`, ref: "MN 8 – Kinh Ðoạn Giảm", url: "../mn/mn8.html#content" },

{ text: `Này Cunda, những gì bậc Ðạo Sư phải làm, vì hạnh phúc, vì lòng thương tưởng đệ tử, những việc ấy Ta đã làm, vì lòng thương tưởng cho các Người. Này Cunda, đây là những gốc cây, đây là những ngôi nhà trống. Này Cunda, hãy Thiền định, chớ có phóng dật, chớ có hối tiếc về sau. Ðó là lời giáo huấn của Ta cho các Người.`, ref: "MN 8 – Kinh Ðoạn Giảm", url: "../mn/mn8.html#content" },
{ text: `Chư Hiền, thế nào là bất thiện, thế nào là căn bổn bất thiện, thế nào là thiện, thế nào là căn bổn thiện? Chư Hiền, sát sanh là bất thiện, lấy của không cho là bất thiện, tà hạnh trong các dục là bất thiện, nói láo là bất thiện, nói hai lưỡi là bất thiện, ác khẩu là bất thiện, nói phù phiếm là bất thiện, tham dục là bất thiện, sân là bất thiện, tà kiến là bất thiện. Chư Hiền, như vậy gọi là bất thiện.\nVà chư Hiền, thế nào là căn bổn bất thiện? Tham là căn bổn bất thiện, sân là căn bổn bất thiện, si là căn bổn bất thiện. Chư Hiền, như vậy gọi là căn bổn bất thiện.`, ref: "MN 9 – Kinh Chánh Tri Kiến", url: "../mn/mn9.html#content" },

{ text: `Và này chư Hiền, thế nào là thiện? Từ bỏ sát sanh là thiện, từ bỏ lấy của không cho là thiện, từ bỏ tà hạnh trong các dục là thiện, từ bỏ nói láo là thiện, từ bỏ nói hai lưỡi là thiện, từ bỏ ác khẩu là thiện, từ bỏ nói phù phiếm là thiện, không tham dục là thiện, không sân là thiện, chánh tri kiến là thiện. Chư Hiền, như vậy gọi là thiện.\nChư Hiền, thế nào là căn bổn thiện? Không tham là căn bổn thiện, không sân là căn bổn thiện, không si là căn bổn thiện. Chư Hiền, như vậy gọi là căn bổn thiện.`, ref: "MN 9 – Kinh Chánh Tri Kiến", url: "../mn/mn9.html#content" },

{ text: `Chư Hiền, khi nào Thánh đệ tử tuệ tri bất thiện,..tuệ tri thiện,... tuệ tri căn bổn thiện, khi ấy, vị ấy đoạn trừ tất cả tham tùy miên, tẩy sạch sân tùy miên, nhổ tận gốc kiến mạn tùy miên “Tôi là”, đoạn trừ vô minh, khiến minh khởi lên, diệt tận khổ đau ngay trong hiện tại. Chư Hiền, như vậy Thánh đệ tử có chánh tri kiến, có tri kiến chánh trực, có lòng tin Pháp tuyệt đối và thành tựu diệu pháp này.`, ref: "MN 9 – Kinh Chánh Tri Kiến", url: "../mn/mn9.html#content" },

{ text: `Chư Hiền, thế nào là thức ăn, thế nào là tập khởi của thức ăn, thế nào là đoạn diệt của thức ăn, thế nào là con đường đưa đến đoạn diệt của thức ăn? Chư Hiền, có bốn loại thức ăn này, khiến các loài chúng sanh đã sanh được an trú hay các loài hữu tình sẽ sanh được hỗ trợ cho sanh. Thế nào là bốn? Ðoàn thực, loại thô hay loại tế, xúc thực là thứ hai, tư niệm thực là thứ ba, thức thực là thứ tư. Từ tập khởi của ái có tập khởi của thức ăn, từ đoạn diệt của ái có đoạn diệt của thức ăn. Thánh Ðạo Tám Ngành này là con đường đưa đến đoạn diệt của thức ăn, tức là: Chánh Tri kiến, Chánh Tư duy, Chánh Ngữ, Chánh Nghiệp, Chánh Mạng, Chánh Tinh tấn, Chánh Niệm, Chánh Ðịnh.`, ref: "MN 9 – Kinh Chánh Tri Kiến", url: "../mn/mn9.html#content" },

{ text: `Chư Hiền, khi nào Thánh đệ tử tuệ tri Khổ, tuệ tri Tập khởi của khổ, tuệ tri Ðoạn diệt của khổ, tuệ tri Con Ðường đưa đến đoạn diệt của khổ, chư Hiền, khi ấy Thánh đệ tử có chánh tri kiến, có tri kiến chánh trực, có lòng tin Pháp tuyệt đối và thành tựu diệu pháp này.`, ref: "MN 9 – Kinh Chánh Tri Kiến", url: "../mn/mn9.html#content" },

{ text: `Chư Hiền, thế nào là Khổ? Sanh là khổ, già là khổ, bệnh là khổ, chết là khổ, sầu bi khổ ưu não là khổ, cầu không được là khổ, tóm lại năm thủ uẩn là khổ. Chư Hiền, như vậy gọi là Khổ. Chư Hiền, thế nào là Tập khởi của khổ? Chính là ái đưa đến tái sanh, cùng khởi hỷ dục và tham hướng đến tái sanh, cùng khởi hỷ dục và tham, tìm cầu hỷ lạc chỗ này chỗ kia, tức là dục ái, hữu ái, phi hữu ái. Chư Hiền, như vậy gọi là Tập khởi của khổ.`, ref: "MN 9 – Kinh Chánh Tri Kiến", url: "../mn/mn9.html#content" },

{ text: `Chư Hiền, thế nào là Ðoạn diệt của khổ? Ðó là sự đoạn diệt, ly tham, không có dư tàn, sự quăng bỏ, sự từ bỏ, sự giải thoát, sự vô chấp khát ái ấy. Chư Hiền, thế nào là Con Ðường đưa đến đoạn diệt của khổ? Chính là Thánh Ðạo Tám Ngành đưa đến khổ diệt, tức là: Chánh Tri kiến, Chánh Tư duy, Chánh Ngữ, Chánh Nghiệp, Chánh Mạng, Chánh Tinh tấn, Chánh Niệm, Chánh Ðịnh.`, ref: "MN 9 – Kinh Chánh Tri Kiến", url: "../mn/mn9.html#content" },
{ text: `Này các Tỷ-kheo, không cần gì nửa tháng, một vị nào tu tập Bốn Niệm xứ này trong bảy ngày, vị ấy có thể chứng một trong hai quả sau đây: Một là chứng Chánh trí ngay trong hiện tại, hai là nếu còn hữu dư y, thì chứng quả Bất hoàn. Này các Tỷ-kheo, đây là con đường độc nhất đưa đến thanh tịnh cho chúng sanh, vượt khỏi sầu não, diệt trừ khổ ưu, thành tựu Chánh trí, chứng ngộ Niết-bàn. Ðó là Bốn Niệm xứ.`, ref: "MN 10 – Kinh Niệm Xứ", url: "../mn/mn10.html#content" },
{ text: `Này Sāriputta, như thế này là sự yểm ly của Ta. Này Sāriputta, tỉnh giác, Ta đi tới; tỉnh giác Ta đi lui, Ta an trú lòng từ cho đến trong một giọt nước với tâm tư: “Mong rằng Ta không làm hại một chúng sanh nhỏ nào trong những ác đạo của họ!” Này Sāriputta, như vậy là sự yểm ly của Ta.`, ref: "MN 12 – Ðại Kinh Sư Tử Hống", url: "../mn/mn12.html#content" },

{ text: `Này Sāriputta, rồi Ta trong những đêm đông lạnh lẽo, giữa những ngày mồng tám, khi có tuyết rơi, trong những đêm như vậy, Ta sống giữa trời, và ban ngày sống trong khu rừng rậm rạp. Ta sống trong những ngày cuối tháng hè, ban ngày thì sống giữa trời, còn ban đêm trong khu rừng rậm rạp. Rồi này Sāriputta, những bài kệ kỳ diệu từ trước chưa từng được nghe sau đây được khởi lên:\n\nNay bị thiêu đốt, bị buốt lạnh,\nCô độc sống trong rừng kinh hoàng,\nTrần truồng, Ta ngồi không lửa ấm,\nẨn sĩ, trong lý tưởng đăm chiêu.`, ref: "MN 12 – Ðại Kinh Sư Tử Hống", url: "../mn/mn12.html#content" },

{ text: `Này Sāriputta, những ai nói một cách chân chánh sẽ nói như sau: “Một vị hữu tình không bị si chi phối, đã sanh ra ở đời vì lợi ích, vì hạnh phúc cho chúng sanh, vì lòng thương tưởng cho đời, vì lợi ích, vì hạnh phúc, vì an lạc cho chư Thiên và loài Người”. Vị ấy sẽ nói về Ta một cách chân chánh như sau: “Một vị hữu tình không bị si chi phối, đã sanh ra ở đời vì lợi ích, vì hạnh phúc cho chúng sanh, vì lòng thương tưởng cho đời, vì lợi ích, vì hạnh phúc, vì an lạc cho chư Thiên và loài Người”.`, ref: "MN 12 – Ðại Kinh Sư Tử Hống", url: "../mn/mn12.html#content" },	
		{ text: `Lại nữa, này các Tỷ-kheo, do dục làm nhân, do dục làm duyên, do dục làm nguyên nhân, do chính dục làm nhân, vua tranh đoạt với vua, Sát-đế-lị tranh đoạt với Sát-đế-lị, Bà-la-môn tranh đoạt với Bà-la-môn, gia chủ tranh đoạt với gia chủ, mẹ tranh đoạt với con, con tranh đoạt với mẹ, cha tranh đoạt với con, con tranh đoạt với cha, anh em tranh đoạt với anh em, anh tranh đoạt với chị, chị tranh đoạt với anh, bạn bè tranh đoạt với bạn bè. Khi họ đã dấn mình vào tranh chấp, tranh luận, tranh đoạt; họ công phá nhau bằng tay; họ công phá nhau bằng đá; họ công phá nhau bằng gậy; họ công phá nhau bằng kiếm. Ở đây họ đi đến tử vong, đi đến sự đau khổ gần như tử vong. Này các Tỷ-kheo, như vậy là sự nguy hiểm các dục, thiết thực hiện tại, thuộc khổ uẩn, lấy dục làm nhân, lấy dục làm duyên, là nguồn gốc của dục, là nguyên nhân của dục.`, ref: "MN 13 – Ðại Kinh Khổ Uẩn", url: "../mn/mn13.html#content" },

{ text: `Lại nữa, này các Tỷ-kheo, do dục làm nhân, do dục làm duyên, do dục làm nguyên nhân, do chính dục làm nhân, họ cầm mâu và thuẫn, họ đeo cung và tên, họ dàn trận hai mặt, và tên được nhắm bắn nhau, đao được quăng ném nhau, kiếm được vung chém nhau. Họ bắn đâm nhau bằng tên, họ quăng đâm nhau bằng đao, họ chặt đầu nhau bằng kiếm. Ở đây họ đi đến tử vong, đi đến sự đau khổ gần như tử vong. Này các Tỷ-kheo, như vậy là sự nguy hiểm các dục, thiết thực hiện tại, thuộc khổ uẩn, lấy dục làm nhân, lấy dục làm duyên, là nguồn gốc của dục, là nguyên nhân của dục.`, ref: "MN 13 – Ðại Kinh Khổ Uẩn", url: "../mn/mn13.html#content" },

{ text: `Lại nữa, này các Tỷ-kheo, do dục làm nhân, do dục làm duyên, do dục làm nguyên nhân, do chính dục làm nhân, họ cầm mâu và thuẫn, họ đeo cung và tên, họ công phá thành quách mới trét vôi hồ và tên được nhắm bắn nhau, đao được quăng ném nhau, kiếm được vung chém nhau. Ở đây, họ bắn đâm nhau bằng tên, họ quăng đâm nhau bằng đao, họ đổ nước phân sôi, họ đè bẹp nhau bằng đá, họ chặt đầu nhau bằng kiếm. Ở đây họ đi đến tử vong, đi đến sự đau khổ gần như tử vong. Này các Tỷ-kheo, như vậy là sự nguy hiểm các dục, thiết thực hiện tại, thuộc khổ uẩn, lấy dục làm nhân, lấy dục làm duyên, là nguồn gốc của dục, là nguyên nhân của dục.`, ref: "MN 13 – Ðại Kinh Khổ Uẩn", url: "../mn/mn13.html#content" },

{ text: `Lại nữa, này các Tỷ-kheo, do dục làm nhân, do dục làm duyên, do dục làm nguyên nhân, do chính dục làm nhân, họ sống làm các ác hạnh về thân, làm các ác hạnh về lời nói, làm các ác hạnh về ý. Do họ sống làm các ác hạnh về thân, làm các ác hạnh về lời nói, làm các ác hạnh về ý, khi thân hoại mạng chung, họ sanh vào cõi dữ, ác thú, đọa xứ, địa ngục. Này các Tỷ-kheo, như vậy là sự nguy hiểm các dục, đưa đến đau khổ tương lai, là khổ uẩn, do dục làm nhân, do dục làm duyên, do dục làm nhân duyên, do chính dục làm nhân.`, ref: "MN 13 – Ðại Kinh Khổ Uẩn", url: "../mn/mn13.html#content" },

{ text: `—Này các Tỷ-kheo, như vậy là sự nguy hiểm các sắc pháp. Lại nữa, này các Tỷ-kheo, người ta thấy cô gái ấy, thi thể bị quăng vào nghĩa địa, một ngày hay hai ngày hay ba ngày, thi thể ấy trương phồng lên, xanh đen lại, nát thối ra. Này các Tỷ-kheo, các Người nghĩ thế nào? Có phải sự mỹ diệu sắc đẹp xưa kia của cô gái đã biến mất và sự nguy hiểm đã hiện ra?\n—Bạch Thế Tôn, sự thật là vậy.\n—Này các Tỷ-kheo, như vậy là sự nguy hiểm các sắc pháp.`, ref: "MN 13 – Ðại Kinh Khổ Uẩn", url: "../mn/mn13.html#content" },

{ text: `—Này các Tỷ-kheo, như vậy là sự nguy hiểm các sắc pháp. Lại nữa, này các Tỷ-kheo, người ta thấy cô gái ấy, thi thể bị quăng vào nghĩa địa, chỉ có toàn xương trắng màu vỏ ốc … chỉ còn một đống xương lâu hơn một năm … chỉ còn các xương thối trở thành bột. Này các Tỷ-kheo, các Người nghĩ thế nào? Có phải sự mỹ diệu về sắc đẹp xưa kia của cô gái nay đã biến mất, và sự nguy hiểm hiện ra?\n—Bạch Thế Tôn, sự thật là vậy.\n—Này các Tỷ-kheo, như vậy là sự nguy hiểm các sắc pháp.`, ref: "MN 13 – Ðại Kinh Khổ Uẩn", url: "../mn/mn13.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là sự nguy hiểm các cảm thọ? Này các Tỷ-kheo, các cảm thọ là vô thường, khổ, biến hoại, như vậy là sự nguy hiểm các cảm thọ. Và này các Tỷ-kheo, thế nào là sự xuất ly các cảm thọ? Này các Tỷ-kheo, sự điều phục dục tham đối với các cảm thọ, sự đoạn trừ dục tham, như vậy gọi là sự xuất ly các cảm thọ.`, ref: "MN 13 – Ðại Kinh Khổ Uẩn", url: "../mn/mn13.html#content" },
{ text: `Này Mahānāma, thuở xưa, khi Ta còn là Bồ-tát, chưa chứng được Bồ-đề, chưa thành Chánh Ðẳng Chánh Giác, Ta khéo thấy với như thật chánh trí tuệ: “Các dục vui ít, khổ nhiều, não nhiều, sự nguy hiểm ở đây lại nhiều hơn”, dầu Ta có thấy với như thật chánh trí tuệ như vậy, nhưng Ta chưa chứng được hỷ lạc do ly dục, ly ác bất thiện pháp sanh hay một pháp nào khác cao thượng hơn. Và như vậy Ta biết rằng, Ta chưa khỏi bị các dục chi phối. Và này Mahānāma, khi nào Ta khéo thấy với như thật chánh trí tuệ: “Các dục, vui ít, khổ nhiều, não nhiều, sự nguy hiểm ở đây lại nhiều hơn”, và Ta chứng được hỷ lạc do ly dục, ly ác bất thiện pháp sanh hay một pháp nào khác cao thượng hơn, như vậy Ta khỏi bị các dục chi phối.`, ref: "MN 14 – Tiểu Kinh Khổ Uẩn", url: "../mn/mn14.html#content" },

{ text: `Và này Mahānāma, thế nào là vị ngọt các dục? Này Mahānāma, có năm pháp tăng trưởng các dục này: Các sắc pháp do mắt nhận thức, khả ái, khả lạc, khả ý, khả hỷ, tương ưng với dục, hấp dẫn; các tiếng do tai nhận thức…; các hương do mũi nhận thức…; các vị do lưỡi nhận thức…; các xúc do thân nhận thức, khả ái, khả lạc, khả ý, khả hỷ, tương ưng với dục, hấp dẫn. Này Mahānāma, có năm pháp tăng trưởng các dục như vậy. Này Mahānāma, y cứ vào năm pháp tăng trưởng các dục này, có lạc và hỷ khởi lên, như vậy là vị ngọt các dục.`, ref: "MN 14 – Tiểu Kinh Khổ Uẩn", url: "../mn/mn14.html#content" },

{ text: `“Chư Hiền Nigaṇṭha, Ta có thể không di động thân thể, không nói lên một lời, sống cảm giác thuần túy lạc thọ luôn trong một ngày một đêm. Chư Hiền Nigaṇṭha, Ta có thể không di động thân thể, không nói lên một lời, sống cảm giác thuần túy lạc thọ luôn trong hai ngày hai đêm, luôn trong ba ngày ba đêm, luôn trong bốn ngày bốn đêm, luôn trong năm ngày năm đêm, luôn trong sáu ngày sáu đêm, luôn trong bảy ngày bảy đêm. Chư Hiền Nigaṇṭha, các Ngươi nghĩ thế nào? Sự kiện là như vậy, ai sống hạnh phúc hơn, vua Magadha Seniya Bimbisāra hay Ta?`, ref: "MN 14 – Tiểu Kinh Khổ Uẩn", url: "../mn/mn14.html#content" },
{ text: `Chư Hiền, nếu Tỷ-kheo thỉnh nguyện: “Mong rằng chư Tôn giả nói với tôi, mong rằng tôi được chư Tôn giả nói!” Nhưng nếu vị ấy là một người khó nói, đầy đủ những tánh khiến người ấy trở thành khó nói, khó kham nhẫn, không cung kính đón nhận khi được giảng dạy thì các vị đồng phạm hạnh nghĩ rằng, Tỷ-kheo ấy không đáng nói đến, nghĩ rằng Tỷ-kheo ấy không đáng được giáo huấn, nghĩ rằng không nên đặt lòng tin vào người ấy.`, ref: "MN 15 – Kinh Tư Lượng", url: "../mn/mn15.html#content" },

{ text: `Chư Hiền, ở đây, Tỷ-kheo cần phải quán sát tự ngã với tự ngã như sau:\n“Không biết ta có ác dục, có bị ác dục chi phối không?” Chư Hiền, nếu Tỷ-kheo quán sát và biết rằng: “Ta có ác dục và bị ác dục chi phối”, thì chư Hiền, Tỷ-kheo ấy cần phải tinh tấn đoạn trừ các ác, bất thiện pháp ấy. Chư Hiền, nếu Tỷ-kheo quán sát và biết rằng: “Ta không có ác dục, không bị ác dục chi phối”, thì chư Hiền, Tỷ-kheo ấy phải sống với tâm niệm hoan hỷ, ngày đêm tu học các thiện pháp.`, ref: "MN 15 – Kinh Tư Lượng", url: "../mn/mn15.html#content" },

{ text: `Chư Hiền, nếu trong khi quán sát, Tỷ-kheo thấy rõ rằng tất cả các ác, bất thiện pháp chưa được đoạn trừ trong nội tâm, thì chư Hiền, Tỷ-kheo ấy cần phải tinh tấn đoạn trừ các ác, bất thiện pháp ấy. Chư Hiền, nếu Tỷ-kheo trong khi quán sát thấy rõ rằng tất cả các ác, bất thiện pháp đã được đoạn trừ trong nội tâm, thì chư Hiền, Tỷ-kheo ấy phải sống với tâm niệm hoan hỷ, ngày đêm tu học thiện pháp.`, ref: "MN 15 – Kinh Tư Lượng", url: "../mn/mn15.html#content" },

{ text: `Chư Hiền, ví như một phụ nữ hay một đàn ông trẻ tuổi, trong tuổi thanh xuân, tánh ưa trang điểm, tự quán sát mặt mày của mình trong một tấm kính sạch sẽ và trong suốt, hay trong một bát nước trong sáng. Nếu người ấy thấy bụi bặm hay cấu uế trên mặt mình, thì người ấy tinh tấn đoạn trừ bụi bặm hay cấu uế ấy. Nếu người ấy không thấy bụi bặm hay cấu uế trên mặt mình, thì người ấy sẽ hoan hỷ nghĩ rằng: “Thật sự ta được điều tốt đẹp; thật sự ta được thanh tịnh”. Cũng vậy chư Hiền, nếu trong khi quán sát, Tỷ-kheo thấy rõ rằng tất cả các ác, bất thiện pháp chưa đoạn trừ ở nội tâm, thì chư Hiền, Tỷ-kheo ấy cần phải tinh tấn đoạn trừ các ác, bất thiện pháp ấy. Chư Hiền, nếu Tỷ-kheo trong khi quán sát thấy rõ rằng các ác, bất thiện pháp đã đoạn trừ ở nội tâm, thì chư Hiền, Tỷ-kheo ấy phải sống với tâm niệm hoan hỷ, ngày đêm tu học thiện pháp.`, ref: "MN 15 – Kinh Tư Lượng", url: "../mn/mn15.html#content" },
{ text: `Chư Tỷ-kheo, Tỷ-kheo nào chưa diệt trừ năm tâm hoang vu, chưa đoạn tận năm tâm triền phược, vị ấy có thể lớn mạnh, trưởng thành, hưng thịnh trong Pháp và Luật này, sự kiện này không xảy ra.`, ref: "MN 16 – Kinh Tâm Hoang Vu", url: "../mn/mn16.html#content" },

{ text: `Thế nào là năm tâm hoang vu chưa được đoạn trừ? Chư Tỷ-kheo, ở đây, Tỷ-kheo nghi ngờ bậc Ðạo Sư, do dự, không quyết đoán, không có tịnh tín. Chư Tỷ-kheo, Tỷ-kheo nào nghi ngờ bậc Ðạo Sư, do dự, không quyết đoán, không có tịnh tín, thời tâm vị này không hướng về nỗ lực, chuyên cần, kiên trì, tinh tấn. Nếu tâm của ai không hướng về nỗ lực, chuyên cần, kiên trì, tinh tấn, như vậy là tâm hoang vu thứ nhất chưa được diệt trừ.`, ref: "MN 16 – Kinh Tâm Hoang Vu", url: "../mn/mn16.html#content" },

{ text: `Và lại nữa, chư Tỷ-kheo, Tỷ-kheo phẫn nộ đối với các đồng phạm hạnh, không có hoan hỷ, tâm tư chống đối, cứng rắn. Chư Tỷ-kheo, Tỷ-kheo nào phẫn nộ đối với các vị đồng phạm hạnh, không có hoan hỷ, tâm tư chống đối, cứng rắn, thời tâm của vị này không hướng về nỗ lực, chuyên cần, kiên trì, tinh tấn. Nếu tâm của ai không hướng về nỗ lực, chuyên cần, kiên trì, tinh tấn, như vậy là tâm hoang vu thứ năm chưa được diệt trừ.`, ref: "MN 16 – Kinh Tâm Hoang Vu", url: "../mn/mn16.html#content" },

{ text: `Thế nào là năm tâm triền phược chưa được đoạn tận? Chư Tỷ-kheo, ở đây, Tỷ-kheo, đối với những dục, không phải không tham ái, không phải không dục cầu, không phải không ái luyến, không phải không khao khát, không phải không nhiệt tình, không phải không khát ái. Chư Tỷ-kheo, vị Tỷ-kheo nào đối với những dục, không phải không tham ái … không phải không khát ái, tâm của vị ấy không hướng về nỗ lực, chuyên cần, kiên trì, tinh tấn. Nếu tâm của ai không hướng về nỗ lực, chuyên cần, kiên trì, tinh tấn, như vậy là tâm triền phược thứ nhất chưa được đoạn tận.`, ref: "MN 16 – Kinh Tâm Hoang Vu", url: "../mn/mn16.html#content" },

{ text: `Và lại nữa, chư Tỷ-kheo, Tỷ-kheo nào ăn cho đến thỏa thê, cho đến bụng chứa đầy, sống thiên nặng về khoái lạc về sàng tọa, khoái lạc về ngủ nghỉ, khoái lạc về thụy miên, tâm của vị ấy không hướng về nỗ lực, chuyên cần, kiên trì, tinh tấn. Nếu tâm của ai không hướng về nỗ lực, chuyên cần, kiên trì, tinh tấn, như vậy là tâm triền phược thứ tư chưa được đoạn tận.`, ref: "MN 16 – Kinh Tâm Hoang Vu", url: "../mn/mn16.html#content" },

{ text: `Vị ấy tu tập như ý túc câu hữu với dục Thiền định, tinh cần hành; tu tập như ý túc câu hữu với tinh tấn Thiền định, tinh cần hành; tu tập như ý túc câu hữu với tâm Thiền định, tinh cần hành; tu tập như ý túc câu hữu với tư duy Thiền định, tinh cần hành; với nỗ lực là thứ năm. Chư Tỷ-kheo, Tỷ-kheo nào đầy đủ mười lăm pháp kể cả nỗ lực, thời có đủ khả năng để phá vỡ, có đủ khả năng để chánh giác, có đủ khả năng để đạt thành vô thượng an ổn khỏi các ách phược.`, ref: "MN 16 – Kinh Tâm Hoang Vu", url: "../mn/mn16.html#content" },

{ text: `Chư Tỷ-kheo, như có khoảng tám, mười hay mười hai cái trứng của con gà mái, những trứng này được con gà mái khéo ấp, ngồi lên trên, khéo ấp nóng, khéo ấp dưỡng, thời dầu cho con gà mái không khởi lên sự mong ước: “Mong rằng những con gà con của ta, sau khi đâm thủng vỏ trứng với móng chân nhọn của chúng, hay với mỏ của chúng, có thể thoát ra một cách yên ổn”, những con gà con ấy, sau khi đâm thủng vỏ trứng với móng chân nhọn của chúng hay với mỏ của chúng, có khả năng thoát ra một cách yên ổn. Chư Tỷ-kheo, cũng vậy, Tỷ-kheo đầy đủ mười lăm pháp, kể cả nỗ lực, thời có đủ khả năng để phá vỡ, có đủ khả năng để chánh giác, có đủ khả năng để đạt thành vô thượng an ổn khỏi các ách phược.`, ref: "MN 16 – Kinh Tâm Hoang Vu", url: "../mn/mn16.html#content" },
{ text: `“Này Hiền giả, theo lời dạy của Ta, trong thế giới với chư Thiên, Māra và Phạm thiên, với các chúng Sa-môn, Bà-la-môn, chư Thiên và loài Người, không có tranh luận một ai ở đời; các tưởng sẽ không ám ảnh vị Bà-la-môn sống không bị dục triền phược, không có nghi ngờ do dự, với mọi hối quá đoạn diệt, không có tham ái đối với hữu và phi hữu. Này Hiền giả, như vậy là quan điểm của Ta, như vậy là lời Ta giảng dạy”.`, ref: "MN 18 – Kinh Mật Hoàn", url: "../mn/mn18.html#content" },

{ text: `Này Tỷ-kheo, do bất cứ nhân duyên gì, một số hý luận vọng tưởng ám ảnh một người. Nếu ở đây không có gì đáng tùy hỷ, đáng đón mừng, đáng chấp thủ, thời như vậy là sự đoạn tận tham tùy miên, sự đoạn tận sân tùy miên, sự đoạn tận kiến tùy miên, sự đoạn tận nghi tùy miên, sự đoạn tận mạn tùy miên, sự đoạn tận hữu tham tùy miên, sự đoạn tận vô minh tùy miên, sự đoạn tận chấp trượng, chấp kiếm, đấu tranh, tránh tranh, luận tranh, kháng tranh, ly gián ngữ, vọng ngữ. Chính ở đây, những ác, bất thiện pháp này đều được tiêu diệt, không còn dư tàn.`, ref: "MN 18 – Kinh Mật Hoàn", url: "../mn/mn18.html#content" },

{ text: `Chư Hiền, do nhân con mắt và các sắc pháp, nhãn thức khởi lên. Sự gặp gỡ của ba pháp này là xúc. Do duyên xúc nên có cảm thọ. Những gì có cảm thọ thời có tưởng, những gì có tưởng thời có suy tầm, những gì có suy tầm thì có hý luận. Do hý luận ấy làm nhân, một số hý luận vọng tưởng ám ảnh một người, đối với các sắc pháp do con mắt nhận thức, quá khứ, tương lai và hiện tại.`, ref: "MN 18 – Kinh Mật Hoàn", url: "../mn/mn18.html#content" },

{ text: `Chư Hiền, do nhân lỗ tai và các tiếng, nhĩ thức khởi lên, do nhân lỗ mũi và các hương, tỷ thức khởi lên, do nhân lưỡi và các vị, thiệt thức khởi lên, do nhân thân và xúc, thân thức khởi lên; do nhân ý và các pháp, ý thức khởi lên. Sự gặp gỡ của ba pháp này là xúc. Do duyên xúc nên có các cảm thọ. Những gì có cảm thọ thời có tưởng. Những gì có tưởng thời có suy tầm. Những gì có suy tầm thời có hý luận. Do hý luận ấy làm nhân, một số hý luận vọng tưởng ám ảnh một người, đối với các pháp do ý thức nhận thức, quá khứ, tương lai và hiện tại.`, ref: "MN 18 – Kinh Mật Hoàn", url: "../mn/mn18.html#content" },

{ text: `Chư Hiền, sự kiện này xảy ra: khi nào có mắt, khi nào có sắc pháp, khi nào có nhãn thức, thời sự thi thiết của xúc được hiển lộ. Sự kiện này xảy ra: khi nào có sự thi thiết của xúc thời sự thi thiết của thọ được hiển lộ. Sự kiện này xảy ra: khi nào có thi thiết của thọ thời sự thi thiết của tưởng được hiển lộ. Sự kiện này xảy ra: khi nào có sự thi thiết của tưởng, thời sự thi thiết của suy tầm được hiển lộ. Sự kiện này xảy ra: khi nào có sự thi thiết của suy tầm thời sự thi thiết của sự ám ảnh một số hý luận vọng tưởng được hiển lộ.`, ref: "MN 18 – Kinh Mật Hoàn", url: "../mn/mn18.html#content" },
{ text: `Chư Tỷ-kheo, trước khi Ta giác ngộ, khi chưa thành Chánh Giác và còn là Bồ-tát, Ta suy nghĩ như sau: “Ta sống suy tư và chia hai suy tầm”. Chư Tỷ-kheo, phàm có dục tầm nào, sân tầm nào, hại tầm nào, Ta phân thành phần thứ nhất; phàm có ly dục tầm nào, vô sân tầm nào, vô hại tầm nào, Ta phân thành phần thứ hai.`, ref: "MN 19 – Kinh Song Tầm", url: "../mn/mn19.html#content" },

{ text: `Chư Tỷ-kheo, rồi Ta sống không phóng dật, nhiệt tâm, tinh cần. Khi dục tầm khởi lên, Ta tuệ tri: “Dục tầm này khởi lên nơi Ta, và dục tầm này đưa đến tự hại, đưa đến hại người, đưa đến hại cả hai, diệt trí tuệ, dự phần vào phiền não, không đưa đến Niết-bàn”. Chư Tỷ-kheo, khi Ta suy tư: “Dục tầm này đưa đến tự hại”, dục tầm được biến mất, Chư Tỷ-kheo, khi Ta suy tư: “Dục tầm đưa đến hại người”, dục tầm được biến mất. Chư Tỷ-kheo, khi Ta suy tư: “Dục tầm đưa đến hại cả hai”, dục tầm được biến mất. Chư Tỷ-kheo, khi Ta suy tư: “Dục tầm diệt trí tuệ, dự phần vào phiền não, không đưa đến Niết-bàn”, dục tầm được biến mất. Chư Tỷ-kheo, như vậy Ta tiếp tục trừ bỏ, xả ly và đoạn tận dục tầm.`, ref: "MN 19 – Kinh Song Tầm", url: "../mn/mn19.html#content" },

{ text: `Chư Tỷ-kheo, Tỷ-kheo suy tư, quán sát nhiều vấn đề gì, thời tâm sanh khuynh hướng đối với vấn đề ấy. Chư Tỷ-kheo, nếu Tỷ-kheo suy tư, quán sát nhiều về dục tầm, vị ấy từ bỏ ly dục tầm. Khi tâm đã nặng về dục tầm, thời tâm vị ấy có khuynh hướng về dục tầm. Chư Tỷ-kheo, nếu Tỷ-kheo suy tư quán sát nhiều về sân tầm … (như trên) … về hại tầm, vị ấy từ bỏ vô hại tầm. Khi tâm đã đặt nặng về hại tầm thời tâm vị ấy có khuynh hướng về hại tầm.`, ref: "MN 19 – Kinh Song Tầm", url: "../mn/mn19.html#content" },

{ text: `Chư Tỷ-kheo, ví như vào cuối tháng mùa mưa, về mùa thu, khi lúa đã trổ hạt, một người mục đồng chăn giữ bò, cầm roi đánh các con bò bên này, đánh bên kia, chế ngự chúng, ngăn chận chúng. Vì sao vậy? Chư Tỷ-kheo, vì người mục đồng thấy do nhân duyên này, đưa đến sự chết, sự tù tội, sự đánh đập hay sự trách móc. Chư Tỷ-kheo, cũng vậy, Ta đã thấy sự nguy hại, sự hạ liệt, sự uế nhiễm của các pháp bất thiện, và thấy sự viễn ly, sự lợi ích, sự thanh tịnh của các thiện pháp.`, ref: "MN 19 – Kinh Song Tầm", url: "../mn/mn19.html#content" },

{ text: `Chư Tỷ-kheo, trong khi Ta sống không phóng dật, nhiệt tâm, tinh cần như vậy, khi ly dục tầm khởi lên, Ta tuệ tri như vầy: “Ly dục tầm này khởi lên nơi Ta và ly dục tầm này không đưa đến tự hại, không đưa đến hại người, không đưa đến hại cả hai, tăng trưởng trí tuệ, không dự phần vào phiền não, đưa đến Niết-bàn”. Chư Tỷ-kheo, nếu ban đêm Ta suy tư, quán sát (về ly dục tầm) không phải từ nhân duyên ấy Ta thấy sợ hãi. Chư Tỷ-kheo, nếu ban ngày Ta suy tư, quán sát (về ly dục tầm), không phải từ nhân duyên ấy Ta thấy sợ hãi. Chư Tỷ-kheo, nếu ban đêm, ban ngày, Ta suy tư, quán sát (về ly dục tầm), không phải từ nhân duyên ấy Ta thấy sợ hãi. Và Ta suy tư, quán sát quá lâu, thân Ta có thể mệt mỏi; khi thân mệt mỏi thì tâm bị dao động; khi tâm bị dao động thì tâm rất khó được định tĩnh. Chư Tỷ-kheo, rồi tự nội thân Ta trấn an tâm, trấn tịnh tâm, khiến được nhất tâm, khiến thành định tĩnh. Vì sao vậy? Vì để tâm Ta khỏi dao động.`, ref: "MN 19 – Kinh Song Tầm", url: "../mn/mn19.html#content" },

{ text: `Chư Tỷ-kheo, ví như vào cuối tháng hè, khi tất cả lúa gạo đã cất vào kho thóc, một người mục đồng chăn giữ các con bò. Khi người mục đồng ở dưới gốc cây hay ở ngoài trời, người ấy có thể nghĩ đến có việc cần phải làm, và người ấy nghĩ: “Ðây là những con bò”. Chư Tỷ-kheo, cũng vậy ở đây, có việc cần phải làm, và Ta nghĩ: “Ðây là những pháp”.\nChư Tỷ-kheo, Ta phát tâm dõng mãnh, tinh tấn, không có tiêu cực, niệm không tán loạn được an trú, thân được khinh an, không có cuồng nhiệt, tâm được định tĩnh nhất tâm.`, ref: "MN 19 – Kinh Song Tầm", url: "../mn/mn19.html#content" },

{ text: `Chư Tỷ-kheo, Ta ly dục, ly ác, bất thiện pháp, chứng và trú Thiền thứ nhất, một trạng thái hỷ lạc do ly dục sanh, có tầm, có tứ. Diệt tầm và tứ, Ta chứng và trú Thiền thứ hai, một trạng thái hỷ lạc do định sanh, không tầm không tứ, nội tĩnh nhất tâm. Ly hỷ trú xả, chánh niệm tỉnh giác, thân cảm sự lạc thọ mà các bậc Thánh gọi là xả niệm lạc trú, Ta chứng và an trú Thiền thứ ba. Xả lạc xả khổ, diệt hỷ ưu đã cảm thọ trước, Ta chứng và trú Thiền thứ tư, không khổ, không lạc, xả niệm thanh tịnh.`, ref: "MN 19 – Kinh Song Tầm", url: "../mn/mn19.html#content" },

{ text: `Chư Tỷ-kheo, giống như trong khu rừng rậm rạp có một hồ nước lớn thâm sâu, và một đoàn nai lớn sống gần một bên. Có một người đến, không muốn chúng được lợi ích, không muốn chúng được hạnh phúc, không muốn chúng được an ổn khỏi các ách nạn. Nếu có con đường nào được yên ổn, được an toàn, đưa đến hoan hỷ, người ấy sẽ chận đóng con đường này lại, sẽ mở con đường nguy hiểm, sẽ đặt con mồi đực, sẽ đặt con mồi cái. Chư Tỷ-kheo, như vậy, sau một thời gian đoàn nai lớn ấy gặp ách nạn và hao mòn dần. Chư Tỷ-kheo, có một người đến, muốn đoàn nai ấy được lợi ích, muốn chúng được hạnh phúc, muốn chúng được an ổn khỏi các ách nạn. Nếu có con đường nào được yên ổn, được an toàn, người ấy sẽ mở con đường này, sẽ đóng con đường nguy hiểm lại, sẽ đem con mồi đực đi, sẽ hủy bỏ con mồi cái. Chư Tỷ-kheo, như vậy đoàn nai lớn ấy sau một thời gian sẽ được tăng trưởng, hưng thịnh, thành mãn.`, ref: "MN 19 – Kinh Song Tầm", url: "../mn/mn19.html#content" },

{ text: `Chư Tỷ-kheo, hồ nước lớn, thâm sâu chỉ cho các dục. Chư Tỷ-kheo, đoàn nai lớn chỉ cho các loài hữu tình. Chư Tỷ-kheo, con người không muốn chúng được lợi ích, không muốn chúng được hạnh phúc, không muốn chúng được an ổn khỏi các ách nạn chỉ cho ác ma. Chư Tỷ-kheo, con đường nguy hiểm chỉ cho con đường tà đạo có tám ngành, tức là tà tri kiến, tà tư duy, tà ngữ, tà nghiệp, tà mạng, tà tinh tấn, tà niệm, tà định. Chư Tỷ-kheo, con mồi đực chỉ cho hỷ và tham. Chư Tỷ-kheo, con mồi cái chỉ cho vô minh. Chư Tỷ-kheo, còn người muốn chúng được lợi ích, muốn chúng được hạnh phúc, muốn chúng được an ổn khỏi các ách nạn chỉ cho Như Lai, bậc A-la-hán, Chánh Ðẳng Giác. Con đường yên ổn, an toàn, đưa đến hoan hỷ chỉ cho con đường Thánh đạo Tám ngành, tức là Chánh tri kiến, Chánh tư duy, Chánh ngữ, Chánh nghiệp, Chánh mạng, Chánh tinh tấn, Chánh niệm, Chánh định.`, ref: "MN 19 – Kinh Song Tầm", url: "../mn/mn19.html#content" },

{ text: `Chư Tỷ-kheo, như vậy Ta mở con đường yên ổn, an toàn, đưa đến hoan hỷ, Ta đóng con đường nguy hiểm, Ta mang đi con mồi đực, Ta hủy bỏ con mồi cái. Chư Tỷ-kheo, những gì vị Ðạo Sư cần phải làm cho các đệ tử vì lòng thương tưởng họ, những điều ấy Ta đã làm, vì lòng thương tưởng các Người. Chư Tỷ-kheo, đây là các gốc cây, đây là các chỗ trống. Hãy Thiền định, chớ có phóng dật, chớ có hối tiếc về sau. Ðó là lời giáo huấn của Ta.`, ref: "MN 19 – Kinh Song Tầm", url: "../mn/mn19.html#content" },
 { text: `Chư Tỷ-kheo, ví như một người thợ mộc thiện xảo hay đệ tử một người thợ mộc, dùng một cái nêm nhỏ đánh bật ra, đánh tung ra, đánh văng ra một cái nêm khác; chư Tỷ-kheo, cũng vậy, khi một Tỷ-kheo y cứ một tướng nào, tác ý một tướng nào, các ác bất thiện tầm liên hệ đến dục, liên hệ đến sân, liên hệ đến si sanh khởi, thời này chư Tỷ-kheo, Tỷ-kheo ấy cần phải tác ý một tướng khác liên hệ đến thiện, không phải tướng kia. Nhờ tác ý một tướng khác liên hệ đến thiện, khác với tướng kia, các ác bất thiện tầm liên hệ đến dục, liên hệ đến sân, liên hệ đến si được trừ diệt, đi đến diệt vong. Chính nhờ diệt trừ chúng, nội tâm được an trú, an tịnh, nhất tâm, định tĩnh.`, ref: "MN 20 – Kinh An Trú Tầm", url: "../mn/mn20.html#content" },

{ text: `Chư Tỷ-kheo, nếu Tỷ-kheo ấy khi tác ý một tướng khác với tướng kia, liên hệ đến thiện, các ác bất thiện tầm liên hệ đến dục, liên hệ đến sân, liên hệ đến si vẫn khởi lên, thời này chư Tỷ-kheo, Tỷ-kheo ấy cần phải quán sát các nguy hiểm của những tầm ấy: “Ðây là những tầm bất thiện, đây là những tầm có tội, đây là những tầm có khổ báo”. Nhờ quán sát các nguy hiểm của những tầm ấy, các bất thiện tầm liên hệ đến dục, liên hệ đến sân, liên hệ đến si được trừ diệt, đi đến diệt vong. Chính nhờ diệt trừ chúng, nội tâm được an trú, an tịnh, nhất tâm, định tĩnh.`, ref: "MN 20 – Kinh An Trú Tầm", url: "../mn/mn20.html#content" },

{ text: `Chư Tỷ-kheo, ví như một người đàn bà hay người đàn ông trẻ tuổi, trong tuổi thanh xuân, tánh ưa trang sức nếu một xác rắn, hay xác chó, hay xác người được quàng vào cổ, người ấy phải lo âu, xấu hổ, ghê tởm. Chư Tỷ-kheo, cũng vậy, nếu Tỷ-kheo ấy quán sát các nguy hiểm của những tầm ấy: “Ðây là những tầm bất thiện, đây là những tầm có tội, đây là những tầm có khổ báo”. Nhờ quán sát các nguy hiểm của những tầm ấy, các bất thiện tầm liên hệ đến dục, liên hệ đến sân, liên hệ đến si được trừ diệt, đi đến diệt vong. Chính nhờ diệt trừ chúng, nội tâm được an trú, an tịnh, nhất tâm, định tĩnh.`, ref: "MN 20 – Kinh An Trú Tầm", url: "../mn/mn20.html#content" },

{ text: `Chư Tỷ-kheo, nếu Tỷ-kheo ấy trong khi quán sát các nguy hiểm của những tầm ấy, các ác bất thiện tầm liên hệ đến dục, liên hệ đến sân, liên hệ đến si vẫn khởi lên, thời này chư Tỷ-kheo, Tỷ-kheo ấy cần phải không ức niệm, không tác ý những tầm ấy. Nhờ không ức niệm, không tác ý các tầm ấy, các ác bất thiện tầm liên hệ đến dục, liên hệ đến sân, liên hệ đến si được trừ diệt, đi đến diệt vong. Chính nhờ diệt trừ chúng, nội tâm được an trú, an tịnh, nhất tâm, định tĩnh. Chư Tỷ-kheo, ví như một người có mắt, không muốn thấy các sắc pháp nằm trong tầm mắt của mình, người ấy nhắm mắt lại hay ngó qua một bên. Chư Tỷ-kheo, cũng vậy, nếu Tỷ-kheo ấy, trong khi không ức niệm, không tác ý … được an trú, an tịnh, nhất tâm, định tĩnh.`, ref: "MN 20 – Kinh An Trú Tầm", url: "../mn/mn20.html#content" },

{ text: `Chư Tỷ-kheo, nếu Tỷ-kheo, trong khi y cứ tướng nào, tác ý tướng nào, các ác bất thiện tầm liên hệ đến dục, liên hệ đến sân, liên hệ đến si sanh khởi. Tỷ-kheo ấy tác ý một tướng khác, liên hệ đến thiện, khác với tướng kia, các ác, bất thiện tầm liên hệ đến dục, liên hệ đến sân, liên hệ đến si được diệt trừ, đi đến diệt vong. Chính nhờ diệt trừ chúng, nội tâm được an trú, an tịnh, nhất tâm, định tĩnh.`, ref: "MN 20 – Kinh An Trú Tầm", url: "../mn/mn20.html#content" },
{ text: `Này Phagguna, Ông phải học tập như sau: “Mong rằng tâm của ta sẽ không bị biến nhiễm! Mong rằng ta sẽ không nói những lời ác ngữ! Mong rằng ta sẽ sống với lòng lân mẫn, với tâm từ bi, không ôm lòng sân hận!” Này Phagguna, Ông phải học tập như vậy.`, ref: "MN 21 – Kinh Ví Dụ Cái Cưa", url: "../mn/mn21.html#content" },

{ text: `Này các Tỷ-kheo, Ta theo hạnh nhất tọa thực. Chư Tỷ-kheo, sống theo hạnh nhất tọa thực, Ta cảm thấy không bệnh tật, không ốm đau, nhẹ nhàng, khang kiện và sảng khoái. Chư Tỷ-kheo, các Ngươi hãy sống theo hạnh nhất tọa thực. Chư Tỷ-kheo, các Ngươi theo hạnh nhất tọa thực thời các Ngươi sẽ cảm thấy không bệnh tật, không ốm đau, nhẹ nhàng, khang kiện và sảng khoái.`, ref: "MN 21 – Kinh Ví Dụ Cái Cưa", url: "../mn/mn21.html#content" },

{ text: `Này các Tỷ-kheo, một thời các Tỷ-kheo của Ta có tâm rất thuần thục hoan hỷ. Chư Tỷ-kheo, Ta không cần phải giảng dạy gì cho các Tỷ-kheo ấy; chư Tỷ-kheo, Ta chỉ cần khơi dậy ức niệm nơi các Tỷ-kheo ấy. Chư Tỷ-kheo, ví như trên đất bằng, tại chỗ ngã tư, có một chiếc xe đang đậu, thắng với ngựa hay, có roi ngựa đặt ngang sẵn sàng. Có người mã thuật sư thiện xảo, người đánh xe điều ngự các con ngựa đáng được điều ngự, leo lên xe ấy, tay trái nắm lấy dây cương, tay mặt cầm lấy roi ngựa, có thể đánh xe ngựa ấy đi tới đi lui, tại chỗ nào và như thế nào, theo ý mình muốn. Cũng vậy chư Tỷ-kheo, Ta không cần phải giảng dạy gì cho các Tỷ-kheo ấy; chư Tỷ-kheo, Ta chỉ cần khơi dậy ức niệm nơi các Tỷ-kheo ấy.`, ref: "MN 21 – Kinh Ví Dụ Cái Cưa", url: "../mn/mn21.html#content" },

{ text: `Do vậy, này các Tỷ-kheo, hãy từ bỏ bất thiện, hãy nỗ lực đối với các thiện pháp, như vậy các Ngươi mới thành tựu sự trưởng thành, hưng thịnh, lớn mạnh trong Pháp và Luật này. Chư Tỷ-kheo, cũng như gần một thôn làng hay thị trấn nhỏ, có ngôi rừng cây tala lớn, ngôi rừng bị các cây leo y lan bao phủ. Có một người đến khu rừng này, muốn lợi ích cho ngôi rừng, muốn hạnh phúc, muốn an ổn khỏi các ách phược cho ngôi rừng. Người ấy chặt đứt các nhành cây cong thiếu hẳn sinh lực, vất chúng ra khỏi ngôi rừng, dọn dẹp trong rừng sạch sẽ. Người ấy săn sóc kỹ lưỡng các nhánh cây tala thẳng thắn, khéo mọc. Chư Tỷ-kheo, sau một thời gian, ngôi rừng như vậy được trưởng thành, hưng thịnh, lớn mạnh. Cũng vậy, này các Tỷ-kheo, các Ngươi hãy từ bỏ bất thiện, hãy nỗ lực đối với các thiện pháp, như vậy các Ngươi mới thành tựu sự trưởng thành, hưng thịnh, lớn mạnh trong Pháp và Luật này.`, ref: "MN 21 – Kinh Ví Dụ Cái Cưa", url: "../mn/mn21.html#content" },

{ text: `Cũng vậy chư Tỷ-kheo, ở đây, Tỷ-kheo hết sức hiền lành, hết sức nhu thuận, hết sức ôn hòa trong khi chưa bị những lời nói bất khả ý, xúc phạm. Và chư Tỷ-kheo, chỉ khi nào Tỷ-kheo bị những lời nói bất khả ý, xúc phạm mà vị ấy vẫn hết sức hiền lành, hết sức nhu thuận, hết sức ôn hòa, khi ấy vị ấy mới được xem là hiền lành, mới được xem là nhu thuận, mới được xem là ôn hòa. Chư Tỷ-kheo, Ta không gọi một Tỷ-kheo là dễ nói, khi vị ấy dễ nói về các vật dụng như y áo, món ăn, sàng tọa, dược phẩm trị bệnh, khi vị ấy thành tựu được tánh dễ nói. Vì sao vậy? Chư Tỷ-kheo, Tỷ-kheo ấy khi không được các vật dụng như y áo, thức ăn, sàng tọa, dược phẩm trị bệnh, không còn là dễ nói, không còn thành tựu tánh dễ nói. Chư Tỷ-kheo, Tỷ-kheo nào tôn trọng Pháp, cung kính Pháp, sùng kính Pháp trở thành dễ nói, thành tựu tánh dễ nói, vị ấy Ta mới gọi là dễ nói. Do vậy, này các Tỷ-kheo, hãy suy nghĩ: “Chỉ vì tôn trọng Pháp, cung kính Pháp, sùng kính Pháp chúng ta sẽ trở thành dễ nói, thành tựu tánh dễ nói”. Chư Tỷ-kheo, các Ngươi phải học tập như vậy.`, ref: "MN 21 – Kinh Ví Dụ Cái Cưa", url: "../mn/mn21.html#content" },

{ text: `Chư Tỷ-kheo, có năm loại ngôn ngữ mà các Ngươi có thể dùng khi nói với các người khác: đúng thời hay phi thời, chơn thực hay không chơn thực, nhu nhuyến hay thô bạo, có lợi ích hay không lợi ích, với từ tâm hay với sân tâm. Chư Tỷ-kheo, khi nói với các người khác, các Ngươi có thể nói đúng thời hay phi thời. Chư Tỷ-kheo, khi nói với các người khác, các Ngươi có thể nói lời chơn thực hay nói lời không chơn thực. Chư Tỷ-kheo, khi nói với các người khác, các Ngươi có thể nói lời nhu nhuyến hay nói lời thô bạo. Chư Tỷ-kheo, khi nói với các người khác, các Ngươi có thể nói lời lợi ích hay nói lời không lợi ích. Chư Tỷ-kheo, khi nói với các người khác, các Ngươi có thể nói với từ tâm hay với sân tâm.`, ref: "MN 21 – Kinh Ví Dụ Cái Cưa", url: "../mn/mn21.html#content" },

{ text: `Chư Tỷ-kheo, ở tại đây, các Ngươi cần phải học tập như sau: “Chúng ta sẽ giữ tâm của chúng ta không biến nhiễm, chúng ta sẽ không thốt ra những lời ác ngữ, chúng ta sẽ sống với lòng lân mẫn, với tâm từ bi, với nội tâm không sân hận. Chúng ta sẽ sống bao phủ người này với tâm câu hữu với từ. Và với người này là đối tượng, ta sống biến mãn cùng khắp thế giới với tâm câu hữu với từ, quảng địa vô biên, không hận, không sân”. Chư Tỷ-kheo, như vậy các Ngươi cần phải học tập.`, ref: "MN 21 – Kinh Ví Dụ Cái Cưa", url: "../mn/mn21.html#content" },

{ text: `Chư Tỷ-kheo, như những kẻ đạo tặc hạ liệt, dùng cưa hai lưỡi mà cưa tay, cưa chân; dầu vậy, nếu một ai ở đây khởi ý nhiễm loạn, người ấy do vậy không phải là người thực hành giáo pháp của Ta. Ở đây, chư Tỷ-kheo các Ông phải học tập như sau: “Chúng ta sẽ giữ tâm của chúng ta không biến nhiễm; chúng ta sẽ không thốt ra những lời ác ngữ; chúng ta sẽ sống với lòng lân mẫn, với tâm từ bi, với nội tâm không sân hận. Chúng ta sẽ sống bao phủ người này với tâm câu hữu với từ. Và với người này là đối tượng, ta sống biến mãn cùng khắp thế giới với tâm câu hữu với từ, quảng đại, vô biên, không hận, không sân”. Chư Tỷ-kheo, các Ông cần phải học tập như vậy.`, ref: "MN 21 – Kinh Ví Dụ Cái Cưa", url: "../mn/mn21.html#content" },
{ text: `Thật sự, này các Tỷ-kheo, sự kiện này không xảy ra, người ta có thể thọ dụng các dục ngoài các dục, ngoài các dục tưởng, ngoài các dục tầm.`, ref: "MN 22 – Kinh Ví Dụ Con Rắn", url: "../mn/mn22.html#content" },

{ text: `Chư Tỷ-kheo, ở đây có một số người ngu si học pháp, như Kinh, Ứng tụng, Giải thuyết, Kệ tụng, Cảm hứng ngữ, Như thị ngữ, Bổn sanh, Vị tằng hữu pháp, Phương quảng. Sau khi học các pháp này, họ không quán sát ý nghĩa những pháp ấy với trí tuệ. Những pháp ấy, vì ý nghĩa không được trí tuệ quán sát, nên không trở thành rõ ràng. Họ học các pháp chỉ vì lợi ích, muốn chỉ trích người khác, chỉ vì lợi ích, muốn khoái khẩu biện luận, và họ không đạt được mục tiêu mà sự học pháp hướng đến. Những pháp ấy vì nắm giữ sai lạc nên đưa họ đến bất hạnh, đau khổ lâu dài. Vì sao vậy? Này các Tỷ-kheo, vì nắm giữ sai lạc các pháp.`, ref: "MN 22 – Kinh Ví Dụ Con Rắn", url: "../mn/mn22.html#content" },

{ text: `Chư Tỷ-kheo, ví như một người ưa muốn rắn nước, tìm cầu rắn nước, đi khắp chỗ để tìm rắn nước. Người đó thấy một con rắn nước lớn, và người đó bắt con rắn ấy ở lưng hay ở đuôi. Con rắn ấy có thể quay lại cắn người đó nơi tay, nơi cánh tay hay ở một phần nào khác của cơ thể, và người đó có thể do nhân này mà bị chết hay bị đau khổ gần như chết. Vì sao vậy? Chư Tỷ-kheo, vì nắm bắt con rắn một cách sai lạc. Cũng vậy này các Tỷ-kheo, ở đây, một số người ngu si học pháp. họ học các pháp chỉ vì lợi ích, muốn chỉ trích người khác, chỉ vì lợi ích, muốn khoái khẩu biện luận, và họ không đạt được mục tiêu mà sự học pháp hướng đến. Những pháp ấy vì nắm giữ sai lạc nên đưa họ đến bất hạnh, đau khổ lâu dài.`, ref: "MN 22 – Kinh Ví Dụ Con Rắn", url: "../mn/mn22.html#content" },

{ text: `Cũng vậy, chư Tỷ-kheo, ở đây, một số Thiện nam tử học pháp … chư Tỷ-kheo, vì khéo nắm giữ các pháp vậy. Do vậy, này các Tỷ-kheo, hãy hiểu rõ ý nghĩa lời Ta thuyết giảng và thọ trì như vậy. Nếu có ai không hiểu rõ ý nghĩa lời Ta thuyết giảng thì ở nơi đây, các Ông hãy hỏi Ta hay hỏi những bậc Tỷ-kheo trí thức.`, ref: "MN 22 – Kinh Ví Dụ Con Rắn", url: "../mn/mn22.html#content" },

{ text: `Chư Tỷ-kheo, Ta sẽ giảng pháp cho các Ông, ví như chiếc bè để vượt qua, không phải để nắm giữ lấy. Ở đây, chư Tỷ-kheo, người đó sau khi vượt qua bờ bên kia, có thể suy nghĩ: “Chiếc bè này lợi ích nhiều cho ta. Nhờ chiếc bè này, ta tinh tấn dùng tay chân đã vượt qua bờ bên kia một cách an toàn. Nay ta hãy kéo chiếc bè này lên trên bờ đất khô, hay nhận chìm xuống nước, và đi đến chỗ nào ta muốn”. Chư Tỷ-kheo, làm như vậy, người đó làm đúng sở dụng chiếc bè ấy. Cũng vậy, này chư Tỷ-kheo, Ta thuyết pháp như chiếc bè để vượt qua, không phải để nắm giữ lấy. Chư Tỷ-kheo, các Ông cần hiểu ví dụ cái bè. Chánh pháp còn phải bỏ đi, huống nữa là phi pháp.`, ref: "MN 22 – Kinh Ví Dụ Con Rắn", url: "../mn/mn22.html#content" },

{ text: `Và này chư Tỷ-kheo, có vị Ða văn Thánh đệ tử đi đến yết kiến các bậc Thánh, thuần thục các pháp bậc Thánh, tu tập pháp các bậc Thánh, đi đến yết kiến các bậc Chơn nhơn, thuần thục pháp các bậc Chơn nhơn, tu tập pháp các bậc Chơn nhơn, xem sắc pháp: “Cái này không phải của tôi, cái này không phải là tôi, cái này không phải tự ngã của tôi”, xem cảm thọ: “Cái này không phải của tôi, cái này không phải là tôi, cái này không phải tự ngã của tôi”, xem tưởng: “Cái này không phải của tôi, cái này không phải là tôi, cái này không phải tự ngã của tôi”, xem các hành: “Cái này không phải của tôi, cái này không phải là tôi, cái này không phải tự ngã của tôi”, xem cái gì được thấy, được nghe, được cảm xúc, được ý thức, được đạt tới, được tìm cầu, được ý suy tư: “Cái này không phải của tôi, cái này không phải là tôi, cái này không phải tự ngã của tôi”, và bất cứ kiến xứ nào đều nói rằng: “Ðây là thế giới, đây là tự ngã, sau khi chết tôi sẽ thường còn, thường hằng, thường trú, không biến chuyển, tôi sẽ trú như thế này cho đến mãi mãi”, xem như vậy là: “Cái này không phải của tôi, cái này không phải là tôi, cái này không phải tự ngã của tôi”. Vị này do quán sát như vậy, đối với sự vật chẳng thật có nên không có lo âu, phiền muộn.`, ref: "MN 22 – Kinh Ví Dụ Con Rắn", url: "../mn/mn22.html#content" },

{ text: `Này Tỷ-kheo, ở đây, có người nghĩ như sau: “Cái gì chắc chắn đã là của tôi, nay chắc chắn không còn là của tôi. Cái gì chắc chắn có thể là của tôi, chắc chắn tôi không được cái ấy”. Người đó sầu muộn, than vãn, khóc lóc, đấm ngực, đi đến bất tỉnh. Này Tỷ-kheo, như vậy, có cái không thực có ở ngoài, có thể gây lo âu, phiền muộn.`, ref: "MN 22 – Kinh Ví Dụ Con Rắn", url: "../mn/mn22.html#content" },

{ text: `Này các Tỷ-kheo, các Ông có thể nắm giữ một vật sở hữu gì, và vật sở hữu được nắm giữ ấy sẽ thường còn, thường hằng, thường trú, không chuyển biến, có thể trú như thế này mãi mãi không? Chư Tỷ-kheo, các Ông có thể thấy một vật sở hữu nào được nắm giữ và vật sở hữu được nắm giữ ấy sẽ thường còn, thường hằng, thường trú, không chuyển biến, có thể trú như thế này mãi mãi không?\n—Bạch Thế Tôn, không.\n—Lành thay, này các Tỷ-kheo. Này các Tỷ-kheo, Ta cũng không thấy... có thể trú như thế này mãi mãi.`, ref: "MN 22 – Kinh Ví Dụ Con Rắn", url: "../mn/mn22.html#content" },

{ text: `Chư Tỷ-kheo, Ta nói như vậy, thuyết như vậy, một số Sa-môn, Bà-la-môn xuyên tạc Ta một cách phi chơn, hồ đồ, hư vọng, không thực: “Sa-môn Gotama chủ trương chủ nghĩa hư vô, đề cao đoạn diệt, hủy diệt, sự tiêu diệt các hữu tình”. Nhưng này các Tỷ-kheo, Ta không là như vậy, Ta không nói như vậy. Chư Tỷ-kheo, xưa cũng như nay, Ta chỉ nói lên sự khổ và sự diệt khổ. Chư Tỷ-kheo, nếu ở đây những người khác nhiếc mắng, phỉ báng, làm cho Như Lai tức giận, thì này các Tỷ-kheo, ở đây, Như Lai không có sân hận, không có bất mãn, tâm không phẫn nộ. Chư Tỷ-kheo, nếu ở đây, những người khác cung kính, tôn trọng, lễ bái, cúng dường Như Lai, thì này các Tỷ-kheo, ở đây Như Lai không có hoan hỷ, sung sướng, Tâm không thích thú. Chư Tỷ-kheo, nếu những người khác cung kính, tôn trọng, lễ bái, cúng dường Như Lai, thì này các Tỷ-kheo, ở đây Như Lai suy nghĩ: “Ðây là điều xưa kia đã từng biết rõ: ở đây là trách nhiệm Ta phải làm”.`, ref: "MN 22 – Kinh Ví Dụ Con Rắn", url: "../mn/mn22.html#content" },

{ text: `Này các Tỷ-kheo, nếu có những người khác nhiếc mắng, phỉ báng, làm cho các Ông tức giận, ở đây các Ông chớ có sân hận, bất mãn, tâm chớ khởi phẫn nộ. Do vậy, này các Tỷ-kheo, nếu có những người khác cung kính, tôn trọng, lễ bái cúng dường các Ông, thì ở đây, các Ông chớ có hoan hỷ, sung sướng, tâm sanh thích thú. Do vậy, này các Tỷ-kheo, nếu có những người khác cung kính, tôn trọng, lễ bái cúng dường các Ông, thì ở đây, các Ông hãy suy nghĩ: “Ðây là điều xưa kia đã từng biết rõ, đây là những trách nhiệm ta phải làm”.`, ref: "MN 22 – Kinh Ví Dụ Con Rắn", url: "../mn/mn22.html#content" },

{ text: `Này các Tỷ-kheo, cái gì không phải của các Ông, các Ông hãy từ bỏ. Các Ông từ bỏ, sẽ đưa lại hạnh phúc, an lạc lâu dài cho các Ông. Chư Tỷ-kheo, cái gì không phải của các Ông? Chư Tỷ-kheo, sắc không phải của các Ông, hãy từ bỏ sắc. Các Ông từ bỏ sắc sẽ đưa lại hạnh phúc, an lạc lâu dài cho các Ông. Chư Tỷ-kheo, thọ không phải của các Ông, hãy từ bỏ thọ. Các Ông từ bỏ thọ sẽ đưa lại hạnh phúc, an lạc lâu dài cho các Ông. Chư Tỷ-kheo, tưởng không phải của các Ông, hãy từ bỏ tưởng. Các Ông từ bỏ tưởng sẽ đem lại hạnh phúc, an lạc lâu dài cho các Ông. Chư Tỷ-kheo, các hành không phải của các Ông, hãy từ bỏ các hành. Các Ông từ bỏ các hành sẽ đem lại hạnh phúc, an lạc lâu dài cho các Ông. Chư Tỷ-kheo, thức không phải của các Ông, hãy từ bỏ thức. Các Ông từ bỏ thức sẽ đem lại hạnh phúc, an lạc lâu dài cho các Ông.`, ref: "MN 22 – Kinh Ví Dụ Con Rắn", url: "../mn/mn22.html#content" },

{ text: `Chư Tỷ-kheo, các Ông nghĩ thế nào? Trong rừng Jetavana này, nếu có người thâu lượm cỏ, cây, nhành, lá rồi đốt hay làm với chúng tùy theo ý muốn, các Ông có nghĩ chăng? Người ấy thâu lượm chúng ta, đốt chúng ta hay làm với chúng ta tùy theo ý muốn?\n—Bạch Thế Tôn, không. Vì sao vậy? Bạch Thế Tôn, vì nó không phải tự ngã hay không phải sở thuộc của ngã.\n—Cũng vậy, này các Tỷ-kheo, cái gì không phải của các Ông, các Ông hãy từ bỏ. Các Ông từ bỏ sẽ đưa lại hạnh phúc, an lạc lâu dài cho các Ông. Chư Tỷ-kheo, và cái gì không phải của các Ông? Chư Tỷ-kheo, sắc không phải của các Ông, hãy từ bỏ sắc. Các Ông từ bỏ sắc sẽ đưa lại hạnh phúc, an lạc lâu dài cho các Ông. Thọ … tưởng … hành … thức không phải của các Ông, hãy từ bỏ thức. Các Ông từ bỏ thức sẽ đem lại hạnh phúc, an lạc lâu dài cho các Ông.`, ref: "MN 22 – Kinh Ví Dụ Con Rắn", url: "../mn/mn22.html#content" },

{ text: `Chư Tỷ-kheo, pháp được Ta khéo giảng, làm cho tỏ lộ, làm cho khai thông, làm cho khai thị, được loại trừ các vải quấn cũ. Chư Tỷ-kheo, vì pháp được Ta khéo giảng, làm tỏ lộ, làm cho khai thông, làm cho khai thị, được loại trừ các vải quấn cũ, nên những vị Tỷ-kheo, là bậc A-la-hán, các lậu hoặc đã tận, tu hành thành mãn, việc nên làm đã làm, gánh nặng đã đặt xuống, lý tưởng đã thành đạt, hữu kiết sử đã đoạn trừ, được giải thoát nhờ chánh trí, vòng luân chuyển (sanh tử) của những vị này không thể chỉ bày.`, ref: "MN 22 – Kinh Ví Dụ Con Rắn", url: "../mn/mn22.html#content" },

{ text: `Chư Tỷ-kheo, pháp được Ta khéo giảng, làm cho tỏ lộ, làm cho khai thông, làm cho khai thị, được loại trừ các vải quấn cũ. Chư Tỷ-kheo, vì pháp được Ta khéo giảng, làm cho tỏ lộ, làm cho khai thông, làm cho khai thị, được loại trừ các vải quấn cũ, nên những vị nào chỉ đủ lòng tin nơi Ta, chỉ đủ lòng thương mến đối với Ta, thì tất cả những vị ấy được hướng về chư Thiên.`, ref: "MN 22 – Kinh Ví Dụ Con Rắn", url: "../mn/mn22.html#content" },
{ text: `Này các Tỷ-kheo, lành thay khi Thiện nam tử các Người, vì lòng tin xuất gia, từ bỏ gia đình, sống không gia đình, cùng nhau hội họp để luận bàn đạo pháp. Này các Tỷ-kheo, khi các Người hội họp với nhau, có hai việc cần phải làm: luận bàn đạo pháp hay giữ sự im lặng của bậc Thánh.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Này các Tỷ-kheo, có hai loại tầm cầu này: Thánh cầu và phi Thánh cầu. Chư Tỷ-kheo, và thế nào là phi Thánh cầu? Ở đây, này các Tỷ-kheo, có người tự mình bị sanh lại tầm cầu cái bị sanh, tự mình bị già lại tìm cầu cái bị già, tự mình bị bệnh … tự mình bị chết … tự mình bị sầu … tự mình bị ô nhiễm lại tầm cầu cái bị ô nhiễm. Này các Tỷ-kheo, cái gì theo các Người gọi là bị sanh? Này các Tỷ-kheo, vợ con là bị sanh; đầy tớ nam, đầy tớ nữ là bị sanh; dê và cừu là bị sanh; gà và heo là bị sanh; voi, bò, ngựa đực, ngựa cái là bị sanh; vàng và bạc là bị sanh. Này các Tỷ-kheo, những chấp thủ ấy bị sanh, và người ấy lại nắm giữ, tham đắm, mê say chúng, tự mình bị sanh lại tầm cầu cái bị sanh.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Và này các Tỷ-kheo, cái gì theo các Người gọi là bị sầu? Này các Tỷ-kheo, vợ con là bị sầu; đầy tớ nam, đầy tớ nữ là bị sầu; dê và cừu là bị sầu, gà và heo là bị sầu; voi, bò, ngựa đực, ngựa cái là bị sầu. Này các Tỷ-kheo, những chấp thủ ấy là bị sầu, và người ấy lại nắm giữ, tham đắm, mê say chúng, tự mình bị sầu lại tìm cầu cái bị sầu.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là Thánh cầu? Ở đây, này các Tỷ-kheo, có người tự mình bị sanh, sau khi biết rõ sự nguy hại của bị sanh, tìm cầu cái vô sanh, vô thượng an ổn khỏi các khổ ách, Niết-bàn; tự mình bị già, sau khi biết rõ sự nguy hại của bị già, tìm cầu cái không già, vô thượng an ổn khỏi các khổ ách, Niết-bàn; tự mình bị bệnh … cái không bệnh … tự mình bị chết … cái bất tử … tự mình bị sầu … cái không sầu … tự mình bị ô nhiễm, sau khi biết rõ sự nguy hại của ô nhiễm, tìm cầu cái không ô nhiễm, vô thượng an ổn khỏi các khổ ách, Niết-bàn. Này các Tỷ-kheo, như vậy, gọi là Thánh cầu.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Này các Tỷ-kheo, Ta cũng vậy, trước khi Giác Ngộ, khi chưa chứng Chánh Ðẳng Giác, khi còn là Bồ-tát, tự mình bị sanh lại tìm cầu cái bị sanh, tự mình bị già, lại tìm cầu cái bị già, tự mình bị bệnh … tự mình bị chết … tự mình bị sầu” … tự mình bị ô nhiễm lại tìm cầu cái bị ô nhiễm. Này các Tỷ-kheo, rồi Ta suy nghĩ như sau: “Tại sao Ta, tự mình bị sanh lại tìm cầu cái bị sanh, tự mình bị già … (như trên) … tự mình bi ô nhiễm lại tìm cầu cái bị ô nhiễm? Vậy Ta, tự mình bị sanh, sau khi biết rõ sự nguy hại của bị sanh, hãy tìm cầu cái không sanh, vô thượng an ổn khỏi các khổ ách, Niết-bàn; tự mình bị già … cái không già … tự mình bị bệnh … cái không bệnh … tự mình bị chết … cái bất tử … tự mình bị sầu … cái không sầu … tự mình bi ô nhiễm, sau khi biết rõ sự nguy hại của cái bị nhiễm, hãy tìm cầu cái không ô nhiễm, vô thượng an ổn khỏi các khổ ách, Niết-bàn.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Rồi này các Tỷ-kheo, sau một thời gian, khi Ta còn trẻ, niên thiếu, tóc đen nhánh, đầy đủ huyết khí của tuổi thanh xuân, trong thời vàng son cuộc đời, mặc dầu cha mẹ không bằng lòng, nước mắt đầy mặt, than khóc, Ta cạo bỏ râu tóc, đắp áo cà-sa, xuất gia, từ bỏ gia đình, sống không gia đình.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Này các Tỷ-kheo, Alāra Kālāma là Ðạo Sư của Ta, lại đặt Ta, đệ tử của vị ấy ngang hàng với mình, và tôn sùng Ta với sự tôn sùng tối thượng. Này các Tỷ-kheo, rồi Ta tự suy nghĩ: “Pháp này không hướng đến yểm ly, không hướng đến ly tham, không hướng đến đoạn diệt, không hướng đến an tịnh, không hướng đến thượng trí, không hướng đến giác ngộ, không hướng đến Niết-bàn, mà chỉ đưa đến sự chứng đạt Vô sở hữu xứ”. Như vậy này các Tỷ-kheo, Ta không tôn kính pháp này, và từ bỏ pháp ấy, Ta bỏ đi.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Này các Tỷ-kheo, Ta, kẻ đi tìm cái gì chí thiện, tìm cầu vô thượng tối thắng an tịnh đạo lộ, tuần tự du hành tại nước Magadha và đến tại tụ lạc Uruvela. Tại đây, Ta thấy một địa điểm khả ái, một khóm rừng thoải mái, có con sông trong sáng chảy gần, với một chỗ lội qua dễ dàng khả ái, và xung quanh có làng mạc bao bọc dễ dàng đi khất thực. Này các Tỷ-kheo, rồi Ta tự nghĩ: “Thật là một địa điểm khả ái, một khóm rừng thoải mái, có con sông trong sáng chảy gần, với một chỗ lội qua dễ dàng khả ái, và xung quanh có làng mạc bao bọc dễ dàng đi khất thực. Thật là một chỗ vừa đủ cho một Thiện nam tử tha thiết tinh cần có thể tinh tấn”. Và này các Tỷ-kheo, Ta ngồi xuống tại chỗ ấy và nghĩ: “Thật là vừa đủ để tinh tấn”.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Này các Tỷ-kheo, rồi Ta suy nghĩ như sau: “Pháp này do Ta chứng được, thật là sâu kín, khó thấy, khó chứng, tịch tịnh, cao thượng, siêu lý luận, vi diệu, chỉ người trí mới hiểu thấu. Còn quần chúng này thì ưa ái dục, khoái ái dục, ham thích ái dục. Ðối với quần chúng ưa ái dục, khoái ái dục, ham thích ái dục, thật khó mà thấy được định lý Idapaccàyata Paticcasamuppada (Y Tánh Duyên Khởi Pháp); sự kiện này thật khó thấy; tức là sự tịnh chỉ tất cả hành, sự trừ bỏ tất cả sanh y, ái diệt, ly tham, đoạn diệt, Niết-bàn.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Sao Ta nói Chánh pháp,\nÐược chứng ngộ khó khăn?\nNhững ai còn tham sân,\nKhó chứng ngộ pháp này.\n\nÐi ngược dòng, thâm diệu,\nKhó thấy, thật tế nhị,\nKẻ ái nhiễm vô minh,\nKhông thấy được pháp này.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Xưa tại Magadha,\nHiện ra pháp bất tịnh,\nPháp do tâm cấu uế,\nDo suy tư tác thành.\nHãy mỡ tung mở rộng,\nCánh cửa bất tử này.\nHãy để họ nghe Pháp,\nBậc Thanh tịnh Chứng Ngộ.\n\nNhư đứng trên tảng đá,\nTrên đỉnh núi tột cao\nCó người đứng nhìn xuống,\nÐám chúng sanh quây quần.\nCũng vậy, ôi Thiện Thệ,\nBậc Biến Nhãn cùng khắp,\nLeo lên ngôi lâu đài,\nXây dựng bằng Chánh pháp\nBậc Thoát Ly sầu muộn,\nNhìn xuống đám quần sanh,\nBị sầu khổ áp bức,\nBị sanh già chi phối,\n\nÐứng lên vị Anh Hùng,\nBậc Chiến Thắng chiến trường.\nVị trưởng đoàn lữ khách,\nBậc Thoát Ly nợ nần.\nHãy đi khắp thế giới,\nBậc Thế Tôn Chánh Giác!\nHãy thuyết vi diệu pháp,\nNgười nghe sẽ thâm hiểu!`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Này các Tỷ-kheo, sau khi biết được lời Phạm thiên yêu cầu, vì lòng từ bi đối với chúng sanh, với Phật nhãn, Ta nhìn quanh thế giới. Này các Tỷ-kheo, với Phật nhãn, Ta thấy có hạng chúng sanh ít nhiễm bụi đời, nhiều nhiễm bụi đời, có hạng lợi căn, độn căn, có hạng thiện tánh, ác tánh, có hạng dễ dạy, khó dạy, và một số ít thấy sự nguy hiểm phải tái sanh thế giới khác và sự nguy hiểm làm những hành động lỗi lầm. Như trong hồ sen xanh, hồ sen hồng hay hồ sen trắng có một số hoa sen xanh, sen hồng, hay sen trắng sanh ra dưới nước, lớn lên dưới nước, không vượt lên khỏi mặt nước, được nuôi dưỡng dưới nước. Có một hoa sen xanh, sen hồng hay sen trắng sanh ra dưới nước, lớn lên dưới nước, sống vươn lên tới mặt nước. Có một số hoa sen xanh, sen hồng hay sen trắng sanh ra dưới nước, lớn lên dưới nước, vươn lên khỏi mặt nước, không bị nước đẫm ướt.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Cửa bất tử rộng mở,\nCho những ai chịu nghe.\nHãy từ bỏ tín tâm,\nKhông chính xác của mình.\nTự nghĩ đến phiền toái,\nTa đã không muốn giảng,\nTối thượng vi diệu pháp,\nGiữa chúng sanh loài Người.\n(Ôi Phạm thiên)`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Này các Tỷ-kheo, rồi Ta tự suy nghĩ: “Ta sẽ thuyết pháp cho ai đầu tiên, ai sẽ mau hiểu Chánh pháp này?” Này các Tỷ-kheo, rồi Ta tự nghĩ: “Nay có Alāra Kālāma là bậc trí thức, đa văn, sáng suốt, đã từ lâu sống ít nhiễm bụi đời. Ta hãy thuyết pháp đầu tiên cho Alāra Kālāma, vị này sẽ mau hiểu Chánh pháp này”. Này các Tỷ-kheo, rồi chư Thiên đến Ta và nói như sau: “Bạch Thế Tôn, Alāra Kālāma đã mệnh chung bảy ngày rồi”. Rồi tri kiến khởi lên nơi Ta: “Alāra Kālāma đã mệnh chung bảy ngày rồi”. Này các Tỷ-kheo, Ta nghĩ: “Thật là một thiệt hại lớn cho Alāra Kālāma: Nếu nghe pháp này, Alāra Kālāma sẽ mau thâm hiểu”.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `—Này các Tỷ-kheo, Như Lai là bậc A-la-hán, Chánh Ðẳng Giác. Hãy lóng tai, Pháp bất tử đã chứng được, Ta giảng dạy, Ta thuyết pháp. Sống đúng theo lời khuyến giáo, các Ông không bao lâu, sau khi tự tri, tư chứng, tự đạt được ngay trong hiện tại mục đích vô thượng của phạm hạnh mà các Thiện nam tử xuất gia, từ bỏ gia đình, sống không gia đình, các Ông sẽ an trú”.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Này các Tỷ-kheo, có năm dục trưởng dưỡng. Thế nào là năm? Các sắc do mắt nhận thức, sắc này khả ái, khả hỷ, khả lạc, khả ý, kích thích lòng dục, hấp dẫn. Các tiếng do tai nhận thức … (như trên) … các hương do mũi nhận thức … các vị do lưỡi nhận thức … các xúc do thân cảm xúc là khả ái, khả hỷ, khả lạc, khả ý, kích thích lòng dục, hấp dẫn. Này các Tỷ-kheo, như vậy, là năm dục trưởng dưỡng.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Này các Tỷ-kheo, những Sa-môn hay Bà-la-môn nào bị trói buộc, bị tham đắm, bị mê say bởi năm dục trưởng dưỡng này, không thấy sự nguy hại của chúng, không biết rõ sự xuất ly khỏi chúng, mà thọ dụng chúng, những vị ấy cần phải được hiểu là: “Các Người đã rơi vào bất hạnh, đã rơi vào tai họa, đã bị Ác ma sử dụng như ý muốn”. Này các Tỷ-kheo, như một con nai sống trong rừng bị sập bẫy nằm xuống, con nai ấy cần phải được hiểu là: “Nó đã rơi vào bất hạnh, đã rơi vào tai họa, đã bị thợ săn sử dụng như ý muốn. Khi người thợ săn đến, con nai không thể bỏ đi như ý muốn. Này các Tỷ-kheo, cũng vậy, những vị Sa-môn hay Bà-la-môn nào bị trói buộc … (như trên) … đã bị Ác ma sử dụng như ý muốn.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Này các Tỷ-kheo, những Sa-môn hay Bà-la-môn nào không bị trói buộc, không bị tham đắm, không bị mê say bởi năm dục trưởng dưỡng này, thấy sự nguy hại của chúng, biết rõ sự xuất ly khỏi chúng, và thọ dụng chúng, những vị ấy cần phải được hiểu là: “Các Người không rơi vào bất hạnh, không rơi vào tai họa, không bị Ác ma sử dụng như ý muốn”. Này các Tỷ-kheo, như một con nai sống trong rừng, không bị sập bẫy phải nằm xuống, con nai ấy cần phải được hiểu là: “Nó không rơi vào bất hạnh, nó không rơi vào tai họa, nó không bị người thợ săn sử dụng như ý muốn”. Khi người thợ săn đến, con nai có thể bỏ đi như ý muốn. Này các Tỷ-kheo, cũng vậy, những Sa-môn hay Bà-la-môn nào không bị trói buộc … không bị Ác ma sử dụng như ý muốn.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Chư Tỷ-kheo, ví như con nai sống trong rừng, đi qua đi lại trong rừng, an tâm nó đi, an tâm nó đứng, an tâm nó ngồi, an tâm nó nằm. Tại sao vậy? Này các Tỷ-kheo, vì nó vượt khỏi tầm tay của người thợ săn. Cũng vậy, này các Tỷ-kheo, một Tỷ-kheo ly dục, ly ác bất thiện pháp chứng và trú Thiền thứ nhất, một trạng thái hỷ lạc, do ly dục sanh, có tầm có tứ. Này các Tỷ-kheo, Tỷ-kheo ấy được gọi là: một vị đã làm Ác Ma mù mắt, đã diệt trừ mọi vết tích, đã vượt khỏi tầm mắt Ác ma.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },

{ text: `Sau khi thấy bằng trí tuệ, các lậu hoặc được đoạn trừ. Này các Tỷ-kheo, Tỷ-kheo ấy được gọi là một vị đã làm Ác ma mù mắt, đã diệt trừ mọi vết tích, đã vượt khỏi tầm mắt Ác ma. Vị ấy đã vượt khỏi mọi triền phược ở đời. An tâm vị ấy đi, an tâm vị ấy đứng, an tâm vị ấy ngồi, an tâm vị ấy nằm. Vì sao vậy? Này các Tỷ-kheo, vì vị ấy vượt khỏi tầm tay của Ác ma.`, ref: "MN 26 – Kinh Thánh Cầu", url: "../mn/mn26.html#content" },
{ text: `Chư Hiền, nếu những người khác xử sự với Tỷ-kheo không có hoàn hảo, không có tốt đẹp, không có khả ái, hoặc dùng tay xúc chạm, hoặc dùng đá xúc chạm, hoặc dùng gậy xúc chạm, hoặc dùng gươm xúc chạm, vị ấy tuệ tri như sau: “Sự thể của thân này là như vậy, nên tay có thể xúc chạm, đá có thể xúc chạm, gậy có thể xúc chạm, gươm có thể xúc chạm. Thế Tôn đã dạy như sau trong ví dụ cái cưa: “Chư Tỷ-kheo, nếu có kẻ trộm cướp hạ tiện lấy cái cưa hai lưỡi cắt từng phần tay và chân. Nếu ai ở đây sanh ý phẫn nộ, người ấy không làm đúng lời Ta dạy”. Ta sẽ tinh cần, tinh tấn, không giải đãi. Niệm được an trú không có loạn niệm, thân thể được khinh an, không dao động, tâm được định tĩnh nhất tâm. Nay mặc cho tay xúc chạm thân này, mặc cho đá xúc chạm thân này, mặc cho gậy xúc chạm thân này, mặc cho gươm xúc chạm thân này, lời dạy chư Phật cần phải được thực hành.`, ref: "MN 28 – Ðại Kinh Dụ Dấu Chân Voi", url: "../mn/mn28.html#content" },

{ text: `Chư Hiền, nếu có những người khác mắng nhiếc, chỉ trích, chọc tức, nhiễu não Tỷ-kheo, vị ấy biết rõ như sau: “Khổ thọ khởi lên nơi tôi này thuộc tai xúc chạm; thọ này do nhân duyên, không phải không do nhân duyên. Do nhân duyên gì? Do nhân duyên xúc vậy”. Vị ấy thấy xúc là vô thường; vị ấy thấy thọ là vô thường; vị ấy thấy tưởng là vô thường; vị ấy thấy hành là vô thường; vị ấy thấy thức là vô thường; tâm của vị này hoan hỷ, thích thú, tịnh chỉ, quyết định, tùy thuộc giới đối tượng.`, ref: "MN 28 – Ðại Kinh Dụ Dấu Chân Voi", url: "../mn/mn28.html#content" },

{ text: `Thế Tôn đã nói như sau: “Ai thấy được lý duyên khởi, người ấy thấy được pháp; ai thấy được pháp, người ấy thấy được lý duyên khởi”. Những pháp này do duyên khởi lên chính là năm thủ uẩn. Sự tham dục, chấp trước, tham đắm, mê say trong năm thủ uẩn này tức là khổ tập; sự nhiếp phục tham dục, sự từ bỏ tham dục tức là sự khổ diệt”. Cho đến mức độ này, Chư Hiền, Tỷ-kheo đã làm rất nhiều.`, ref: "MN 28 – Ðại Kinh Dụ Dấu Chân Voi", url: "../mn/mn28.html#content" },


{ text: `Ở đây, này các Tỷ-kheo, có Thiện nam tử do lòng tin xuất gia, từ bỏ gia đình, sống không gia đình: “Ta bị chìm đắm trong sanh, già, chết, sầu, bi, khổ, ưu, não, bị chìm đắm trong đau khổ, bị chi phối bởi đau khổ. Rất có thể, toàn bộ khổ uẩn này có thể chấm dứt được”. Vị ấy xuất gia như vậy, được lợi dưỡng, tôn kính, danh vọng. Do lợi dưỡng, tôn kính, danh vọng này, vị ấy hoan hỷ, mãn nguyện. Do lợi dưỡng, tôn kính, danh vọng này, vị ấy khen mình, chê người: “Ta được lợi dưỡng như vậy, được danh vọng như vậy. Còn các Tỷ-kheo khác ít được biết đến, ít có uy quyền”. Vị ấy, vì lợi dưỡng, tôn kính, danh vọng này, trở thành mê say, tham đắm, phóng dật. Do sống phóng dật, vị ấy bị đau khổ.`, ref: "MN 29 – Ðại kinh Thí dụ Lõi cây", url: "../mn/mn29.html#content" },

{ text: `Như vậy, này các Tỷ-kheo, phạm hạnh này không phải vì lợi ích, lợi dưỡng, danh vọng, không phải vì lợi ích thành tựu giới đức, không phải vì lợi ích thành tựu thiền định, không phải vì lợi ích tri kiến. Và này các Tỷ-kheo, tâm giải thoát bất động chính là mục đích của phạm hạnh này, là lõi cây, là mục tiêu cuối cùng của phạm hạnh.`, ref: "MN 29 – Ðại kinh Thí dụ Lõi cây", url: "../mn/mn29.html#content" },


{ text: `Cũng vậy, này Bà-la-môn, ở đây, có người do lòng tin xuất gia, từ bỏ gia đình, sống không gia đình: “Ta bị chìm đắm trong sanh, già, chết, sầu, bi, khổ, ưu, não, bị chìm đắm trong đau khổ, bị chi phối bởi đau khổ, Rất có thể toàn bộ khổ uẩn này có thể chấm dứt”. Vị ấy xuất gia như vậy, được lợi dưỡng, tôn kính, danh vọng. Do lợi dưỡng, tôn kính, danh vọng này, vị ấy hoan hỷ, tự mãn. Do lợi dưỡng, tôn kính, danh vọng này, vị ấy khen mình, chê người: “Ta được lợi dưỡng như vậy, được danh vọng như vậy, còn các Tỷ-kheo khác ít được biết đến, ít có uy quyền”. Và vị ấy không phát khởi lòng ao ước và không cố gắng tinh tấn để chứng được các pháp khác cao thượng hơn, thù thắng hơn những lợi dưỡng, tôn kính, danh vọng. Vị ấy trở thành biếng nhác và thụ động. Này Bà-la-môn, ví như một người muốn được lõi cây, tìm cầu lõi cây. Trong khi đi tìm lõi cây, trước một cây lớn, đứng thẳng, có lõi cây, người ấy bỏ qua lõi cây, bỏ qua giác cây, bỏ qua vỏ trong, bỏ qua vỏ ngoài, chặt cành lá, lấy chúng mang đi, tưởng rằng đó là lõi cây. Và người ấy sẽ không đạt được mục đích mà lõi cây có thể thành tựu. Này Bà-la-môn, Ta nói rằng người này giống như ví dụ ấy.`, ref: "MN 30 – Tiểu kinh Thí dụ Lõi cây", url: "../mn/mn30.html#content" },
{ text: `Bạch Thế Tôn, ở đây chúng con nghĩ như sau: “Thật lợi ích thay cho ta, thật khéo lợi ích thay cho ta, khi ta được sống với các vị đồng phạm hạnh như vậy”. Bạch Thế Tôn, do vậy, đối với các vị đồng phạm hạnh này, con khởi lên từ thân nghiệp, trước mặt và sau lưng, con khởi lên từ khẩu nghiệp, trước mặt và sau lưng, con khởi lên từ ý nghiệp, trước mặt và sau lưng. Bạch Thế Tôn, do vậy, chúng con nghĩ như sau: “Ta hãy từ bỏ tâm của ta và sống thuận theo tâm của những Tôn giả này”. Bạch Thế Tôn, con từ bỏ tâm của con và sống thuận theo tâm của những Tôn giả ấy. Bạch Thế Tôn, chúng con tuy khác thân nhưng giống như đồng một tâm. Bạch Thế Tôn, như vậy chúng con sống hòa hợp, hoan hỷ với nhau, như nước với sữa, sống nhìn nhau với cặp mắt thiện cảm.`, ref: "MN 31 – Tiểu Kinh Rừng Sừng Bò", url: "../mn/mn31.html#content" },

{ text: `Này Dīgha, nếu gia đình nào, ba Thiện nam tử này xuất gia, từ bỏ gia đình, sống không gia đình, nghĩ đến ba Thiện nam tử này với tâm niệm hoan hỷ, thì gia đình ấy sẽ được an lạc, hạnh phúc lâu dài. Này Dīgha, nếu bà con quyến thuộc của gia đình mà ba Thiện nam tử này xuất gia, từ bỏ gia đình, sống không gia đình, nghĩ đến ba Thiện nam tử này với tâm niệm hoan hỷ, thì bà con quyến thuộc của gia đình ấy sẽ được an lạc, hạnh phúc lâu dài. Này Dīgha, hãy xem ba Thiện nam tử này sống như thế nào? —Vì hạnh phúc cho chúng sanh, vì an lạc cho chúng sanh, vì lòng thương tưởng cho đời, vì hạnh phúc, vì an lạc cho chư Thiên và loài Người.`, ref: "MN 31 – Tiểu Kinh Rừng Sừng Bò", url: "../mn/mn31.html#content" },
{ text: `Tôn giả Ānanda hãy đến đây, thiện lai, Tôn giả Ānanda, vị thị giả Thế Tôn, vị hầu cận Thế Tôn. Này Hiền giả Ānanda, khả ái thay khu rừng Gosinga! Ðêm rằm sáng trăng, cây Ta-la trổ hoa cùng khắp, hương trời như được tỏa rộng khắp nơi. Này Hiền giả Ānanda, hạng Tỷ-kheo nào có thể làm chói sáng khu rừng Gosinga?\nỞ đây, này Hiền giả Sāriputta, Tỷ-kheo nghe nhiều, gìn giữ điều đã nghe, tích tụ điều đã nghe. Những pháp sơ thiện, trung thiện, hậu thiện, văn nghĩa cụ túc, nói lên phạm hạnh hoàn toàn thanh tịnh, những pháp ấy được vị ấy nghe nhiều và gìn giữ kỹ, được lập lại lớn tiếng, được ý tư duy, được tri kiến khéo quán sát; vị ấy thuyết pháp cho bốn hội chúng với văn cú viên dung, lưu loát, với mục đích đoạn trừ mọi tùy miên. Này Hiền giả Sāriputta, hạng Tỷ-kheo này có thể làm sáng chói khu rừng Gosinga.`, ref: "MN 32 – Ðại Kinh Rừng Sừng Bò", url: "../mn/mn32.html#content" },

{ text: `Ở đây, này Hiền giả Sāriputta, Tỷ-kheo ưa thích đời sống tịnh cư, vui thú đời sống tịnh cư, nội tâm tu pháp, tịnh chỉ, không gián đoạn thiền định, thành tựu quán hạnh, luôn luôn lui tới các chỗ không tịch. Này Hiền giả Sāriputta, hạng Tỷ-kheo này có thể làm sáng chói khu rừng Gosinga.`, ref: "MN 32 – Ðại Kinh Rừng Sừng Bò", url: "../mn/mn32.html#content" },

{ text: `Ở đây, này Hiền giả Sāriputta, Tỷ-kheo, tự mình sống ở rừng núi và tán thán đời sống ở rừng núi, tự mình sống khất thực, và tán thán đời sống khất thực, tự mình mặc y phấn tảo và tán thán hạnh mặc y phấn tảo, tự mình sống với ba y và tán thán hạnh ba y, tự mình sống thiểu dục và tán thán hạnh thiểu dục, tự mình sống biết đủ và tán thán hạnh biết đủ, tự mình sống độc cư và tán thán hạnh sống độc cư, tự mình sống không nhiễm thế tục và tán thán hạnh không nhiễm thế tục, tự mình tinh cần, tinh tấn và tán thán hạn tinh cần, tinh tấn, tự mình thành tựu giới hạnh và tán thán sự thành tựu giới hạnh, tự mình thành tựu Thiền định và tán thán sự thành tựu thiền định, tự mình thành tựu trí tuệ và tán thán sự thành tựu trí tuệ, tự mình thành tựu giải thoát và tán thán sự thành tựu giải thoát, tự mình thành tựu giải thoát tri kiến và tán thán sự thành tựu giải thoát tri kiến. Này Hiền giả Sāriputta, hạng Tỷ-kheo như vậy có thể làm sáng chói khu rừng Gosinga.`, ref: "MN 32 – Ðại Kinh Rừng Sừng Bò", url: "../mn/mn32.html#content" },

{ text: `Ở đây, này Hiền giả Moggallāna, Tỷ-kheo điều phục được tâm, không phải Tỷ-kheo không điều phục được tâm. An trú quả nào vị ấy muốn an trú vào buổi sáng, vị ấy an trú quả ấy vào buổi sáng; an trú quả nào vị ấy muốn an trú vào buổi trưa, vị ấy an trú quả ấy buổi trưa; an trú quả nào vị ấy muốn an trú vào buổi chiều, vị ấy an trú quả ấy vào buổi chiều. Này Hiền giả Moggallāna, hạng Tỷ-kheo như vậy có thể làm sáng chói khu rừng Gosinga.`, ref: "MN 32 – Ðại Kinh Rừng Sừng Bò", url: "../mn/mn32.html#content" },

{ text: `Này Sāriputta, các Ông hãy nghe Ta nói hạng Tỷ-kheo nào có thể làm sáng chói khu rừng Gosinga. Ở đây, này Sāriputta, Tỷ-kheo, sau buổi ăn, sau khi đi khất thực về, ngồi kiết-già, lưng thẳng, đặt niệm trước mặt, và nghĩ rằng: “Ta sẽ không bỏ ngồi kiết-già này cho đến khi tâm của ta được khéo giải thoát các lậu hoặc, không có chấp thủ”. Này Sāriputta, hạng Tỷ-kheo như vậy có thể làm sáng chói khu rừng Gosinga.`, ref: "MN 32 – Ðại Kinh Rừng Sừng Bò", url: "../mn/mn32.html#content" },
{ text: `Này các Tỷ-kheo, thế nào là công việc đáng phải làm hơn nữa? “Thân hành chúng ta phải được thanh tịnh, minh chánh, cởi mở, không có tỳ vết, che giấu. Nhưng chúng ta không vì thân hành thanh tịnh ấy, khen mình, chê người”. Như vậy, này các Tỷ-kheo, các Ông cần phải tu tập. Này các Tỷ-kheo, các Ông có thể khởi lên ý kiến: “Chúng ta đã thành tựu tàm quý, thân hành chúng ta thanh tịnh, đến mức độ này, như vậy là vừa đủ; đến mức độ này, như vậy đã làm xong. Chúng ta đã đạt được mục đích Sa-môn hạnh. Chúng ta không có gì phải làm hơn nữa”. Và cho đến mức độ ấy, các Ông có thể tự thỏa mãn. Này các Tỷ-kheo, Ta khuyến cáo các Ông. Này các Tỷ-kheo, Ta tuyên bố cho các ông: Khi các Ông hướng đến mục đích Sa-môn hạnh, chớ có từ bỏ mục đích này, khi đang còn công việc đáng phải làm hơn nữa.`, ref: "MN 39 – Ðại Kinh Xóm Ngựa", url: "../mn/mn39.html#content" },

{ text: `Này các Tỷ-kheo, thế nào là các công việc đáng phải làm hơn nữa? “Chúng ta phải hộ trì các căn. Khi mắt thấy sắc, không nắm giữ tướng chung, không nắm giữ tướng riêng. Những nguyên nhân gì khiến con mắt không được chế ngự, khiến tham ái, ưu bi, các ác, bất thiện pháp khởi lên, chúng ta sẽ tự chế ngự nguyên nhân ấy, hộ trì con mắt, thực hành sự hộ trì con mắt. Khi tai nghe tiếng … mũi ngửi hương … lưỡi nếm vị … thân cảm xúc … ý nhận thức các pháp, không nắm giữ tướng chung, không nắm giữ tướng riêng. Những nguyên nhân gì khiến ý căn không được chế ngự, khiến tham ái, ưu, bi, các ác, bất thiện pháp khởi lên, chúng ta sẽ tự chế ngự nguyên nhân ấy, hộ trì ý căn, thực hành sự hộ trì ý căn”.`, ref: "MN 39 – Ðại Kinh Xóm Ngựa", url: "../mn/mn39.html#content" },

{ text: `Này các Tỷ-kheo, thế nào là các công việc đáng phải làm hơn nữa? “Chúng ta phải biết tiết độ trong ăn uống, với chánh tư duy, chúng ta thọ thực, không phải để vui đùa, không phải để đam mê, không phải để trang sức, không phải để tự làm đẹp mình, mà chỉ để thân này được sống lâu và được bảo dưỡng, để (thân này) khỏi bị thương hại, để hỗ trợ phạm hạnh, nghĩ rằng: “Như vậy chúng ta diệt trừ các cảm thọ cũ và không cho khởi lên cảm thọ mới, và chúng ta sẽ không có lỗi lầm, sống được an ổn”. Như vậy, này các Tỷ-kheo, các Ông cần phải tu tập.`, ref: "MN 39 – Ðại Kinh Xóm Ngựa", url: "../mn/mn39.html#content" },

{ text: `Này các Tỷ-kheo, thế nào là các công việc đáng phải làm hơn nữa? “Chúng ta phải chú tâm cảnh giác. Ban ngày đi kinh hành (hay) trong lúc ngồi, chúng ta phải tẩy sạch tâm tư khỏi các pháp chướng ngại. Ban đêm canh một đi kinh hành (hay) trong lúc ngồi, chúng ta phải tẩy sạch tâm tư khỏi các pháp chướng ngại. Ban đêm canh giữa, chúng ta phải nằm dáng nằm con sư tử, nghiêng bên hông tay phải, một chân đặt trên chân kia, chánh niệm tỉnh giác, tâm nghĩ đến lúc thức dậy lại. Ban đêm canh đầu thức dậy, đi kinh hành (hay) trong lúc ngồi, chúng ta phải tẩy sạch tâm tư khỏi các pháp chướng ngại”. Như vậy, này các Tỷ-kheo, các Ông cần phải tu tập.`, ref: "MN 39 – Ðại Kinh Xóm Ngựa", url: "../mn/mn39.html#content" },

{ text: `Nhờ hiểu biết như vậy, nhận thức như vậy, tâm của vị ấy thoát khỏi dục lậu, thoát khỏi hữu lậu, thoát khỏi vô minh lậu. Ðối với tự thân đã giải thoát như vậy, khởi lên sự hiểu biết: “Ta đã giải thoát”. Vị ấy tuệ tri: “Sanh đã tận, phạm hạnh đã thành, những việc cần làm đã làm xong, sau đời hiện tại không có đời sống nào khác nữa”.`, ref: "MN 39 – Ðại Kinh Xóm Ngựa", url: "../mn/mn39.html#content" },

{ text: `Này các Tỷ-kheo, như thế nào, Tỷ-kheo là Sa-môn? Vị này đã làm cho dừng lại các ác, các pháp bất thiện, những pháp này ô nhiễm, đưa đến tái sanh, đáng sợ hãi, đem lại khổ quả, đưa đến sanh, già, chết trong tương lai. Như vậy, này các Tỷ-kheo, Tỷ-kheo là Sa-môn.`, ref: "MN 39 – Ðại Kinh Xóm Ngựa", url: "../mn/mn39.html#content" },

{ text: `Và này các Tỷ-kheo, như thế nào là Tỷ-kheo đã tắm sạch sẽ? Vị này đã tắm gội sạch sẽ các ác, các pháp bất thiện, những pháp này ô nhiễm, đưa đến tái sanh, đáng sợ hãi, đem lại khổ quả, đưa đến sanh già, chết trong tương lai. Như vậy, này các Tỷ-kheo, Tỷ-kheo đã tắm sạch sẽ.`, ref: "MN 39 – Ðại Kinh Xóm Ngựa", url: "../mn/mn39.html#content" },

{ text: `Và này các Tỷ-kheo, như thế nào là Tỷ-kheo đã biết và hiểu rõ? Vị này đã biết và hiểu rõ các ác, các pháp bất thiện, những pháp này ô nhiễm, đưa đến tái sanh, đáng sợ hãi, đem lại khổ quả, đưa đến sanh già, chết trong tương lai. Như vậy, này các Tỷ-kheo, Tỷ-kheo đã biết và hiểu rõ.`, ref: "MN 39 – Ðại Kinh Xóm Ngựa", url: "../mn/mn39.html#content" },

{ text: `Và này các Tỷ-kheo, như thế nào là Tỷ-kheo có học? Vị này đã tiêu diệt các ác, các pháp bất thiện, những pháp này ô nhiễm, đưa đến tái sanh, đáng sợ hãi, đem lại khổ quả, đưa đến sanh già, chết trong tương lai. Như vậy, này các Tỷ-kheo, Tỷ-kheo có học.`, ref: "MN 39 – Ðại Kinh Xóm Ngựa", url: "../mn/mn39.html#content" },

{ text: `Và này các Tỷ-kheo, như thế nào là Tỷ-kheo được gọi là bậc Thánh? Vị này đã làm cho xa lìa các ác pháp bất thiện, những pháp này ô nhiễm, đưa đến tái sanh, đáng sợ hãi, đem lại khổ quả, đưa đến sanh già, chết trong tương lai. Như vậy, này các Tỷ-kheo, Tỷ-kheo được gọi là bậc Thánh.`, ref: "MN 39 – Ðại Kinh Xóm Ngựa", url: "../mn/mn39.html#content" },

{ text: `Và này các Tỷ-kheo, như thế nào là Tỷ-kheo được gọi là bậc A-la-hán? Vị này đã làm cho xa lìa các ác, các pháp bất thiện, những pháp này ô nhiễm, đưa đến tái sanh, đáng sợ hãi, đem lại khổ quả, đưa đến sanh già, chết trong tương lai. Như vậy, này các Tỷ-kheo, Tỷ-kheo là bậc A-la-hán.`, ref: "MN 39 – Ðại Kinh Xóm Ngựa", url: "../mn/mn39.html#content" },
{ text: `Này các Tỷ-kheo, các Ông đã chấp nhận rằng, trong khi các Ông sống cạnh tranh, luận tranh, đấu tranh, đả thương nhau bằng binh khí miệng lưỡi, trong khi ấy, không có an trú từ thân hành đối với các vị đồng phạm hạnh cả trước mặt lẫn sau lưng, không có an trú từ khẩu hành đối với các vị đồng phạm hạnh cả trước mặt lẫn sau lưng, không có an trú từ ý hành đối với các vị đồng phạm hạnh cả trước mặt lẫn sau lưng. Như vậy, này các kẻ mê mờ kia, do biết gì, do thấy gì, các Ông sống cạnh tranh, luận tranh, đấu tranh, đả thương nhau với những binh khí miệng lưỡi; và các Ông không tự thông cảm nhau, không chấp nhận thông cảm, không tự hòa giải nhau, không chấp nhận hòa giải. Như vậy, này các kẻ mê mờ kia, các Ông sẽ phải chịu bất hạnh, đau khổ trong một thời gian dài.`, ref: "MN 48 – Kinh Kosambiya", url: "../mn/mn48.html#content" },

{ text: `—Này các Tỷ-kheo, có sáu pháp này cần phải ghi nhớ, tạo thành tương ái, tạo thành tương kính, đưa đến hòa đồng, đưa đến vô tranh luận, hòa hợp, nhất trí. Thế nào là sáu? Ở đây, này các Tỷ-kheo, Tỷ-kheo an trú từ thân hành, an trú từ khẩu hành, an trú từ ý hành đối với các vị đồng phạm hạnh cả trước mặt lẫn sau lưng. Pháp này cần phải ghi nhớ, tạo thành tương ái, tạo thành tương kính, đưa đến hòa đồng, đưa đến không tranh luận, hòa hợp, nhất trí.`, ref: "MN 48 – Kinh Kosambiya", url: "../mn/mn48.html#content" },

{ text: `Này các Tỷ-kheo, đối với các tài vật nhận được đúng pháp, hợp pháp, cho đến những tài vật thâu nhận chỉ trong bình bát, Tỷ-kheo không phải là người không san sẻ, các tài vật nhận được như vậy, phải là người san sẻ dùng chung với các vị đồng phạm hạnh có giới đức. Pháp này cần phải ghi nhớ, tạo thành tương ái, tạo thành tương kính, đưa đến hòa đồng, đưa đến không tranh luận, hòa hợp, nhất trí.`, ref: "MN 48 – Kinh Kosambiya", url: "../mn/mn48.html#content" },

{ text: `Này các Tỷ-kheo, đối với các giới luật không có vi phạm, không có tỳ vết, không có vẩn đục, không có uế tạp, giải thoát, được người trí tán thán, không bị chấp trước, đưa đến thiền định, Tỷ-kheo sống thành tựu trong các giới luật ấy với các vị đồng phạm hạnh cả trước mặt lẫn sau lưng. Pháp này cần phải ghi nhớ, tạo thành tương ái, tạo thành tương kính, đưa đến hòa đồng, đưa đến không tranh luận, hòa hợp, nhất trí.`, ref: "MN 48 – Kinh Kosambiya", url: "../mn/mn48.html#content" },

{ text: `Này các Tỷ-kheo, đối với các tri kiến thuộc về bậc Thánh có khả năng hướng thượng, khiến người thực hành chân chánh diệt tận khổ đau, Tỷ-kheo, sống thành tựu tri kiến như vậy, cùng với các đồng phạm hạnh cả trước mặt lẫn sau lưng. Pháp này cần phải ghi nhớ, tạo thành tương ái, tạo thành tương kính, đưa đến hòa đồng, đưa đến không tranh luận, hòa hợp, nhất trí.`, ref: "MN 48 – Kinh Kosambiya", url: "../mn/mn48.html#content" },
{ text: `Này Kandaraka, trong chúng Tỷ-kheo này, có những Tỷ-kheo là bậc hữu học, giới luật kiên trì, giới hạnh kiên trì, sáng suốt, hạnh nghiệp sáng suốt, sống với tâm khéo an trú Bốn Niệm xứ. Thế nào là bốn? Ở đây này Kandaraka, Tỷ-kheo sống quán thân trên thân, nhiệt tâm tỉnh giác, chánh niệm, để nhiếp phục tham ưu trên đời; sống quán thọ trên các cảm thọ, nhiệt tâm tỉnh giác, chánh niệm, để nhiếp phục tham ưu trên đời; sống quán tâm trên tâm, nhiệt tâm, tỉnh giác, chánh niệm để nhiếp phục tham ưu trên đời; sống quán pháp trên các pháp, nhiệt tâm, tỉnh giác, chánh niệm, để nhiếp phục tham ưu trên đời.`, ref: "MN 51 – Kinh Kandaraka", url: "../mn/mn51.html#content" },

{ text: `Thật vi diệu thay, bạch Thế Tôn! Thật hy hữu thay, bạch Thế Tôn! Bốn Niệm xứ này đã được Thế Tôn khéo trình bày, để chúng sanh được thanh tịnh, để sầu bi được vượt qua, để khổ ưu được diệt trừ, để chánh lý được thành đạt, để Niết-bàn được chứng ngộ. Bạch Thế Tôn, chúng con là hàng tại gia, mặc đồ trắng, thỉnh thoảng chúng con sống khéo an trú tâm vào Bốn Niệm xứ này. Ở đây, Bạch Thế Tôn, chúng con sống quán thân trên thân, quán thọ trên các cảm thọ...quán pháp trên các pháp, nhiệt tâm, tỉnh giác, chánh niệm, để nhiếp phục tham ưu trên đời.`, ref: "MN 51 – Kinh Kandaraka", url: "../mn/mn51.html#content" },

{ text: `Thật vi diệu thay, bạch Thế Tôn! Thật hy hữu thay, bạch Thế Tôn! Bạch Thế Tôn, Thế Tôn hiểu được hạnh phúc và sự bất hạnh của chúng sanh trong khi loài người sống trong sự rối ren như vậy, trong sự cặn bã như vậy, trong sự xảo quyệt như vậy. Bạch Thế Tôn, rối ren thay như loài người. Bạch Thế Tôn, cởi mở thay như loài thú vật. Bạch Thế Tôn, con có thể nhiếp phục con voi, một cách khiến con voi ấy mỗi khi đi hay đến Campā, liền trình bày mọi sự gian dối, giả dối, xảo trá, xảo quyệt. Nhưng bạch Thế Tôn, những người đầy tớ của chúng con, những người phục dịch, những người làm công, thân hành họ làm một cách, khẩu hành họ làm một cách khác, ý hành họ làm một cách khác nữa.`, ref: "MN 51 – Kinh Kandaraka", url: "../mn/mn51.html#content" },
{ text: `Và này Mahānāma, thế nào là vị Thánh đệ tử thành tựu giới hạnh? Ở đây, này Mahānāma, vị Thánh đệ tử có giới hạnh, sống chế ngự với sự chế ngự của giới bổn Pātimokkha, đầy đủ oai nghi chánh hạnh, thấy nguy hiểm trong những lỗi nhỏ nhặt, thọ lãnh và tu học các học pháp. Này Mahānāma, như vậy là vị Thánh đệ tử thành tựu giới hạnh.`, ref: "MN 53 – Kinh Hữu học", url: "../mn/mn53.html#content" },

{ text: `Và này Mahānāma, thế nào là vị Thánh đệ tử hộ trì các căn? Ở đây, này Mahānāma, vị Thánh đệ tử, khi mắt thấy sắc, không nắm giữ tướng chung, không nắm giữ tướng riêng. Những nguyên nhân gì vì nhãn căn không được chế ngự, khiến tham ưu, các ác, bất thiện pháp khởi lên, vị ấy tự chế ngự nguyên nhân ấy, hộ trì nhãn căn, thực hành sự hộ trì nhãn căn. Khi tai nghe tiếng … mũi ngửi hương … lưỡi nếm vị … thân cảm xúc … ý nhận thức các pháp, vị ấy không nắm giữ tướng chung, không nắm giữ tướng riêng. Những nguyên nhân gì vì ý căn không được chế ngự, khiến tham ưu, các ác, bất thiện pháp khởi lên, vị ấy chế ngự nguyên nhân ấy, hộ trì ý căn, thực hành sự hộ trì ý căn. Này Mahānāma, như vậy là vị Thánh đệ tử hộ trì các căn.`, ref: "MN 53 – Kinh Hữu học", url: "../mn/mn53.html#content" },

{ text: `Và này Mahānāma, thế nào là vị Thánh đệ tử biết tiết độ trong ăn uống? Ở đây, này Mahānāma, vị Thánh đệ tử chơn chánh giác sát, thọ dụng món ăn, không phải để vui đùa, không phải để đam mê, không phải để trang sức, không phải để tự làm đẹp mình, chỉ để thân này được duy trì, được bảo dưỡng, khỏi bị gia hại, để chấp trì Phạm hạnh, nghĩ rằng: “Như vậy ta diệt trừ các cảm thọ cũ và không cho khởi lên các cảm thọ mới; và ta sẽ không phạm lỗi lầm, sống được an ổn”. Này Mahānāma, như vậy là vị Thánh đệ tử biết tiết độ trong sự ăn uống.`, ref: "MN 53 – Kinh Hữu học", url: "../mn/mn53.html#content" },

{ text: `Và này Mahānāma, thế nào là vị Thánh đệ tử chú tâm cảnh giác? Ở đây, này Mahānāma, vị Thánh đệ tử ban ngày trong khi đi kinh hành và trong khi đang ngồi, gột sạch tâm trí khỏi các chướng ngại pháp, ban đêm trong canh một, trong khi đi kinh hành và trong khi đang ngồi, gột sạch tâm trí khỏi các chướng ngại pháp, ban đêm trong canh giữa, vị này nằm xuống phía hông bên phải, như dáng nằm con sư tử, chân gác trên chân với nhau, chánh niệm tỉnh giác, hướng niệm đến lúc ngồi dậy lại. Ban đêm trong canh cuối, khi đã thức dậy, trong khi đi kinh hành và trong khi đang ngồi, gột sạch tâm trí khỏi các chướng ngại pháp. Này Mahānāma, như vậy là vị Thánh đệ tử chú tâm cảnh giác.`, ref: "MN 53 – Kinh Hữu học", url: "../mn/mn53.html#content" },

{ text: `Ở đây, này Mahānāma, vị Thánh đệ tử có lòng tin, có lòng tin ở sự giác ngộ của Như Lai: Ngài là Thế Tôn, bậc A-la-hán, Chánh Ðẳng Giác, Minh Hạnh Túc, Thiện Thệ, Thế Gian Giải, Vô Thượng Sĩ, Ðiều Ngự Trượng Phu, Thiên Nhân Sư, Phật, Thế Tôn.`, ref: "MN 53 – Kinh Hữu học", url: "../mn/mn53.html#content" },

{ text: `Ở đây, này Mahānāma, vị Thánh đệ tử có lòng tàm, tự xấu hổ vì thân ác hạnh, khẩu ác hạnh, ý ác hạnh, tự xấu hổ vì thành tựu ác, bất thiện pháp. Vị này có lòng quý, tự sợ hãi vì thân ác hạnh, khẩu ác hạnh, ý ác hạnh, tự sợ hãi vì thành tựu ác, bất thiện pháp.`, ref: "MN 53 – Kinh Hữu học", url: "../mn/mn53.html#content" },

{ text: `Ở đây, này Mahānāma, vị Thánh đệ tử là vị đa văn, nhớ nghĩ những điều đã nghe, tích tụ những điều đã nghe. Những pháp nào, sơ thiện, trung thiện, hậu thiện, có nghĩa, có văn, nói lên phạm hạnh hoàn toàn đầy đủ thanh tịnh, những pháp như vậy, vị ấy nghe nhiều, thọ trì, đọc tụng bằng lời, được ý suy tư, được chánh kiến thể nhập.`, ref: "MN 53 – Kinh Hữu học", url: "../mn/mn53.html#content" },

{ text: `Ở đây, này Mahānāma, vị Thánh đệ tử sống tinh cần tinh tấn, trừ bỏ các pháp bất thiện, thành tựu các thiện pháp, nỗ lực, kiên trì, không từ bỏ gánh nặng đối với các thiện pháp. Vị ấy có niệm, thành tựu niệm tuệ tối thắng, nhớ lại, nhớ lại nhiều lần những gì đã làm từ lâu, đã nói từ lâu. Vị ấy có trí tuệ, thành tựu trí tuệ về sanh diệt, thành tựu Thánh thể nhập đưa đến chơn chánh đoạn tận khổ đau. Này Mahānāma, như vậy vị Thánh đệ tử thành tựu diệu pháp.`, ref: "MN 53 – Kinh Hữu học", url: "../mn/mn53.html#content" },
{ text: `Vị ấy xuất gia như vậy, hành trì các học giới và hạnh sống của các Tỷ-kheo, từ bỏ sát sanh, tránh xa sát sanh, bỏ trượng, bỏ kiếm, biết xấu hổ, sợ hãi, có lòng từ, sống thương xót đến hạnh phúc tất cả chúng sanh và loài hữu tình. Vị ấy từ bỏ lấy của không cho, tránh xa lấy của không cho, chỉ mong những vật đã cho, tự sống thanh tịnh, không có trộm cướp. Vị ấy từ bỏ đời sống không Phạm hạnh, sống theo Phạm hạnh, sống đời sống viễn ly, tránh xa dâm dục hạ liệt.`, ref: "MN 60 – Kinh Không Gì Chuyển Hướng", url: "../mn/mn60.html#content" },
{ text: `Rồi Thế Tôn, sau khi để một ít nước còn lại trong chậu nước (rửa chân), bảo Tôn giả Rāhula\n—Này Rāhula, Ông có thấy một ít nước còn lại này trong chậu nước không?\n—Thưa vâng, bạch Thế Tôn.\n—Cũng ít vậy, này Rāhula, là Sa-môn hạnh của những người nào biết mà nói láo, không có tàm quý.`, ref: "MN 61 – Kinh Giáo Giới Rahula", url: "../mn/mn61.html#content" },

{ text: `Rồi Thế Tôn, sau khi đổ đi chút ít nước (rửa chân) còn lại ấy rồi bảo Rāhula\n—Này Rāhula, Ông có thấy chút ít nước còn lại ấy bị đổ đi không?\n—Thưa vâng, bạch Thế Tôn.\n—Cũng đổ đi vậy, này Rāhula, là Sa-môn hạnh của những người nào biết mà nói láo, không có tàm quý.`, ref: "MN 61 – Kinh Giáo Giới Rahula", url: "../mn/mn61.html#content" },

{ text: `Này Rāhula, Ông nghĩ thế nào? Mục đích của cái gương là gì?\n—Bạch Thế Tôn, mục đích là để phản tỉnh.\n—Cũng vậy, này Rāhula, sau khi phản tỉnh nhiều lần, hãy hành thân nghiệp. Sau khi phản tỉnh nhiều lần, hãy hành khẩu nghiệp. Sau khi phản tỉnh nhiều lần, hãy hành ý nghiệp.`, ref: "MN 61 – Kinh Giáo Giới Rahula", url: "../mn/mn61.html#content" },

{ text: `Này Rāhula, khi Ông muốn làm một thân nghiệp gì, hãy phản tỉnh thân nghiệp ấy như sau: “Thân nghiệp này của ta có thể đưa đến tự hại, có thể đưa đến hại người, có thể đưa đến hại cả hai; thời thân nghiệp này là bất thiện, đưa đến đau khổ, đem đến quả báo đau khổ”. Này Rāhula, nếu trong khi phản tỉnh, Ông biết: “Thân nghiệp này, ta muốn làm. Thân nghiệp này của ta có thể đưa đến tự hại, có thể đưa đến hại người, có thể đưa đến hại cả hai; thời thân nghiệp này là bất thiện, đưa đến đau khổ, đem đến quả báo đau khổ”. Một thân nghiệp như vậy, này Rāhula, Ông nhất định chớ có làm. Này Rāhula, nếu sau khi phản tỉnh, ông biết: “Thân nghiệp này ta muốn làm. Thân nghiệp này của ta không có thể đưa đến tự hại, không có thể đưa đến hại người, không có thể đưa đến hại cả hai; thời thân nghiệp này là thiện, đưa đến an lạc, đem đến quả báo an lạc”. Một thân nghiệp như vậy, này Rāhula, Ông nên làm.`, ref: "MN 61 – Kinh Giáo Giới Rahula", url: "../mn/mn61.html#content" },
{ text: `Này Rāhula, hãy tu tập sự tu tập niệm hơi thở vô, hơi thở ra. Này Rāhula, tu tập niệm hơi thở vô hơi thở ra, làm cho sung mãn, được quả lớn, được lợi ích lớn.`, ref: "MN 62 – Đại Kinh Giáo Giới Rahula", url: "../mn/mn62.html#content" },

{ text: `Này Rāhula, hãy tu tập sự tu tập như đất. Này Rāhula, do tu tập sự tu tập như đất, các xúc khả ái, không khả ái được khởi lên, không có nắm giữ tâm, không có tồn tại. Này Rāhula, ví như trên đất người ta quăng đồ tịnh, quăng đồ không tịnh, quăng phân uế, quăng nước tiểu, nhổ nước miếng, quăng mủ và quăng máu; tuy vậy đất không lo âu, không dao động, hay không nhàm chán; cũng vậy, này Rāhula, hãy tu tập như đất. Này Rāhula, do tu tập sự tu tập như đất, các xúc khả ái, không khả ái được khởi lên, không có nắm giữ tâm, không có tồn tại.`, ref: "MN 62 – Đại Kinh Giáo Giới Rahula", url: "../mn/mn62.html#content" },

{ text: `Này Rāhula, hãy tu tập sự tu tập như nước. Này Rāhula, do tu tập sự tu tập như nước, các xúc khả ái, không khả ái được khởi lên, không có nắm giữ tâm, không có tồn tại. Này Rāhula, ví như trong nước người ta rửa đồ tịnh, rửa đồ không tịnh, rửa sạch phân uế, rửa sạch nước tiểu, rửa sạch nước miếng, rửa sạch mủ, rửa sạch máu; tuy vậy nước không lo âu, không dao động, không nhàm chán; cũng vậy, này Rāhula, hãy tu tập sự tụ tập như nước, các xúc khả ái, không khả ái được khởi lên, không có nắm giữ tâm, không có tồn tại.`, ref: "MN 62 – Đại Kinh Giáo Giới Rahula", url: "../mn/mn62.html#content" },

{ text: `Này Rāhula, hãy tu tập sự tu tập như lửa. Này Rāhula, do tu tập sự tu tập như lửa, các xúc khả ái, không khả ái được khởi lên, không có nắm giữ tâm, không có tồn tại. Này Rāhula, ví như lửa đốt các đồ tịnh, đốt các đồ không tịnh, đốt phân uế, đốt nước tiểu, đốt nước miếng, đốt mủ, đốt máu; tuy vậy lửa không lo âu, không dao động, không nhàm chán; cũng vậy, này Rāhula, hãy tu tập sự tu tập như lửa, các xúc khả ái, không khả ái được khởi lên, không có nắm giữ tâm, không có tồn tại.`, ref: "MN 62 – Đại Kinh Giáo Giới Rahula", url: "../mn/mn62.html#content" },

{ text: `Này Rāhula, hãy tu tập sự tu tập như gió. Này Rāhula, do tu tập sự tu tập như gió, các xúc khả ái, không khả ái được khởi lên, không có nắm giữ tâm, không có tồn tại. Này Rāhula, như gió thổi các đồ tịnh, thổi các đồ không tịnh, thổi phân uế, thổi nước tiểu, thổi nước miếng, thổi mủ, thổi máu, tuy vậy gió không lo âu, không dao động, không nhàm chán; cũng vậy, này Rāhula, hãy tu tập sự tu tập như gió, các xúc khả ái, không khả ái được khởi lên, không có nắm giữ tâm, không có tồn tại.`, ref: "MN 62 – Đại Kinh Giáo Giới Rahula", url: "../mn/mn62.html#content" },

{ text: `Này Rāhula, hãy tu tập sự tu tập như hư không. Này Rāhula, do tu tập sự tu tập như hư không, các xúc khả ái, không khả ái được khởi lên, không có nắm giữ tâm, không có tồn tại. Này Rāhula, ví như hư không không bị trú tại một chỗ nào; cũng vậy, này Rāhula, hãy tu tập sự tu tập như hư không. Này Rāhula, do tu tập sự tu tập như hư không, các xúc khả ái không, khả ái được khởi lên, không có nắm giữ tâm, không có tồn tại.`, ref: "MN 62 – Đại Kinh Giáo Giới Rahula", url: "../mn/mn62.html#content" },

{ text: `Này Rāhula, hãy tu tập sự tu tập về lòng từ. Này Rāhula, do tu tập sự tu tập về lòng từ, cái gì thuộc sân tâm sẽ được trừ diệt. Này Rāhula, hãy tu tập sự tu tập về lòng bi. Này Rāhula, do tu tập sự tu tập về lòng bi, cái gì thuộc hại tâm sẽ được trừ diệt. Này Rāhula, hãy tu tập sự tu tập về hỷ. Này Rāhula, do tu tập sự tu tập về hỷ, cái gì thuộc bất lạc sẽ được trừ diệt. Này Rāhula, hãy tu tập sự tu tập về xả. Này Rāhula, do tu tập sự tu tập về xả, cái gì thuộc hận tâm sẽ được trừ diệt.`, ref: "MN 62 – Đại Kinh Giáo Giới Rahula", url: "../mn/mn62.html#content" },

{ text: `Này Rāhula, hãy tu tập sự tu tập về bất tịnh. Này Rāhula, do tu tập sự tu tập về bất tịnh, cái gì thuộc tham ái được trừ diệt. Này Rāhula, hãy tu tập sự tu tập về vô thường. Này Rāhula, do tu tập sự tu tập về vô thường, cái gì thuộc ngã mạn được trừ diệt.`, ref: "MN 62 – Đại Kinh Giáo Giới Rahula", url: "../mn/mn62.html#content" },
{ text: `Và này Ānanda, thế nào là con đường, thế nào là lộ trình đưa đến sự đoạn trừ năm hạ phần kiết sử? Ở đây, này Ānanda, Tỷ-kheo do viễn ly các sanh y (Upadhiviveka), do đoạn trừ các bất thiện pháp, do làm cho an tịnh thân thô ác hành một cách toàn diện, ly dục, ly bất thiện pháp, chứng và trú Thiền thứ nhất, một trạng thái hỷ lạc do ly dục sanh, có tầm, có tứ.`, ref: "MN 64 – Ðại Kinh Màlunkyà", url: "../mn/mn64.html#content" },

{ text: `Vị ấy chánh quán mọi sắc pháp, thọ pháp, tưởng pháp, hành pháp, thức pháp là vô thường, khổ, như bệnh, như cục bướu, như mũi tên, như điều bất hạnh, như bệnh chướng, như kẻ địch, như phá hoại, là không, là vô ngã. Vị này giải thoát tâm khỏi các pháp ấy. Sau khi giải thoát tâm khỏi các pháp ấy, vị ấy tập trung tâm vào bất tử giới (Amatadhatu) và nghĩ rằng: “Ðây là tịch tịnh, đây là vi diệu, tức là sự an chỉ tất cả hành, sự xả ly tất cả sanh y, sự ái diệt, vô tham, đoạn diệt, Niết-bàn”. Nếu an trú vững chắc ở đây, vị này đạt đến sự đoạn tận các lậu hoặc. Nếu vị ấy không đạt đến sự đoạn tận các lậu hoặc, thời do sự tham pháp, hỷ pháp của mình, thời do sự đoạn tận năm hạ phần kiết sử, vị ấy được hóa sanh, nhập Niết-bàn ở đấy, không phải trở lui đời này nữa.`, ref: "MN 64 – Ðại Kinh Màlunkyà", url: "../mn/mn64.html#content" },
{ text: `Này các Tỷ-kheo, Ta ăn chỉ ngồi một lần. Này các Tỷ-kheo, do Ta ăn chỉ ngồi một lần, Ta cảm thấy ít bệnh, ít não, nhẹ nhàng, có sức và lạc trú. Này các Tỷ-kheo, hãy ăn chỉ ngồi một lần. Này các Tỷ-kheo, hãy ăn chỉ ngồi một lần, và các Ông sẽ cảm thấy ít bệnh, ít não, nhẹ nhàng, có sức và lạc trú.`, ref: "MN 65 – Kinh Bhaddali", url: "../mn/mn65.html#content" },

{ text: `Này Bhaddali, thật sự một lỗi lầm đã chiếm đoạt Ông, thật là ngu ngốc, thật là si mê, thật là bất thiện. Trong khi chúng Tỷ-kheo chấp hành học giới đã được Ta chế định, Ông đã tuyên bố sự bất lực của Ông. Này Bhaddali, nếu Ông sau khi thấy một lỗi lầm là một lỗi lầm, và như pháp phát lộ, chúng ta sẽ chấp nhận cho Ông. Vì rằng, này Bhaddali, như vậy là sự lớn mạnh trong giới luật của bậc Thánh, nghĩa là bất cứ ai, sau khi thấy một lỗi lầm là một lỗi lầm, phải như pháp phát lộ và phòng hộ trong tương lai.`, ref: "MN 65 – Kinh Bhaddali", url: "../mn/mn65.html#content" },

{ text: `Ở đây, này Bhaddali, có Tỷ-kheo thực hành trọn vẹn học giới trong giáo pháp bậc Ðạo Sư. Vị ấy suy nghĩ như sau: “Ta hãy sống tại một trú xứ xa vắng, khu rừng, gốc cây, sườn núi, chỗ hoang dã, hang núi, nghĩa địa, tùng lâm, ngoài trời, đống rơm. Và ta có thể chứng được thượng nhân pháp, tri kiến thù thắng xứng đáng bậc Thánh”. Vị ấy sống tại một trú xứ xa vắng, khu rừng, gốc cây, sườn núi, chỗ hoang dã, hang núi, nghĩa địa, tùng lâm, ngoài trời, đống rơm. Khi vị ấy sống viễn ly như vậy, bậc Ðạo Sư không quở trách, các vị đồng Phạm hạnh có trí sau khi quán sát không quở trách, chư Thiên không quở trách, tự mình không quở trách mình. Vị này không bị bậc Ðạo Sư quở trách, không bị các đồng Phạm hạnh sau khi quán sát quở trách, không bị chư Thiên quở trách, không bị mình quở trách mình, nên chứng được thượng nhân pháp, tri kiến thù thắng xứng đáng bậc Thánh.`, ref: "MN 65 – Kinh Bhaddali", url: "../mn/mn65.html#content" },
{ text: `Rồi Tôn giả Udāyi, trong khi độc cư Thiền tịnh, sự suy tư sau đây đã khởi lên trong tâm trí Tôn giả: “Thế Tôn thật sự là vị đã đoạn trừ nhiều khổ pháp cho chúng ta. Thế Tôn thật sự là vị đã mang lại nhiều lạc pháp cho chúng ta. Thế Tôn thật sự là vị đã đoạn trừ nhiều bất thiện pháp cho chúng ta. Thế Tôn thật sự là vị đã mang lại nhiều thiện pháp cho chúng ta”.`, ref: "MN 66 – Kinh Ví Dụ Con Chim Cáy", url: "../mn/mn66.html#content" },

{ text: `Bạch Thế Tôn, thuở trước chúng con thường ăn buổi chiều, buổi sáng, ban ngày và phi thời. Bạch Thế Tôn, thời ấy, Thế Tôn gọi các Tỷ-kheo và bảo: “Này các Tỷ-kheo, hãy từ bỏ ăn ban ngày phi thời”. Bạch Thế Tôn, do vậy con cảm thấy thất vọng, con cảm thấy sầu muộn, nghĩ rằng: “Những món ăn thượng vị loại cứng và loại mềm, các tín chủ cúng dường cho chúng ta ban ngày và phi thời. Nay Thế Tôn dạy chúng ta phải đoạn trừ, bậc Thiện Thệ dạy chúng ta phải từ bỏ”. Bạch Thế Tôn, giữa chúng con, những ai nhìn Thế Tôn với lòng ái mộ, với lòng tôn kính và với lòng tàm quý, liền từ bỏ ăn ban ngày phi thời.`, ref: "MN 66 – Kinh Ví Dụ Con Chim Cáy", url: "../mn/mn66.html#content" },

{ text: `Này Udāyi, ở đây có một số người ngu si; khi Ta nói: “Hãy từ bỏ việc này”, liền nói như sau: “Có sá gì sự việc tiểu tiết, nhỏ mọn này. Sa-môn này đặt quá nặng về cấm đoán đoạn giảm”. Họ không chịu từ bỏ và gây lên bất mãn chống Ta và chống những Tỷ-kheo muốn thực hành học giới. Sự việc ấy, này Udāyi, đối với họ, trở thành một trói buộc mạnh mẽ, một trói buộc vững chắc, một trói buộc kiên cường, một trói buộc không mục nát, một khúc gỗ to lớn.`, ref: "MN 66 – Kinh Ví Dụ Con Chim Cáy", url: "../mn/mn66.html#content" },

{ text: `Ví như, này Udāyi, một người nghèo khổ thấy một Tỷ-kheo trong tịnh xá, tay chân lau rửa sạch sẽ, sau khi ăn buổi cơm ngon lành, đang ngồi trong bóng mát, hướng về tăng thượng tâm. Người ấy suy nghĩ: “An lạc thay, Sa-môn hạnh! Vô bệnh thay, Sa-môn hạnh! Vậy sau khi cạo bỏ râu tóc, đắp áo cà-sa, ta hãy xuất gia, từ bỏ gia đình, sống không gia đình”. Nhưng người ấy không có thể từ bỏ cái chòi ở hư nát, mở toang cho quạ, không đẹp mắt chút nào, không có thể từ bỏ cái giường nằm hư nát, không đẹp mắt chút nào, không có thể từ bỏ các loại gạo lúa cất chứa trong một cái chum không đẹp mắt chút nào, không có thể từ bỏ bà vợ không đẹp mắt chút nào, để có thể sau khi cạo bỏ râu tóc, đắp áo cà-sa, xuất gia, từ bỏ gia đình, sống không gia đình.`, ref: "MN 66 – Kinh Ví Dụ Con Chim Cáy", url: "../mn/mn66.html#content" },

{ text: `Này Udāyi, một gia chủ hay con người gia chủ, giàu có, tài sản lớn, tiền của lớn, vô số vàng bạc, vô số gạo thóc, vô số ruộng nương, vô số đất đai, vô số thê thiếp, vô số đầy tớ nam, vô số nữ tỳ. Vị này thấy một Tỷ-kheo trong một tinh xá, tay chân lau rửa sạch sẽ, sau khi ăn bữa cơm ngon lành, đang ngồi trong bóng mát, hướng về tăng thượng tâm. Vị này suy nghĩ: “An lạc thay, Sa-môn hạnh! Vô bệnh thay, Sa-môn hạnh! Vậy sau khi cạo bỏ râu tóc, đắp áo cà-sa, ta hãy xuất gia, từ bỏ gia đình, sống không gia đình”.`, ref: "MN 66 – Kinh Ví Dụ Con Chim Cáy", url: "../mn/mn66.html#content" },

{ text: `Ở đây, này Udāyi, có người sống, hướng đến sự đoạn trừ sanh y, sự từ bỏ sanh y. Nhưng trong khi vị này sống hướng đến sự đoạn trừ sanh y, sự từ bỏ sanh y, những tư niệm, tư duy liên hệ đến sanh y hiện hành khởi lên. Vị này chấp nhận chúng, không đoạn trừ chúng, không từ bỏ chúng, không chấm dứt chúng, không tiêu diệt chúng. Này Udāyi, Ta nói: “Người này bị trói buộc, không phải không bị trói buộc”. Vì sao vậy? Này Udāyi, sự sai biệt về căn tánh trong người này đã được Ta biết rõ.`, ref: "MN 66 – Kinh Ví Dụ Con Chim Cáy", url: "../mn/mn66.html#content" },

{ text: `Ở đây, này Udāyi, có người sống, hướng đến sự đoạn trừ sanh y, sự từ bỏ sanh y. Nhưng trong khi vị này sống hướng đến sự đoạn trừ sanh y, sự từ bỏ sanh y, các tư niệm điên đảo, các tư niệm, tư duy liên hệ đến sanh y, tùy lúc tùy thời hiện hành khởi lên. Này Udāyi, niệm khởi lên chậm chạp và vị này đoạn trừ niệm ấy một cách mau chóng, từ bỏ, chấm dứt, tiêu diệt (niệm ấy). Này Udāyi, ví như một người nhỏ hai hay ba giọt nước vào một ấm nước đun sôi cả ngày. Này Udāyi giọt nước rơi một cách chậm chạp như bị tiêu diệt, tiêu mất một cách mau chóng. Này Udāyi, Ta nói: “Người này cũng bị trói buộc, không phải không bị trói buộc”. Vì sao vậy? Này Udāyi, sự sai biệt về căn tánh trong người này đã được Ta biết rõ.`, ref: "MN 66 – Kinh Ví Dụ Con Chim Cáy", url: "../mn/mn66.html#content" },

{ text: `Nhưng ở đây, này Udāyi, có người nghĩ rằng: “Sanh y là nguồn gốc của đau khổ”, sau khi biết như vậy, vị ấy thành vô sanh y, giải thoát với sự đoạn diệt sanh y. Này Udāyi, Ta nói: “Người này không bị trói buộc, không phải bị trói buộc”. Vì sao vậy? Này Udāyi, sự sai biệt về căn tánh trong người này đã được Ta biết rõ.`, ref: "MN 66 – Kinh Ví Dụ Con Chim Cáy", url: "../mn/mn66.html#content" },

{ text: `Này Udāyi, có năm dục trưởng dưỡng này. Thế nào là năm? Sắc do mắt nhận thức, khả ái, khả hỷ, khả lạc, khả ý, kích thích lòng dục, hấp dẫn. Tiếng do tai nhận thức, … hương do mũi nhận thức, … vị do lưỡi nhận thức, … xúc do thân cảm xúc, khả ái, khả hỷ, khả lạc, khả ý, kích thích lòng dục, hấp dẫn. Những pháp này, này Udāyi, là năm dục trưởng dưỡng. Này Udāyi, phàm có lạc gì, hỷ gì khởi lên, do duyên năm dục trưởng dưỡng này, lạc hỷ ấy được gọi là dục lạc, ô uế lạc, phàm phu lạc, phi Thánh lạc, không nên thực hiện, không nên tu tập, không nên làm cho sung mãn. Ta nói rằng lạc ấy đáng phải sợ hãi.`, ref: "MN 66 – Kinh Ví Dụ Con Chim Cáy", url: "../mn/mn66.html#content" },

{ text: `Ở đây, này Udāyi, Tỷ-kheo ly dục, ly bất thiện pháp, chứng và trú Thiền thứ nhất, một trạng thái hỷ lạc do ly dục sanh, có tầm, có tứ. Diệt tầm và tứ,...diệt hỷ ưu đã cảm thọ trước, chứng và trú Thiền thứ tư, không khổ, không lạc, xả niệm, thanh tịnh. Như vậy được gọi là yếm ly lạc, độc trú lạc, tịch tịnh lạc, chánh giác lạc, cần phải thực hiện, cần phải tu tập, cần làm cho sung mãn. Ta nói rằng lạc ấy không đáng sợ hãi.`, ref: "MN 66 – Kinh Ví Dụ Con Chim Cáy", url: "../mn/mn66.html#content" },
{ text: `Lành thay, lành thay, các Anuruddha, thật xứng đáng cho các Ông, những Thiện gia nam tử, vì lòng tin xuất gia, từ bỏ gia đình, sống không gia đình, các Ông có hoan hỷ trong Phạm hạnh. Này các Anuruddha, trong khi các Ông với tuổi trẻ tốt đẹp, trong tuổi thanh xuân, với tóc đen nhánh, có thể hưởng thụ các dục lạc, thời các Ông, này các Anuruddha, với tuổi trẻ tốt đẹp, trong tuổi thanh xuân, với tóc đen nhánh, lại xuất gia, từ bỏ gia đình, sống không gia đình. Này các Anuruddha, các Ông không vì mệnh lệnh của vua mà xuất gia, từ bỏ gia đình, sống không gia đình. Các Ông không vì mệnh lệnh của kẻ ăn trộm mà xuất gia, từ bỏ gia đình, sống không gia đình. Các Ông không vì nợ nần, không vì sợ hãi, không vì mất nghề sinh sống mà xuất gia, từ bỏ gia đình, sống không gia đình. Nhưng với tư tưởng như sau: “Ta bị sanh, già, chết, sầu, bi, khổ, não áp bức, bị khổ áp bức, bị khổ chi phối. Tuy vậy, ta mong có thể thấy được sự chấm dứt toàn bộ khổ uẩn này.”`, ref: "MN 68 – Kinh Nalakapāna", url: "../mn/mn68.html#content" },

{ text: `Và xuất gia như vậy, này các Anuruddha, người Thiện gia nam tử cần phải làm gì? Này các Anuruddha, ly dục, ly bất thiện pháp. Nếu không chứng được hỷ lạc hay một trạng thái khác an tịnh hơn, thời dục tham xâm chiếm tâm và an trú, sân xâm chiếm tâm và an trú, hôn trầm thụy miên … trạo cử, hối quá … nghi hoặc … bất lạc … giải đãi xâm chiếm tâm và an trú. Này các Anuruddha, khi chưa ly dục, chưa ly bất thiện pháp, vị ấy không chứng được hỷ lạc hay một trạng thái khác an tịnh hơn. Này các Anuruddha, ly dục, ly bất thiện pháp, vị ấy chứng được hỷ lạc hay một trạng thái khác an tịnh hơn, thời dục tham không xâm chiếm tâm và an trú, sân không xâm chiếm tâm và an trú, hôn trầm thụy miên … trạo cử hối quá … nghi hoặc … bất lạc … giải đãi không xâm chiếm tâm và an trú. Này các Anuruddha, ly dục, ly bất thiện pháp, vị ấy chứng được hỷ lạc hay một trạng thái khác an tịnh hơn.`, ref: "MN 68 – Kinh Nalakapāna", url: "../mn/mn68.html#content" },
{ text: `Này các Tỷ-kheo, Ta không nói rằng trí tuệ được hoàn thành lập tức. Nhưng này các Tỷ-kheo, trí tuệ được hoàn thành nhờ học từ từ, hành từ từ, thực tập từ từ.`, ref: "MN 70 – Kinh Kīṭāgiri", url: "../mn/mn70.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là trí tuệ được hoàn thành nhờ học từ từ, hành từ từ, thực tập từ từ? Ở đây, này các Tỷ-kheo, một vị có lòng tin đi đến gần; sau khi đến gần, vị ấy tỏ sự kính lễ; sau khi tỏ sự kính lễ, vị ấy lóng tai; sau khi lóng tai, vị ấy nghe pháp; sau khi nghe pháp, vị ấy thọ trì pháp; sau khi thọ trì, vị ấy suy tư ý nghĩa các pháp được thọ trì; sau khi suy tư ý nghĩa, các pháp được chấp thuận; sau khi các pháp được chấp thuận, ước muốn sanh khởi; sau khi ước muốn sanh khởi, vị ấy nỗ lực; sau khi nỗ lực, vị ấy cân nhắc; sau khi cân nhắc, vị ấy tinh cần. Do tinh cần, vị ấy tự thân chứng được sự thật tối thượng, và với trí tuệ thể nhập sự thật ấy, vị ấy thấy.`, ref: "MN 70 – Kinh Kīṭāgiri", url: "../mn/mn70.html#content" },

{ text: `Này các Tỷ-kheo, cho đến một bậc Ðạo sư sống quá trọng vọng tài vật, là vị thừa tự tài vật, và sống liên hệ với tài vật, thời sự mua may bán đắt này không xảy ra: “Chúng tôi sẽ làm việc này như vậy, và như vậy chúng tôi sẽ không làm việc này như vậy”, huống nữa là Như Lai, này các Tỷ-kheo, là vị sống hoàn toàn không liên hệ với các tài vật.`, ref: "MN 70 – Kinh Kīṭāgiri", url: "../mn/mn70.html#content" },

{ text: `Này các Tỷ-kheo, đến với một đệ tử, có lòng tin giáo pháp bậc Ðạo sư và sống thể nhập giáo pháp ấy, thời giáo pháp bậc Ðạo sư được hưng thịnh, được nhiều sinh lực. Này các Tỷ-kheo, đối với đệ tử có lòng tin giáo pháp bậc Ðạo Sư và sống thể nhập giáo pháp ấy, thời tùy pháp này được khởi lên: “Dầu chỉ còn da, gân và xương, dầu thịt và máu trên thân bị khô héo, mong rằng sẽ có tinh tấn lực để chứng đắc những gì chưa chứng đắc, nhờ trượng phu nhẫn nại, nhờ trượng phu tinh tấn, nhờ trượng phu cần dõng”. Này các Tỷ-kheo, đối với một đệ tử có lòng tin giáo pháp bậc Ðạo sư và sống thể nhập giáo pháp ấy, vị ấy sẽ chứng được một trong hai quả như sau: Chánh trí ngay trong hiện tại, và nếu có dư y, chứng quả Bất hoàn.`, ref: "MN 70 – Kinh Kīṭāgiri", url: "../mn/mn70.html#content" },
{ text: `Nhưng này Aggivessana, thân này có sắc, do bốn đại thành, do cha mẹ sanh, nhờ cơm cháo nuôi dưỡng, vô thường, biến hoại, phân toái, đoạn tuyệt, hoại diệt, cần phải được quán sát là vô thường, khổ, như bệnh, như cục bướu, như mũi tên, như điều bất hạnh, như bệnh chướng, như kẻ địch, như phá hoại, là không, là vô ngã. Khi vị ấy quán sát thân này là vô thường, khổ, như bệnh, như cục bướu, như mũi tên, như điều bất hạnh, như bệnh chướng, như kẻ địch, như phá hoại, là không, là vô ngã, thời thân, thân dục, thân ái, thân phục tòng được đoạn diệt.`, ref: "MN 74 – Kinh Trường Trảo", url: "../mn/mn74.html#content" },

{ text: `Này Aggivessana, lạc thọ là vô thường, hữu vi, do duyên sanh, bị đoạn diệt, bị hủy hoại, bị suy tàn, bị tiêu diệt. Này Aggivessana, khổ thọ là vô thường, hữu vi, do duyên sanh, bị đoạn diệt, bị hủy hại, bị suy tàn, bị tiêu diệt. Này Aggivessana, bất khổ bất lạc thọ là vô thường, hữu vi, do duyên sanh, bị đoạn diệt, bị hủy hoại, bị suy tàn, bị tiêu diệt.`, ref: "MN 74 – Kinh Trường Trảo", url: "../mn/mn74.html#content" },
{ text: `Ông nghĩ thế nào, ? Ở đây, này Magandiya, có người trước kia đam mê các sắc pháp do mắt nhận thức, các sắc pháp này là khả ái, khả hỷ, khả lạc, khả ý, liên hệ đến dục, hấp dẫn. Người ấy sau một thời gian, sau khi như chơn biết được sự tập khởi, sự đoạn diệt, vị ngọt, sự nguy hiểm và sự xuất ly của các sắc pháp, sau khi đoạn tận sắc ái, sau khi trừ diệt nhiệt não đối với sắc pháp, người này trú với khát ái được đoạn trừ, với nội tâm an tịnh.`, ref: "MN 75 – Kinh Māgandiya", url: "../mn/mn75.html#content" },

{ text: `Rồi Ta sau một thời gian, sau khi như chơn biết được sự tập khởi, sự đoạn diệt, vị ngọt, sự nguy hiểm và sự xuất ly của các dục vọng, sau khi đoạn tận dục ái, sau khi trừ diệt nhiệt não của các dục, Ta trú với khát ái được đoạn trừ, với nội tâm an tịnh. Rồi Ta thấy các chúng sanh khác, chưa xả ly tham ái đối với các dục đang bị các dục ái nhai nghiến, đang bị dục nhiệt não thiêu đốt, đang chạy theo các dục. Ta không ước vọng được như họ; ở đây, Ta không ham thích. Vì sao vậy? Vì rằng, này Magandiya, có hỷ lạc này, ly dục, ly bất thiện pháp, sau khi chứng đạt Thiên lạc, được an trú, hoan hỷ trong hỷ lạc ấy. Ta không ao ước cái gì thấp kém; ở đây, Ta không ham thích.`, ref: "MN 75 – Kinh Māgandiya", url: "../mn/mn75.html#content" },

{ text: `Cũng vậy, này Magandiya, sự xúc chạm với các dục trong thời quá khứ cũng là đau khổ, rất là nồng cháy, rất là nhiệt não, và sự xúc chạm với các dục trong thời vị lai cũng là đau khổ, rất là nồng cháy, rất là nhiệt não, và sự xúc chạm với các dục trong thời hiện lại cũng là đau khổ, rất là nồng cháy, rất là nhiệt não. Và này Magandiya, những chúng sanh này chưa đoạn trừ tham ái đối với các dục, đang bị các dục ái nhai nghiến, đang bị dục nhiệt não thiêu đốt, với các căn bị hư hoại, do sự xúc chạm đau khổ với các dục, lại có phản tưởng là được lạc thọ.`, ref: "MN 75 – Kinh Māgandiya", url: "../mn/mn75.html#content" },

{ text: `Ví như, này Magandiya, một người bị bệnh cùi thân (đầy) lở lói, thân bị hư thối nứt chảy, bị các loài trùng đục khoét, đang cào rách miệng các vết thương với móng tay, hơ đốt thân mình trên hố than hừng. Này Magandiya, người bị bệnh cùi với thân (đầy) lở lói, thân bị hư thối nứt chảy, bị các loài trùng đục khoét, càng cào rách miệng các vết thương với các móng tay, càng hơ đốt thân mình trên hố than hừng chừng nào thời miệng các vết thương ấy lại càng thêm bất tịnh, càng thêm hôi thối và càng thêm thối nát, và người ấy chỉ có cảm giác dễ chịu, thỏa thích do nhân duyên gãi ngứa miệng các vết thương; cũng vậy, này Magandiya, các chúng sanh, chưa đoạn trừ tham ái đối với các dục, đang bị các dục ái nhai nghiến, đang bị dục nhiệt não thiêu đốt, chạy theo các dục. Này Magandiya các chúng sanh, chưa đoạn trừ tham ái đối với các dục, đang bị các dục ái nhai nghiến, đang bị dục nhiệt não thiêu đốt, càng chạy theo dục chừng nào, thời dục ái các chúng sanh ấy càng tăng trưởng, càng bị dục nhiệt não thiêu đốt, và họ chỉ có cảm giác dễ chịu, thỏa thích do duyên năm dục trưởng dưỡng.`, ref: "MN 75 – Kinh Māgandiya", url: "../mn/mn75.html#content" },

{ text: `Này Magandiya, Ông nghĩ thế nào? Ông có thấy hay nghe một vị vua hay vị đại thần của vua hưởng thụ một cách đầy đủ, một cách sung mãn năm dục trưởng dưỡng, dục ái chưa được đoạn tận, dục nhiệt não chưa được trừ diệt, đã trú, đang trú hay sẽ trú với khát ái được đoạn trừ, với nội tâm an tịnh không?\n—Thưa không, Tôn giả Gotama.`, ref: "MN 75 – Kinh Māgandiya", url: "../mn/mn75.html#content" },

{ text: `—Lành thay, này Magandiya! Này Magandiya, Ta cũng không thấy, cũng không nghe một vị vua hay vị đại thần của vua hưởng thụ một cách đầy đủ, một cách sung mãn năm dục trưởng dưỡng, dục ái chưa được đoạn tận, dục nhiệt não chưa được trừ diệt, đã trú, đang trú hay sẽ trú với khát ái được đoạn trừ, với nội tâm an tịnh. Nhưng này Magandiya, những vị Sa-môn hay Bà-la-môn nào đã sống, đang sống hay sẽ sống với khát ái được đoạn trừ, với nội tâm an tịnh, tất cả những vị này, sau khi như chơn biết sự tập khởi, sự đoạn diệt, vị ngọt, sự nguy hiểm và sự xuất ly của các dục ấy, với dục ái được đoạn tận, với dục nhiệt não được trừ diệt, đã trú, đang trú hay sẽ trú với khát ái được đoạn trừ, với nội tâm được an tịnh.`, ref: "MN 75 – Kinh Māgandiya", url: "../mn/mn75.html#content" },

{ text: `Không bệnh, lợi tối thắng,\nNiết-bàn, lạc tối thắng,\nBát chánh là độc đạo,\nAn ổn và bất tử.`, ref: "MN 75 – Kinh Māgandiya", url: "../mn/mn75.html#content" },

{ text: `Cũng vậy, này Magandiya, nếu Ta thuyết pháp cho Ông: “Ðây là không bệnh, đây là Niết-bàn”, Ông có thể biết không bệnh, Ông có thể thấy Niết-bàn. Và với mắt được khởi lên cho Ông, lòng tham dục đối với năm thủ uẩn được đoạn trừ; và Ông có thể nghĩ như sau: “Thật sự trong một thời gian dài, ta bị tâm này lường gạt, lừa dối, phỉnh gạt, chấp thủ sắc, ta đã chấp thủ, chấp thủ thọ, ta đã chấp thủ, chấp thủ tưởng, ta đã chấp thủ, chấp thủ các hành, ta đã chấp thủ, chấp thủ thức, ta đã chấp thủ. Do duyên chấp thủ ấy nơi ta, nên có hữu; do duyên hữu, có sanh; do duyên sanh, có già chết, sầu, bi, khổ, ưu, não khởi lên. Như vậy là sự tập khởi của toàn bộ Khổ uẩn”.`, ref: "MN 75 – Kinh Māgandiya", url: "../mn/mn75.html#content" },

{ text: `Vậy này Magandiya, hãy thân cận các vị chân nhân. Này Magandiya, do Ông thân cận các vị chân nhân, thời này Magandiya, Ông sẽ được nghe diệu pháp. Này Magandiya, do Ông được nghe diệu pháp, thời này Magandiya, Ông sẽ sống đúng với Chánh pháp và tùy pháp. Này Magandiya, do Ông sống đúng với Chánh pháp và tùy pháp, thời này Magandiya, Ông sẽ tự mình biết, tự mình thấy: “Ðây là những bệnh chướng, những cục bướu, những mũi tên. Ở đây, những bệnh chướng, những cục bướu, những mũi tên được trừ diệt, không có dư tàn. Do chấp thủ được diệt ở ta, nên hữu diệt; do hữu diệt, sanh diệt; do sanh diệt, già, chết, sầu, bi, khổ, ưu, não được diệt trừ. Như vậy là sự đoạn diệt của toàn bộ khổ uẩn này”.`, ref: "MN 75 – Kinh Māgandiya", url: "../mn/mn75.html#content" },
{ text: `Vị ấy sống biết đủ, bằng lòng với tấm y để che thân với đồ ăn khất thực để nuôi sống, đi tại chỗ nào cũng mang theo y và bình bát. Như con chim bay đến chỗ nào cũng mang theo hai cánh, cũng vậy, Tỷ-kheo bằng lòng với tấm y để che thân, với đồ ăn khất thực để nuôi bụng, đi tại chỗ nào cũng mang theo. Vị ấy thành tựu Thánh giới uẩn này, nội tâm hưởng lạc thọ không khuyết phạm.`, ref: "MN 76 – Kinh Sandaka", url: "../mn/mn76.html#content" },
{ text: `Các Tôn giả hãy nhỏ tiếng! Các Tôn giả hãy lặng tiếng! Nay đệ tử của Sa-môn Gotama, Sa-môn Ānanda đang đến. Khi nào các đệ tử của Sa-môn Gotama trú ở Kosambi, thời Sa-môn Ānanda này là một vị trong những vị ấy. Các Tôn giả ấy ưa mến trầm lặng, tu tập trong trầm lặng, tán thán trầm lặng, nếu biết chúng này trầm lặng, có thể ghé tại đây.\nRồi các du sĩ ấy đều im lặng.`, ref: "MN 76 – Kinh Sandaka", url: "../mn/mn76.html#content" },
{ text: `Bạch Thế Tôn, Thế Tôn ăn ít và tán thán hạnh ăn ít. Bạch Thế Tôn, Thế Tôn ăn ít và tán thán hạnh ăn ít. Chính pháp này, bạch Thế Tôn, là pháp thứ nhất, con thấy nơi Thế Tôn. Do pháp này các đệ tử cung kính, tôn trọng, kính lễ, cúng dường Thế Tôn, và sau khi cung kính, tôn trọng, sống nương tựa vào Thế Tôn.`, ref: "MN 77 – Ðại kinh Sakaludāyin", url: "../mn/mn77.html#content" },

{ text: `Lại nữa, bạch Thế Tôn, Thế Tôn biết đủ với bất cứ loại y nào và tán thán hạnh biết đủ với bất cứ loại y nào. Bạch Thế Tôn, Thế Tôn biết đủ với bất cứ loại y nào và tán thán hạnh biết đủ với bất cứ loại y nào. Chính pháp này, bạch Thế Tôn là pháp thứ hai con thấy nơi Thế Tôn. Do pháp này, các đệ tử cung kính, tôn trọng, kính lễ, cúng dường Thế Tôn, và sau khi cung kính, tôn trọng, sống nương tựa vào Thế Tôn.`, ref: "MN 77 – Ðại kinh Sakaludāyin", url: "../mn/mn77.html#content" },

{ text: `Lại nữa, bạch Thế Tôn, Thế Tôn biết đủ với bất cứ món ăn khất thực nào và tán thán hạnh biết đủ với bất cứ món ăn khất thực nào. Bạch Thế Tôn, Thế Tôn biết đủ với bất cứ món ăn khất thực nào và tán thán hạnh biết đủ với bất cứ món ăn khất thực nào. Chính pháp này, bạch Thế Tôn, là pháp thứ ba, con thấy nơi Thế Tôn. Do pháp này, các đệ tử cung kính, tôn trọng, kính lễ, cúng dường Thế Tôn, và sau khi cung kính, tôn trọng, sống nương tựa vào Thế Tôn.`, ref: "MN 77 – Ðại kinh Sakaludāyin", url: "../mn/mn77.html#content" },

{ text: `Lại nữa, bạch Thế Tôn, Thế Tôn biết đủ với bất cứ sàng tọa nào và tán thán hạnh biết đủ với bất cứ sàng tọa nào. Bạch Thế Tôn, Thế Tôn biết đủ với bất cứ sàng tọa nào và tán thán hạnh biết đủ với bất cứ sàng tọa nào. Chính pháp này, bạch Thế Tôn, là pháp thứ tư, con thấy nơi Thế Tôn. Do pháp này, các đệ tử cung kính, tôn trọng, kính lễ, cúng dường Thế Tôn, và sau khi cung kính, tôn trọng, sống nương tựa vào Thế Tôn.`, ref: "MN 77 – Ðại kinh Sakaludāyin", url: "../mn/mn77.html#content" },

{ text: `Lại nữa, bạch Thế Tôn, Thế Tôn sống viễn ly và tán thán hạnh sống viễn ly. Bạch Thế Tôn, Thế Tôn sống viễn ly và tán thán hạnh sống viễn ly. Chính pháp này bạch Thế Tôn, là pháp thứ năm, con thấy nơi Thế Tôn. Do pháp này, các đệ tử cung kính, tôn trọng, kính lễ, cúng dường Thế Tôn, và sau khi cung kính, tôn trọng, sống nương tựa vào Thế Tôn.`, ref: "MN 77 – Ðại kinh Sakaludāyin", url: "../mn/mn77.html#content" },

{ text: `Lại nữa, này Udāyi, những đệ tử của Ta bị đắm chìm trong đau khổ, bị đau khổ chi phối, đến Ta và hỏi về khổ Thánh đế. Ðược hỏi về Khổ Thánh đế, Ta trả lời cho họ. Ta làm cho tâm của họ thỏa mãn với câu trả lời của Ta. Họ hỏi Ta về Khổ tập, Khổ diệt, Khổ diệt đạo Thánh đế, Ta trả lời cho họ. Ta làm cho tâm của họ thỏa mãn với câu trả lời của Ta. Ðây là pháp thứ tư, này Udāyi, mà các đệ tử của Ta cung kính, tôn trọng, kính lễ, cúng dường Ta và sau khi cung kính, tôn trọng, sống nương tựa vào Ta.`, ref: "MN 77 – Ðại kinh Sakaludāyin", url: "../mn/mn77.html#content" },

{ text: `Lại nữa, này Udāyi, Ta thuyết giảng con đường tu hành cho các đệ tử. Và các đệ tử của Ta y cứ theo đường tu hành này, tu tập Bốn Niệm xứ. Ở đây, này Udāyi, vị Tỷ-kheo sống quán thân trên thân, nhiệt tâm tỉnh giác, chánh niệm để nhiếp phục tham ưu trên đời, quán thọ trên các cảm thọ … quán tâm trên các tâm … quán pháp trên các pháp, nhiệt tâm, tỉnh giác, chánh niệm để nhiếp phục tham ưu trên đời. Và ở đây, các đệ tử của Ta phần đông an trú, sau khi chứng ngộ nhờ thắng trí và chứng đắc cứu cánh viên mãn.`, ref: "MN 77 – Ðại kinh Sakaludāyin", url: "../mn/mn77.html#content" },

{ text: `Lại nữa, này Udāyi, Ta thuyết giảng con đường tu hành cho các đệ tử. Và các đệ tử của Ta y cứ con đường tu hành này, tu tập Bốn Chánh cần. Ở đây, này Udāyi, vị Tỷ-kheo với mục đích khiến cho các ác, bất thiện pháp từ trước chưa sanh không cho sanh khởi, khởi lên ý muốn cố gắng, tinh tấn, sách tâm, trì tâm; với mục đích khiến cho các ác, bất thiện pháp đã sanh ra được trừ diệt, khởi lên ý muốn cố gắng, tinh tấn, sách tâm, trì tâm; với mục đích khiến cho các thiện pháp từ trước chưa sanh nay cho sanh khởi, khởi lên ý muốn cố gắng, tinh tấn, sách tâm, trì tâm; với mục đích khiến cho các thiện pháp đã được sanh có thể duy trì, không có mù mờ, được tăng trưởng, được quảng đại, được tu tập, được viên mãn, khởi lên ý muốn cố gắng, tinh tấn, sách tâm, trì tâm … Và ở đây, các đệ tử của Ta phần đông an trú, sau khi chứng ngộ nhờ thắng trí và chứng đắc cứu cánh viên mãn.`, ref: "MN 77 – Ðại kinh Sakaludāyin", url: "../mn/mn77.html#content" },

{ text: `Này Udāyi, chính đệ tử của Ta thán phục tri kiến vi diệu và nghĩ rằng: “Khi nói: “Ta biết”, nghĩa là Sa-môn Gotama có biết: Khi nói: “Ta thấy”, nghĩa là Sa-môn Gotama có thấy. Sa-môn Gotama thuyết pháp với thắng trí, không phải không với thắng trí. Sa-môn thuyết pháp với nhân duyên, không phải không có nhân duyên. Sa-môn Gotama thuyết pháp có thần thông lực, không phải không có thần thông lực”. Ðây là pháp thứ hai, này Udāyi, các đệ tử của Ta cung kính, tôn trọng, kính lễ, cúng dường Ta và sau khi cung kính, tôn trọng, sống nương tựa vào Ta.`, ref: "MN 77 – Ðại kinh Sakaludāyin", url: "../mn/mn77.html#content" },
{ text: `Và này Thợ mộc, những bất thiện tư duy này sanh khởi như thế nào? Sự sanh khởi của chúng cũng được nói đến. Cần phải trả lời là từ tưởng sanh khởi. Thế nào là tưởng? Tưởng có nhiều loại, đa chủng, sai biệt: dục tưởng, sân tưởng, hại tưởng, từ đấy những bất thiện tư duy sanh khởi.`, ref: "MN 78 – Ðại kinh Samanamandikà", url: "../mn/mn78.html#content" },

{ text: `Và này Thợ mộc, những bất thiện tư duy này từ đâu được trừ diệt, không có dư tàn? Sự trừ diệt của chúng cũng được nói đến. Ở đây, này Thợ mộc, vị Tỷ-kheo ly dục, ly bất thiện pháp chứng và trú Thiền thứ nhất, một trạng thái hỷ lạc do ly dục sanh, với tầm, với tứ. Ở đây, những bất thiện tư duy được trừ diệt, không có dư tàn.`, ref: "MN 78 – Ðại kinh Samanamandikà", url: "../mn/mn78.html#content" },

{ text: `Và sự thực hành như thế nào, này Thợ mộc, là sự thực hành đưa đến diệt trừ các bất thiện tư duy? Ở đây, vị Tỷ-kheo khởi lên ý muốn nỗ lực, tinh tấn, quyết tâm, sách tấn tâm khiến cho các ác, bất thiện pháp chưa sanh không được sanh khởi … khiến cho các ác, bất thiện pháp đã sanh được trừ diệt; khiến cho các thiện pháp chưa sanh nay được sanh khởi; khởi lên ý muốn nỗ lực, tinh tấn, quyết tâm, sách tấn tâm; khiến cho các thiện pháp đã sanh có thể duy trì, không có mơ hồ, được tăng trưởng, được quảng đại, được tu tập, được viên mãn. Sự thực hành như vậy là sự thực hành đưa đến diệt trừ các bất thiện tư duy.`, ref: "MN 78 – Ðại kinh Samanamandikà", url: "../mn/mn78.html#content" },

{ text: `Này Thợ mộc, thế nào là thiện tư duy? Ly dục tư duy, vô sân tư duy, bất hại tư duy; những pháp này, này Thợ mộc, được gọi là thiện tư duy.`, ref: "MN 78 – Ðại kinh Samanamandikà", url: "../mn/mn78.html#content" },
{ text: `—Bạch Thế Tôn, như con được hiểu lời Thế Tôn thuyết pháp, thời sống tại gia đình thật không dễ gì thực hành Phạm hạnh, hoàn toàn viên mãn, hoàn toàn trong sạch, trắng bạch như vỏ ốc. Con muốn, bạch Thế Tôn, cạo bỏ râu tóc, đắp áo cà-sa, xuất gia, từ bỏ gia đình, sống không gia đình. Bạch Thế Tôn, mong Thế Tôn cho con xuất gia dưới sự chỉ dẫn của Thế Tôn, cho con thọ đại giới.\n—Nhưng này Raṭṭḥapāla, Ông có được cha mẹ bằng lòng cho Ông xuất gia chưa?\n—Bạch Thế Tôn, con chưa được cha mẹ bằng lòng cho con xuất gia.\n—Này Raṭṭḥapāla, Như Lai không có cho ai xuất gia nếu không được cha mẹ người ấy bằng lòng.\n—Như vậy, bạch Thế Tôn, con sẽ làm những gì cần thiết để cha mẹ bằng lòng cho con được xuất gia, từ bỏ gia đình, sống không gia đình.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `Rồi thiện nam tử Raṭṭḥapāla không được cha mẹ cho xuất gia, liền ngay tại chỗ ấy nằm xuống trên đất trần và nói:\n—Ta sẽ chết ở đây, hay được xuất gia.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `Rồi các thân hữu của thiện nam tử Raṭṭḥapāla đi đến cha mẹ thiện nam tử Raṭṭḥapāla, sau khi đến liền thưa:\n—Thưa Mẹ và Cha, thiện nam tử Raṭṭḥapāla đang nằm xuống trên đất trần kia và nói: “Ở đây, ta sẽ chết, hay được xuất gia”. Nếu Cha Mẹ không bằng lòng cho thiện nam tử Raṭṭḥapāla xuất gia, từ bỏ gia đình, sống không gia đình, thời Raṭṭḥapāla sẽ chết ở tại chỗ ấy. Còn nếu Cha Mẹ bằng lòng cho thiện nam tử Raṭṭḥapāla xuất gia, từ bỏ gia đình, sống không gia đình, thời Cha Mẹ có thể thấy Raṭṭḥapāla sau khi xuất gia. Nếu thiện nam tử Raṭṭḥapāla không cảm thấy hoan hỷ trong khi xuất gia, từ bỏ gia đình, sống không gia đình, thời Raṭṭḥapāla không còn con đường nào đi khác hơn. Raṭṭḥapāla sẽ trở lại ở đây. Hãy bằng lòng cho phép thiện nam tử Raṭṭḥapāla xuất gia, từ bỏ gia đình, sống không gia đình.\n—Này các con thân mến, chúng ta bằng lòng cho phép thiện nam tử Raṭṭḥapāla xuất gia, từ bỏ gia đình, sống không gia đình, nhưng sau khi xuất gia, cần phải về thăm cha mẹ.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `Rồi Tôn giả Raṭṭḥapāla vào buổi sáng đắp y, cầm bát đi đến ngồi nhà của người cha mình, sau khi đến ngồi xuống trên chỗ đã soạn sẵn. Rồi người cha của Tôn giả Raṭṭḥapāla cho trình bày ra đống vàng nén và tiền vàng và nói với Tôn giả Raṭṭḥapāla\n—Này con thân yêu Raṭṭḥapāla, đây là tiền tài của mẹ, kia là tiền tài của cha, kia là tiền tài của tổ tiên. Này con thân yêu Raṭṭḥapāla, con có thể thụ hưởng tài vật và làm các phước đức. Này con thân yêu Raṭṭḥapāla, hãy từ bỏ tu học, hoàn tục thụ hưởng các tài vật và làm các phước đức.\n—Thưa gia chủ, nếu gia chủ làm theo lời nói của tôi, sau khi chồng chất đống vàng nén và tiền vàng này vào trong các xe, sau khi cho chở và hạ xuống giữa sông Hằng, hãy đổ đống vàng này vào giữa dòng sông. Vì sao vậy? Này gia chủ, vì do nhân duyên này, mà sầu, bi, khổ, ưu, não sẽ khởi lên cho gia chủ.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `Rồi những người vợ cũ của Tôn giả Raṭṭḥapāla ôm mỗi chân (Tôn giả) và nói:\n—Thưa phu quân, vì thiên nữ nào mà phu quân sống phạm hạnh?\n—Các bà chị, không phải vì thiên nữ nào mà chúng tôi sống phạm hạnh.\n—Phu quân Raṭṭḥapāla đối với chúng ta gọi chúng ta là bà chị.\nNói lên như vậy, (các người vợ cũ) liền ngã xuống đất, bất tỉnh.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `Hãy nhìn hình bóng trang sức này,\nMột nhóm vết thương được tích tụ,\nBệnh nhiều, tham tưởng cũng khá nhiều,\nNhưng không gì kiên cố, thường trú.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `Hãy nhìn dung mạo trang sức này,\nVới các châu báu, với vòng tai,\nMột bộ xương được da bao phủ,\nÐược y phục làm cho sáng chói.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `Chân được sơn với son với sáp,\nMặt được thoa với phấn, với bột,\nVừa đủ làm mê hoặc kẻ ngu,\nNhưng vô phương kẻ cầu bờ giác.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `Tóc được uốn bảy vòng, bảy lớp,\nMắt được xoa với thuốc, với son,\nVừa đủ làm mê hoặc kẻ ngu,\nNhưng vô phương kẻ cầu bờ giác.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `Như hộp thuốc trang hoàng mới mẻ,\nLà uế thân được điểm thời trang,\nVừa đủ làm mê hoặc kẻ ngu,\nNhưng vô phương kẻ cầu bờ giác.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `Người thợ săn đặt bày lưới sập,\nLoài nai khôn chẳng chạm bén chân,\nĂn lúa xong, chúng ta lên đường,\nMặc cho kẻ bắt nai than khóc.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `“Thế giới là vô thường, đi đến hủy diệt”, thưa Ðại vương, đó là thuyết giáo Chánh pháp thứ nhất, do Thế Tôn, bậc Tri Giả, Kiến Giả, bậc A-la-hán, Chánh Ðẳng Giác, thuyết giảng. Do tôi biết, tôi thấy và tôi nghe thuyết giáo ấy, mà tôi xuất gia, từ bỏ gia đình, sống không gia đình.\n“Thế giới là vô hộ, vô chủ”, thưa Ðại vương, đó là thuyết giáo Chánh pháp thứ hai, do Thế Tôn, bậc Tri Giả. Kiến Giả, bậc A-la-hán, Chánh Ðẳng Giác thuyết giảng. Do tôi biết, tôi thấy và tôi nghe thuyết giáo ấy, mà tôi xuất gia, từ bỏ gia đình, sống không gia đình.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `“Thế giới là vô sở hữu, ra đi cần phải từ bỏ tất cả”, thưa Ðại vương đó là thuyết giáo Chánh pháp thứ ba, do Thế Tôn, bậc Tri Giả, Kiến Giả, bậc A-la-hán, Chánh Ðẳng Giác thuyết giảng. Do tôi biết, tôi thấy, tôi nghe thuyết giáo ấy, mà tôi xuất gia, từ bỏ gia đình, sống không gia đình.\n“Thế giới là thiếu thốn, khao khát, nô lệ cho tham ái”, thưa Ðại vương, đó là thuyết giáo Chánh pháp thứ tư, do Thế Tôn, bậc Tri Giả, Kiến Giả, bậc A-la-hán, Chánh Ðẳng Giác thuyết giảng. Do tôi biết, tôi thấy, tôi nghe thuyết giáo ấy, mà tôi xuất gia, từ bỏ gia đình, sống không gia đình.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `—Thưa Ðại vương, Ðại vương nghĩ thế nào? Ðại vương có thể nói chăng, với các thân hữu quen biết, bà con huyết thống của Ðại vương: “Mong rằng Tôn giả thân hữu quen biết, bà con huyết thống làm vơi nhẹ sự đau khổ của tôi! Mong tất cả hãy san sẻ cảm thọ này, để tôi có thể có một cảm thọ nhẹ nhàng hơn”; hay là Ðại vương chỉ có thể thọ lãnh cảm thọ ấy một mình?\n—Thưa Tôn giả Raṭṭḥapāla, tôi không có thể nói với các thân hữu quen biết, bà con huyết thống của tôi: “Mong rằng các Tôn giả thân hữu quen biết, bà con huyết thống làm vơi nhẹ sự đau khổ của tôi. Mong tất cả hãy san sẻ cảm thọ này để có thể có một cảm thọ nhẹ nhàng hơn”; và tôi chỉ có thể thọ lãnh cảm thọ ấy một mình”.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `—Thưa Ðại vương, Ðại vương nghĩ thế nào? Dầu cho nay Ðại vương sống thụ hưởng mãn túc, cụ túc năm món dục trưởng dưỡng, Ðại vương có thể nói được như sau: “Chính như vậy, tôi thọ hưởng mãn túc, cụ túc năm món dục trưởng dưỡng này”; hay là người khác sẽ thọ hưởng tài sản này, còn Ðại vương sẽ phải đi theo nghiệp của mình?\n—Thưa Tôn giả Raṭṭḥapāla, dầu cho nay tôi sống thụ hưởng mãn túc, cụ túc năm món dục trưởng dưỡng. Tôi không có thể nói được như sau: “Chính như vậy tôi thọ hưởng mãn túc, cụ túc năm món dục trưởng này”. Chính người khác sẽ thọ hưởng tài sản này, còn tôi phải đi theo nghiệp của tôi.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `Ta thấy người giàu sang ở đời,\nCó của vì si không bố thí.\nVì tham, họ tích tụ tài vật,\nVà chạy theo dục vọng càng nhiều.\nDùng bạo lực, chinh phục quả đất,\nVua trị vì cho đến hải biên,\nKhông thỏa mãn bờ biển bên này,\nVà chạy theo bờ biển bên kia.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `Vua cùng rất nhiều loại người khác,\nÁi chưa ly, mạng chung đã đến,\nBị thiếu thốn, không bỏ thân họ,\nKhông thỏa mãn lòng dục ở đời.\nQuyến thuộc tán loạn, khóc người ấy:\n“Than ôi, người ấy không bất tử! ”.\nMạng thân người ấy vải bao phủ,\nHọ đốt lửa làm lễ hỏa thiêu.\nBị thọc với cây, người ấy cháy,\nÐộc mảnh vải, bỏ tiền của lại.\nỞ đây, quyến thuộc cùng thân hữu,\nKhông nơi nương tựa cho kẻ chết.\nKẻ thừa tự, nhận mang tài sản,\nRiêng con người, theo nghiệp phải đi,\nTiền của đâu có theo người chết,\nCả vợ con, tài sản, quốc độ.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `Tài sản không mua được trường thọ,\nPhú quý không tránh được già suy,\nKẻ trí nói đời này thật ngắn,\nThật vô thường, biến đổi luôn luôn.\nKẻ giàu, kẻ nghèo đều cảm xúc,\nNgười ngu, kẻ trí đồng cảm thọ,\nKẻ ngu bị ngu đánh nằm ngã,\nBậc trí cảm xúc, không run sợ.\nDo vậy, trí tuệ thắng tài vật,\nNhờ trí, ở đây được viên thành.\nKhông thành mãn trong hữu, phi hữu,\nKẻ ngu tạo tác các ác nghiệp.\nNhập thai thác sanh thế giới khác,\nNgười ấy luân hồi, tiếp tục sanh,\nKẻ thiểu trí chắc hẳn phải là\nNhập thai và sanh thế giới khác.\nNhư kẻ trộm bị bắt khi trộm,\nÁc tánh hại mình do tự nghiệp,\nChúng sanh cũng vậy chết đời khác,\nÁc tánh hại mình, do tự lực.`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },

{ text: `Dục vọng nhiều loại, ngọt, khả ái,\nNhiễu loạn tâm dưới nhiều hình thức,\nThấy hoạn nạn trong dục trưởng dưỡng,\nNên tôi xuất gia, tâu Ðại vương!\nNhư quả từ đây, người bị rụng,\nCả già lẫn trẻ, khi thân hoại,\nDo thấy chính vậy, tôi xuất gia,\nHạnh Sa-môn phải là tối thắng,\nThưa Ðại vương!`, ref: "MN 82 – Kinh Raṭṭḥapāla", url: "../mn/mn82.html#content" },
{ text: `Ai trước phóng dật, sau không phóng dật,\nSáng chói đời này, như trăng thoát mây,\nAi làm ác nghiệp, nhờ thiện chặn lại,\nSáng chói đời này, như trăng thoát mây.`, ref: "MN 86 – Kinh Aṅgulimāla", url: "../mn/mn86.html#content" },

{ text: `Thời thời nghe pháp, y pháp hành trì.\nMột kẻ như vậy, không có hại ta,\nCũng không làm hại một người nào khác.\nVị ấy sẽ chứng tối thượng tịch tịnh.`, ref: "MN 86 – Kinh Aṅgulimāla", url: "../mn/mn86.html#content" },

{ text: `Hộ trì mọi người, kẻ mạnh người yếu,\nNhư người dẫn nước, hướng dẫn nước chảy,\nNhư kẻ làm tên uốn cong thân tên,\nNhư người thợ mộc uốn nắn cây gỗ.\nKẻ trí tự mình, tự điều phục mình,\nCó kẻ được điều bởi gậy, roi, móc,\nRiêng Ta được điều không gậy, không kiếm.\n(Bởi bậc như vậy).`, ref: "MN 86 – Kinh Aṅgulimāla", url: "../mn/mn86.html#content" },

{ text: `Kẻ ngu vô trí, đam mê phóng dật,\nCòn người có trí, giữ không phóng dật,\nNhư giữ tài sản, tối thượng, tối quý,\nChớ mê phóng dật, chớ mê dục lạc.`, ref: "MN 86 – Kinh Aṅgulimāla", url: "../mn/mn86.html#content" },

{ text: `Giữ không phóng dật, luôn luôn Thiền định,\nChứng đắc đại lạc, quảng đại vô lượng,\nThiện lai, ta đến, không đi lạc hướng,\nKhông ai khuyên ta theo tư tưởng ác.\nGiữa các chân lý được khéo giảng dạy,\nChân lý ta theo, chân lý tối thượng,\nThiện lai ta đến, không đi lạc hướng,\nKhông ai khuyên ta theo tư tưởng ác,\nBa minh ta chứng, Phật lý viên thành.`, ref: "MN 86 – Kinh Aṅgulimāla", url: "../mn/mn86.html#content" },
{ text: `—Này Gia chủ, có phải các căn của Ông đổi khác?\n—Bạch Thế Tôn, sao các căn của con có thể không đổi khác được? Bạch Thế Tôn, đứa con một khả ái, đáng thương của con đã mệnh chung. Sau khi nó chết, con không còn muốn làm việc, con không còn muốn ăn uống, con luôn luôn đi đến nghĩa địa và than khóc: “Con ở đâu, đứa con một của ta? Con ở đâu, đứa con một của ta?”\n—Sự thật là như vậy, này Gia chủ, vì rằng, này Gia chủ, sầu, bi, khổ, ưu, não do ái sanh ra, hiện hữu từ nơi ái.`, ref: "MN 87 – Kinh Ái Sanh", url: "../mn/mn87.html#content" },
{ text: `Này Bà-la-môn, đây là một pháp môn, do pháp môn này cần phải được hiểu là sầu, bi, khổ, não do ái sanh ra, hiện hữu từ nơi ái. Này Bà-la-môn, thuở xưa, ở tại Sāvatthi này, người mẹ của một người đàn ông mệnh chung. Từ khi bà ta mệnh chung, người đàn ông này phát điên cuồng, tâm tư hỗn loạn, đi từ đường này qua đường khác, đi từ ngã tư đường này qua ngã tư đường khác và nói: “Người có thấy mẹ tôi đâu không? Người có thấy mẹ tôi đâu không?”`, ref: "MN 87 – Kinh Ái Sanh", url: "../mn/mn87.html#content" },

{ text: `Này Bà-la-môn, đây là một pháp môn, do pháp môn này cần phải được hiểu là sầu, bi, khổ, ưu, não do ái sanh ra, hiện hữu từ nơi ái. Này Bà-la-môn, thuở xưa chính tại thành Sāvatthi này, một người đàn bà đi về thăm gia đình bà con. Những người bà con ấy của người đàn bà muốn dùng sức mạnh bắt người đàn bà ấy phải xa chồng và muốn gả cho một người đàn ông khác. Người đàn bà ấy không chịu. Rồi người đàn bà ấy nói với chồng mình: “Này Hiền phu, những người bà con này muốn dùng sức mạnh bắt tôi phải xa anh và muốn gả cho một người đàn ông khác. Nhưng tôi không muốn như vậy”. Rồi người ấy chặt người đàn bà ấy làm hai, rồi tự vận, nghĩ rằng: “Hai chúng ta sẽ gặp nhau trong đời sau”. Này Bà-la-môn, do pháp môn này cần phải được hiểu rằng sầu, bi, khổ, ưu, não do ái sanh ra, hiện hữu từ nơi ái.`, ref: "MN 87 – Kinh Ái Sanh", url: "../mn/mn87.html#content" },
{ text: `Rồi trong khi tản bộ thưởng ngoạn, vua Pasenadi nước Kosala thấy những gốc cây khả ái, đẹp mắt, lặng tiếng, ít ồn, vắng người, thoáng gió, xa lánh mọi tụ hội đông đảo, thích hợp với trầm tư mặc tưởng. Thấy vậy, vua liền nghĩ đến Thế Tôn: “Những gốc cây khả ái, đẹp mắt, lặng tiếng, ít ồn, vắng người, thoáng gió, xa lánh mọi tụ hội đông đảo, thích hợp với trầm tư mặc tưởng này, chính tại đây, chúng ta đảnh lễ Thế Tôn, bậc A-la-hán, Chánh Ðẳng Giác”.`, ref: "MN 89 – Kinh Pháp Trang Nghiêm", url: "../mn/mn89.html#content" },

{ text: `Ở đây, Bạch Thế Tôn, con thấy các Tỷ-kheo sống hành trì Phạm hạnh viên mãn, thanh tịnh cho đến trọn đời, cho đến hơi thở cuối cùng. Bạch Thế Tôn, con không thấy ngoài đây ra có một Phạm hạnh nào khác viên mãn, thanh tịnh như vậy. Bạch Thế Tôn, đây là pháp truyền thống của con đối với Thế Tôn. “Thế Tôn là bậc Chánh Ðẳng Giác. Pháp được Thế Tôn khéo giảng, chư Tăng đệ tử của Thế Tôn khéo tu tập, hành trì”.`, ref: "MN 89 – Kinh Pháp Trang Nghiêm", url: "../mn/mn89.html#content" },

{ text: `Lại nữa bạch Thế Tôn, vua chúa cãi lộn với vua chúa, Sát-đế-lị cãi lộn với Sát-đế-lị, Bà-la-môn cãi lộn với Bà-la-môn, gia chủ cãi lộn với gia chủ, mẹ cãi lộn với con, con cãi lộn với mẹ, cha cãi lộn với con, con cãi lộn với cha, anh em cãi lộn với anh em, anh em cãi lộn với chị em, chị em cãi lộn với anh em, bạn bè cãi lộn với bạn bè. Còn ở đây, bạch Thế Tôn, con thấy các Tỷ-kheo sống với nhau thuận hòa, thân hữu, không cãi lộn nhau, hòa hợp như nước với sữa, nhìn nhau với cặp mắt ái kính. Bạch Thế Tôn, con không thấy ngoài đây ra, có một Phạm hạnh nào khác viên mãn, thanh tịnh như vậy. Bạch Thế Tôn, đây là pháp truyền thống của con đối với Thế Tôn: “Thế Tôn là bậc Chánh Ðẳng Giác, Pháp được Thế Tôn khéo giảng, đệ tử chúng Tăng của Thế Tôn khéo tu tập, hành trì”.`, ref: "MN 89 – Kinh Pháp Trang Nghiêm", url: "../mn/mn89.html#content" },

{ text: `Còn ở đây, bạch Thế Tôn, con thấy các Tỷ-kheo hân hoan, phấn khởi, hỷ lạc, các căn thoải mái, không dao động, bình tĩnh, sống dựa vào sự hỷ cúng của người khác, với tâm tư như con thú rừng. Bạch Thế Tôn, con suy nghĩ như sau: “Thật sự các bậc Tôn giả này ý thức được một sự tối thắng thù diệu nào trong giáo lý Thế Tôn, một sự thành đạt tuần tự nên các bậc Tôn giả này hân hoan, phấn khởi, hỷ lạc, các căn thoải mái, không dao động, bình tĩnh, sống dựa vào sự hỷ cúng của người khác, với tâm tư như con thú rừng. Bạch Thế Tôn, đây là pháp truyền thống của con đối với Thế Tôn: “Thế Tôn là bậc Chánh Ðẳng Giác, Pháp được Thế Tôn khéo giảng, đệ tử chúng Tăng của Thế Tôn khéo tu tập hành trì”.`, ref: "MN 89 – Kinh Pháp Trang Nghiêm", url: "../mn/mn89.html#content" },

{ text: `Ở đây, bạch Thế Tôn, con thấy các Tỷ-kheo, trong khi Thế Tôn thuyết pháp cho đồ chúng hàng trăm người, trong khi ấy không có một tiếng nhảy mũi hay tiếng ho khởi lên. Bạch Thế Tôn, thuở xưa, trong khi Thế Tôn thuyết pháp cho đồ chúng hàng trăm người, có người đệ tử Thế Tôn ho lên. Một đồng Phạm hạnh khẽ đập vào đầu gối và nói: “Tôn giả hãy im lặng, Tôn giả chớ có làm ồn. Thế Tôn, bậc Ðạo Sư của chúng ta đang thuyết pháp”. Bạch Thế Tôn, con khởi lên ý nghĩ như sau: “Thật vi diệu thay! Thật hy hữu thay! Thính chúng này thật khéo được huấn luyện, không gậy, không kiếm. Bạch Thế Tôn, con không thấy ngoài đồ chúng này có một đồ chúng nào khác được khéo huấn luyện như đồ chúng này.”`, ref: "MN 89 – Kinh Pháp Trang Nghiêm", url: "../mn/mn89.html#content" },
{ text: `—Này Dhananjani, Ông nghĩ thế nào? Ở đây, có người vì vợ con làm các điều phi pháp, làm các điều bất chánh. Do nhân duyên làm các điều phi pháp, làm các điều bất chánh, các địa ngục quân kéo người ấy đến địa ngục. Người ấy làm được gì khi nói: “Tôi vì vợ con đã làm các điều phi pháp, đã làm điều bất chánh. Chớ có để các địa ngục quân kéo tôi đến địa ngục”? Hay vợ con người ấy có làm được gì khi nói: “Chồng, cha tôi vì chúng tôi đã làm các điều phi pháp, đã làm các điều bất chánh. Chớ có để các địa ngục quân kéo chồng, cha tôi đến địa ngục”?\n—Thưa không được, Tôn giả Sāriputta. Các địa ngục quân vẫn quăng người ấy xuống địa ngục, dầu người ấy có khóc than.`, ref: "MN 97 – Kinh Dhànanjàni", url: "../mn/mn97.html#content" },
{ text: `Này các Tỷ-kheo, các dục là vô thường, trống rỗng, giả dối, thuộc ngu si tánh. Này các Tỷ-kheo, đây là lời chào xáo của kẻ ngu xây dựng trên giả dối. Các dục hiện tại, và các dục tương lai, các dục tưởng hiện tại và các dục tưởng tương lai, cả hai đều thuộc lãnh vực của ma, là cảnh giới của ma, là chỗ dinh dưỡng của ma, là chỗ ăn uống của ma.`, ref: "MN 106 – Kinh Bất Động Lợi Ích", url: "../mn/mn106.html#content" },

{ text: `Ở đây, các ác bất thiện ý này dẫn đến tham dục, sân hận, khích động, và chính những pháp ấy tác thành chướng ngại ở đây cho Thánh đệ tử học tập. Ở đây, này các Tỷ-kheo, vị Thánh đệ tử suy nghĩ như sau: “Các dục hiện tại, và các dục tương lai, các dục tưởng hiện tại và các dục tưởng tương lai, cả hai đều thuộc lãnh vực của ma, là cảnh giới của ma, là chỗ dinh dưỡng của ma, là chỗ ăn uống của ma. Vậy ta hãy an trú với tâm quảng đại, đại hành, sau khi chiến thắng thế giới, sau khi xác định vị trí của ý. Khi ta an trú với tâm quảng đại, đại hành chiến thắng thế giới, xác định vị trí của ý, các ác bất thiện ý: tham dục, sân hận, khích động sẽ không khởi lên; với các pháp ấy được đoạn trừ, tâm của ta không trở thành hạn hẹp, trái lại thành vô lượng, khéo tu tập”.`, ref: "MN 106 – Kinh Bất Động Lợi Ích", url: "../mn/mn106.html#content" },

{ text: `Lại nữa này các Tỷ-kheo, vị Thánh đệ tử suy nghĩ như sau: “Những dục hiện tại và những dục tương lai, những dục tưởng hiện tại, và những dục tưởng tương lai, phàm bất cứ sắc pháp gì, là bốn đại chủng và sắc do bốn đại tạo thành”. Trong khi vị ấy hành trì như vậy, an trú nhiều lần như vậy, tâm trở thành an tịnh trong giới xứ (của nó). Với tâm an tịnh, vị ấy thành tựu Bất động ngay trong hiện tại hay thiên nặng về trí tuệ. Sau khi thân hoại mạng chung, sự tình này xảy ra, thức diễn tiến ấy có thể tùy theo đây đạt đến Bất động.`, ref: "MN 106 – Kinh Bất Động Lợi Ích", url: "../mn/mn106.html#content" },

{ text: `Lại nữa này các Tỷ-kheo, vị Thánh đệ tử suy nghĩ như sau: “Những dục hiện tại và những dục tương lai, những dục tưởng hiện tại và những dục tưởng tương lai, những sắc pháp hiện tại và những sắc pháp tương lai, những sắc tưởng hiện tại và những sắc tưởng tương lai, cả hai đều vô thường. Cái gì vô thường thời không đáng để được hoan hỷ, không đáng để được hoan nghênh, không đáng để được chấp trước”. Trong khi vị ấy hành trì như vậy, an trú nhiều lần như vậy, tâm trí trở thành an tịnh trong giới xứ (của nó). Với tâm an tịnh, vị ấy thành tựu Bất động ngay trong hiện tại hay thiên nặng về trí tuệ. Sau khi thân hoại mạng chung, sự tình này xảy ra, thức diễn tiến ấy có thể tùy theo đây đạt đến Bất động.`, ref: "MN 106 – Kinh Bất Động Lợi Ích", url: "../mn/mn106.html#content" },

{ text: `Ở đây, này Ānanda, một Tỷ-kheo hành trì như vậy và suy nghĩ: “Nếu trước không có như vậy thời có thể không là của ta. Nếu nay không có như vậy, thời có thể sẽ không là của ta. Ta đoạn trừ những gì hiện có và những gì đã có”. Và như vậy vị ấy được xả. Vị ấy hoan hỷ trong xả ấy, hoan nghênh, chấp trước xả ấy. Do vị ấy hoan hỷ trong xả ấy, hoan nghênh, chấp trước xả ấy, thức lệ thuộc xả ấy và thủ trước xả ấy. Có thủ trước, này Ānanda, vị Tỷ-kheo không chứng cứu cánh Niết-bàn.`, ref: "MN 106 – Kinh Bất Động Lợi Ích", url: "../mn/mn106.html#content" },

{ text: `Những gì, này Ānanda, vị Ðạo sư cần phải làm, vì lòng từ mẫn mưu tìm hạnh phúc cho các đệ tử, những điều ấy đã được Ta làm, vì lòng từ mẫn của Ta đối với Ông. Này Ānanda, đây là những gốc cây, đây là những khoảng trống. Hãy tu Thiền, này Ānanda, chớ có phóng dật, chớ có hối hận về sau. Ðây là lời dạy của Ta cho Ông.`, ref: "MN 106 – Kinh Bất Động Lợi Ích", url: "../mn/mn106.html#content" },
{ text: `Có thể trình bày, này Bà-la-môn, trong Pháp và Luật này, có một tuần tự học tập, có một tuần tự công trình, có một tuần tự đạo lộ. Ví như, này Bà-la-môn, một người huấn luyện ngựa thiện xảo, sau khi được một con ngựa hiền thiện, trước tiên luyện tập cho nó quen mang dây cương, rồi tập luyện cho nó quen các hạnh khác; cũng vậy, này Bà-la-môn, Như Lai khi được một người đáng được điều phục, trước tiên huấn luyện người ấy như sau: “Hãy đến Tỷ-kheo, hãy giữ giới hạnh, hãy sống chế ngự với sự chế ngự của giới bổn, đầy đủ oai nghi chánh hạnh, thấy sự nguy hiểm trong những lỗi nhỏ nhặt, thọ trì và học tập các học giới”.`, ref: "MN 107 – Kinh Ganaka Moggallāna", url: "../mn/mn107.html#content" },

{ text: `Này Bà-la-môn, khi vị Tỷ-kheo giữ giới hạnh, chế ngự với sự chế ngự của giới bổn, đầy đủ oai nghi chánh hạnh, thấy sự nguy hiểm trong những lỗi nhỏ nhặt, thọ trì và học tập các học giới, Như Lai mới huấn luyện vị ấy thêm như sau: “Hãy đến Tỷ-kheo, hãy hộ trì các căn, khi mắt thấy sắc chớ có nắm giữ tướng chung, chớ có nắm giữ tướng riêng. Những nguyên nhân gì, vì nhãn căn không được chế ngự khiến tham ái, ưu bi, các ác bất thiện pháp khởi lên, vị Tỷ-kheo tự chế ngự nguyên nhân ấy, hộ trì con mắt, thực hành sự hộ trì con mắt. Khi tai nghe tiếng … mũi ngửi hương … lưỡi nếm vị. Thân cảm xúc … ý nhận thức các pháp, vị ấy không nắm giữ tướng chung, không nắm giữ tướng riêng. Những nguyên nhân gì, vì ý căn không được chế ngự, khiến tham ái, ưu bi, các pháp ác bất thiện khởi lên, Tỷ-kheo chế ngự nguyên nhân ấy, hộ trì ý căn, thực hành sự hộ trì ý căn”.`, ref: "MN 107 – Kinh Ganaka Moggallāna", url: "../mn/mn107.html#content" },

{ text: `Này Bà-la-môn, sau khi Tỷ-kheo hộ trì các căn rồi, Như Lai mới huấn luyện vị ấy thêm như sau: “Hãy đến Tỷ-kheo, hãy tiết độ trong ăn uống, chơn chánh giác sát thọ dụng món ăn, không phải để vui đùa, không phải để đam mê, không phải để trang sức, không phải để tự làm đẹp mình, chỉ để thân này được duy trì, được bảo dưỡng, khỏi bị gia hại, để chấp trì Phạm hạnh, nghĩ rằng: “Như vậy ta diệt trừ các cảm thọ cũ và không cho khởi lên các cảm thọ mới; và ta sẽ không phạm lỗi lầm, sống được an ổn”.`, ref: "MN 107 – Kinh Ganaka Moggallāna", url: "../mn/mn107.html#content" },

{ text: `Này Bà-la-môn, sau khi Tỷ-kheo tiết độ trong ăn uống rồi, Như Lai mới huấn luyện vị ấy thêm như sau: “Hãy đến Tỷ-kheo, hãy chú tâm cảnh giác! Ban ngày trong khi đi kinh hành và trong khi đang ngồi, gột sạch tâm trí khỏi các chướng ngại pháp; ban đêm trong canh đầu, trong khi đi kinh hành và trong khi đang ngồi, gột sạch tâm trí khỏi các chướng ngại pháp; ban đêm trong canh giữa, hãy nằm xuống phía hông bên phải, như dáng nằm con sư tử, chân gác trên chân với nhau, chánh niệm tỉnh giác, hướng niệm đến lúc ngồi dậy lại. Ban đêm trong canh cuối, khi đã thức dậy, trong khi đi kinh hành và trong khi đang ngồi, gột sạch tâm trí khỏi các chướng ngại pháp”.`, ref: "MN 107 – Kinh Ganaka Moggallāna", url: "../mn/mn107.html#content" },

{ text: `Này, Bà-la-môn, sau khi vị Tỷ-kheo chú tâm tỉnh giác, Như Lai mới huấn luyện vị ấy thêm nữa như sau: “Hãy đến Tỷ-kheo, hãy thành tựu chánh niệm tỉnh giác, khi đi tới khi đi lui đều tỉnh giác; khi nhìn thẳng, khi nhìn quanh đều tỉnh giác; khi co tay, khi duỗi tay đều tỉnh giác; khi mang y kép, bình bát, thượng y đều tỉnh giác; khi ăn, uống, nhai, nuốt, đều tỉnh giác; khi đi đại tiện, tiểu tiện đều tỉnh giác; khi đi, đứng, ngồi, nằm, thức, nói, yên lặng đều tỉnh giác”.`, ref: "MN 107 – Kinh Ganaka Moggallāna", url: "../mn/mn107.html#content" },

{ text: `Này Bà-la-môn, sau khi chánh niệm tỉnh giác rồi, Như Lai mới huấn luyện vị ấy thêm như sau: “Hãy đến Tỷ-kheo, hãy lựa một chỗ thanh vắng, tịch mịch như rừng, gốc cây, khe núi, hang đá, bãi tha ma, lùm cây, ngoài trời, đống rơm”.`, ref: "MN 107 – Kinh Ganaka Moggallāna", url: "../mn/mn107.html#content" },

{ text: `Vị ấy lựa một chỗ thanh vắng, tịch mịch, như rừng, gốc cây, khe núi, hang đá, bãi tha ma, lùm cây, ngoài trời, đống rơm. Sau khi đi khất thực về và ăn xong, vị ấy ngồi kiết-già, lưng thẳng tại chỗ nói trên và an trú chánh niệm trước mặt. Vị ấy từ bỏ tham ái ở đời, sống với tâm thoát ly tham ái, gột rửa tâm hết tham ái. Từ bỏ sân hận, vị ấy sống với tâm không sân hận, lòng từ mẫn thương xót tất cả chúng hữu tình, gột rửa tâm hết sân hận. Từ bỏ hôn trầm thụy miên, vị ấy sống thoát ly hôn trầm thụy miên, với tâm tưởng hướng về ánh sáng, chánh niệm tỉnh giác, gột rửa tâm hết hôn trầm thụy miên; từ bỏ trạo cử hối tiếc, vị ấy sống không trạo cử, nội tâm trầm lặng, gột rửa tâm hết trạo cử hối tiếc; từ bỏ nghi ngờ, vị ấy sống thoát khỏi nghi ngờ, không phân vân lưỡng lự, gột rửa tâm hết nghi ngờ đối với các thiện pháp.`, ref: "MN 107 – Kinh Ganaka Moggallāna", url: "../mn/mn107.html#content" },

{ text: `Khi đoạn trừ năm triền cái ấy, những pháp làm ô nhiễm tâm, làm trí tuệ yếu ớt, vị ấy ly dục, ly bất thiện pháp chứng và trú Thiền thứ nhất, một trạng thái hỷ lạc do ly dục sanh, với tầm với tứ. Vị ấy diệt tầm và tứ, chứng và trú Thiền thứ hai, một trạng thái hỷ lạc do định sanh, không tầm không tứ, nội tĩnh nhất tâm. Vị ấy ly hỷ trú xả, chánh niệm tỉnh giác, thân cảm sự lạc thọ mà các bậc Thánh gọi là xả niệm lạc trú, chứng và trú Thiền thứ ba. Xả lạc, xả khổ, diệt hỷ ưu đã cảm thọ trước, chứng và trú Thiền thứ tư, không khổ, không lạc, xả niệm thanh tịnh.`, ref: "MN 107 – Kinh Ganaka Moggallāna", url: "../mn/mn107.html#content" },

{ text: `Này Bà-la-môn, do nhân gì, do duyên gì, trong khi có mặt Rājagaha, trong khi có mặt con đường đưa đến Rājagaha, trong khi có mặt Ông là người chỉ đường, dầu cho Ông có khuyến giáo như vậy, giảng dạy như vậy, một người lấy con đường sai lạc, đi về hướng Tây, còn một người có thể đi đến Rājagaha một cách an toàn?\n—Thưa Tôn giả Gotama, ở đây, con làm gì được? Con chỉ là người chỉ đường, thưa Tôn giả Gotama.\n—Cũng vậy, này Bà-la-môn, trong khi có mặt Niết-bàn, trong khi có mặt con đường đi đến Niết-bàn, và trong khi có mặt Ta là bậc chỉ đường. Nhưng các đệ tử của Ta, được Ta khuyến giáo như vậy, giảng dạy như vậy, một số chứng được cứu cánh đích Niết-bàn, một số không chứng được. Ở đây, này Bà-la-môn, Ta làm gì được? Như Lai chỉ là người chỉ đường.`, ref: "MN 107 – Kinh Ganaka Moggallāna", url: "../mn/mn107.html#content" },

{ text: `Thưa Tôn giả Gotama, đối với những người không phải vì lòng tin, chỉ vì sinh kế, xuất gia, từ bỏ gia đình, sống không gia đình, những người xảo trá, lường gạt, hư ngụy, mất thăng bằng, cao mạn, dao động, nói phô tạp nhạp, không hộ trì các căn, ăn uống không tiết độ, không chú tâm cảnh giác, thờ ơ với Sa-môn hạnh, không tôn kính học tập, sống quá đầy đủ, uể oải, đi đầu trong thối thất, từ bỏ gánh nặng viễn ly, biếng nhác, tinh cần thấp kém, thất niệm, không tỉnh giác, không định tâm, tâm tán loạn, liệt tuệ, câm ngọng; Tôn giả Gotama không thể sống với những người như vậy.`, ref: "MN 107 – Kinh Ganaka Moggallāna", url: "../mn/mn107.html#content" },

{ text: `Thưa Tôn giả Gotama, với những Thiện gia nam tử vì lòng tin xuất gia, từ bỏ gia đình, sống không gia đình, không xảo trá, không lường gạt, không hư ngụy, không mất thăng bằng, không cao mạn, không dao động, không nói phô tạp nhạp, hộ trì các căn, ăn uống có tiết độ, chú tâm tỉnh giác, không thờ ơ với Sa-môn hạnh, tôn kính học tập, sống không quá đầy đủ, không uể oải, từ bỏ thối thất, đi đầu trong viễn ly, tinh cần, tinh tấn, chánh niệm, an trú, tỉnh giác, định tĩnh, nhứt tâm, có trí tuệ, không câm ngọng; Tôn giả Gotama sống hòa hợp với những vị ấy.`, ref: "MN 107 – Kinh Ganaka Moggallāna", url: "../mn/mn107.html#content" },

{ text: `Thưa Tôn giả Gotama, Ví như trong các loại căn hương, hắc chiên đàn hương được gọi là tối thượng; trong các loại lõi cây hương, xích chiên đàn hương được gọi là tối thượng; trong các loại hoa hương, vũ quý hương (jasmine) được gọi là tối thượng. Cũng vậy là lời khuyến giáo của Tôn giả Gotama được xem là cao nhất trong những lời khuyến giáo hiện nay.`, ref: "MN 107 – Kinh Ganaka Moggallāna", url: "../mn/mn107.html#content" },

{ text: `Thật vi diệu thay, thưa Tôn giả Gotama! Thật vi diệu thay, thưa Tôn giả Gotama! Như người dựng đứng lại những gì bị quăng ngã xuống, phơi bày những gì bị che kín, chỉ đường cho những người bị lạc hướng, đem đèn sáng vào trong bóng tối để những ai có mắt có thể thấy sắc; cũng vậy, Chánh pháp đã được Tôn giả Gotama dùng nhiều phương tiện trình bày giải thích. Con xin quy y Tôn giả Gotama, quy y Pháp và chúng Tỷ-kheo Tăng. Mong Tôn giả Gotama nhận con làm đệ tử, từ nay cho đến mạng chung, con trọn đời quy ngưỡng.`, ref: "MN 107 – Kinh Ganaka Moggallāna", url: "../mn/mn107.html#content" },
{ text: `Này Bà-la-môn, Thế Tôn, bậc Tri Giả, Kiến Giả, bậc A-la-hán, Chánh Ðẳng Giác đã thi thiết học pháp, đã tuyên bố giới bổn Pātimokkha cho các Tỷ-kheo. Trong những ngày Bố-tát Uposatha chúng tôi cận trú ở chung một thôn điền, tất cả chúng tôi hội họp với nhau tại một chỗ; sau khi tụ họp, chúng tôi hỏi những gì đã xảy ra cho mỗi một người. Nếu trong khi hỏi nhau như vậy, có Tỷ-kheo phạm tội, phạm giới, chúng tôi bảo vị ấy làm đúng Pháp, đúng lời dạy. Thật vậy, không phải các Tôn giả xử sự chúng tôi, chính pháp xử sự chúng tôi.`, ref: "MN 108 – Kinh Ganaka Moggallāna", url: "../mn/mn108.html#content" },

{ text: `Này Bà-la-môn, giữa chúng tôi, vị nào có đầy đủ các pháp này, chúng tôi nay cung kính, tôn trọng, lễ bái, cúng dường vị ấy; sau khi cung kính, tôn trọng, chúng tôi an trú, nương tựa vị ấy. Ở đây, này Bà-la-môn, Tỷ-kheo có giới hạnh, sống chế ngự với sự chế ngự của giới bổn Pātimokkha, đầy đủ oai nghi chánh hạnh, thấy sự nguy hiểm trong những lỗi nhỏ nhặt, sau khi thọ trì, học tập trong các học pháp. Vị ấy là bậc đa văn, thọ trì những điều đã nghe, cất chứa những điều đã nghe; những pháp nào sơ thiện, trung thiện, hậu thiện, với nghĩa, với văn, nói lên Phạm hạnh hoàn toàn đầy đủ thanh tịnh, những pháp ấy đều được nghe nhiều, được thọ trì, được lời nói làm cho quen thuộc, được ý tư niệm, được chánh kiến khéo ngộ nhập. Vị ấy biết đủ đối với các vật thực dụng như y, đồ ăn khất thực, sàng tọa, dược phẩm trị bệnh. Vị ấy là người tùy theo ý muốn, không có khó khăn, không có mệt nhọc, chứng được bốn Thiền, thuộc tăng thượng tâm hiện tại lạc trú. Vị ấy với sự đoạn diệt các lậu hoặc, sau khi với thượng trí đã chứng ngộ, vị ấy chứng đạt và an trú ngay trong hiện tại vô lậu tâm giải thoát, tuệ giải thoát.`, ref: "MN 108 – Kinh Ganaka Moggallāna", url: "../mn/mn108.html#content" },

{ text: `Thật vậy, thưa Tôn giả Ānanda, Veluvana là một chỗ khả ái, ít tiếng động, ít tiếng ồn, được che khỏi gió, xa lánh dân cư đông đúc, thích hợp Thiền tịnh, xứng đáng với những người tu Thiền và tánh thiên về Thiền định như quý vị Tôn giả. Và chư vị Tôn giả là những vị tu Thiền và tánh thiên về Thiền định. Thưa Tôn giả Ānanda, một thời Tôn giả Gotama ở tại Vesālī, Ðại Lâm, ở Kutagarasala. Rồi, thưa Tôn giả Ānanda, tôi đi đến Tôn giả Gotama. Ở đấy, Tôn giả Gotama dùng nhiều phương tiện nói về Thiền định luận. Tôn giả Gotama thật là vị tu Thiền và tánh thiên về Thiền định.`, ref: "MN 108 – Kinh Ganaka Moggallāna", url: "../mn/mn108.html#content" },

{ text: `Này Bà-la-môn, loại Thiền định nào Thế Tôn không tán thán? Ở đây, này Bà-la-môn, một số vị sống với tâm thấm nhuần dục tham, bị dục tham chi phối, và không như thật biết sự giải thoát khỏi dục tham đã được khởi lên. Vị ấy lấy dục tham làm đối tượng tối hậu, Thiền tu, Thiền tư, Thiền định, Thiền nhập. Vị ấy sống với tâm thấm nhuần sân hận, bị sân hận chi phối, và không như thật biết sự giải thoát khỏi sân hận đã được khởi lên. Vị ấy lấy sân hận làm đối tượng tối hậu, Thiền tu, Thiền tư, Thiền định, Thiền nhập. Này Bà-la-môn, Thế Tôn không tán thán loại Thiền định như vậy.`, ref: "MN 108 – Kinh Ganaka Moggallāna", url: "../mn/mn108.html#content" },

{ text: `Này Bà-la-môn, loại Thiền định nào Thế Tôn không tán thán? Vị ấy sống với tâm thấm nhuần hôn trầm thụy miên, bị hôn trầm thụy miên chi phối, và không như thật biết sự giải thoát khỏi hôn trầm thụy miên đã được khởi lên. Vị ấy lấy hôn trầm thụy miên làm đối tượng tối hậu, Thiền tu, Thiền tư, Thiền định, Thiền nhập. Vị ấy sống với tâm thấm nhuần trạo hối, bị trạo hối chi phối và không như thật biết sự giải thoát khỏi trạo hối đã được khởi lên. Vị ấy lấy trạo hối làm đối tượng tối hậu, Thiền tu, Thiền tư, Thiền định, Thiền nhập. Vị ấy sống với tâm thấm nhuần nghi hoặc, bị nghi hoặc chi phối và không như thật biết sự giải thoát khỏi nghi hoặc đã được khởi lên. Vị ấy lấy nghi hoặc làm đối tượng tối hậu, Thiền tu, Thiền tư, Thiền định, Thiền nhập. Này Bà-la-môn, Thế Tôn không tán thán loại Thiền định như vậy.`, ref: "MN 108 – Kinh Ganaka Moggallāna", url: "../mn/mn108.html#content" },

{ text: `Và này Bà-la-môn, loại Thiền định nào Thế Tôn ấy tán thán? Ở đây, này Bà-la-môn, Tỷ-kheo ly dục, ly bất thiện pháp chứng và trú Thiền thứ nhất, một trạng thái hỷ lạc do ly dục sanh, với tầm với tứ. Vị ấy diệt tầm và tứ, chứng và trú Thiền thứ hai, một trạng thái hỷ lạc do định sanh, không tầm không tứ, nội tĩnh nhất tâm. Vị ấy ly hỷ trú xả, chánh niệm tỉnh giác, thân cảm sự lạc thọ mà các bậc Thánh gọi là xả niệm lạc trú, chứng và trú Thiền thứ ba. Xả lạc, xả khổ, diệt hỷ ưu đã cảm thọ trước, chứng và trú Thiền thứ tư, không khổ, không lạc, xả niệm thanh tịnh. Này Bà-la-môn, loại Thiền như vậy, Thế Tôn ấy tán thán.`, ref: "MN 108 – Kinh Ganaka Moggallāna", url: "../mn/mn108.html#content" },

{ text: `Này Bà-la-môn, Thế Tôn là bậc làm cho khởi dậy con đường trước đây chưa từng được hiện khởi, làm cho biết con đường trước đây chưa từng được biết, nói lên con đường trước đây chưa từng được nói; là bậc hiểu đạo, biết đạo và thiện xảo về đạo. Và nay các đệ tử Ngài là những vị sống hành đạo và tùy hành đạo, và sẽ thành tựu những pháp ấy về sau.`, ref: "MN 108 – Kinh Ganaka Moggallāna", url: "../mn/mn108.html#content" },
{ text: `Do vậy, này các Tỷ-kheo, phàm có sắc gì, quá khứ, vị lai hay hiện tại, nội hay ngoại … tất cả loại sắc, cần phải như thật quán: “Cái này không phải của tôi, cái này không phải là tôi, cái này không phải tự ngã của tôi”. Phàm có thọ gì, phàm có tưởng gì, phàm có hành gì, phàm có thức gì quá khứ, vị lai hay hiện tại, nội hay ngoại. Tất cả loại thức, cần phải như thật quán: “Cái này không phải của tôi, cái này không phải là tôi, cái này không phải tự ngã của tôi”.`, ref: "MN 109 – Ðại kinh Mãn nguyệt", url: "../mn/mn109.html#content" },
{ text: `Và này các Tỷ-kheo, như thế nào là người bất chánh có tà kiến như người bất chánh? Ở đây, này các Tỷ-kheo, người bất chánh có tà kiến như sau: “Không có bố thí, không có lễ hy sinh, không có tế tự, không có quả dị thục các nghiệp thiện ác, không có đời này, không có đời khác, không có cha, không có mẹ, không có loại hóa sanh. Ở đời, không có những vị Sa-môn, những vị Bà-la-môn chánh hướng, chánh hạnh đã tự mình chứng đạt với thượng trí đời này và đời khác, và truyền dạy lại”. Như vậy, này các Tỷ-kheo, là người bất chánh có tà kiến như người bất chánh.`, ref: "MN 110 – Tiểu kinh Mãn nguyệt", url: "../mn/mn110.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là người bất chánh bố thí như người bất chánh? Ở đây, này các Tỷ-kheo, người bất chánh bố thí một cách vô lễ, bố thí không phải tự tay, bố thí không có suy tư kỹ lưỡng, bố thí những vật không cần dùng, bố thí không nghĩ đến tương lai. Như vậy, này các Tỷ-kheo, là người bất chánh bố thí như người bất chánh.`, ref: "MN 110 – Tiểu kinh Mãn nguyệt", url: "../mn/mn110.html#content" },

{ text: `Và này, các Tỷ-kheo, như thế nào là người chơn chánh suy tư như người chơn chánh? Ở đây, này các Tỷ-kheo, người chơn chánh không suy nghĩ tự làm hại mình, không suy nghĩ làm hại người khác, không suy nghĩ làm hại cả hai. Như vậy, này các Tỷ-kheo, là người chơn chánh suy tư như người chơn chánh.`, ref: "MN 110 – Tiểu kinh Mãn nguyệt", url: "../mn/mn110.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là người chơn chánh có chánh kiến như bậc chơn chánh? Ở đây, này các Tỷ-kheo, người chơn chánh có chánh kiến như sau: “Có bố thí, có lễ hy sinh, có tế tự, có quả dị thục các nghiệp thiện ác, có đời này, có đời khác, có cha, có mẹ, có loại hóa sanh. Ở đời có những vị Sa-môn, những vị Bà-la-môn chánh hướng, chánh hạnh, đã tự mình chứng đạt với thượng trí đời này và đời khác, và truyền dạy lại. Như vậy, này các Tỷ-kheo, là người chơn chánh có chánh kiến như người chơn chánh.`, ref: "MN 110 – Tiểu kinh Mãn nguyệt", url: "../mn/mn110.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là người chơn chánh bố thí như người chơn chánh? Ở đây, này các Tỷ-kheo, người chơn chánh bố thí một cách lễ độ, bố thí với tự tay, bố thí có suy tư kỹ lưỡng, bố thí những vật cần dùng, bố thí có nghĩ đến tương lai. Như vậy, này các Tỷ-kheo, là người chơn chánh bố thí như người chơn chánh.`, ref: "MN 110 – Tiểu kinh Mãn nguyệt", url: "../mn/mn110.html#content" },
{ text: `Này các Tỷ-kheo, nếu nói một cách chơn chánh về Sāriputta, một người có thể nói như sau: “Sāriputta được tự tại, được cứu cánh trong Thánh giới, được tự tại, được cứu cánh trong Thánh định, được tự tại, được cứu cánh trong Thánh tuệ, được tự tại, được cứu cánh trong Thánh giải thoát”.`, ref: "MN 111 – Kinh Bất Đoạn", url: "../mn/mn111.html#content" },

{ text: `Này các Tỷ-kheo, nếu nói một cách chơn chánh về Sāriputta, một người có thể nói như sau: “Sāriputta là con chánh tông của Thế Tôn, sanh ra từ miệng, sanh ra từ Pháp, do Pháp hóa thành, thừa tự Chánh pháp, không thừa tự vật chất”.`, ref: "MN 111 – Kinh Bất Đoạn", url: "../mn/mn111.html#content" }, 
{ text: `Này các Tỷ-kheo, với Tỷ-kheo, các lậu hoặc đã đoạn tận, tu hành thành mãn, những việc phải làm đã làm, đã đặt gánh nặng xuống, đã thành đạt mục đích, đã đoạn trừ hữu kiết sử, và đã được giải thoát nhờ chánh trí, câu trả lời tùy pháp (anudhamma) của vị ấy phải như sau: “Này chư Hiền, tôi không cảm thấy luyến ái, không chống đối, độc lập, không trói buộc, giải thoát, không hệ lụy, an trú với tâm không có hạn chế, đối với những vật được thấy … được nghe … được cảm giác … được nhận thức. Chư Hiền, vì rằng tôi biết như vậy, thấy như vậy, đối với bốn hình thức tuyên bố này, tôi có thể nói tâm tôi được giải thoát khỏi các lậu hoặc, không có chấp thủ”.`, ref: "MN 112 – Kinh Sáu Thanh Tịnh", url: "../mn/mn112.html#content" },
{ text: `Này các Tỷ-kheo, người Chân nhân suy nghĩ như sau: “Không phải vì thuộc về một gia đình quý phái mà các tham pháp đi đến đoạn trừ, hay các sân pháp đi đến đoạn trừ, hay các si pháp đi đến đoạn trừ. Nếu một người xuất gia không phải từ một gia đình quý phái và người ấy hành trì đúng pháp và thuận pháp, hành trì chơn chánh, hành trì thuận pháp, thời ở đây, người ấy được kính trọng, ở đây, người ấy được tán thán”. Người ấy, sau khi lấy đạo lộ làm chính yếu, không khen mình chê người vì tự mình thuộc vào gia đình quý phái. Như vậy, này các Tỷ-kheo, là Chân nhân pháp.`, ref: "MN 113 – Kinh Chân Nhân", url: "../mn/mn113.html#content" },

{ text: `Này các Tỷ-kheo, người Chân Nhân suy nghĩ như sau: “Không phải vì mình được nhiều người biết đến mà các tham pháp đi đến đoạn trừ, hay sân pháp đi đến đoạn trừ, hay các si pháp đi đến đoạn trừ. Nếu một người xuất gia không được nhiều người biết, không có danh xưng, và người ấy hành trì đúng pháp và thuận pháp, hành trì chơn chánh, hành trì thuận pháp, thời ở đây, người ấy được kính trọng, ở đây, người ấy được tán thán”. Người ấy, sau khi lấy đạo lộ làm chính yếu, không khen mình chê người vì tự mình được nhiều người biết và có danh xưng. Như vậy, này các Tỷ-kheo, là Chân nhân pháp.`, ref: "MN 113 – Kinh Chân Nhân", url: "../mn/mn113.html#content" },

{ text: `Này các Tỷ-kheo, người Chân nhân suy nghĩ như sau: “Không phải vì tự mình là bậc trì luật mà các tham pháp đi đến đoạn trừ hay các sân pháp đi đến đoạn trừ hay các si pháp đi đến đoạn trừ. Nếu có người không phải là bậc trì luật, những người này hành trì đúng pháp và thuận pháp, hành trì chơn chánh, hành trì thuận pháp, thời ở đây, người ấy được kính trọng, ở đây, người ấy được tán thán”. Người ấy sau khi lấy đạo lộ làm chánh yếu, không khen mình chê người vì tự mình là bậc trì luật. Như vậy, này các Tỷ-kheo, là Chân nhân pháp.`, ref: "MN 113 – Kinh Chân Nhân", url: "../mn/mn113.html#content" },

{ text: `Và người Chân nhân, này các Tỷ-kheo, suy nghĩ như sau: “Không phải do tự mình là bậc thuyết pháp mà các tham pháp đi đến đoạn trừ, hay các sân pháp đi đến đoạn trừ, hay các si pháp đi đến đoạn trừ. Nếu một người không phải là người thuyết pháp, nhưng hành trì đúng pháp, và thuận pháp, hành trì chơn chánh, hành trì thuận pháp, thời ở đây người ấy được kính trọng, ở đây, người ấy được tán thán”. Người ấy, sau khi lấy đạo lộ làm chánh yếu, không khen mình chê người vì tự mình là bậc thuyết pháp. Như vậy, này các Tỷ-kheo, là Chân nhân pháp.`, ref: "MN 113 – Kinh Chân Nhân", url: "../mn/mn113.html#content" },

{ text: `Và người Chân nhân, này các Tỷ-kheo, suy nghĩ như sau: “Không phải vì tự mình theo hạnh sống ở rừng núi mà các tham pháp đi đến đoạn trừ, hay các sân pháp đi đến đoạn trừ, hay các si pháp đi đến đoạn trừ. Nếu một người không theo hạnh sống ở rừng núi, nhưng hành trì đúng pháp và thuận pháp, hành trì chơn chánh, hành trì thuận pháp, thời ở đây, người ấy được kính trọng, ở đây, người ấy được tán thán”. Người ấy, sau khi lấy đạo lộ làm chánh yếu, không khen mình chê người, vì tự mình theo hạnh sống ở rừng núi. Như vậy, này các Tỷ-kheo, là Chân nhân pháp.`, ref: "MN 113 – Kinh Chân Nhân", url: "../mn/mn113.html#content" },
{ text: `Và này các Tỷ-kheo, thế nào là tà kiến? Không có bố thí, không có cúng dường, không có tế tự, không có quả báo các nghiệp thiện ác, không có đời này, không có đời khác, không có mẹ, không có cha, không có các loại hóa sanh; ở đời không có các vị Sa-môn, Bà-la-môn, chánh hướng, chánh hạnh, sau khi với thượng trí tự mình chứng đạt lại tuyên bố lên. Như vậy, này các Tỷ-kheo, là tà kiến.`, ref: "MN 117 – Ðại Kinh Bốn Mươi", url: "../mn/mn117.html#content" },

{ text: `Tà niệm, này các Tỷ-kheo, do chánh niệm làm cho tiêu diệt. Và những ác bất thiện pháp được tà niệm duyên khởi, các pháp ấy được tiêu diệt trong người có chánh niệm. Và những thiện pháp được chánh niệm duyên khởi, các pháp ấy được tu tập và trở thành viên mãn.`, ref: "MN 117 – Ðại Kinh Bốn Mươi", url: "../mn/mn117.html#content" },
{ text: `Trong khi vị ấy sống không phóng dật, nhiệt tâm, tinh cần, các niệm và tư duy thuộc về thế tục được đoạn trừ. Nhờ đoạn trừ các pháp ấy, nội tâm được an trú, an tọa, chuyên nhất, định tĩnh. Như vậy, này các Tỷ-kheo, Tỷ-kheo tu tập thân hành niệm.`, ref: "MN 119 – Kinh Thân Hành Niệm", url: "../mn/mn119.html#content" },

{ text: `Này các Tỷ-kheo, đối với vị nào tu tập, làm cho sung mãn thân hành niệm, các thiện pháp của vị ấy đi vào nội tâm đều thuộc về minh phần. Ví như, này các Tỷ-kheo, biển lớn của ai được thấm nhuần bởi tâm, thời các con sông của vị ấy đi vào trong biển, đều thuộc về biển lớn; cũng vậy, này các Tỷ-kheo, đối với vị nào tu tập làm cho sung mãn thân hành niệm, các thiện pháp của vị ấy đi vào nội tâm đều thuộc về minh phần.`, ref: "MN 119 – Kinh Thân Hành Niệm", url: "../mn/mn119.html#content" },
{ text: `Này Ānanda, một Tỷ-kheo không chói sáng nếu thích thú trong hội chúng của mình, nếu hân hoan trong hội chúng của mình, nếu hoan hỷ trong hội chúng của mình, nếu thích thú trong hội chúng của người, nếu hân hoan trong hội chúng của người, nếu hoan hỷ trong hội chúng của người. Này Ānanda, nếu Tỷ-kheo nào thích thú trong hội chúng của mình,... hoan hỷ trong hội chúng của người, có thể là một vị chứng đắc tùy theo ý muốn, chứng đắc không khó khăn, chứng đắc không mệt nhọc, viễn ly lạc, độc cư lạc, an tịnh lạc, chánh giác lạc; sự kiện như vậy không xảy ra. Nhưng này Ānanda, Tỷ-kheo nào sống một mình, xa lánh tụ hội, thời vị ấy có hy vọng chứng đắc tùy theo ý muốn, chứng đắc không khó khăn, chứng đắc không mệt nhọc, viễn ly lạc, độc cư lạc, an tịnh lạc, chánh giác lạc; sự kiện như vậy có thể xảy ra.`, ref: "MN 122 – Kinh Đại Không", url: "../mn/mn122.html#content" },

{ text: `Này Ānanda, Ta không quán thấy một sắc pháp nào trong ấy có hoan hỷ, trong ấy có hoan lạc, chịu sự biến dịch, chịu sự đổi khác mà không khởi lên sầu, bi, khổ, ưu, não.`, ref: "MN 122 – Kinh Đại Không", url: "../mn/mn122.html#content" },

{ text: `Nhưng sự (an) trú này, này Ānanda, đã được Như Lai hoàn toàn giác ngộ, tức là sau khi không tác ý với tất cả tướng, chứng đắc và (an) trú nội không. Và nếu này Ānanda, trong khi Như Lai an trú trong an trú này, nếu có những Tỷ-kheo, Tỷ-kheo ni, nam cư sĩ, nữ cư sĩ, quốc vương, đại thần, ngoại đạo, ngoại đạo đệ tử đến yết kiến, trong khi ấy, này Ānanda, Như Lai với tâm hướng đến viễn ly, thiên về viễn ly, nặng nề viễn ly, sống độc cư, hoan hỷ trong ly dục, làm cho đoạn tận tất cả các pháp dựa trên các lậu hoặc an trú, nói lên tại chỗ ấy những lời thuần túy liên hệ đến khích lệ.`, ref: "MN 122 – Kinh Đại Không", url: "../mn/mn122.html#content" },

{ text: `Này Ānanda, vị ấy suy nghĩ: “Ðối với những suy tầm hạ liệt, đê tiện, phàm phu, không thuộc bậc Thánh, không liên hệ đến mục đích, không đưa đến yếm ly, ly tham, đoạn diệt, an tịnh, thắng trí, giác ngộ, Niết-bàn, như là dục tầm, sân tầm, hại tầm, ta sẽ không suy nghĩ các loại suy tầm ấy”. Ở đây, vị ấy ý thức rõ ràng như vậy.`, ref: "MN 122 – Kinh Đại Không", url: "../mn/mn122.html#content" },

{ text: `Này Ānanda, đối với những suy tầm này, thuộc bậc Thánh, có khả năng cầu tiến, hướng dẫn đến sự đoạn trừ hoàn toàn đau khổ, như là ly dục tầm, vô sân tầm, bất hại tầm, vị ấy nghĩ: “Ta sẽ suy tư các loại suy tầm này”. Ở đây, vị ấy ý thức rõ ràng như vậy.`, ref: "MN 122 – Kinh Đại Không", url: "../mn/mn122.html#content" },

{ text: `Và như thế nào, này Ānanda, là các đệ tử đối xử với bậc Ðạo sư với tâm thân hữu, không với tâm thù nghịch? Ở đây, này Ānanda, vị Ðạo sư với lòng từ mẫn thuyết pháp cho các đệ tử, tìm cầu hạnh phúc cho họ, vì lòng từ mẫn nói rằng: “Ðây là hạnh phúc cho các Ông, đây là an lạc cho các Ông”. Các đệ tử của vị ấy chịu nghe theo, chịu lóng tai, không chú tâm vào hướng khác, và không ngược lại đi xa lời dạy của bậc Ðạo sư. Như vậy, này Ānanda, là các đệ tử đối xử với bậc Ðạo sư, với tâm thân hữu, không phải với tâm thù nghịch. Do vậy, này Ānanda, hãy đối xử với Ta với tâm thân hữu, chớ với tâm thù nghịch và như vậy sẽ là hạnh phúc, là an lạc lâu dài cho các Ông.`, ref: "MN 122 – Kinh Đại Không", url: "../mn/mn122.html#content" },

{ text: `Ta không sách tấn các Ông như người thợ gốm đối với các đồ gốm chưa nung, chưa được nung chín. Ta sẽ nói hết lời khiển trách này đến lời khiển trách khác, hết lời thúc giục này đến lời thúc giục khác. Cái gì là lõi cây, cái ấy sẽ đứng vững tồn tại.`, ref: "MN 122 – Kinh Đại Không", url: "../mn/mn122.html#content" },
{ text: `Ở đây, này Ānanda, các cảm thọ khởi lên nơi Thế Tôn được biết đến; được biết đến, chúng an trú; được biết đến, chúng đi đến biến hoại; các tưởng được biết đến; các tầm khởi lên được biết đến; được biết đến, chúng an trú; được biết đến, chúng đi đến biến hoại. Này Ānanda, hãy thọ trì việc này là một hy hữu, một vị tằng hữu của Như Lai.`, ref: "MN 123 – Kinh Hy hữu vị tằng hữu pháp", url: "../mn/mn123.html#content" },
{ text: `Này Aggivessana, nào có lợi ích gì? Vương tử Jayasenna sống giữa các dục, thọ hưởng các dục, bị tư tưởng dục nhai nghiến, bị nhiệt não dục thiêu đốt, tha thiết truy cầu dục, lại có thể biết, có thể thấy, hay có thể chứng quả vị chỉ có ly dục mới biết được, chỉ có ly dục mới thấy được. Chỉ có ly dục mới đạt được, hay chỉ có ly dục mới chứng được; sự kiện như vậy không xảy ra.`, ref: "MN 125 – Kinh Ðiều Ngự Địa", url: "../mn/mn125.html#content" },

{ text: `Tỷ-kheo kham nhẫn lạnh, nóng, đói, khát, sự xúc chạm của muỗi, ruồi, gió, mặt trời và các loài bò sát, các ác ngữ, các lời nói chửi mắng, vị ấy sống quen kham nhẫn với những cảm thọ về thân, thống khổ, đau nhói, đau đớn, kịch liệt, bất khoái, không thích ý, đau đớn đến chết, được gột sạch về uế nhiễm tham, sân, si. Vị ấy xứng đáng được cúng dường, cung kính, tôn trọng, chấp tay, là vô thượng phước điền trên đời.`, ref: "MN 125 – Kinh Ðiều Ngự Địa", url: "../mn/mn125.html#content" },
{ text: `—Này các Anuruddha, các Ông có sống hòa hợp, hoan hỷ với nhau, không có cãi nhau. Như nước với sữa, sống nhìn nhau với cặp mắt thiện cảm không?\n—Bạch Thế Tôn, thật sự chúng con sống hòa hợp, hoan hỷ với nhau, không có cãi nhau, như nước với sữa, sống nhìn nhau với cặp mắt thiện cảm.`, ref: "MN 128 – Kinh Tùy Phiền Não", url: "../mn/mn128.html#content" },

{ text: `Bạch Thế Tôn, ở đây chúng con nghĩ như sau: “Thật lợi ích thay cho ta! Thật khéo lợi ích thay cho ta, khi ta được sống với các vị đồng Phạm hạnh như vậy!” Bạch Thế Tôn, do vậy đối với các vị đồng Phạm hạnh này, con khởi lên từ thân nghiệp, trước mặt và sau lưng; con khởi lên từ khẩu nghiệp, trước mặt và sau lưng, con khởi lên từ ý nghiệp, trước mặt và sau lưng. Bạch Thế Tôn, do vậy chúng con nghĩ như sau: “Ta hãy từ bỏ tâm của ta và sống thuận theo tâm của những Tôn giả này”. Và bạch Thế Tôn, con từ bỏ tâm của con và sống thuận theo tâm của những Tôn giả ấy. Bạch Thế Tôn, chúng con tuy khác thân nhưng giống như đồng một tâm. Bạch Thế Tôn, như vậy chúng con sống hòa hợp, hoan hỷ với nhau, như nước với sữa, sống nhìn nhau với cặp mắt thiện cảm.`, ref: "MN 128 – Kinh Tùy Phiền Não", url: "../mn/mn128.html#content" },
{ text: `Rồi này các Tỷ-kheo, vua Yāma nói với người ấy: “Này người kia, nếu vì phóng dật nên Ngươi không làm điều thiện về thân, khẩu, ý; chắc chắn chúng sẽ làm cho Ngươi, này Người kia, tùy theo sự phóng dật ấy của Ngươi. Vì rằng đây là một ác nghiệp của Ngươi, không phải do mẹ làm, không phải do cha làm, không phải do anh làm, không phải do chị làm, không phải do bạn và thân hữu làm, không phải do bà con huyết thống làm, không phải do Sa-môn, Bà-la-môn làm, không phải do chư Thiên làm. Ác nghiệp ấy chính do Ngươi làm, chính Người phải cảm thọ quả báo việc làm ấy”.`, ref: "MN 130 – Kinh Thiên Sứ", url: "../mn/mn130.html#content" },

{ text: `Dầu Thiên sứ báo động,\nThanh niên vẫn phóng dật,\nHọ ưu buồn lâu dài,\nSanh làm người hạ liệt.\nỞ đây bậc Chân nhân,\nÐược Thiên sứ báo động,\nKhông bao giờ phóng dật,\nTrong diệu pháp bậc Thánh.\nThấy sợ trong chấp thủ,\nTrong hiện hữu sanh tử.\nÐược giải thoát chấp thủ,\nSanh tử được đoạn trừ,\nÐược yên ổn an lạc,\nNgay hiện tại tịch tịnh,\nMọi oán hận sợ hãi,\nCác vị ấy vượt qua,\nMọi đau đớn sầu khổ,\nThảy đều được siêu thoát.`, ref: "MN 130 – Kinh Thiên Sứ", url: "../mn/mn130.html#content" },
{ text: `Quá khứ không truy tìm\nTương lai không ước vọng.\nQuá khứ đã đoạn tận,\nTương lai lại chưa đến,\nChỉ có pháp hiện tại\nTuệ quán chính ở đây.\nKhông động, không rung chuyển\nBiết vậy, nên tu tập,\nHôm nay nhiệt tâm làm,\nAi biết chết ngày mai?\nKhông ai điều đình được,\nVới đại quân thần chết,\nTrú như vậy nhiệt tâm,\nÐêm ngày không mệt mỏi,\nXứng gọi Nhất dạ Hiền,\nBậc an tịnh, trầm lặng.`, ref: "MN 131 – Kinh Nhất Dạ Hiền Giả", url: "../mn/mn131.html#content" },
{ text: `Này Thanh niên, các loài hữu tình là chủ nhân của nghiệp, là thừa tự của nghiệp. Nghiệp là thai tạng, nghiệp là quyến thuộc, nghiệp là điểm tựa, nghiệp phân chia các loài hữu tình; nghĩa là có liệt, có ưu.`, ref: "MN 135 – Tiểu Kinh Nghiệp Phân Biệt", url: "../mn/mn135.html#content" },
{ text: `Và những sanh y vô trí thức trước của nó đã được đầy đủ, đã được thành tựu. Chúng được đoạn tận, chặt tận gốc rễ, làm cho như thân cây tala, không thể hiện hữu nữa trong tương lai, không có khả năng sanh khởi nữa. Do vậy, một Tỷ-kheo thành tựu như vậy là thành tựu với tối thắng huệ thí thắng xứ này. Vì rằng, này Tỷ-kheo, như vậy là tối thắng Thánh huệ thí, tức là sự xả ly tất cả sanh y.`, ref: "MN 140 – Kinh Giới Phân Biệt", url: "../mn/mn140.html#content" },

{ text: `Và tham ái vô trí thức trước của nó, thuộc tham dục, tham nhiễm; pháp ấy được đoạn tận, chặt tận gốc rễ, làm cho như thân cây tala, không thể hiện hữu nữa trong tương lai, không có khả năng sanh khởi nữa. Và sự phẫn nộ vô trí thức trước của nó, thuộc sân hận, thuộc tội quá; pháp ấy được đoạn tận, cắt tận gốc rễ, làm cho như thân cây tala, không thể hiện hữu nữa trong tương lai, không có khả năng sanh khởi nữa. Và vô minh vô trí thức trước của nó, thuộc si mê, thuộc tội quá; pháp ấy được đoạn tận, cắt tận gốc rễ, làm cho như thân cây tala, không thể hiện hữu trong tương lai, không có khả năng sanh khởi nữa. Do vậy, Tỷ-kheo thành tựu như vậy là thành tựu tối thắng tịch tịnh thắng xứ. Này Tỷ-kheo, như vậy là tối thắng Thánh tịch tịnh, tức là sự tịch tịnh tham sân si.`, ref: "MN 140 – Kinh Giới Phân Biệt", url: "../mn/mn140.html#content" },

{ text: `Này Tỷ-kheo, “Tôi là”, như vậy là vọng tưởng. “Tôi là cái này”, như vậy là vọng tưởng. “Tôi sẽ là”, như vậy là vọng tưởng. “Tôi sẽ không là”, như vậy là vọng tưởng. “Tôi sẽ có sắc”, như vậy là vọng tưởng. “Tôi sẽ không có sắc”, như vậy là vọng tưởng. “Tôi sẽ có tưởng”, như vậy là vọng tưởng. “Tôi sẽ không có tưởng”, như vậy là vọng tưởng. “Tôi sẽ không có tưởng, không không có tưởng”, như vậy là vọng tưởng. Vọng tưởng, này Tỷ-kheo, là bệnh, vọng tưởng là cục bướu, vọng tưởng là mũi tên. Này Tỷ-kheo, khi vượt khỏi mọi vọng tưởng, vị ẩn sĩ được gọi là tịch tịnh. Nhưng này Tỷ-kheo, vị ẩn sĩ tịch tịnh không sanh, không già, không có dao động, không có hy cầu. Vì không có cái gì do đó có thể sanh, này Tỷ-kheo, không sanh làm sao già được? Không già, làm sao chết được? Không chết làm sao dao động được? Không dao động, làm sao hy cầu?`, ref: "MN 140 – Kinh Giới Phân Biệt", url: "../mn/mn140.html#content" },
{ text: `Và này Ānanda, thế nào là loại cúng dường được thanh tịnh bởi người cho và cũng bởi người nhận? Ở đây, này Ānanda, người cho giữ giới, theo thiện pháp; và người nhận cũng giữ giới, theo thiện pháp. Như vậy, này Ānanda, là sự cúng dường được thanh tịnh bởi người cho và cũng bởi người nhận.`, ref: "MN 142 – Kinh Phân Biệt Cúng Dường", url: "../mn/mn142.html#content" },

{ text: `Ai đầy đủ giới luật,\nBố thí cho thiện giới;\nVật thí được đúng pháp,\nVới tâm khéo hoan hỷ,\nVới lòng tin vững vàng,\nVào quả lớn của nghiệp,\nTa nói bố thí ấy,\nChắc chắn có quả lớn.`, ref: "MN 142 – Kinh Phân Biệt Cúng Dường", url: "../mn/mn142.html#content" },

{ text: `Ai xuất ly tham ái,\nBố thí không tham ái,\nVật thí được đúng pháp.\nVới tâm khéo hoan hỷ,\nVới lòng tin vững vàng,\nVào quả lớn của nghiệp,\nTa nói bố thí ấy,\nLà bố thí tối thượng.`, ref: "MN 142 – Kinh Phân Biệt Cúng Dường", url: "../mn/mn142.html#content" },
{ text: `-Này Puñña, người nước Sunaparanta là hung bạo. Này Puñña, người nước Sunaparanta là thô ác. Này Puñña, nếu người nước Sunaparanta mắng nhiếc Ông, nhục mạ Ông, thời này Puñña, tại đấy Ông sẽ như thế nào?\n-Bạch Thế Tôn, nếu người nước Sunaparanta mắng nhiếc con, nhục mạ con, thời tại đấy, con sẽ nghĩ như sau: “Thật là hiền thiện, người nước Sunaparanta này! Thật là chí thiện, người nước Sunaparanta này! Vì rằng họ không lấy tay đánh đập ta”. Bạch Thế Tôn, tại đấy con sẽ nghĩ như vậy. Bạch Thiện Thệ, tại đấy con sẽ nghĩ như vậy.`, ref: "MN 145 – Kinh Giáo Giới Phú-Lâu-Na", url: "../mn/mn145.html#content" },
{ text: `Này Sāriputta, nếu Tỷ-kheo sau khi tư duy biết rằng: “Trên con đường ta đã đi vào làng để khất thực, tại trú xứ ta đã đi khất thực và trên con đường từ làng ta đi khất thực trở về, đối với các sắc do mắt nhận thức, có khởi lên nơi ta dục, tham, sân, si hay hận tâm”, thời này Sāriputta, Tỷ-kheo ấy phải tinh tấn đoạn tận các ác bất thiện pháp ấy. Nhưng này Sāriputta, nếu Tỷ-kheo trong khi suy tư được biết như sau: “Trên con đường ta đã đi … ta đi khất thực trở về, đối với các sắc do mắt nhận thức, không có khởi lên nơi dục, tham, sân, si hay hận tâm”, thời này Sāriputta, Tỷ-kheo ấy phải an trú với hỷ và hân hoan ngày đêm tu học trong các thiện pháp.`, ref: "MN 151 – Kinh Khất Thực Thanh Tịnh", url: "../mn/mn151.html#content" },

{ text: `Lại nữa, này Sāriputta, Tỷ-kheo cần phải suy tư như sau: “Ta đã đoạn tận năm dục trưởng dưỡng chưa? Này Sāriputta, nếu Tỷ-kheo, trong khi suy tư được biết như sau: “Ta chưa đoạn tận năm dục trưởng dưỡng”, thời này Sāriputta, Tỷ-kheo ấy phải tinh tấn đoạn tận năm dục trưởng dưỡng. Nhưng nếu, này Sāriputta, Tỷ-kheo trong khi suy tư được biết như sau: “Ta đã đoạn tận năm dục trưởng dưỡng”, thời này Sāriputta, Tỷ-kheo ấy phải an trú với hỷ và hân hoan ngày đêm tu học trong các thiện pháp.`, ref: "MN 151 – Kinh Khất Thực Thanh Tịnh", url: "../mn/mn151.html#content" },

{ text: `Lại nữa, này Sāriputta, Tỷ-kheo cần phải suy tư như sau: “Ta đã đoạn tận năm triền cái chưa?” Nếu, này Sāriputta, trong khi suy tư, Tỷ-kheo được biết như sau: “Ta chưa đoạn tận năm triền cái”, thời này Sāriputta, Tỷ-kheo ấy phải tinh tấn đoạn tận năm triền cái. Nhưng nếu, này Sāriputta, Tỷ-kheo trong khi suy tư được biết như sau: “Ta đã đoạn tận năm triền cái ”, thời này Sāriputta, Tỷ-kheo ấy phải an trú với hỷ và hân hoan ngày đêm tu học trong các thiện pháp.`, ref: "MN 151 – Kinh Khất Thực Thanh Tịnh", url: "../mn/mn151.html#content" },

{ text: `Lại nữa, này Sāriputta, Tỷ-kheo cần phải suy tư như sau: “Ta đã tu tập bốn niệm xứ chưa?” Này Sāriputta, nếu trong khi suy tư, Tỷ-kheo được biết: “Ta chưa tu tập bốn niệm xứ”, thời này Sāriputta, vị Tỷ-kheo cần phải tinh tấn tu tập bốn niệm xứ. Nhưng nếu, này Sāriputta, trong khi suy tư, Tỷ-kheo được biết như sau: “Ta đã tu tập bốn niệm xứ ”, thời này Sāriputta, Tỷ-kheo ấy cần phải an trú với hỷ và hân hoan ngày đêm tu học trong các thiện pháp.`, ref: "MN 151 – Kinh Khất Thực Thanh Tịnh", url: "../mn/mn151.html#content" },

{ text: `Lại nữa, này Sāriputta, Tỷ-kheo cần phải suy tư: “Ta đã tu tập Chỉ và Quán chưa? ” Nếu Tỷ-kheo, này Sāriputta, trong khi suy tư được biết như sau: “Ta chưa tu tập Chỉ và Quán ”, thời này Sāriputta, Tỷ-kheo ấy cần phải tinh tấn tu tập Chỉ và Quán. Nhưng nếu, này các Tỷ-kheo, Tỷ-kheo trong khi suy tư được biết như sau: “Ta đã tu tập Chỉ và Quán ”, thời này Sāriputta, Tỷ-kheo ấy cần phải an trú với hỷ và hân hoan ngày đêm tu học trong các thiện pháp.`, ref: "MN 151 – Kinh Khất Thực Thanh Tịnh", url: "../mn/mn151.html#content" },
{ text: `Như vậy, này Ānanda, Ta đã giảng vô thượng căn tu tập trong giới luật bậc Thánh, đã giảng đạo lộ của bậc hữu học, đã giảng bậc Thánh, các căn được tu tập. Này Ānanda, những gì một bậc Ðạo sư phải làm, vì lòng từ mẫn, mưu cầu hạnh phúc cho các đệ tử, những điều ấy Ta đã làm cho các Ông. Này Ānanda, đây là những gốc cây, đây là những chỗ trống. Này Ānanda, hãy Thiền tư, chớ có phóng dật, chớ có hối hận về sau. Ðây là những lời giáo giới của Ta cho các Ông.`, ref: "MN 152 – Kinh Căn Tu Tập", url: "../mn/mn152.html#content" },

            ],
            sn: [
                { text: "Đang Cập Nhật", ref: "SN 56.11", url: "../sn/sn56.11.html" },
            ],
            an: [
                { text: `Ta không thấy một sắc nào khác, này các Tỷ-kheo, xâm chiếm và ngự trị tâm người đàn ông như sắc người đàn bà. Này các Tỷ-kheo, sắc người đàn bà xâm chiếm và ngự trị tâm người đàn ông.`, ref: "AN 1.1", url: "../an/an1.1.html#content" },

{ text: `Ta không thấy một sắc nào khác, này các Tỷ-kheo, xâm chiếm và ngự trị tâm người đàn bà như sắc người đàn ông. Này các Tỷ-kheo, sắc người đàn ông xâm chiếm và ngự trị tâm người đàn bà.`, ref: "AN 1.6", url: "../an/an1.6.html#content" },

{ text: `Ta không thấy một tiếng nào khác, này các Tỷ-kheo, xâm chiếm và ngự trị tâm người đàn ông, như tiếng người đàn bà. Này các Tỷ-kheo, tiếng người đàn bà xâm chiếm và ngự trị tâm người đàn ông.`, ref: "AN 1.2", url: "../an/an1.2.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ-kheo, dẫn đến dục tham chưa sanh được sanh khởi, hay dục tham đã sanh được tăng trưởng quảng đại, này các Tỷ-kheo, như tịnh tướng. Tịnh tướng, này các Tỷ-kheo, nếu không như lý tác ý, đưa đến dục tham chưa sanh được sanh khởi, hay dục tham đã sanh được tăng trưởng quảng đại.`, ref: "AN 1.11", url: "../an/an1.11.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ-kheo, đưa đến hôn trầm thụy miên chưa sanh được sanh khởi, hay hôn trầm thụy miên đã sanh được tăng trưởng quảng đại, này các Tỷ-kheo, như không hân hoan, biếng nhác, chán nản, ăn quá no, tâm thụ động. Với người có tâm thụ động, này các Tỷ-kheo, hôn trầm thụy miên chưa sanh được sanh khởi, hay hôn trầm thụy miên đã sanh được tăng trưởng quảng đại.`, ref: "AN 1.13", url: "../an/an1.13.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ-kheo, đưa đến dục tham chưa sanh không sanh khởi, hay dục tham đã sanh được đoạn tận, này các Tỷ-kheo, như bất tịnh tướng. Bất tịnh tướng, này các Tỷ-kheo, nếu như lý tác ý, thời dục tham chưa sanh không sanh khởi, hay dục tham đã sanh được đoạn tận.`, ref: "AN 1.16", url: "../an/an1.16.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ-kheo, đưa đến sân chưa sanh không sanh khởi, hay sân đã sanh được đoạn tận, này các Tỷ-kheo, như từ tâm giải thoát. Từ tâm giải thoát, này các Tỷ-kheo, nếu như lý tác ý, thời sân chưa sanh không sanh khởi, hay sân đã sanh được đoạn tận.`, ref: "AN 1.17", url: "../an/an1.17.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ-kheo, đưa đến hôn trầm thụy miên chưa sanh không sanh khởi, hay hôn trầm thụy miên đã sanh được đoạn tận, này các Tỷ kheo, như tinh cần giới, tinh tấn giới, dõng mãnh giới. Người tinh cần tinh tấn, này các Tỷ kheo, hôn trầm thụy miên chưa sanh không sanh khởi, hay hôn trầm thụy miên đã sanh được đoạn tận.`, ref: "AN 1.18", url: "../an/an1.18.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ kheo, lại khó sử dụng, này các Tỷ kheo, như tâm không được tu tập. Tâm không được tu tập, này các Tỷ kheo, khó sử dụng.`, ref: "AN 1.21", url: "../an/an1.21.html#content" },


{ text: `Ta không thấy một pháp nào khác, này các Tỷ kheo, lại dễ sử dụng, này các Tỷ kheo, như tâm được tu tập. Tâm được tu tập, này các Tỷ kheo, dễ sử dụng.`, ref: "AN 1.22", url: "../an/an1.22.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ kheo, lại đưa đến bất lợi lớn, này các Tỷ kheo, như tâm không được tu tập. Tâm không được tu tập, này các Tỷ kheo, đưa đến bất lợi lớn.`, ref: "AN 1.23", url: "../an/an1.23.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ kheo, lại đưa đến lợi ích lớn, này các Tỷ kheo, như tâm được tu tập. Tâm được tu tập, này các Tỷ kheo, đưa đến lợi ích lớn.`, ref: "AN 1.24", url: "../an/an1.34.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, với tâm của Ta biết tâm một người là uế nhiễm, Ta rõ biết: “Nếu trong thời gian này, người này mệnh chung, người ấy bị rơi vào địa ngục như vậy tương xứng”. Vì cớ sao? Này các Tỷ-kheo, vì rằng tâm người ấy uế nhiễm. Cũng do tâm uế nhiễm làm nhân như vậy, này các Tỷ-kheo, một số loài hữu tình ở đời, sau khi thân hoại mạng chung, sanh vào cõi dữ, ác thú, đọa xứ, địa ngục.`, ref: "AN 1.43", url: "../an/an1.43.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, với tâm của Ta biết tâm một người là thanh tịnh, Ta biết rõ: “Nếu trong thời gian này, người này mệnh chung, người ấy được sanh lên Thiên giới như vậy tương xứng”. Vì cớ sao? Này các Tỷ-kheo, vì rằng tâm người ấy thanh tịnh. Cũng do tâm thanh tịnh làm nhân như vậy, này các Tỷ-kheo, một số loài hữu tình ở đời này, sau khi thân hoại mạng chung, sanh vào cõi thiện, cõi Trời, cõi đời này.`, ref: "AN 1.44", url: "../an/an1.44.html#content" },

{ text: `Tâm này, này các Tỷ-kheo, là sáng chói, nhưng bị ô nhiễm bởi các cấu uế từ ngoài vào.`, ref: "AN 1.49", url: "../an/an1.49.html#content" },

{ text: `Nếu chỉ trong khoảnh khắc búng móng tay, này các Tỷ-kheo, vị Tỷ-kheo phát từ tâm; Vị ấy, này các Tỷ-kheo, được gọi là: vị Tỷ-kheo trú Thiền tịnh không có trống không, làm theo lời dạy bậc Ðạo Sư, là người làm theo giáo giới, ăn đồ ăn khất thực của xứ không có uổng phí. Còn nói gì những người làm cho sung mãn từ tâm ấy.`, ref: "AN 1.53", url: "../an/an1.53.html#content" },

{ text: `Phàm những pháp nào, này các Tỷ-kheo, là bất thiện, thuộc thành phần bất thiện, đứng về phía bất thiện, tất cả các pháp ấy đều được ý đi trước. Ý khởi trước các pháp ấy. Các pháp bất thiện theo sau.`, ref: "AN 1.56", url: "../an/an1.56.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ-kheo, do pháp ấy, các pháp bất thiện chưa sanh được sanh khởi, và các pháp thiện đã sanh bị đoạn tận, này các Tỷ-kheo, như phóng dật. Với người phóng dật, này các Tỷ-kheo, các pháp bất thiện chưa sanh được sanh khởi, và các pháp thiện đã sanh bị đoạn tận.`, ref: "AN 1.58", url: "../an/an1.58.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ-kheo, do pháp ấy, các pháp bất thiện chưa sanh được sanh khởi, và các pháp thiện đã sanh bị đoạn tận, này các Tỷ-kheo, như biếng nhác. Với người biếng nhác, này các Tỷ-kheo, các pháp bất thiện chưa sanh được sanh khởi, và các pháp thiện đã sanh bị đoạn tận.`, ref: "AN 1.60", url: "../an/an1.60.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ-kheo, do pháp ấy, các pháp thiện chưa sanh được sanh khởi, và các pháp bất thiện đã sanh được đoạn tận, này các Tỷ-kheo, như tinh tấn tinh cần. Với người tinh cần tinh tấn, này các Tỷ-kheo, các pháp thiện chưa sanh được sanh khởi, và các pháp bất thiện đã sanh được đoạn tận.`, ref: "AN 1.61", url: "../an/an1.61.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ-kheo, do pháp ấy, các pháp thiện chưa sanh được sanh khởi, và các pháp bất thiện đã sanh được đoạn tận, này các Tỷ-kheo, như ít dục. Với người có ít dục, này các Tỷ-kheo, các pháp thiện chưa sanh được sanh khởi, và các pháp bất thiện đã sanh được đoạn tận.`, ref: "AN 1.63", url: "../an/an1.63.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ-kheo, do pháp ấy, các pháp bất thiện chưa sanh được sanh khởi, và các pháp thiện đã sanh bị đoạn tận, này các Tỷ-kheo, như là không biết vừa đủ. Với người không biết vừa đủ, này các Tỷ-kheo, các pháp bất thiện chưa sanh được sanh khởi, và các pháp thiện đã sanh bị đoạn tận.`, ref: "AN 1.64", url: "../an/an1.64.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ-kheo, do pháp ấy, các pháp thiện chưa sanh được sanh khởi, và các pháp bất thiện đã sanh được đoạn tận, này các Tỷ-kheo, như biết vừa đủ. Với người biết vừa đủ, này các Tỷ-kheo, các pháp thiện chưa sanh được sanh khởi, và các pháp bất thiện đã sanh được đoạn tận.`, ref: "AN 1.65", url: "../an/an1.65.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ-kheo, do pháp ấy, các pháp thiện chưa sanh được sanh khởi, và các pháp bất thiện đã sanh được đoạn tận, này các Tỷ-kheo, như như lý tác ý. Với người như lý tác ý, này các Tỷ-kheo, các pháp thiện chưa sanh được sanh khởi, và các pháp bất thiện đã sanh được đoạn tận.`, ref: "AN 1.67", url: "../an/an1.67.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ-kheo, do pháp ấy, các pháp thiện chưa sanh được sanh khởi, và các pháp bất thiện đã sanh được đoạn tận, này các Tỷ-kheo, như tỉnh giác. Với người tỉnh giác, này các Tỷ-kheo, các pháp thiện chưa sanh được sanh khởi, và các pháp bất thiện đã sanh được đoạn tận.`, ref: "AN 1.69", url: "../an/an1.69.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ-kheo, do pháp ấy, các pháp bất thiện chưa sanh được sanh khởi, và các pháp thiện đã sanh bị đoạn tận, này các Tỷ-kheo, như làm bạn với ác. Với người làm bạn với ác, này các Tỷ-kheo, các pháp bất thiện chưa sanh được sanh khởi, và các pháp thiện đã sanh bị đoạn tận.`, ref: "AN 1.70", url: "../an/an1.70.html#content" },

{ text: `Ta không thấy một pháp nào khác, này các Tỷ-kheo, do pháp ấy, các pháp thiện chưa sanh được sanh khởi, và các pháp bất thiện đã sanh được đoạn tận, này các Tỷ-kheo, như làm bạn với thiện. Với người làm bạn với thiện, này các Tỷ-kheo, các pháp thiện chưa sanh được sanh khởi, và các pháp bất thiện đã sanh được đoạn tận.`, ref: "AN 1.71", url: "../an/an1.71.html#content" },

{ text: `Ít có giá trị, này các Tỷ-kheo, là những mất mát này, như mất mát tài sản. Cái này là khốn cùng giữa các mất mát, này các Tỷ-kheo, tức là mất mát trí tuệ.`, ref: "AN 1.78", url: "../an/an1.78.html#content" },

{ text: `Ít có giá trị, này các Tỷ-kheo, là những mất mát này, như mất mát danh tiếng. Cái này là khốn cùng giữa các mất mát, này các Tỷ-kheo, tức là mất mát trí tuệ.`, ref: "AN 1.80", url: "../an/an1.80.html#content" },

{ text: `Ít có giá trị, này các Tỷ-kheo, là những tăng trưởng này, như tăng trưởng danh tiếng. Cái này là tối thượng giữa các tăng trưởng, này các Tỷ-kheo, tức là tăng trưởng trí tuệ. Do vậy, này các Tỷ-kheo, các Thầy cần phải học tập như sau: “Chúng ta sẽ làm tăng trưởng sự tăng trưởng trí tuệ”. Như vậy, này các Tỷ-kheo, các Thầy cần phải học tập.`, ref: "AN 1.81", url: "../an/an1.81.html#content" },

{ text: `Những Tỷ-kheo nào, này các Tỷ-kheo, nêu rõ pháp là pháp, nêu rõ phi pháp là phi pháp, các Tỷ-kheo ấy, này các Tỷ-kheo, sở hành như vậy, đem lại hạnh phúc cho đa số, an lạc cho đa số, lợi ích cho đa số, đem lại hạnh phúc an lạc cho chư Thiên và loài Người. Và hơn nữa, này các Tỷ-kheo, các Tỷ-kheo ấy tạo phước đức và an trú diệu pháp này.`, ref: "AN 1.140", url: "../an/an1.140.html#content" },

{ text: `Một người, này các Tỷ-kheo, khi xuất hiện ở đời, sự xuất hiện đem lại hạnh phúc cho đa số, an lạc cho đa số, vì lòng thương tưởng cho đời, vì lợi ích, vì hạnh phúc, vì an lạc cho chư Thiên và loài Người. Một người ấy là ai? Chính là Thế Tôn, bậc A-la-hán, Chánh Ðẳng Giác. Chính một người này, này các Tỷ-kheo, khi xuất hiện ở đời, sự xuất hiện đem lại hạnh phúc cho đa số, an lạc cho đa số, vì lòng thương tưởng cho đời, vì lợi ích, vì hạnh phúc, vì an lạc cho chư Thiên và loài Người.”`, ref: "AN 1.170", url: "../an/an1.170.html#content" },

{ text: `Sự xuất hiện của một người, này các Tỷ-kheo, khó gặp được ở đời. Của người nào? Của Như Lai, bậc A-la-hán, Chánh Ðẳng Giác. Sự xuất hiện của một người này, này các Tỷ-kheo, khó gặp được ở đời.`, ref: "AN 1.171", url: "../an/an1.171-174.html#content" },

{ text: `Sự kiện này không xảy ra, này các Tỷ-kheo, không có được: Một người thành tựu chánh kiến có thể chấp nhận các hành là thường còn. Sự kiện này không xảy ra. Và sự kiện này có xảy ra, này các Tỷ-kheo, kẻ phàm phu có thể chấp nhận các hành là thường còn. Sự kiện này có xảy ra.`, ref: "AN 1.268", url: "../an/an1.268.html#content" },

{ text: `Sự kiện này không xảy ra, này các Tỷ-kheo, không có được: là quả dị thục của thân làm ác có thể là khả lạc, khả hỷ, khả ý. Sự kiện này không xảy ra. Sự kiện này có xảy ra, này các Tỷ-kheo, là quả dị thục của thân làm ác là không khả lạc, không khả hỷ, không khả ý. Sự kiện này có xảy ra.`, ref: "AN 1.284", url: "../an/an1.284-286.html#content" },

{ text: `Ðối với người có chánh kiến, này các Tỷ-kheo, phàm mọi thân hành hoàn toàn được thực hiện, được chấp nhận theo chánh kiến, phàm mọi khẩu hành… phàm mọi ý hành hoàn toàn được thực hiện, được chấp nhận theo chánh kiến, phàm có tư tâm sở nào, phàm có quyết định nào, phàm có ước nguyện nào, và phàm có các hành nào, tất cả pháp ấy đưa đến khả lạc, khả hỷ, khả ý, đưa đến hạnh phúc, an lạc.`, ref: "AN 1.315", url: "../an/an1.315.html#content" },
{ text: `Ở đây, này các Tỷ-kheo, có người suy xét như sau: “Quả dị thục của thân làm ác trong đời sau là ác và khổ, Quả dị thục của miệng nói ác trong đời sau là ác và khổ, Quả dị thục của ý nghĩ ác trong đời sau là ác và khổ. Nếu thân ta làm ác, nói lời ác, nghĩ việc ác. Sao ta lại không có thể, sau khi thân hoại mạng chung, phải sanh vào cõi dữ, ác thú, đọa xứ, địa ngục”. Người ấy sợ hãi tội có kết quả trong đời sau, từ bỏ thân làm ác, tu tập thân làm thiện, từ bỏ miệng nói ác, tu tập miệng nói thiện, từ bỏ ý nghĩ ác, tu tập ý nghĩ thiện, và cư xử tự ngã hoàn toàn thanh tịnh.`, ref: "AN 2.1", url: "../an/an2.1.html#content" },

{ text: `Này các Tỷ-kheo, cần phải học tập như sau: “Chúng ta phải sợ hãi đối với tội có kết quả hiện tại. Chúng ta phải sợ hãi đối với tội có kết quả trong đời sau. Chúng ta phải tránh xa các tội. Chúng ta phải thấy rõ sự nguy hiểm của các tội”. Như vậy, này các Tỷ-kheo, các ngươi cần phải học tập. Ðối với ai tránh xa các tội, này các Tỷ-kheo, đối với ai thấy rõ sự nguy hiểm của các tội, thời được chờ đợi rằng người ấy sẽ được giải thoát tất cả tội.`, ref: "AN 2.1", url: "../an/an2.1.html#content" },

{ text: `Này các Tỷ-kheo, nếu các Thầy không có thối chuyển, cố gắng như sau: “Ta sẵn sàng, dầu chỉ còn da, gân và xương, dầu thịt và máu trên thân bị khô héo, mong rằng sẽ có tinh tấn kiên trì để chứng đắc những gì chưa chứng đắc, nhờ sức mạnh của người, nhờ tinh tấn của người, nhờ cần dõng của người”. Thời không bao lâu, này các Tỷ-kheo, các Thầy sẽ đạt được mục đích mà các Thiện nam tử chơn chánh xuất gia, từ bỏ gia đình, sống không gia đình: Ðó chính là vô thượng cứu cánh Phạm hạnh, ngay trong hiện tại, các Thầy với thắng trí, tự mình chứng ngộ, chứng đạt và an trú.`, ref: "AN 2.5", url: "../an/an2.5.html#content" },

{ text: `Này các Tỷ-kheo, ai sống thấy vị ngọt trong các pháp có thể khởi lên kiết sử, này các Tỷ-kheo, tham không đoạn tận, sân không đoạn tận, si không đoạn tận. Do tham không đoạn tận, sân không đoạn tận, si không đoạn tận, nên không giải thoát khỏi sanh, già, chết, sầu, bi, khổ, ưu, não. Ta nói rằng người ấy không giải thoát khỏi khổ đau.`, ref: "AN 2.6", url: "../an/an2.6.html#content" },

{ text: `Này các Tỷ-kheo, ai sống thấy nhàm chán trong các pháp có thể khởi lên kiết sử, này các Tỷ-kheo, tham được đoạn tận, sân được đoạn tận, si được đoạn tận. Do tham được đoạn tận, sân được đoạn tận, si được đoạn tận, nên được giải thoát khỏi sanh, già, chết, sầu, bi, khổ, ưu, não. Ta nói rằng người ấy giải thoát khỏi khổ đau.`, ref: "AN 2.6", url: "../an/an2.6.html#content" },

{ text: `Hai pháp trắng này, này các Tỷ-kheo, che chở cho thế giới. Thế nào là hai? Tàm và quý. (Xấu hổ và sợ hãi tội lỗi) Nếu hai pháp trắng này, không che chở cho thế giới, thời không thể chỉ được đây là mẹ hay là em, chị của mẹ, hay đây là vợ của anh hay em của mẹ, hay đây là vợ của Thầy hay đây là vợ của các vị tôn trưởng. Và thế giới sẽ đi đến hỗn loạn như giữa các loài dê, loài gà vịt, loài heo, loài chó, loài dã can.`, ref: "AN 2.9", url: "../an/an2.9.html#content" },

{ text: `Này các Tỷ-kheo, thế nào là sức mạnh tư sát? Ở đây, này các Tỷ-kheo, có người tư sát như sau: “Với thân làm ác, quả dị thục là ác ngay hiện tại và trong đời sau. Với miệng nói ác, quả dị thục là ác ngay trong hiện tại và trong đời sau. Với ý nghĩ ác, quả dị thục là ác ngay trong hiện tại và trong đời sau”. Vị ấy, tư sát như vậy, từ bỏ thân làm ác, tu tập thân làm thiện, từ bỏ miệng nói ác, tu tập miệng nói thiện, từ bỏ ý nghĩ ác, tu tập ý nghĩ thiện, tư sát sự thật thanh tịnh. Này các Tỷ-kheo, đây gọi là sức mạnh tư sát.`, ref: "AN 2.11", url: "../an/an2.11.html#content" },

{ text: `Và thế nào, này các Tỷ-kheo, là sức mạnh tu tập? Ở đây, này các Tỷ-kheo, sức mạnh tu tập tức là sức mạnh của người hữu học.\nNhư vậy, này các tỳ kheo, do sức mạnh tu học, vị ấy từ bỏ tham, từ bỏ sân, từ bỏ si. Sau khi từ bỏ tham, từ bỏ sân, từ bỏ si, vị ấy không làm các điều bất thiện, không phục vụ các điều ác. Này các Tỷ-kheo, đây gọi là sức mạnh tu tập.`, ref: "AN 2.11", url: "../an/an2.11.html#content" },

{ text: `Trong bất cứ tranh tụng nào, này các Tỷ-kheo, Tỷ-kheo phạm tội và Tỷ-kheo buộc tội, không tự mình khéo quán sát lấy mình, thời tranh tụng ấy được chờ đợi là sẽ đưa đến kéo dài, gay gắt, ác liệt, và các Tỷ-kheo sẽ sống không được an lạc. Và trong bất cứ cuộc tranh tụng nào, này các Tỷ-kheo, Tỷ-kheo phạm tội và Tỷ-kheo buộc tội, có tự mình khéo quán sát lấy mình, thời tranh tụng ấy, này các Tỷ-kheo, được chờ đợi là không đưa đến kéo dài, gay gắt, ác liệt, và các Tỷ-kheo sẽ sống được an lạc.`, ref: "AN 2.15", url: "../an/an2.15.html#content" },

{ text: `Này Ananda, Ta đã tuyên bố một cách dứt khoát rằng, thân làm ác, miệng nói ác, ý nghĩ ác là điều không nên làm. Nếu làm những điều không nên làm ấy, thời có những nguy hại như sau được chờ đợi: Tự mình chê trách mình; sau khi được biết, kẻ trí chê trách, tiếng ác đồn xa, bị mê ám khi mạng chung; sau khi thân hoại mạng chung, bị sanh vào cõi dữ, ác thú, đọa xứ, địa ngục. Vì thế, này Ananda, Ta đã tuyên bố một cách dứt khoát rằng, thân làm ác, miệng nói ác, ý nghĩ ác là điều không nên làm. Nếu làm những điều không nên làm ấy, thời có những nguy hại như vậy được chờ đợi.`, ref: "AN 2.18", url: "../an/an2.18.html#content" },

{ text: `Này Ananda, Ta dã tuyên bố một cách dứt khoát rằng, thân làm thiện, miệng nói thiện, ý nghĩ thiện là điều nên làm. Nếu làm những điều nên làm ấy, thời có những lợi ích như sau được chờ đợi: Tự mình không chê trách mình; sau khi được biết, kẻ trí tán thán, tiếng lành đồn xa, không bị mê ám khi mạng chung; sau khi thân hoại mạng chung, được sanh vào cõi Thiện, cõi Trời, cõi đời này. Vì thế, này Ananda, Ta đã tuyên bố một cách dứt khoát rằng, thân làm thiện, miệng nói thiện, ý nghĩ thiện là điều nên làm. Nếu làm những điều nên làm ấy, thời có những lợi ích như vậy được chờ đợi.`, ref: "AN 2.18", url: "../an/an2.18.html#content" },

{ text: `Này các Tỷ-kheo, hãy từ bỏ bất thiện, này các Tỷ-kheo, từ bỏ bất thiện có thể làm được. Nếu từ bỏ bất thiện không thể làm được thời ta đã không nói như sau: “Này các Tỷ-kheo, hãy từ bỏ bất thiện”. Vì rằng, này các Tỷ-kheo, từ bỏ bất thiện có thể làm được, do vậy Ta mới nói rằng: “Này các Tỷ-kheo, hãy từ bỏ bất thiện”. Và nếu, này các Tỷ-kheo, từ bỏ bất thiện đưa đến bất hạnh, đau khổ, thời ta không nói như sau: “Này các Tỷ-kheo, hãy từ bỏ bất thiện”. Và này các Tỷ-kheo, vì từ bỏ bất thiện đưa đến hạnh phúc, an lạc, nên Ta đã nói như sau: “Này các Tỷ-kheo, hãy từ bỏ bất thiện”.`, ref: "AN 2.19", url: "../an/an2.19.html#content" },

{ text: `Hai pháp này, này các Tỷ-kheo, đưa đến sự hỗn loạn (mê mờ) và biến mất của diệu pháp. Thế nào là hai? Văn cú bị đảo ngược và ý nghĩa bị hiểu lầm. Nếu văn cú bị đảo ngược thời ý nghĩa bị hiểu lầm. Những pháp này, này các Tỷ-kheo, là hai pháp đưa đến hỗn loạn và biến mất của diệu pháp.`, ref: "AN 2.20", url: "../an/an2.20.html#content" },

{ text: `Này các Tỷ-kheo, thế nào là địa vị bậc không phải Chân nhân? Người không phải Chân nhân, này các Tỷ-kheo, không biết ơn, không nhớ ơn. Ðối với những người độc ác, đây là đặc tánh của họ được biết đến, này các Tỷ-kheo, tức là không biết ơn, không nhớ ơn. Ðây hoàn toàn là địa vị kẻ không Chân nhân, này các Tỷ-kheo, tức là không biết ơn, không nhớ ơn. Còn bậc Chân nhân, này các Tỷ-kheo, là biết ơn, là nhớ ơn. Ðối với những thiện nhân, đây là đặc tánh của họ được biết đến, này các Tỷ-kheo, tức là biết ơn, nhớ ơn. Ðây hoàn toàn là địa vị bậc Chân nhân, này các Tỷ-kheo, tức là biết ơn, nhớ ơn.`, ref: "AN 2.32", url: "../an/an2.32.html#content" },

{ text: `Có hai hạng người, này các Tỷ-kheo, ta nói không thể trả ơn được. Thế nào là hai? Mẹ và Cha. Nếu một bên vai cõng mẹ, này các Tỷ-kheo, nếu một bên vai cõng cha, làm vậy suốt trăm năm, cho đến trăm tuổi; nếu đấm bóp, thoa xức, tắm rửa, xoa gội, và dầu tại đấy, mẹ cha có vãi tiểu tiện đại tiện, như vậy, này các Tỷ-kheo, cũng chưa làm đủ hay trả ơn đủ mẹ và cha. Hơn nữa, này các Tỷ-kheo, nếu có an trí cha mẹ vào quốc độ với tối thượng uy lực, trên quả đất lớn với bảy báu này, như vậy, này các Tỷ-kheo, cũng chưa làm đủ hay trả ơn đủ mẹ và cha. Vì cớ sao? Vì rằng, này các Tỷ-kheo, cha mẹ đã làm nhiều cho con cái, nuôi nấng, nuôi dưỡng chúng lớn, giới thiệu chúng vào đời này.`, ref: "AN 2.33", url: "../an/an2.33.html#content" },

{ text: `Này các Tỷ-kheo, ai đối với cha mẹ không có lòng tin, khuyến khích, hướng dẫn an trú các vị ấy vào lòng tin; đối với mẹ cha theo ác giới, khuyến khích, hướng dẫn, an trú các vị ấy vào thiện giới; đối với mẹ cha xan tham, khuyến khích, hướng dẫn, an trú các vị ấy vào bố thí; đối với mẹ cha theo ác trí tuệ, khuyến khích, hướng dẫn, an trú các vị ấy vào trí tuệ. Cho đến như vậy, này các Tỷ-kheo, là làm đủ và trả ơn đủ mẹ và cha.`, ref: "AN 2.33", url: "../an/an2.33.html#content" },

{ text: `—Có bao nhiêu người, bạch Thế Tôn, đáng được cúng dường ở đời? Và chỗ nào cần phải bố thí cúng dường.\n—Có hai hạng người, này gia chủ, đáng được cúng dường ở đời: Hữu học và vô học. Ðối với hai hạng người này đáng được cúng dường ở đời, này gia chủ, ở đây cần phải bố thí cúng dường.\nThế Tôn thuyết như vậy, Thiện Thệ nói như vậy xong, bậc Ðạo sư lại nói thêm:\n\nHữu học và vô học\nCả hai ở trong đời\nÐều đáng được cúng dường\nÐối với người dâng lễ\nHọ giữ thân chánh trực\nCả lời nói ý nghĩ\nPhước điền người dâng cúng\nÐây thí có quả lớn.`, ref: "AN 2.35", url: "../an/an2.35.html#content" },

{ text: `Này Sàriputta, cần phải học tập như sau: “Chúng tôi sẽ có các căn an tịnh, các ý an tịnh”. Này Sàriputta, cần phải học tập như vậy. Với những ai có các căn an tịnh, này Sàriputta, với những ai có các ý an tịnh, thời thân nghiệp cũng sẽ được an tịnh, khẩu nghiệp được an tịnh, ý nghiệp được an tịnh. “Chúng ta sẽ đem tặng cho các vị đồng Phạm hạnh một quà tặng an tịnh”. Như vậy, này Sàriputta, các Thầy cần phải học tập.`, ref: "AN 2.36", url: "../an/an2.36.html#content" },

{ text: `—Do nhân gì, thưa Tôn giả Kaccàna, do duyên gì các người Sát-đế-lỵ tranh chấp với các người Sát-đế-lỵ, các người Bà-la-môn tranh chấp với các người Bà-la-môn, các người gia chủ tranh chấp với các người gia chủ?\n—Do nhân thiên chấp, bị trói buộc, bị đắm say, bị xâm chiếm, bị đắm trước bởi các dục tham, này Bà-la-môn, nên các quý tộc tranh chấp với các quý tộc, các người Bà-la-môn tranh chấp với các người Bà La môn, các người gia chủ tranh chấp với các người gia chủ.`, ref: "AN 2.37", url: "../an/an2.37.html#content" },

{ text: `—Do nhân gì, thưa Tôn giả Kaccàna, do duyên gì các Sa-môn tranh chấp với các Sa-môn?\n—Do nhân thiên chấp, bị trói buộc, bị đắm say, bị xâm chiếm, bị đắm trước bởi các kiến chấp, này Bà-la-môn, nên các Sa-môn tranh chấp với các Sa-môn.`, ref: "AN 2.37", url: "../an/an2.37.html#content" },

{ text: `Vị trưởng lão, này Bà-la-môn, 80 tuổi hay 90 tuổi, hay 100 tuổi đời, nếu vị ấy thọ hưởng các dục vọng, sống giữa các dục vọng, bị đốt cháy bởi lửa nhiệt não của dục vọng, bị nhai nghiến bởi các tầm tư dục vọng, cố gắng tìm cầu các dục vọng; người như vậy được gọi là kẻ ngu, không phải là bậc trưởng lão. Dầu cho này Bà-la-môn, một người còn trẻ, một thanh niên trẻ trung với tóc đen nhánh, đầy đủ tuổi trẻ hiền thiện trong thời sơ khởi của tuổi đời, mà người ấy không hưởng thọ các dục vọng, không sống giữa các dục vọng, không bị đốt cháy bởi lửa nhiệt não của dục vọng, không bị nhai nghiến bởi các tầm tư dục vọng, không có cố gắng tìm cầu các dục vọng; người như vậy được gọi là bậc có trí, bậc trưởng lão.`, ref: "AN 2.38", url: "../an/an2.38.html#content" },

{ text: `Này các Tỷ-kheo, khi các ác Tỷ-kheo cường mạnh, trong khi ấy, các thuần tịnh Tỷ-kheo yếu đuối. Trong khi ấy, này các Tỷ-kheo, các Tỷ-kheo thuần tịnh giữ thái độ im lặng, hoặc ẩn mình giữa chúng Tỷ-kheo, hoặc đi đến các quốc độ biên địa. Và như vậy, này các Tỷ-kheo, là bất hạnh cho đa số, là không an lạc cho đa số, là không lợi ích cho đa số, là bất hạnh, đau khổ cho chư Thiên và loài Người.`, ref: "AN 2.39", url: "../an/an2.39.html#content" },

{ text: `Những Tỷ-kheo nào, này các Tỷ-kheo, chặn đứng cả văn và nghĩa, bằng cách nắm giữ sai lạc các kinh điển và những văn tự thích ứng, thì những Tỷ-kheo ấy, này các Tỷ-kheo, chịu trách nhiệm về bất hạnh cho đa số, không an lạc cho đa số, không lợi ích cho đa số, bất hạnh, đau khổ cho chư Thiên và loài Người. Ngoài ra, các Tỷ-kheo ấy, này các Tỷ-kheo, chất chứa nhiều vô phước làm cho diệu pháp biến mất.`, ref: "AN 2.41", url: "../an/an2.41.html#content" },

{ text: `Những Tỷ-kheo nào, này các Tỷ-kheo, tùy thuận cả văn và nghĩa, bằng cách nắm giữ đúng đắn các kinh điển và những văn tự thích ứng, thì những Tỷ-kheo ấy, này các Tỷ-kheo, chịu trách nhiệm về hạnh phúc cho đa số, an lạc cho đa số, lợi ích cho đa số, hạnh phúc, và an lạc cho chư Thiên và loài Người. Ngoài ra, các Tỷ-kheo ấy, này các Tỷ-kheo, chất chứa nhiều phước đức, làm cho diệu pháp an trú.`, ref: "AN 2.41", url: "../an/an2.41.html#content" },

{ text: `Có hai loại hội chúng này, này các Tỷ-kheo. Thế nào là hai? Hội chúng nông nổi và hội chúng thâm sâu. Này các Tỷ-kheo, thế nào là hội chúng nông nổi? Ở đây, này các Tỷ-kheo, tại hội chúng nào có các Tỷ-kheo tháo động, kiêu căng, lắm mồm lắm miệng, lắm lời, thất niệm, không tỉnh giác, không định tĩnh, tâm tán loạn, các căn thả lỏng. Này các Tỷ-kheo, đây gọi là hội chúng nông nổi. Này các Tỷ-kheo, thế nào là hội chúng thâm sâu? Ở đây, này các Tỷ-kheo, tại hội chúng nào có các Tỷ-kheo, không tháo động, không kiêu căng, không dao động, không lắm mồm lắm miệng, không lắm lời, không thất niệm, tỉnh giác, có định tĩnh, có nhất tâm, có các căn được bảo vệ. Này các Tỷ-kheo, đây gọi là hội chúng thâm sâu.`, ref: "AN 2.42", url: "../an/an2.42.html#content" },

{ text: `Có hai loại hội chúng này, này các Tỷ-kheo. Thế nào là hai? Hội chúng bất hòa và hội chúng hòa hợp. Và này các Tỷ-kheo, thế nào là hội chúng bất hòa? Ở đây, này các Tỷ-kheo, tại hội chúng nào, các Tỷ-kheo sống cạnh tranh, luận tranh, đấu tranh, đả thương nhau bằng binh khí miệng lưỡi, này các Tỷ-kheo, đây gọi là hội chúng bất hòa. Và này các Tỷ-kheo, thế nào là hội chúng hòa hợp? Ở đây, này các Tỷ-kheo, tại hội chúng nào, các Tỷ-kheo hòa hợp, hòa kính, không có đấu tranh, hòa hợp như sữa với nước, sống nhìn nhau với cặp mắt từ ái, này các Tỷ-kheo, đây gọi là hội chúng hòa hợp.`, ref: "AN 2.43", url: "../an/an2.43.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, tại hội chúng nào, các trưởng lão Tỷ-kheo sống trong sự đầy đủ, lười biếng, dẫn đầu về đọa lạc, bỏ rơi gánh nặng sống viễn ly, không có gia sức tinh tấn để đạt đến những gì chưa đạt, để chứng được những gì chưa chứng, để ngộ được những gì chưa ngộ. Còn lớp hậu nhân, tùy thuận hậu kiến của họ, sống trong sự đầy đủ, biếng nhác, dẫn đầu về đọa lạc, bỏ rơi gánh nặng sống viễn ly, không có gia sức tinh tấn để đạt được những gì chưa đạt, để chứng được những gì chưa chứng, để ngộ được những gì chưa ngộ. Này các Tỷ-kheo, đây gọi là hội chúng không thù thắng.`, ref: "AN 2.44", url: "../an/an2.44.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, tại hội chúng nào, các trưởng lão Tỷ-kheo không sống trong sự đầy đủ, không lười biếng, từ bỏ gánh nặng đọa lạc, dẫn đầu trong đời sống viễn ly, có gia sức tinh tấn để đạt đến những gì chưa đạt, để chứng được những gì chưa chứng, để ngộ được những gì chưa ngộ. Còn lớp hậu nhân, tùy thuận hậu kiến của họ, không sống trong sự đầy đủ, không biếng nhác, từ bỏ gánh nặng đọa lạc, dẫn đầu trong đời sống viễn ly, có gia sức tinh tấn để đạt được những gì chưa đạt, để chứng được những gì chưa chứng, để ngộ được những gì chưa ngộ. Này các Tỷ-kheo, đây gọi là hội chúng thù thắng.`, ref: "AN 2.44", url: "../an/an2.44.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, tại hội chúng nào, các Tỷ-kheo đối với các kinh điển do Như Lai tuyên thuyết, thâm sâu, ý nghĩa sâu kín, siêu thế, liên hệ đến không, khi các kinh điển ấy được thuyết giảng, họ không khéo nghe, không lóng tai, không an trú tâm để hiểu biết chúng, không nghĩ rằng các pháp ấy cần phải lãnh thọ, cần phải học thuộc lòng. Nhưng đối với các kinh điển thi văn do thi sĩ làm ra, với các nguyên âm hoa mỹ, với các phụ âm hoa mỹ, các kinh thuộc ngoại giáo, được các đệ tử ngoại giáo nói lên, khi các kinh điển ấy được thuyết giảng, họ khéo nghe, họ lóng tai, họ an trú tâm để hiểu biết chúng, họ nghĩ rằng các pháp ấy cần phải lãnh thọ, cần phải học thuộc lòng. Này các Tỷ-kheo, đây gọi là hội chúng được huấn luyện trong khoa trương, không được huấn luyện trong chất vấn.`, ref: "AN 2.45", url: "../an/an2.45.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, tại hội chúng nào, các Tỷ-kheo đối với các kinh điển do Như Lai tuyên thuyết, thâm sâu, ý nghĩa sâu kín, siêu thế, liên hệ đến không, khi các kinh điển ấy được thuyết giảng, họ khéo nghe, lóng tai, họ an trú tâm để hiểu biết chúng, họ nghĩ rằng các pháp ấy cần phải lãnh thọ, cần phải học thuộc lòng. Và sau khi học thuộc lòng các pháp ấy, họ hỏi đi hỏi lại cùng nhau, họ mở rộng ra để thảo luận với những câu hỏi như sau : “Cái này là gì? Thế nào là ý nghĩa của cái này?” Họ mở rộng những gì được che kín, họ phơi bày những gì không được phơi bày, họ giải nghi về các điểm nghi vấn trong Chánh pháp. Này các Tỷ-kheo, đây gọi là hội chúng được huấn luyện trong chất vấn, không được huấn luyện trong khoa trương.`, ref: "AN 2.45", url: "../an/an2.45.html#content" },
{ text: `Có hai loại lạc này, này các Tỷ-kheo. Thế nào là hai? Lạc tại gia và lạc xuất gia. Những pháp này, này các Tỷ-kheo, là hai lạc. Tối thắng trong hai lạc này, này các Tỷ-kheo, tức là lạc xuất gia.`, ref: "AN 2.64", url: "../an/an2.64.html#content" },

{ text: `Có hai loại lạc này, này các Tỷ-kheo. Thế nào là hai? Dục lạc và viễn ly lạc. Những pháp này, này các Tỷ-kheo, là hai lạc. Tối thắng trong hai lạc này, này các Tỷ-kheo, tức là viễn ly lạc.`, ref: "AN 2.65", url: "../an/an2.65.html#content" },
{ text: `Này các Tỷ-kheo, thế nào là hạng người có hy vọng? Ở đây, này các Tỷ-kheo, một Tỷ-kheo giữ tánh tình hiền thiện. Vị ấy nghe: “Tỷ-kheo có tên như vậy, đã đoạn tận các lậu hoặc ngay trong hiện tại, tự mình với thắng trí, chứng ngộ, chứng đạt và an trú vô lậu tâm giải thoát, tuệ giải thoát”. Người ấy suy nghĩ như sau: “Ðến khi nào, do đoạn tận các lậu hoặc ngay trong hiện tại, tự mình với thắng trí, ta sẽ chứng đạt, chứng ngộ và an trú vô lậu tâm giải thoát, tuệ giải thoát?” Người như vậy, này các Tỷ-kheo, được gọi là người có hy vọng.`, ref: "AN 3.13", url: "../an/an3.13.html#content" },

{ text: `Có ba pháp này, này các Tỷ-kheo, đưa đến hại mình, đưa đến hại người, đưa đến hại cả hai. Thế nào là ba? Thân làm ác, miệng nói ác, ý nghĩ ác. Ba pháp này, này các Tỷ-kheo, đưa đến hại mình, đưa đến hại người, đưa đến hại cả hai.`, ref: "AN 3.17", url: "../an/an3.17.html#content" },

{ text: `Có ba pháp này, này các Tỷ-kheo, không đưa đến hại mình, không đưa đến hại người, không đưa đến hại cả hai. Thế nào là ba? Thân làm thiện, miệng nói thiện, ý nghĩ thiện. Có ba pháp này, này các Tỷ-kheo, không đưa đến hại mình, không đưa đến hại người, không đưa đến hại cả hai.`, ref: "AN 3.17", url: "../an/an3.17.html#content" },

{ text: `Này các Tỷ-kheo, thành tựu ba pháp, Tỷ kheo thâu nhận được thiện pháp chưa được thâu nhận, tăng trưởng thiện pháp đã được thâu nhận. Thế nào là ba? Ở đây, này các Tỷ-kheo, Tỷ kheo vào buổi sáng có nhiệt tâm chăm chú vào định tướng, vào buổi trưa có nhiệt tâm chăm chú vào định tướng, vào buổi chiều có nhiệt tâm chăm chú vào định tướng. Thành tựu với ba pháp này, này các Tỷ-kheo, một Tỷ-kheo thâu nhận được thiện pháp chưa được thâu nhận, và tăng trưởng thiện pháp đã được thâu nhận.`, ref: "AN 3.19", url: "../an/an3.19.html#content" },

{ text: `Và như thế nào, này các Tỷ-kheo, là Tỷ-kheo khéo phấn đấu? Ở đây, này các Tỷ-kheo, Tỷ-kheo sống tinh cần tinh tấn, đoạn tận các pháp bất thiện, làm cho sanh khởi các pháp thiện, dõng mãnh, kiên trì, tinh tấn, không có từ bỏ gánh nặng đối với các thiện pháp. Như vậy, này các Tỷ-kheo, là Tỷ-kheo khéo phấn đấu.`, ref: "AN 3.20", url: "../an/an3.20.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là Tỷ-kheo xây dựng được căn bản? Ở đây, này các Tỷ-kheo, Tỷ-kheo đối với các Tỷ-kheo nghe nhiều, thông hiểu các tập Agàma (A-hàm), bậc trì Pháp, trì Luật, trì Toát yếu, thường thường đến yết kiến, phỏng vấn, đặt các câu hỏi: “Thưa Tôn giả, cái này là thế nào? Pháp này ý nghĩa gì? “Các Tôn giả ấy mở rộng những gì chưa được mở rộng, phơi bày những gì chưa được phơi bày, và đối với những đoạn sai khác còn có những chỗ nghi ngờ, các vị ấy giải thích các sự nghi ngờ. Như vậy, này các Tỷ-kheo, là Tỷ-kheo xây dựng được căn bản.`, ref: "AN 3.20", url: "../an/an3.20.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, có hạng người chất chứa các thân hành có não hại, chất chứa các khẩu hành có não hại, chất chứa các ý hành có não hại. Sau khi chất chứa thân hành có não hại, chất chứa khẩu hành có não hại, chất chứa ý hành có não hại, người ấy sanh trong thế giới có não hại. Vì phải sanh trong thế giới có não hại, người ấy cảm giác các cảm xúc có não hại. Người ấy, vì cảm giác các cảm xúc có não hại, nên cảm giác các cảm thọ có não hại, nhất hướng đau khổ, như các chúng sanh ở trong địa ngục.`, ref: "AN 3.24", url: "../an/an3.24.html#content" },

{ text: `Này các Tỷ-kheo, thế nào là hạng người với tâm ví dụ như vết thương? Ở đây, này các Tỷ-kheo, có người phẫn nộ, nhiều hiềm hận, dầu có bị nói chút ít, cũng tức tối phẫn nộ, sân hận, sừng sộ, biểu lộ sự phẫn nộ, sân hận và bực tức. Ví như một vết thương đang làm mủ, nếu bị cây gậy hay một miếng sành đánh phải, liền chảy mủ nhiều hơn. Cũng vậy, này các Tỷ-kheo, ở đây có người phẫn nộ và bực tức. Này các Tỷ kheo, đây gọi là hạng người được ví dụ với vết thương đang làm mủ.`, ref: "AN 3.25", url: "../an/an3.25.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, có hạng người thấp kém về giới, định, tuệ. Hạng người như vậy, này các Tỷ-kheo, không nên gần gũi, không nên sống chung, không nên hầu hạ cúng dường, trừ khi vì lòng thương tưởng, vì lòng từ mẫn.`, ref: "AN 3.26", url: "../an/an3.26.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, có hạng người đồng đẳng với mình về giới, định, tuệ. Hạng người như vậy, này các Tỷ-kheo, nên gần gũi, nên sống chung, nên hầu hạ cúng dường. Vì cớ sao? Với ý nghĩ: “(Cả hai) thiện xảo về giới, câu chuyện của chúng ta sẽ thuộc về giới, được diễn tiến (lợi ích) cho cả hai chúng ta, và sẽ làm cho hai chúng ta được an lạc. (Cả hai) là thiện xảo về định ...... (Cả hai) là thiện xảo về tuệ, câu chuyện của chúng ta sẽ thuộc về tuệ, được diễn tiến (lợi ích) cho cả hai, và chúng sẽ làm cho hai chúng ta an lạc”. Cho nên, người như vậy nên gần gũi, nên sống chung, nên hầu hạ cúng dường.`, ref: "AN 3.26", url: "../an/an3.26.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, có hạng người thù thắng về giới, định và tuệ. Hạng người ấy, này các Tỷ-kheo, sau khi cung kính, tôn trọng, cần phải gần gũi, cần phải sống chung, cần phải hầu hạ cúng dường. Vì cớ sao? Với ý nghĩ: “Như vậy, nếu giới chưa đầy đủ, ta sẽ làm đầy đủ, hay nếu giới được đầy đủ, ta sẽ hỗ trợ thêm cho chỗ này chỗ kia với trí tuệ. Hay nếu định chưa đầy đủ, ta sẽ làm cho đầy đủ, hay nếu định được đầy đủ, ta sẽ hỗ trợ thêm cho chỗ này chỗ kia với trí tuệ. Hay nếu tuệ chưa đầy đủ, ta sẽ làm đầy đủ, hay nếu tuệ được đầy đủ, ta sẽ hỗ trợ thêm cho chỗ này chỗ kia với trí tuệ”. Cho nên, với hạng người này, sau khi cung kính tôn trọng, nên gần gũi, nên sống chung, nên hầu hạ cúng dường.`, ref: "AN 3.26", url: "../an/an3.26.html#content" },

{ text: `Người gần kẻ hạ liệt,\nRồi cũng bị hạ liệt;\nThân cận người đồng đẳng,\nÐược khỏi bị thối đọa;\nAi gần bậc thù thắng,\nMau chóng được thăng tiến;\nDo vậy hãy sống chung,\nBậc ưu thắng hơn mình.`, ref: "AN 3.26", url: "../an/an3.26.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, có hạng người giữ giới, tánh tình hiền thiện. Người như vậy, này các Tỷ-kheo, cần phải gần gũi, cần phải sống chung, cần phải hầu hạ cúng dường. Vì cớ sao? Vì rằng, dầu không thuận theo chút nào tri kiến của người như vậy, nhưng tiếng tốt được đồn xa về người ấy là có bạn lành, là có bằng hữu lành, là tôn sùng kẻ lành. Cho nên, hạng người như vậy, cần phải gần gũi, cần phải sống chung, cần phải hầu hạ cúng dường.`, ref: "AN 3.27", url: "../an/an3.27.html#content" },


{ text: `Và này các Tỷ-kheo, thế nào là hạng người nói như phân? Ở đây, này các Tỷ-kheo, có hạng người khi đi vào hội trường, hay đi vào hội chúng, hay khi đi đến giữa các người bà con, hay khi đi đến giữa các người đồng một tổ hợp, hay đi đến giữa cung vua, hay bị dẫn như là người làm chứng, được nói: “Ngươi biết gì, hãy nói lên”. Người ấy không biết, nói rằng: “Tôi có biết”; có biết, nói rằng: “Tôi không biết”; không thấy, nói rằng: “Tôi có thấy”; có thấy, nói rằng: “Tôi không thấy”. Do vì mình hay vì người, hay vì một vài lợi vật nhỏ, mà đã cố ý nói láo. Người như vậy, này các Tỷ-kheo, được gọi là người nói như phân.`, ref: "AN 3.27", url: "../an/an3.27.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là hạng người nói như hoa? Ở đây, này các Tỷ-kheo, có người khi đi vào hội trường, hay khi đi vào hội chúng, hay khi đi đến giữa các người bà con, hay khi đi đến giữa các người đồng một tổ hợp, hay đi đến cung vua, hay bị dẫn như là người làm chứng, được nói: “Ngươi biết gì, hãy nói lên”. Người ấy không biết, nói rằng: “Tôi không biết”; có biết, nói rằng: “Tôi có biết”; không thấy, nói rằng: “Tôi không thấy”; có thấy, nói rằng: “Tôi có thấy”. Không vì mình hay vì người, hay vì một vài lợi vật nhỏ mà đã cố ý nói láo. Người như vậy, này các Tỷ-kheo, được gọi là người nói như hoa.`, ref: "AN 3.27", url: "../an/an3.27.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là hạng người nói như mật? Ở đây, này các Tỷ-kheo, có người đoạn tận ác ngữ, từ bỏ lời nói ác ngữ. Lời nói của người ấy không hại, tai ưa nghe, khả ái, đi thẳng đến tâm, lễ độ, được nhiều người ưa thích, được nhiều người thích ý, người ấy nói những lời như vậy. Này các Tỷ-kheo, đây gọi là hạng người nói như mật.`, ref: "AN 3.27", url: "../an/an3.27.html#content" },



{ text: `Và này các Tỷ-kheo, thế nào là người với trí tuệ lộn ngược? Ở đây, này các Tỷ-kheo, có hạng người đi đến khu vườn (tinh xá) thường thường nghe pháp từ các Tỷ-kheo, các vị Tỷ-kheo thuyết pháp cho người ấy, sơ thiện, trung thiện, hậu thiện, có nghĩa, có văn, trình bày Phạm hạnh hoàn toàn viên mãn thanh tịnh. Người ấy, tại chỗ ngồi ấy, đối với bài thuyết giảng ấy, không có tác ý đến đoạn đầu, không có tác ý đến đoạn giữa, không có tác ý đến đoạn cuối. Cũng vậy, khi người ấy từ chỗ ngồi ấy đứng lên, đối với bài thuyết giảng ấy, người ấy không có tác ý đến đoạn đầu, không có tác ý đến đoạn giữa, không có tác ý đến đoạn cuối. Ví như này các Tỷ-kheo, một cái ghè bị lộn ngược, nước chứa trong ấy tuôn chảy, không có dừng lại. Cũng vậy, này các Tỷ-kheo, ở đây, có hạng người đi đến khu vườn ... không có tác ý đoạn cuối. Cũng vậy, khi người ấy từ chỗ ngồi ấy đứng lên ... không có tác ý đoạn cuối. Này các Tỷ-kheo, đây gọi là hạng người với trí tuệ lộn ngược.`, ref: "AN 3.30", url: "../an/an3.30.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là hạng người có trí tuệ rộng lớn? Ở đây, này các Tỷ-kheo, có hạng người đi đến khu vườn (tinh xá) thường thường nghe pháp từ các Tỷ-kheo, các vị Tỷ-kheo thuyết pháp cho người ấy, sơ thiện, trung thiện, hậu thiện, có nghĩa, có văn, trình bày Phạm hạnh hoàn toàn viên mãn thanh tịnh. Người ấy, tại chỗ ngồi ấy, đối với bài thuyết giảng ấy, có tác ý đến đoạn đầu, có tác ý đến đoạn giữa, có tác ý đến đoạn cuối. Cũng vậy, khi người ấy từ chỗ ngồi ấy đứng lên, đối với bài thuyết giảng ấy, người ấy có tác ý đến đoạn đầu, có tác ý đến đoạn giữa, có tác ý đến đoạn cuối. Ví như này các Tỷ-kheo, một cái ghè bị lộn ngược, nước chứa trong ấy tuôn chảy, có dừng lại. Cũng vậy, này các Tỷ-kheo, ở đây, có hạng người đi đến khu vườn ... có tác ý đoạn cuối.  Cũng vậy, khi vị ấy, từ chỗ ngồi ấy đứng lên, đối với bài thuyết giảng ấy, có tác ý đến đoạn đầu ... có tác ý đến đoạn cuối. Này các Tỷ-kheo, đây gọi là hạng người có trí tuệ rộng lớn.`, ref: "AN 3.30", url: "../an/an3.30.html#content" },

{ text: `Bậc trí tuệ rộng lớn\nÐược gọi tốt hơn cả\nHọ thường thường đi đến\nÐến gần các Tỷ-kheo\nÐoạn đầu của bài giảng\nÐoạn giữa và đoạn cuối\nNgồi trên chỗ mình ngồi\nNắm giữ được lời văn\nThọ trì điều được nghe\nSuy tư điều tối thắng\nVới ý không dao động\nLà hạng người như vậy\nThực hành pháp, tùy pháp\nCó thể đoạn khổ đau.`, ref: "AN 3.30", url: "../an/an3.30.html#content" },

{ text: `Những gia đình nào, này các Tỷ-kheo, trong ấy, các con cái kính lễ mẹ cha ở trong nhà, những gia đình ấy được chấp nhận ngang bằng với Phạm Thiên. Những gia đình nào, này các Tỷ-kheo, trong ấy, các con cái kính lễ mẹ cha ở trong nhà, những gia đình ấy được chấp nhận như các Ðạo sư thời xưa. Những gia đình nào, này các Tỷ-kheo, trong ấy, các con cái kính lễ mẹ cha ở trong nhà, những gia đình ấy được chấp nhận là đáng được cúng dường.`, ref: "AN 3.31", url: "../an/an3.31.html#content" },

{ text: `Phạm Thiên, này các Tỷ-kheo, là đồng nghĩa với cha mẹ. Các Ðạo sư thời xưa, này các Tỷ-kheo, là đồng nghĩa với cha mẹ. Ðáng được cúng dường, này các Tỷ-kheo, là đồng nghĩa với cha mẹ. Vì cớ sao? Giúp đỡ rất nhiều, này các Tỷ-kheo, là cha mẹ đối với con cái, nuôi chúng lớn, dưỡng dục chúng, giới thiệu chúng vào đời.`, ref: "AN 3.31", url: "../an/an3.31.html#content" },

{ text: `Ở đây, này Ananda, vị Tỷ-kheo suy nghĩ như sau: “Ðây là an tịnh, đây là thù diệu, tức là chỉ tức tất cả hành, từ bỏ tất cả sanh y, đoạn tận tham, ly tham, đoạn diệt, Niết-bàn”. Như vậy, này Ananda, rất có thể Tỷ-kheo được định như vậy, trong cái thân có thức này, không có ngã kiến, ngã sở kiến, ngã mạn tuỳ miên; đối với tất cả tướng ở ngoài, không có ngã kiến, ngã sở kiến, ngã mạn tuỳ miên; và do chứng đạt và an trú tâm giải thoát, tuệ giải thoát, không có ngã kiến, ngã sở kiến, ngã mạn tuỳ miên; vị ấy có thể chứng đạt và an trú tâm giải thoát, tuệ giải thoát.`, ref: "AN 3.32", url: "../an/an3.32.html#content" },
{ text: `Ngồi xuống một bên, Hatthaka người Alavì bạch Thế Tôn: - Bạch Thế Tôn, Thế Tôn sống có an lạc không?\n- Phải, này Hoàng Tử, ta sống được an lạc. Và những ai cảm thấy an lạc ở đời, Ta là một trong số những người ấy.\n- Bạch Thế Tôn, lạnh là đêm mùa đông, thời gian giữa những ngày tám là thời gian tuyết rơi, cứng rắn là đất do trâu bò dẫm đạp, mỏng manh là nệm làm bằng lá, lưa thưa là những lá của cây, lạnh là tấm vải cà sa, và lạnh là làn gió thổi.\nRồi Thế Tôn nói như sau: - Dẫu vậy, này Hoàng Tử, Ta sống được an lạc. Và những ai cảm thấy an lạc ở đời, Ta là một trong số những người ấy.`, ref: "AN 3.35", url: "../an/an3.35.html#content" },

{ text: `—Hoàng Tử nghĩ thế nào, này Hoàng tử, với người gia chủ hay người con của người gia chủ ấy, khởi lên những nhiệt não về thân hay về tâm, do tham ái sanh. Bị nung đốt bởi những nhiệt não do tham ái sanh, người ấy có cảm thấy đau khổ không?\n—Thưa có, bạch Thế Tôn.\n—Người gia chủ hay con của người gia chủ ấy, này Hoàng Tử, bị nung đốt bởi những nhiệt não do tham ái sanh, cảm thấy đau khổ. Tham ái ấy, Như Lai đã đoạn tận, cắt đứt từ gốc rễ, làm cho như thân cây tala, làm cho không thể hiện hữu, làm cho không thể sanh khởi trong tương lai. Do vậy ta cảm thấy an lạc.`, ref: "AN 3.35", url: "../an/an3.35.html#content" },

{ text: `Luôn luôn được an lạc,\nVi phạm chí tịch tịnh\nKhông bị dục uế nhiễm\nTrong mát, không sanh y,\nMọi tham trước dứt đoạn,\nNhiếp phục tâm sầu khổ,\nAn tịnh, cảm thọ lạc\nVới tâm đạt an tịnh.`, ref: "AN 3.35", url: "../an/an3.35.html#content" },
{ text: `Với Ta, này các Tỷ-kheo, được đầy đủ với sự giàu sang như vậy, được cứu cánh nuôi dưỡng tế nhị như vậy, ta suy nghĩ rằng: “Kẻ vô văn phàm phu tự mình bị già, không vượt qua khỏi già, khi thấy người khác bị già, lại bực phiền, hổ thẹn, ghê tởm, quên rằng mình cũng như vậy. Ta cũng bị già, không vượt qua khỏi già, sau khi thấy người khác già, ta có thể bực phiền, hổ thẹn, ghê tởm sao? Như vậy, thật không xứng đáng cho ta”. Sau khi quan sát về ta như vậy, này các Tỷ-kheo, sự kiêu mạn của tuổi trẻ trong tuổi trẻ được đoạn trừ hoàn toàn.`, ref: "AN 3.39", url: "../an/an3.39.html#content" },

{ text: `Với Ta, này các Tỷ-kheo, được đầy đủ với sự giàu sang như vậy, được cứu cánh nuôi dưỡng tế nhị như vậy, ta suy nghĩ rằng: “Kẻ vô văn phàm phu tự mình bị bệnh, không vượt khỏi bệnh, thấy người khác bị bệnh, lại bực phiền, hổ thẹn, ghê tởm, quên rằng mình cũng như vậy. Ta cũng bị bệnh, không vượt qua khỏi bệnh, sau khi thấy người khác bị bệnh, ta có thể bực phiền, hổ thẹn, ghê tởm sao? Như vậy, thật không xứng đáng cho ta”. Sau khi quan sát về ta như vậy, này các Tỷ-kheo, sự kiêu mạn của không bệnh trong không bệnh được đoạn trừ hoàn toàn.`, ref: "AN 3.39", url: "../an/an3.39.html#content" },

{ text: `Với Ta, này các Tỷ-kheo, được đầy đủ với sự giàu sang như vậy, được cứu cánh nuôi dưỡng tế nhị như vậy, ta suy nghĩ rằng: “Kẻ vô văn phàm phu tự mình bị chết, không vượt khỏi chết, thấy người khác bị chết, lại bực phiền, hổ thẹn, ghê tởm, quên rằng mình cũng như vậy. Ta cũng bị chết, không vượt qua khỏi chết, sau khi thấy người khác chết, ta có thể bực phiền, hổ thẹn, ghê tởm sao? Như vậy, thật không xứng đáng cho ta”. Sau khi quan sát về ta như vậy, này các Tỷ-kheo, sự kiêu mạn của sự sống trong sự sống được đoạn trừ hoàn toàn.`, ref: "AN 3.39", url: "../an/an3.39.html#content" },
{ text: `Có ba kiêu mạn này, này các Tỷ-kheo, Thế nào là ba? Kiêu mạn của tuổi trẻ, Kiêu mạn của không bệnh, Kiêu mạn của sự sống.`, ref: "AN 3.39", url: "../an/an3.39.html#content" },

{ text: `Say sưa trong Kiêu mạn của tuổi trẻ, này các Tỷ-kheo, kẻ vô văn phàm phu làm các ác hành về thân, làm các ác hành về lời nói, làm các ác hành về ý. Do làm các ác hành về thân, làm các ác hành về lời nói, làm các ác hành về ý, sau khi thân hoại mạng chung, bị sanh vào cõi dữ, ác thú, đọa xứ, địa ngục.`, ref: "AN 3.39", url: "../an/an3.39.html#content" },

{ text: `Say sưa trong Kiêu mạn của sự sống, này các Tỷ-kheo, kẻ vô văn phàm phu làm các ác hành về thân, làm các ác hành về lời nói, làm các ác hành về ý. Do làm các ác hành về thân, làm các ác hành về lời nói, làm các ác hành về ý, sau khi thân hoại mạng chung, bị sanh vào cõi dữ, ác thú, đọa xứ, địa ngục.`, ref: "AN 3.39", url: "../an/an3.39.html#content" },

{ text: `Say sưa trong Kiêu mạn của tuổi trẻ, này các Tỷ-kheo, vị Tỷ-kheo từ bỏ học pháp, trở lui lại đời sống thế tục. Say sưa trong kiêu mạn của không bệnh, này các Tỷ-kheo, vị Tỷ-kheo từ bỏ học pháp, trở lui lại đời sống thế tục. Say sưa trong kiêu mạn của đời sống, này các Tỷ-kheo, vị Tỷ-kheo từ bỏ học pháp, trở lui lại đời sống thế tục.`, ref: "AN 3.39", url: "../an/an3.39.html#content" },
{ text: `Ở đây, này các Tỷ-kheo, vị Tỷ-kheo đi đến ngôi rừng, hay đi đến gốc cây, hay đi đến ngôi nhà trống, quan sát như sau: “Không phải vì y áo, ta xuất gia từ bỏ gia đình, sống không gia đình. Không phải vì món ăn khất thực, không phải vì sàng tọa, không phải vì nhân có mặt hay không có mặt ở đây mà ta xuất gia từ bỏ gia đình, sống không gia đình, (nhưng với ý nghĩ như sau): “Nay ta bị rơi vào sanh, già, chết, sầu, bi, khổ, ưu, não, rơi vào khổ, bị khổ chi phối. Có thể do làm như vậy, sự đoạn tận tất cả khổ uẩn này được hiện khởi lên (cho ta). Và ta đã xuất gia từ bỏ gia đình, sống không gia đình, sau khi đã đoạn tận tất cả các dục vọng như vậy, lại còn đeo đuổi các dục vọng như kia hay còn ác tệ hơn. Như vậy, thật không xứng đáng cho ta”.`, ref: "AN 3.40", url: "../an/an3.40.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, vị Tỷ-kheo quan sát như sau: “Thắng tấn là tinh tấn của ta, không có thụ động; an trú là niệm của ta, không có thất niệm; khinh an là thân của ta, không có dao động; định tĩnh là tâm của ta, được nhất tâm”. Vị ấy làm cho tăng thượng tự ngã, từ bỏ bất thiện, tu tập thiện, từ bỏ có tội, tu tập không tội, gìn giữ cho tự ngã được thanh tịnh. Này các Tỷ-kheo, đây gọi là tự ngã tăng thượng.`, ref: "AN 3.40", url: "../an/an3.40.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, vị Tỷ-kheo đi đến ngôi rừng hay đi đến gốc cây, hay đi đến ngôi nhà trống, rồi thẩm sát như sau: “Không phải vì y áo, ta xuất gia từ bỏ gia đình, sống không gia đình. Không phải vì món ăn khất thực, không phải vì sàng tọa, không phải vì nhân có mặt hay không có mặt ở đây mà ta xuất gia từ bỏ gia đình, sống không gia đình, (nhưng với ý nghĩ như sau): “Nay ta bị rơi vào sanh, già, chết, sầu, bi, khổ, ưu, não, rơi vào khổ, bị khổ chi phối. Có thể làm như vậy, đoạn tận của tất cả khổ uẩn này được hiện khởi lên cho ta. Và ta đã xuất gia như vậy, lại có thể suy nghĩ về dục tầm hay có thể suy nghĩ về sân tầm, hay có thể suy nghĩ về hại tầm. Như vậy, thật không xứng đáng cho ta”.`, ref: "AN 3.40", url: "../an/an3.40.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, vị Tỷ-kheo quan sát như sau: “Có các chư Thiên có thần thông, có thiên nhãn, có tha tâm thông. Các vị này có thể thấy từ xa, tuy ở gần nhưng không thấy họ được, và họ có thể biết tâm ta với tâm của họ. Các vị ấy có thể biết về ta như sau: “Hãy xem thiện nam tử này, tuy vì lòng tin xuất gia, từ bỏ gia đình, sống không gia đình, nhưng sống xen lẫn với các pháp ác, bất thiện.”`, ref: "AN 3.40", url: "../an/an3.40.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, vị Tỷ-kheo quan sát như sau: “Pháp được Thế Tôn khéo thuyết, thiết thực hiện tại, có kết quả ngay tức thời, đến để mà thấy, có khả năng hướng thượng, được người có trí tự mình giác hiểu. Nay ta có những người đồng Phạm hạnh, họ sống biết và thấy. Ta đã được xuất gia trong pháp và Luật khéo giảng như vậy, không lẽ ta lại có thể sống biếng nhác phóng dật. Như vậy, thật không xứng đáng cho ta”.`, ref: "AN 3.40", url: "../an/an3.40.html#content" },
{ text: `Do sự có mặt của ba pháp, này các Tỷ-kheo, một thiện nam tử có lòng tin tạo ra nhiều phước. Thế nào là ba? Do sự có mặt của lòng tin, này các Tỷ-kheo, một thiện nam tử có lòng tin tạo ra nhiều phước. Do sự có mặt của vật bố thí, này các Tỷ-kheo, một thiện nam tử có lòng tin tạo ra nhiều phước. Do sự có mặt của các vị xứng đáng được cúng dường, này các Tỷ-kheo, một thiện nam tử có lòng tin tạo ra nhiều phước.`, ref: "AN 3.41", url: "../an/an3.41.html#content" },
 { text: `Do ba sự kiện, này các Tỷ-kheo, một người được biết là có lòng tin. Thế nào là ba? Ưa thấy người có giới hạnh, ưa nghe diệu pháp, với tâm ly cấu uế của xan tham, sống trong nhà, bố thí rộng rãi với bàn tay sạch sẽ, ưa thích từ bỏ, sẵn sàng để được yêu cầu, thích phân phát vật bố thí. Do ba sự kiện này, này các Tỷ-kheo, một người được biết là có lòng tin.`, ref: "AN 3.42", url: "../an/an3.42.html#content" },

{ text: `Ba pháp này, này các Tỷ-kheo, được người Hiền trí tuyên bố, được bậc Chân nhân tuyên bố. Thế nào là ba? Bố thí, này các Tỷ-kheo, được người Hiền trí tuyên bố, được bậc Chân nhân tuyên bố. Xuất gia, này các Tỷ-kheo, được người Hiền trí tuyên bố, được bậc Chân nhân tuyên bố. Hầu hạ cha mẹ, này các Tỷ-kheo, được người Hiền trí tuyên bố, được bậc Chân nhân tuyên bố. Ba pháp này, này các Tỷ-kheo, được người Hiền trí tuyên bố, được bậc Chân nhân tuyên bố.`, ref: "AN 3.45", url: "../an/an3.45.html#content" },

{ text: `Gần làng hay thị trấn nào, này các Tỷ-kheo, các bậc xuất gia có giới hạnh trú ở, tại chỗ ấy, các người nhờ ba sự kiện được gặt nhiều công đức. Thế nào là ba? Bởi thân, bởi lời nói, bởi ý.`, ref: "AN 3.46", url: "../an/an3.46.html#content" },

{ text: `Khi nào Tỷ-kheo, này các Tỷ-kheo, đối với các pháp ác, bất thiện chưa sanh, nhiệt tình làm mạnh đừng để cho sanh, đối với các pháp thiện chưa sanh, nhiệt tình làm mạnh để cho sanh khởi. Ðể chịu đựng các thân thọ đã sanh, khổ đau, nhói đau, da diết đau, gay gắt đau, không thích thú, không thích ý, đoạt mạng sống, nhiệt tình làm mạnh. Tỷ-kheo ấy, này các Tỷ-kheo, được gọi là vị có nhiệt tình, thận trọng, chánh niệm để chơn chánh đoạn tận khổ đau.`, ref: "AN 3.49", url: "../an/an3.49.html#content" },

{ text: `Thật vậy, này các Bà-la-môn, thế giới này đã bị già, bệnh, chết dắt dẫn. Thế giới đã bị già, bệnh, chết dắt dẫn như vậy, này các Bà-la-môn, thời chế ngự thân, chế ngự lời nói, chế ngự ý trong đời này, đối với kẻ đã đi đến cõi chết, phải là chỗ nương tựa, là hang trú ẩn, là hòn cù lao (hay ngọn đèn), là chỗ quy y và là đích xứ đi đến.`, ref: "AN 3.51", url: "../an/an3.51.html#content" },

{ text: `Ðời sống bị dắt dẫn\nMạng sống chẳng là bao\nBị già kéo dẫn đi\nKhông có nơi nương tựa\nHãy luôn luôn quán tưởng\nSợ hãi tử vong này\nHãy làm các công đức\nÐưa đến chơn an lạc.\nỞ đây chế ngự thân,\nChế ngự lời và ý,\nKẻ ấy dầu có chết,\nCũng được hưởng an lạc,\nVì khi còn đang sống\nÐã làm các công đức.`, ref: "AN 3.51", url: "../an/an3.51.html#content" },


{ text: `Bị tham ái làm say đắm, này Bà-la-môn, bị chinh phục, tâm bị xâm chiếm, nên suy nghĩ điều hại mình, suy nghĩ điều hại người, suy nghĩ điều hại cả hai, cảm thọ tâm khổ tâm ưu. Tham ái được đoạn trừ, thời không nghĩ đến tự hại, không nghĩ đến hại người, không nghĩ đến hại cả hai, không cảm thọ tâm khổ tâm ưu. Như vậy, này Bà-la-môn, pháp là thiết thực hiện tại, không có thời gian, đến để mà thấy, có khả năng hướng thượng, được người trí tự mình giác hiểu.`, ref: "AN 3.53", url: "../an/an3.53.html#content" },

{ text: `Bị sân làm uế nhiễm, này Bà-la-môn, bị chinh phục, tâm bị xâm chiếm, nên suy nghĩ điều hại mình, suy nghĩ điều hại người, suy nghĩ điều hại cả hai, cảm thọ tâm khổ tâm ưu. Sân được đoạn trừ, thời không nghĩ đến tự hại, không nghĩ đến hại người, không nghĩ đến hại cả hai, không cảm thọ tâm khổ tâm ưu. Như vậy, này Bà-la-môn, pháp là thiết thực hiện tại, không có thời gian, đến để mà thấy, có khả năng hướng thượng, được người trí tự mình giác hiểu.`, ref: "AN 3.53", url: "../an/an3.53.html#content" },

{ text: `Thật vi diệu thay, Tôn giả Gotama! Thật vi diệu thay, Tôn giả Gotama! Như người dựng đứng những gì bị quăng ngã xuống, hay trình bày cái gì bị che kín, hay chỉ đường cho người bị lạc hướng, hay cầm đèn sáng vào bóng tối để những ai có mắt có thể thấy sắc. Cũng vậy, Chánh pháp đã được Tôn giả Gotama dùng nhiều phương tiện thuyết giảng. Con nay xin quy y Tôn giả Gotama, quy y Pháp, quy y Tăng. Mong Tôn giả Gotama nhận con làm đệ tử cư sĩ, từ nay cho đến mạng chung, con trọn đời quy ngưỡng.`, ref: "AN 3.53", url: "../an/an3.53.html#content" },

{ text: `Ngày nay, này Bà-la-môn, loài người bị tham ái phi pháp làm cho say đắm, và bị ác tham chinh phục, bị tà kiến chi phối. Vì bị tham ái phi pháp làm cho say đắm, vì bị ác tham chinh phục, vì bị tà kiến chi phối, chúng cầm gươm sắc bén sát hại lẫn nhau. Do vậy, nhiều người mạng chung. Ðây là nhân, này Bà-la-môn, đây là duyên, ngày nay loài người bị tiêu diệt, bị giảm thiểu trông rõ như thế, các làng trở thành không phải làng, các thị trấn trở thành không phải thị trấn, các thành phố trở thành không phải thành phố, các quốc độ trở thành không quốc độ.`, ref: "AN 3.56", url: "../an/an3.56.html#content" },

{ text: `Giới hạnh không dao động\nKhôn khéo và thiền tịnh,\nVới tâm được chinh phục,\nNhứt tâm, khéo định tĩnh,\nBậc trí đoạn mê ám,\nBa minh, diệt tử thần,\nVị ấy được tôn xưng,\nÐại hạnh cho Trời Người,\nBậc “Ðoạn tận tất cả”,\nÐầy đủ cả ba minh.`, ref: "AN 3.58", url: "../an/an3.58.html#content" },

{ text: `Ai đầy đủ giới hạnh\nTinh cần và định tĩnh\nVới tầm được chinh phục\nNhứt tâm khéo định tĩnh\nAi biết được đời trước\nThấy Thiên giới đọa xứ\nVị ấy là đạo sĩ\nÐoạn sanh, đạt thắng trí\nVị Bà-la-môn nào,\nChứng được ba minh này,\nTa gọi là ba minh\nKhông như thường được gọi.`, ref: "AN 3.59", url: "../an/an3.59.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là Khổ Thánh đế?\nSanh là khổ, già là khổ, bệnh là khổ, chết là khổ, sầu bi, khổ, ưu, não là khổ. Ðiều mong cầu không được là khổ. Tóm lại, năm thủ uẩn là khổ. Này các Tỷ-kheo, đây là Khổ Thánh đế.`, ref: "AN 3.61", url: "../an/an3.61.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là Thánh đế về Khổ tập?\nVô minh duyên hành, hành duyên thức, thức duyên sắc, danh sắc duyên sáu xứ, sáu xứ duyên xúc, xúc duyên thọ, thọ duyên ái, ái duyên thủ, thủ duyên hữu, hữu duyên sanh, sanh duyên già, chết, sầu, bi, khổ, ưu não. Như vầy là sự tập khởi của toàn bộ khổ uẩn này. Này các Tỷ-kheo, đây gọi là Thánh đế về Khổ tập.`, ref: "AN 3.61", url: "../an/an3.61.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là Thánh đế về Khổ diệt?\nDo vô minh diệt không có tàn dư, nên các hành diệt. Do hành diệt, nên thức diệt. Do thức diệt nên danh sắc diệt. Do danh sắc diệt nên sáu xứ diệt. Do sáu xứ diệt nên xúc diệt. Do xúc diệt nên thọ diệt. Do thọ diệt nên ái diệt. Do ái diệt nên thủ diệt. Do thủ diệt nên hữu diệt. Do hữu diệt nên sanh diệt. Do sanh diệt nên già, chết, sầu, bi, khổ, ưu não đều diệt. Như vậy là sự đoạn diệt toàn bộ của khổ uẩn này. Này các Tỷ-kheo, Ðây gọi là Thánh đế về Khổ diệt.`, ref: "AN 3.61", url: "../an/an3.61.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là Thánh đế về con đường đưa đến Khổ diệt?\nÐây là Thánh đạo Tám ngành, tức là chánh tri kiến, chánh tư duy, chánh ngữ, chánh nghiệp, chánh mạng, chánh tinh tấn, chánh niệm, chánh định. Này các Tỷ-kheo, đây gọi là Thánh đế về con đường đưa đến Khổ diệt.`, ref: "AN 3.61", url: "../an/an3.61.html#content" },

{ text: `Ở đây, này Bà-la-môn, Ta sống gần một làng hay một thị trấn. Buổi sáng, Ta đắp y, cầm y bát, đi vào làng ấy hay vào thị trấn ấy để khất thực. Sau khi ăn xong, trên con đường đi khất thực trở về, Ta đi đến góc cuối của ngôi rừng. Ở tại đấy, Ta lượm cỏ hay lá chất thành một đống, rồi ta ngồi kiết già, lưng thẳng, để niệm trước mặt, ly dục, ly pháp bất thiện, Ta chứng đạt và an trú sơ Thiền, một trạng thái hỷ lạc do ly dục sanh, có tầm có tứ.`, ref: "AN 3.63", url: "../an/an3.63.html#content" },

{ text: `Này các Kàlàmà, chớ có tin vì nghe báo cáo, chớ có tin vì nghe truyền thuyết; chớ có tin vì theo truyền thống; chớ có tin vì được kinh điển truyền tụng; chớ có tin vì lý luận suy diễn; chớ có tin vì diễn giải tương tự; chớ có tin vì đánh giá hời hợt những dữ kiện; chớ có tin vì phù hợp với định kiến; chớ có tin vì phát xuất từ nơi có uy quyền, chớ có tin vì vị Sa-môn là bậc đạo sư của mình.\nNhưng này các Kàlàmà, khi nào tự mình biết rõ như sau: “Các pháp này là bất thiện; Các pháp này là đáng chê; Các pháp này bị các người có trí chỉ trích; Các pháp này nếu thực hiện và chấp nhận đưa đến bất hạnh khổ đau”, thời này Kàlàmà, hãy từ bỏ chúng!`, ref: "AN 3.65", url: "../an/an3.65.html#content" },

{ text: `Vị ấy rõ biết như sau: “Trước ta có tham, tham ấy là bất thiện. Nay ta không có nữa. Như vầy là thiện. Trước ta có sân, sân ấy là bất thiện. Nay ta không có nữa. Như vầy là thiện. Trước ta có si, si ấy là bất thiện. Nay ta không có nữa. Như vậy là thiện”. Như vậy, ngay trong đời sống hiện tại, vị ấy được giải thoát khỏi hy cầu, được tịch tịnh, được thanh lương, cảm thấy an lạc, tự mình an trú trong Phạm thể.`, ref: "AN 3.66", url: "../an/an3.66.html#content" },

{ text: `Cái gì là tham, này các Tỷ-kheo, cái ấy bất thiện. Ai với lòng tham có làm gì về thân, về lời, về ý, cái ấy bất thiện. Với ai có lòng tham, bị lòng tham chinh phục, tâm không được tự chủ, vu cáo làm người khác đau khổ, bằng cách sát hại, trói buộc, tịch thu tài sản, mắng nhiếc hay tẩn xuất, dựa trên: “Ta là sức mạnh, ta có sức mạnh.” Cái ấy là bất thiện. Như vậy, rất nhiều ác bất thiện pháp này sanh từ tham, duyên khởi từ tham, tập khởi từ tham, khởi lên nơi người ấy.`, ref: "AN 3.69", url: "../an/an3.69.html#content" },

{ text: `—Cái gì là sân, này các Tỷ-kheo, cái ấy bất thiện. Ai với lòng sân có làm gì về thân, về lời, về ý, cái ấy bất thiện. Với ai có lòng sân, bị lòng sân chinh phục, tâm không được tự chủ, vu cáo làm người khác đau khổ, bằng cách sát hại, trói buộc, tịch thu tài sản, mắng nhiếc hay tẩn xuất, dựa trên: “Ta là sức mạnh, ta có sức mạnh.” Cái ấy là bất thiện. Như vậy, rất nhiều ác bất thiện pháp này sanh từ sân, duyên khởi từ sân, tập khởi từ sân, khởi lên nơi người ấy.`, ref: "AN 3.69", url: "../an/an3.69.html#content" },

{ text: `Như vậy, này Ananda, nghiệp là thửa ruộng, thức là hột giống, ái là sự nhuận ướt. Chúng sanh bị vô minh che lấp, bị ái trói buộc, nên thức được an lập trong giới thấp kém. Như vậy, trong tương lai có sự tái sanh sanh khởi. Như vậy, này Ananda, hữu có mặt.`, ref: "AN 3.76", url: "../an/an3.76.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, hãy học tập như sau: “Sắc bén sẽ là ước muốn chúng ta để thọ trì tăng thượng giới học. Sắc bén sẽ là ước muốn chúng ta để thọ trì tăng thượng định học. Sắc bén sẽ là ước muốn chúng ta để thọ trì tăng thượng tuệ học”. Như vậy, này các Tỷ-kheo, các Thầy cần phải học tập.`, ref: "AN 3.81", url: "../an/an3.81.html#content" },

{ text: `Người tinh tấn, nghị lực\nKiên trì và Thiền tu\nSống hộ trì các căn\nHãy hành ba tăng thượng\nTrước thế nào, sau vậy\nSau thế nào, trước vậy\nDưới thế nào, trên vậy\nTrên thế nào, dưới vậy\nNgày thế nào, đêm vậy\nÐêm thế nào, ngày vậy.\nHãy nhiếp phục mọi phương\nVới vô lượng tâm định\nÐây gọi hữu đạo học\nLà thuần tịnh hạnh đức\nÐây gọi là Chánh giác\nBậc trí đạt tối hậu\nVới thức được đoạn diệt\nÁi diệt, được giải thoát\nNhư đèn sáng tịch diệt\nTâm vị ấy giải thoát.`, ref: "AN 3.90", url: "../an/an3.90.html#content" },

{ text: `Ví như, này các Tỷ-kheo, vào mùa thu, khi bầu trời quang đãng, không có mây và mặt trời mọc lên giữa bầu trời, phá sạch hắc ám khắp cả hư không, và chói sáng, bừng sáng, rực sáng; cũng vậy, này các Tỷ-kheo, với vị Thánh đệ tử; pháp nhãn ly trần ly cấu khởi lên; và do tri kiến này khởi lên, này các Tỷ-kheo, ba kiết sử được đoạn tận, thân kiến, nghi, giới cấm thủ. Lại nữa, vị ấy được thoát khỏi hai pháp tham và sân. Vị ấy ly dục, ly pháp bất thiện, chứng đạt và an trú sơ Thiền, một trạng thái hỷ lạc do ly dục sanh, có tầm có tứ. Trong thời gian ấy, này các Tỷ-kheo, vị Thánh đệ tử nếu có mạng chung, sẽ không có kiết sử nào, do kiết sử ấy, vị Thánh đệ tử phải đi đến thế giới này nữa.`, ref: "AN 3.94", url: "../an/an3.94.html#content" },

{ text: `Lúc nào, này các Tỷ-kheo, các Tỷ-kheo sống hòa hợp, hoan hỷ, không có luận tranh, như nước và sữa lẫn lộn, nhìn nhau với cặp mắt ái kính, lúc ấy, này các Tỷ-kheo, các Tỷ-kheo tạo được công đức, lúc ấy, này các Tỷ-kheo, các Tỷ-kheo sống phạm trú. Nghĩa là, với ai hân hoan với tâm giải thoát liên hệ với hỷ, thời hỷ sanh; với ai có hỷ, thân được khinh an; với thân khinh an, cảm giác được lạc thọ; với ai cảm giác lạc thọ, tâm được định tĩnh.`, ref: "AN 3.95", url: "../an/an3.95.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là Tỷ-kheo đầy đủ sắc đẹp?\nỞ đây, này các Tỷ-kheo, Tỷ-kheo giữ gìn giới luật, sống hộ trì với sự hộ trì của giới bổn, đầy đủ uy nghi chánh hạnh, thấy sợ hãi trong những lỗi nhỏ nhặt, chấp nhận và học tập trong các học pháp. Như vậy, này các Tỷ-kheo, là Tỷ-kheo đầy đủ sắc đẹp.`, ref: "AN 3.96", url: "../an/an3.96.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là Tỷ-kheo đầy đủ sức mạnh?\nỞ đây, này các Tỷ-kheo, Tỷ-kheo sống tinh cần tinh cấn, đoạn tận các pháp bất thiện, thành tựu đầy đủ các pháp thiện, nỗ lực kiên trì, dõng mãnh, không từ bỏ trách nhiệm đối với các pháp thiện. Như vậy, này các Tỷ-kheo, là Tỷ-kheo đầy đủ sức mạnh.`, ref: "AN 3.96", url: "../an/an3.96.html#content" },

{ text: `Như vậy, này các Tỷ-kheo, nếu Tỷ-kheo trưởng lão này nói lên ở giữa chúng Tăng. Các Tỷ kheo ấy nói như sau: “Chư Tôn giả hãy im lặng, Tỷ-kheo trưởng lão đang nói pháp và luật, và lời nói của vị ấy trở thành châu báu cần phải cất giữ, như một người cất giữ tấm vải kàsi trong một hộp có hương thơm.” Do vậy, này các Tỷ-kheo, hãy học tập như sau: “Chúng ta sẽ được như ví dụ tấm vải kàsi, không giống như ví dụ tấm vải bằng vỏ cây”. Như vậy, này các Tỷ-kheo, các Thầy cần phải học tập.`, ref: "AN 3.99", url: "../an/an3.99.html#content" },

{ text: `Ðịnh như vậy không có an tịnh, không có thù thắng, không được khinh an, không đạt đến nhất tâm, nhưng là một trạng thái chế ngự thường xuyên dằn ép. Nhưng đến một thời, này các Tỷ-kheo, tâm của vị ấy được nội trú, lắng đứng lại, được nhất tâm, được định tĩnh. Ðịnh ấy được an tịnh, được thù diệu, được khinh an, đạt đến nhất tâm, không phải một trạng thái chế ngự thường xuyên dằn ép, tùy thuộc vào pháp gì tâm người ấy hướng đến để thắng tri, để chứng ngộ; vị ấy có khả năng, có năng lực đạt đến pháp ấy, dầu thuộc loại xứ nào.`, ref: "AN 3.101", url: "../an/an3.101.html#content" },

{ text: `Này các Tỷ-kheo, trước khi Ta giác ngộ, chưa chánh đẳng giác, còn là Bồ-tát, ta suy nghĩ như sau: “Cái gì là vị ngọt ở đời? Cái gì là nguy hại, cái gì là xuất ly?”. Rồi này các Tỷ-kheo, về vấn đề ấy, tư tưởng sau đây khởi lên nơi ta: “Do duyên với đời, khởi lên lạc hỷ gì, đây là vị ngọt ở đời. Cái gì ở đời là vô thường, khổ, chịu sự biến hoại, đấy là nguy hại ở đời. Ðiều phục dục tham ở đời, đoạn tận tham dục, đấy là xuất ly ở đời”.`, ref: "AN 3.104", url: "../an/an3.104.html#content" },

{ text: `Này các Tỷ-kheo, ta đã đi tìm cầu vị ngọt ở đời. Vị ngọt ở đời là gì, Ta đã tìm được. Cho đến như thế nào, vị ngọt có mặt ở đời, với trí tuệ ta khéo thấy vị ấy ngọt. Này các Tỷ-kheo, ta đã tìm cầu nguy hại ở đời. Nguy hại ở đời là gì, Ta đã tìm được. Cho đến như thế nào, nguy hại có mặt ở đời, với trí tuệ ta, ta khéo thấy nguy hại ấy, này các Tỷ-kheo ta đã tìm cầu xuất ly ở đời. Xuất ly ở đời là gì, Ta đã tìm được. Cho đến như thế nào, xuất ly có mặt ở đời, với trí tuệ ta, ta khéo thấy xuất ly ấy.`, ref: "AN 3.104", url: "../an/an3.104.html#content" },

{ text: `Này các Tỷ-kheo, cho đến khi nào ta như thật giác tri vị ngọt ở đời là vị ngọt, nguy hại là nguy hại, xuất ly là xuất ly, cho đến khi ấy, này các Tỷ-kheo, ta mới xác nhận Ta đã giác liễu vô thượng Chánh đẳng Chánh giác, cùng với thế giới gồm có Thiên giới, Ma giới, Phạm thiên giới, cùng với quần chúng Sa-môn, Bà-la-môn, chư Thiên và loài Người. Và tri kiến khởi lên nơi ta: “Bất động là tâm giải thoát của ta. Ðây là đời sống cuối cùng. Nay không còn tái sanh nữa”.`, ref: "AN 3.104", url: "../an/an3.104.html#content" },

{ text: `Này các Tỷ-kheo, nếu không có vị ngọt ở đời, thời các loài hữu tình không có tham nhiễm đối với đời. Vì rằng, này các Tỷ-kheo, có vị ngọt ở đời, nên các loài hữu tình có tham nhiễm ở đời. Này các Tỷ-kheo, nếu không có nguy hại ở đời, thời các loài hữu tình không có nhàm chán đối với đời. Vì rằng, này các Tỷ-kheo, có nguy hại ở đời, nên các loài hữu tình có nhàm chán đối với đời. Này các Tỷ-kheo, nếu không có xuất ly ra khỏi đời, thời các loài hữu tình không có xuất ly đối với đời. Vì rằng, này các Tỷ-kheo, có xuất ly đối với đời, nên các loài hữu tình có xuất ly ra khỏi đời.`, ref: "AN 3.105", url: "../an/an3.105.html#content" },

{ text: `Này các Tỷ-kheo, đây được xem là khóc than trong giới luật bậc Thánh, tức là ca vịnh. Này các Tỷ-kheo, đây được xem là điên loạn trong giới luật bậc Thánh, tức là múa nhảy. Này các Tỷ-kheo, đây được xem là trẻ con trong giới luật bậc Thánh, tức là cười quá đáng để lộ cả răng. Do luật này, này các Tỷ-kheo, hãy phá cây cầu đi đến hát. Hãy phá cây cầu đi đến múa nhảy. Thật là vừa đủ nếu các Thầy được hoan hỷ đúng pháp, mỉm cười để tỏ là các Thầy được hoan hỷ.`, ref: "AN 3.107", url: "../an/an3.107.html#content" },

{ text: `Này các Tỷ-kheo, hưởng thọ ba sự ở đời, không bao giờ thỏa mãn. Thế nào là ba? Hưởng thọ ngủ nghỉ, này các Tỷ-kheo, không bao giờ thỏa mãn. Hưởng thọ rượu men rượu nấu, này các Tỷ-kheo, không bao giờ thỏa mãn. Hưởng thọ sự dâm dục giao hợp, này các Tỷ kheo, không bao giờ thỏa mãn.`, ref: "AN 3.108", url: "../an/an3.108.html#content" },

{ text: `Này gia chủ, ví như ngôi nhà nóc nhọn vụng lợp, thời nóc nhọn không được phòng hộ, rui kèo không được phòng hộ, vách tường không được phòng hộ; nóc nhọn bị đầy ứ, rỉ nước, các rui kèo bị đầy ứ rỉ nước, các vách tường bị đầy ứ, rỉ nước, nóc nhọn bị hủ bại, rui kèo bị hủ bại, vách tường bị hủ bại. Cũng vậy, này gia chủ, khi tâm không được phòng hộ, thời thân nghiệp cũng không được phòng hộ, khẩu nghiệp ... ý nghiệp ...  thời thân nghiệp đầy ứ tham dục và rỉ chảy; khẩu nghiệp đầy ứ tham dục và rỉ chảy; ý nghiệp đầy ứ tham dục và rỉ chảy; Với ai thân nghiệp đầy ứ tham dục và rỉ chảy, khẩu nghiệp đầy ứ tham dục và rỉ chảy, ý nghiệp đầy ứ tham dục và rỉ chảy, thời thân nghiệp bị hủ bại, khẩu nghiệp ... ý nghiệp bị hủ bại. Với ai thân nghiệp bị hủ bại, khẩu nghiệp ... ý nghiệp bị hủ bại, thời sự chết không được hiền thiện, mạng chung không được hiền thiện.`, ref: "AN 3.109", url: "../an/an3.109.html#content" },

{ text: `Này các Tỷ-kheo, ba hạng người này rơi vào đọa xứ, rơi vào địa ngục, trừ phi họ đoạn bỏ pháp này. Thế nào là ba? Ai sống không Phạm hạnh, tự xưng là có sống Phạm hạnh; đối với người sống Phạm hạnh thanh tịnh, hành Phạm hạnh thật thanh tịnh, ai công kích là không Phạm hạnh một cách không căn cứ; ai chủ trương như sau: “Không có lỗi lầm trong các dục vọng” và rơi vào say đắm trong các dục vọng; những hạng người này, này các Tỷ-kheo, là ba hạng người rơi vào trong đọa xứ, rơi vào địa ngục, trừ phi họ đoạn bỏ pháp này.`, ref: "AN 3.113", url: "../an/an3.113.html#content" },

{ text: `Sự xuất hiện của ba hạng người này, này các Tỷ-kheo, khó tìm được ở đời. Thế nào là ba? Này các Tỷ-kheo, sự xuất hiện của Như Lai, bậc A-la-hán, Chánh Ðẳng Chánh Giác, khó tìm được ở đời. Người có thể thuyết pháp và luật do Như Lai tuyên thuyết, khó tìm được ở đời. Người tri ân, người biết ơn, khó tìm được ở đời.`, ref: "AN 3.114", url: "../an/an3.114.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, có hạng người không tháo động, không kiêu căng, không dao động, không lắm mồm lắm miệng, không lắm lời, trú niệm, tỉnh giác, định tĩnh, nhất tâm, các căn được bảo vệ. Này các Tỷ-kheo, đây gọi là hạng người khó ước lượng.`, ref: "AN 3.115", url: "../an/an3.115.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, có người tháo động, kiêu căng, dao động, lắm mồm lắm miệng, lắm lời, thất niệm không tỉnh giác, không định tĩnh, tâm tán loạn, các căn thả lỏng. Này các Tỷ-kheo, đây gọi là hạng người dễ ước lượng.`, ref: "AN 3.115", url: "../an/an3.115.html#content" },
{ text: `Tại phương hướng nào, này các Tỷ-kheo, các Tỷ-kheo sống cạnh tranh, luận tranh, đấu tranh, đả thương nhau với binh khí miệng lưỡi, thật không thoải mái cho ta, này các Tỷ-kheo, khi nghĩ đến phương hướng ấy, còn nói gì đến chỗ ấy. Ở đây, Ta đi đến kết luận như sau: “Thật vậy, các Tỷ-kheo ấy đã từ bỏ ba pháp và đã làm quá nhiều ba pháp”.nBa pháp họ đã từ bỏ là gì? Viễn ly tầm, vô sân tầm, bất hại tầm. Ba pháp này họ đã từ bỏ. Ba pháp gì họ đã làm quá nhiều? Dục tầm, sân tầm, hại tầm. Ba pháp này họ đã làm quá nhiều.`, ref: "AN 3.124", url: "../an/an3.124.html#content" },

{ text: `Tại phương hướng nào, này các Tỷ-kheo, các Tỷ-kheo sống hòa hợp, hoan hỷ, không đấu tranh nhau, như sữa và nước lẫn lộn, nhìn nhau với cặp mắt ái kính, này các Tỷ-kheo, đi đến phương hướng ấy thật thoải mái cho ta, còn nói gì nghĩ đến phương hướng ấy. Ở đây, Ta đi đến kết luận như sau: “Thật vậy, các Tỷ-kheo ấy đã từ bỏ ba pháp này và đã làm quá nhiều ba pháp này”.Ba pháp họ đã từ bỏ là gì? Dục tầm, sân tầm, hại tầm. Ba pháp này họ đã từ bỏ.Ba pháp gì họ đã làm quá nhiều? Viễn ly tầm, vô sân tầm, bất hại tầm.`, ref: "AN 3.124", url: "../an/an3.124.html#content" },

{ text: `Này các Tỷ-kheo, ở đây, sau khi đắp y vào buổi sáng, Ta cầm lấy y bát, đi vào Ba-la-nại để khất thực. Này các Tỷ-kheo, trong khi đi khất thực tại Goyogapilakkha, Ta thấy một Tỷ-kheo hưởng thọ hương vị trống không, không có Thiền định, hưởng thọ hương vị hướng ngoại của vật dục, thất niệm, không tỉnh giác, không định tĩnh, với tâm tán loạn, với các căn phóng túng. Thấy vậy, Ta liền nói với vị Tỷ-kheo ấy: “Này Tỷ-kheo, này Tỷ-kheo! Thầy chớ có làm cho tự ngã trở thành thối nát. Này Tỷ-kheo, ai làm cho tự ngã thối nát đầy ứ, thoát ra toàn mùi hôi thối, rồi mong rằng: “Các loài ruồi lằng sẽ không bu đậu, sẽ không có chiếm cứ, sự kiện như vậy không xảy ra”. Này các Tỷ-kheo, Tỷ-kheo ấy được ta giáo giới với lời giáo giới này, cảm thấy xúc động mạnh.`, ref: "AN 3.128", url: "../an/an3.128.html#content" },

{ text: `Tham cầu, này các Tỷ-kheo, là thối nát; sân là mùi hôi thối, các suy tầm ác bất thiện là ruồi lằng. Này các Tỷ-kheo, ai làm cho các tự ngã thối nát, đầy ứ, thoát ra mùi hôi thối, rồi mong rằng: “Các loài ruồi lằng sẽ không bu đậu, sẽ không chiếm cứ”, sự kiện như vậy không xảy ra.`, ref: "AN 3.128", url: "../an/an3.128.html#content" },

{ text: `Tai mắt không giữ gìn\nCác căn không phòng hộ\nRuồi lằng sẽ bu đậu\nCác tư duy tham ái\nTỷ-kheo làm thối nát\nÐầy ứ những mùi hôi\nXa thay là Niết-bàn!\nChịu phần về bất hạnh\nTại làng hay trong rừng\nTự ngã không an tịnh\nKẻ ngu và không trí\nÐi đứng đầy ruồi lằng\nAi đầy đủ giới luật\nThích tịch tịnh trí tuệ\nSống an tịnh hạnh phúc\nMọi ruồi lằng diệt trừ`, ref: "AN 3.128", url: "../an/an3.128.html#content" },

{ text: `Này các Tỷ-kheo, ba pháp này chói sáng, được hiển lộ, không có che giấu. Vành tròn của mặt trăng, này các Tỷ-kheo, chói sáng, được hiển lộ, không có che giấu. Vành tròn của mặt trời, này các Tỷ-kheo, chói sáng, được hiển lộ, không có che giấu. Pháp và Luật được Thế Tôn tuyên thuyết, này các Tỷ-kheo, chói sáng, được hiển lộ, không có che giấu. Ba pháp này chói sáng, được hiển lộ, không có che giấu.`, ref: "AN 3.131", url: "../an/an3.131.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, có người dầu bị nói một cách kịch liệt, dầu có bị nói một cách ác độc, dầu có bị nói một cách thô lỗ, tuy vậy vẫn dễ dàng hòa hợp, thân thiện, và hoan hỷ. Này các Tỷ-kheo, ví như chữ viết trên nước được mau chóng biến mất, không có tồn tại lâu dài. Cũng vậy, này các Tỷ-kheo, có người dầu bị nói một cách kịch liệt, dầu có bị nói một cách ác độc, dầu có bị nói một cách thô lỗ, tuy vậy vẫn dễ dàng hòa hợp, thân thiện, và hoan hỷ. Này các Tỷ-kheo, đây được gọi là hạng người như chữ được viết trên nước.`, ref: "AN 3.132", url: "../an/an3.132.html#content" },

{ text: `Các loại hữu tình nào, này các Tỷ-kheo, vào buổi sáng, thân làm việc thiện, nói lời nói thiện, ý nghĩ điều thiện, các loài hữu tình ấy, này các Tỷ-kheo, có một buổi sáng tốt đẹp. Các loại hữu tình nào, này các Tỷ-kheo, vào buổi trưa, thân làm việc thiện, nói lời nói thiện, ý nghĩ điều thiện, các loài hữu tình ấy, này các Tỷ-kheo, có một buổi trưa tốt đẹp. Các loại hữu tình nào, này các Tỷ-kheo, vào buổi chiều, thân làm việc thiện, nói lời nói thiện, ý nghĩ điều thiện, các loài hữu tình ấy, này các Tỷ-kheo, có một buổi chiều tốt đẹp.`, ref: "AN 3.155", url: "../an/an3.155.html#content" },

{ text: `Giới, Thiền định, Trí tuệ\nVới giải thoát vô thượng\nGotama danh xưng\nGiác ngộ những pháp này\nÐức Phật thắng tri chúng\nThuyết pháp cho Tỷ-kheo\nÐạo sư đoạn tận khổ\nBậc Tuệ nhãn tịch tịnh.`, ref: "AN 4.1", url: "../an/an4.1.html#content" },
{ text: `Những ai sống ở đời\nKhông chế ngự các dục\nKhông từ bỏ ly tham\nThọ hưởng các dục vọng\nHọ đi đến sanh già\nÐến rồi lại đến nữa\nBị khát ái trói buộc\nHọ đi thuận dòng đời\nDo vậy bậc có trí\nỞ đời, trú chánh niệm\nKhông thọ hưởng các dục\nKhông hành trì điều ác\nDầu chịu sự khổ đau\nTừ bỏ các dục vọng\nHọ được gọi hạng người\nÐi ngược lại dòng đời.`, ref: "AN 4.5", url: "../an/an4.5.html#content" },

{ text: `Những ai quyết đoạn tận\nNăm phiền não kiết sử\nBậc hữu học viên mãn\nKhông còn bị thối thất\nÐạt được tâm điều phục\nCác căn được định tĩnh\nVị ấy được gọi là\nNgười đã tự đứng lại\nÐối các pháp thắng liệt\nVị ấy được giác tri\nÐã được quét, quạt sạch\nCác pháp được chấm dứt\nVị ấy bậc trí giả\nPhạm hạnh được thành tựu\nÐược tên gọi danh xưng\nBậc đã đi đến nơi\nChỗ tận cùng thế giới\nBậc đã đến bờ kia.`, ref: "AN 4.5", url: "../an/an4.5.html#content" },


{ text: `Người có ái làm bạn\nSẽ luân chuyển dài dài\nKhi hiện hữu chỗ này\nKhi hiện hữu chỗ khác\nNgười ấy không dừng được\nSự luận chuyển tái sanh\nRõ biết nguy hại này\nChính ái sanh đau khổ\nTỷ-kheo từ bỏ ái\nKhông nắm giữ chấp thủ\nAn trú, không thất niệm\nVị ấy sống xuất gia.`, ref: "AN 4.9", url: "../an/an4.9.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, có hạng người như thật quán tri sự tập khởi, sự chấm dứt, vị ngọt, sự nguy hại, sự xuất ly của các dục. Do như thật quán tri sự tập khởi, sự chấm dứt, vị ngọt, sự nguy hại, sự xuất ly của các dục, nên dục tham, dục hỷ, dục luyến, dục đam mê, dục khát, dục não, dục chấp thủ, dục ái trong các dục không xâm chiếm và tồn tại. Này các Tỷ-kheo, đây gọi là ly dục ách.`, ref: "AN 4.10", url: "../an/an4.10.html#content" },

{ text: `Này các Tỷ-kheo, nếu Tỷ-kheo khi đang đi ... khi đang đứng ... khi đang ngồi ... khi đang nằm, thức khởi lên dục tầm, hay sân tầm, hay hại tầm mà nếu Tỷ-kheo chấp nhận, không có từ bỏ, không có tẩy sạch, không có chấm dứt, không có đi đến không hiện hữu; này các Tỷ-kheo, nếu Tỷ-kheo khi đang nằm, thức có sở hành như vậy, vị ấy được gọi là người không có nhiệt tình, không có xấu hổ, liên tục thường hằng biếng nhác, tinh tấn hạ liệt.`, ref: "AN 4.11", url: "../an/an4.11.html#content" },

{ text: `Này các Tỷ-kheo, nếu Tỷ-kheo khi đang đi ... khi đang đứng ... khi đang ngồi ... khi đang nằm, thức khởi lên dục tầm, hay sân tầm, hay hại tầm mà nếu Tỷ-kheo không chấp nhận, từ bỏ, tẩy sạch, chấm dứt, đi đến không hiện hữu; này các Tỷ-kheo, nếu Tỷ-kheo khi đang nằm, thức có sở hành như vậy, vị ấy được gọi là người có nhiệt tình, có xấu hổ, liên tục thường hằng tinh cần, tinh tấn, siêng năng.`, ref: "AN 4.11", url: "../an/an4.11.html#content" },

{ text: `Nếu khi đi khi đứng\nKhi ngồi hay khi nằm\nKhởi lên ác tầm tư\nLiên hệ đến gia đình\nThực hành theo ác đạo\nMờ ám bởi si mê\nVị Tỷ-kheo như vậy\nKhông chứng Vô thượng giác\nAi khi đi khi đứng\nKhi ngồi hay khi nằm\nÐiều phục được tâm tư\nYêu thích tầm chỉ tịnh\nVị Tỷ-kheo như vậy\nChứng được Vô thượng giác`, ref: "AN 4.11", url: "../an/an4.11.html#content" },

{ text: `Nếu Tỷ-kheo trong khi đi ... trong khi đứng ... nếu Tỷ-kheo trong khi ngồi ... nếu Tỷ-kheo trong khi nằm thức, tham, sân, si được từ bỏ ... hôn trầm thụy miên, trạo hối, nghi được đoạn tận , tinh cần, tinh tấn, không có thụ động, niệm được an trú không có thất niệm, thân được khinh an, không có cuồng nhiệt, tâm được định tĩnh nhất tâm. Này các Tỷ-kheo, nếu các Tỷ-kheo khi đang thức có sở hành như vậy; vị ấy được gọi là người có nhiệt tâm, có xấu hổ, liên tục thường hằng tinh cần tinh tấn, siêng năng.`, ref: "AN 4.12", url: "../an/an4.12.html#content" },

{ text: `Ði đứng biết tự chế\nNgồi nằm biết tự chế\nTỷ-kheo biết tự chế\nKhi co tay, duỗi tay\nPhía trên, ngang cùng khắp\nXa cho đến cùng tột\nBất cứ sanh thú nào\nỞ tại thế giới này\nKhéo quán sát sanh diệt\nCủa tất cả pháp uẩn\nTâm chỉ tịnh chánh hạnh\nThường xuyên chuyên học tập\nLiên tục, hằng siêng năng\nTỷ-kheo được gọi vậy.`, ref: "AN 4.12", url: "../an/an4.12.html#content" },

{ text: `—Một thời, này các Tỷ-kheo, Ta trú ở Uruvelà trên bờ sông Neranjarà, dưới cây bàng ajapàla, khi mới thành Chánh giác. Trong khi Ta Thiền tịnh độc cư, này các Tỷ-kheo, tư tưởng sau đây được khởi lên: “Thật là khó khăn, sống không cung kính, không vâng lời, vậy Ta hãy cung kính, đảnh lễ và sống y chỉ vào một vị Sa-môn hay Bà-la-môn”. Rồi này các Tỷ-kheo, Ta suy nghĩ: “Với mục đích làm cho giới uẩn ...định uẩn ... tuệ uẩn ... giải thoát uẩn chưa được đầy đủ, Ta hãy cung kính, đảnh lễ và sống y chỉ vào một vị Sa-môn hay Bà-la-môn nào khác. Nhưng Ta không thấy một chỗ nào trong thế giới chư Thiên, Ác ma và Phạm thiên, giữa quần chúng Sa-môn và Bà-la-môn, chư Thiên hay loài Người, không có một vị Sa-môn hay Bà-la-môn nào khác với giới đầy đủ hơn Ta, mà Ta có thể cung kính, đảnh lễ, sống y chỉ. Rồi này các Tỷ-kheo, Ta suy nghĩ như sau: “Với pháp này mà Ta đã chơn chánh giác ngộ, Ta hãy cung kính đảnh lễ và sống y chỉ pháp ấy”. Và Ta sống cung kính, tôn trọng và y chỉ pháp ấy và Ta đã tự Chánh Ðẳng Giác. Và này các Tỷ-kheo, vì rằng chúng Tăng thành tựu sự cao cả nên Ta tôn trọng đặc biệt chúng Tăng.`, ref: "AN 4.21", url: "../an/an4.21.html#content" },

{ text: `Nếu trưởng lão, này các Tỷ-kheo, là 80 tuổi, hay 90 tuổi, hay 100 tuổi đời, và nếu vị ấy nói phi thời, nói phi chân, nói phi nghĩa, nói phi pháp, nói phi luật, nói những lời không đáng giữ gìn, lời nói không hợp thời cơ, không hợp lý, không có giới hạn, không có liên hệ đến mục đích, thời vị ấy chỉ được gọi là vị trưởng lão ngu. Nếu là một vị tuổi trẻ, này các Tỷ kheo, một thanh niên còn non trẻ, tóc đen nhánh, trong tuổi hiền thiện của đời, còn trong tuổi thanh xuân, vị ấy nói lời đúng thời, nói lời chân thực, nói lời có nghĩa, nói lời đúng pháp, nói lời đúng luật, nói những lời đáng giữ gìn, lời nói hợp thời cơ, hợp lý, có giới hạn, liên hệ đến mục đích, thời vị ấy chỉ được gọi là vị trưởng lão hiền trí.`, ref: "AN 4.22", url: "../an/an4.22.html#content" },

{ text: `Này các Tỷ-kheo, có bốn pháp tác thành trưởng lão này. Thế nào là bốn? Ở đây, này các Tỷ-kheo, vị Tỷ-kheo có giới, sống chế ngự với sự chế ngự của giới bổn Pàtimokkha, đầy đủ uy nghi chánh hạnh, thấy sợ hãi trong các lỗi nhỏ nhặt, chấp nhận và học tập trong các học pháp. Là vị nghe nhiều, thọ trì điều đã nghe, tích tụ điều đã nghe, những pháp sơ thiện, trung thiện, hậu thiện, có nghĩa có văn, đề cao Phạm hạnh hoàn toàn viên mãn thanh tịnh, các pháp như vậy, vị ấy nghe nhiều, thọ trì đọc tụng bằng lời, quán sát với ý, thể nhập với chánh kiến, đối với bốn thiền thuộc tăng thượng tâm, hiện tại lạc trú, có được không khó khăn, có được không mệt nhọc, có được không phí sức; do đoạn diệt các lậu hoặc, ngay trong hiện tại, tự mình với thắng trí, chứng ngộ, chứng đạt và an trú vô lậu tâm giải thoát, tuệ giải thoát. Này các Tỷ-kheo, bốn pháp này tác thành vị trưởng lão.`, ref: "AN 4.22", url: "../an/an4.22.html#content" },

{ text: `Ai với tâm cống cao\nNói nhiều lời phù phiếm\nVới tư duy không định\nNhư thú không ưa pháp\nXa địa vị trưởng lão\nÁc kiến, không kính trọng\nVà ai đủ giới hạnh\nNghe nhiều trí biện tài\nSống chế ngự bậc trí\nÐối với tất cả pháp\nVị ấy với trí tuệ\nQuán thấy chơn ý nghĩa\nÐạt cứu cánh các pháp\nKhông hoang vu, biện tài\nÐoạn tận sanh và chết\nViên mãn hành Phạm hạnh\nVị ấy Ta gọi tên\nTrưởng lão không lậu hoặc\nDo đoạn trừ lậu hoặc\nÐược gọi là trưởng lão.`, ref: "AN 4.22", url: "../an/an4.22.html#content" },

{ text: `Cái gì, này các Tỷ-kheo, trong toàn thế giới với Thiên giới, Ma giới, Phạm thiên giới, cùng với quần chúng Sa-môn, Bà-la-môn, chư Thiên và loài Người, được thấy, được nghe, được cảm giác, được thức tri, được đạt đến, được tầm cầu, được ý tư sát, tất cả đều được Như Lai chánh đẳng giác. Do vậy, được gọi là Như Lai. Từ đêm, này các Tỷ-kheo, Như Lai được chánh đẳng giác, đến đêm Như Lai nhập Niết-bàn, trong thời gian ấy, điều gì Như Lai nói, nói lên, tuyên bố, tất cả là như vậy, không có khác được. Do vậy, được gọi là Như Lai. Này các Tỷ-kheo, Như Lai nói gì thì làm vậy, làm gì thì nói vậy. Vì rằng nói gì thì làm vậy, làm gì thì nói vậy, nên được gọi là Như Lai.`, ref: "AN 4.23", url: "../an/an4.23.html#content" },

{ text: `Này các Tỷ-kheo, cái gì trong toàn thế giới với Thiên giới, Ma giới, Phạm thiên giới, cùng với quần chúng Sa-môn, Bà-la-môn, chư Thiên và loài Người, được thấy ... được ý tư sát, tất cả Ta đều biết. Này các Tỷ-kheo, cái gì trong toàn thế giới này ... được thấy, được ý tư sát, Ta đã được biết rõ như sau: “Tất cả đều được Như Lai biết đến. Như Lai không có dựng đứng lên”. Này các Tỷ-kheo, nếu Ta nói rằng: “Ta biết tất cả, cái gì trong toàn thế giới ... được thấy, được ý tư sát”. Như vậy, là có nói láo trong ta. Nếu Ta nói như sau: “Ta cả hai biết và không biết”. Như vậy, là có nói láo trong ta. Nếu Ta nói như sau: “Ta không biết và cũng không phải biết”. Như vậy là có nói láo trong Ta. Như vậy có lỗi trong Ta.`, ref: "AN 4.24", url: "../an/an4.24.html#content" },

{ text: `Như vậy, này các Tỷ-kheo, Như Lai là vị đã thấy những gì cần thấy, nhưng không có tưởng tượng điều đã được thấy, không có tưởng tượng những cái gì không được thấy, không có tưởng tượng những gì cần phải thấy, không có tưởng tượng đối với người thấy. Ðã nghe những gì cần nghe, nhưng không có tưởng tượng điều đã được nghe, không có tưởng tượng những cái gì không được nghe, không có tưởng tượng những gì cần phải nghe, không có tưởng tượng đối với người nghe. Ðã cảm giác những gì cần cảm giác, nhưng không có tưởng tượng điều đã được cảm giác, không có tưởng tượng những cái gì không được cảm giác, không có tưởng tượng những gì cần phải cảm giác, không có tưởng tượng đối với người cảm giác. Ðã thức tri những gì cần thức tri, nhưng không có tưởng tượng điều đã được thức tri, không có tưởng tượng những cái gì không được thức tri, không có tưởng tượng những cái gì cần phải thức tri, không có tưởng tượng đối với người thức tri. Như vậy, này các Tỷ-kheo, Như Lai đối với các pháp được thấy, được nghe, được cảm giác, được thức tri, đều đã biết rõ, nên vị ấy là như vậy. Lại nữa, hơn người như vậy, không có ai khác tối thượng hơn và thù thắng hơn, Ta tuyên bố như vậy.`, ref: "AN 4.24", url: "../an/an4.24.html#content" },

{ text: `Phạm hạnh được sống, này các Tỷ-kheo, không vì mục đích lừa dối quần chúng, không vì mục đính mơn trớn quần chúng, không vì mục đích được lợi ích về lợi dưỡng, cung kính, danh vọng, không vì mục đích được lợi ích thoát khỏi lời phê bình bàn tán, không với ý nghĩ: “Mong quần chúng biết Ta như vậy”. Và này các Tỷ-kheo, Phạm hạnh này được sống với mục đích được chế ngự, với mục đích đoạn tận, với mục đích ly tham, với mục đích đoạn diệt.`, ref: "AN 4.25", url: "../an/an4.25.html#content" },

{ text: `Với mục đích chế ngự,\nVới mục đích đoạn tận,\nLà đời sống Phạm hạnh,\nTránh xa lời nói suông,\nThế Tôn đã tuyên bố,\nÐi đến nhập Niết-bàn,\nCon đường này được đi,\nBởi đại nhân, đại sĩ,\nAi dấn bước thực hành,\nÐúng như lời Phật dạy,\nSẽ chấm dứt khổ đau,\nLàm theo Ðạo Sư dạy.`, ref: "AN 4.25", url: "../an/an4.25.html#content" },

{ text: `Những vị Tỷ-kheo nào, này các Tỷ-kheo, lừa dối cứng đầu, lắm mồm lắm miệng, hoang dâm, hỗn hào, không có định tĩnh, những Tỷ-kheo ấy không phải là Tỷ-kheo của Ta. Những Tỷ-kheo ấy đã rơi khỏi Pháp Luật này. Và họ không đi đến tăng trưởng, tăng thịnh, tăng rộng trong Pháp Luật này. Và này các Tỷ-kheo, các Tỷ-kheo nào không lừa dối, không lắm mồm lắm miệng, có trí, không cứng đầu, khéo định tĩnh, những Tỷ-kheo ấy phải là Tỷ-kheo của Ta. Và những Tỷ-kheo ấy không rơi khỏi Pháp Luật này, và họ đi đến tăng trưởng, tăng thịnh, tăng rộng trong Pháp Luật này.`, ref: "AN 4.26", url: "../an/an4.26.html#content" },

{ text: `Kẻ lừa dối cứng đầu,\nKẻ lắm mồm, hoang dâm,\nKẻ hỗn hào, không định,\nKhông tăng trưởng các pháp,\nÐược bậc Chánh Ðẳng Giác,\nTuyên bố và thuyết giảng,\nKhông lừa, không lắm mồm,\nCó trí, không cứng đầu,\nVới tâm khéo định tĩnh,\nChúng tăng trưởng các pháp,\nÐược bậc Chánh Ðẳng Giác,\nTuyên bố và thuyết giảng.`, ref: "AN 4.26", url: "../an/an4.26.html#content" },

{ text: `Biết đủ với sự vật,\nKhông quan trọng, dễ được,\nLại không có phạm tội,\nTâm không bị phiền nhiễu,\nVề vấn đề trú xứ,\nY áo và ăn uống,\nTâm không bị lo lắng,\nVề phương hướng phải đi,\nCác pháp được tuyên bố,\nThuận lợi Sa-môn hạnh,\nChúng được có đầy đủ.\nVới vị biết vừa đủ,\nVới vị không phóng dật,\nTinh cần trong học tập.`, ref: "AN 4.27", url: "../an/an4.27.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, Tỷ-kheo biết đủ với bất cứ loại y nào, và nói lời tán thán sự biết đủ với bất cứ loại y nào, không vì nhân y phục rơi vào sự tầm cầu bất chính, không thích hợp. Nếu không được y, không có lo âu tiếc nuối; nếu được y không có tham lam, mê say, tham đắm; thấy sự nguy hiểm và với trí tuệ thấy được sự xuất ly, vị ấy hưởng thọ y, không vì biết đủ với bất cứ loại y nào, không có khen mình chê người. Ai ở đây, khôn khéo (thiện xảo), không có thụ động, tỉnh giác, chánh niệm, này các Tỷ-kheo, đấy gọi là Tỷ-kheo đứng ở trên Thánh truyền thống, kỳ cựu, được nhận biết là tối sơ.`, ref: "AN 4.28", url: "../an/an4.28.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, Tỷ-kheo biết đủ với bất cứ loại đồ ăn khất thực nào, và nói lời tán thán sự biết đủ với bất cứ loại đồ ăn khất thực nào, không vì nhân khất thực rơi vào sự tầm cầu bất chính, không thích hợp. Nếu không được đồ ăn khất thực, không có lo âu tiếc nuối; nếu được đồ ăn khất thực, không có tham lam, mê say, tham đắm; thấy sự nguy hiểm và với trí tuệ thấy được sự xuất ly, vị ấy hưởng thọ đồ ăn khất thực, không vì biết đủ với bất cứ loại đồ ăn khất thực nào, không có khen mình, chê người. Ai ở đây khôn khéo (thiện xảo), không có thụ động, tỉnh giác, chánh niệm, này các Tỷ-kheo, đây gọi là Tỷ-kheo đứng ở trên Thánh truyền thống, kỳ cựu, được nhận biết là tối sơ.`, ref: "AN 4.28", url: "../an/an4.28.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, Tỷ-kheo ưa thích tu tập, vui thích tu tập, ưa thích đoạn tận, vui thích đoạn tận, nhưng không vì ưa thích tu tập, vui thích tu tập, ưa thích đoạn tận, vui thích đoạn tận mà khen mình chê người. Ai ở đây khôn khéo, không có thụ động, tỉnh giác, chánh niệm, này các Tỷ-kheo, đây gọi là Tỷ-kheo đứng trên Thánh truyền thống, kỳ cựu, được nhận biết là tối sơ.`, ref: "AN 4.28", url: "../an/an4.28.html#content" },

{ text: `Hãy sống không có tham,\nVới tâm không có sân,\nChánh niệm và nhất tâm,\nNội tâm khéo định tĩnh.`, ref: "AN 4.29", url: "../an/an4.29.html#content" },

{ text: `Có bốn bánh xe này, này các Tỷ-kheo, thành tựu với chúng, bốn bánh xe được vận chuyển giữa chư Thiên và loài Người thành tựu với chúng, chư Thiên và loài nguời không bao lâu đạt đến sự lớn mạnh, tăng thịnh trong các tài sản. Thế nào là bốn? Trú xứ thích hợp, thân cận các bậc Chân nhân, tự nguyện chân chánh, phước đã làm từ trước.`, ref: "AN 4.31", url: "../an/an4.31.html#content" },

{ text: `Dầu cho các loại hữu tình nào, này các Tỷ-kheo, không chân hay hai chân, bốn chân hay nhiều chân, có sắc hay không sắc, có tưởng hay không tưởng, hay phi tưởng phi phi tưởng, Thế Tôn, bậc A-la-hán, Chánh Ðẳng Giác được xem là tối thượng. Những ai đặt lòng tin vào đức Phật, họ đặt lòng tin vào tối thượng. Với những ai đặt lòng tin vào tối thượng, họ được quả dị thục tối thượng.`, ref: "AN 4.34", url: "../an/an4.34.html#content" },

{ text: `Này các Tỷ-kheo, dầu cho loại pháp hữu vi nào, Thánh đạo tám ngành được xem là tối thượng, những ai đặt lòng tin vào Thánh đạo Tám ngành, họ đặt lòng tin vào tối thượng. Với những ai đặt lòng tin vào tối thượng, họ được quả dị thục tối thượng.`, ref: "AN 4.34", url: "../an/an4.34.html#content" },

{ text: `Dầu cho loại pháp nào, này các Tỷ-kheo, hữu vi hay vô vi, ly tham được xem là tối thượng trong tất cả pháp, tức là sự nhiếp phục kiêu mạn, sự nhiếp phục khát ái, sự nhổ lên tham ái, sự chặt đứt tái sanh, sự đoạn diệt tham ái, sự ly tham đoạn diệt, Niết-bàn. Những ai đặt lòng tin vào pháp ly tham, này các Tỷ-kheo, họ đặt lòng tin vào tối thượng. Với những ai đặt lòng tin vào tối thượng, họ được quả dị thục tối thượng.`, ref: "AN 4.34", url: "../an/an4.34.html#content" },

{ text: `Dầu cho loại chúng Tăng hay hội chúng nào, này các Tỷ-kheo, chúng Tăng đệ tử của Như Lai được xem là tối thượng trong tất cả hội chúng ấy. Tức là bốn đôi tám vị, chúng Tăng đệ tử của Thế Tôn đáng được cung kính, đáng được tôn trọng, đáng được cúng dường, đáng được chắp tay, là vô thượng phước điền ở đời. Những ai đặt lòng tin vào chúng Tăng, này các Tỷ-kheo, họ đặt lòng tin vào tối thượng. Với những ai đặt lòng tin vào tối thượng, họ được quả dị thục tối thượng. Này các Tỷ-kheo, đây là bốn lòng tin tối thượng.`, ref: "AN 4.34", url: "../an/an4.34.html#content" },

{ text: `Tin tưởng vào tối thượng,\nBiết được pháp tối thượng,\nTin tưởng Phật tối thượng,\nÐáng tôn trọng vô thượng,\nTin tưởng Pháp tối thượng,\nLy tham, an tịnh, lạc,\nTin tưởng Tăng tối thượng,\nLà ruộng phước vô thượng,\nBố thí bậc tối thượng,\nPhước tối thượng tăng trưởng,\nTối thượng về thọ mạng,\nDung sắc và danh văn,\nTối thượng về an lạc,\nTối thượng về sức mạnh,\nBậc trí thí tối thượng,\nPháp tối thượng chánh định,\nChư Thiên hay loài người,\nÐạt được hỷ tối thượng.`, ref: "AN 4.34", url: "../an/an4.34.html#content" },

{ text: `Này Bà-la-môn, Ta đã thực hành, hướng đến hạnh phúc cho nhiều người, hướng đến an lạc cho nhiều người, đã an lập nhiều người trên Thánh lý, tức là hiền thiện pháp tánh, thiện pháp tánh. Ta là vị, với tầm tư nào Ta nghĩ cần phải tầm tư, Ta tầm tư tầm tư ấy. Với tầm tư nào Ta nghĩ không cần phải tầm tư, Ta không tầm tư tầm tư ấy. Với tư duy nào Ta nghĩ cần phải tư duy, Ta tư duy tư duy ấy, Với tư duy nào Ta nghĩ không cần phải tư duy, Ta không tư duy tư duy ấy. Này Bà-la-môn, Ta đạt được tâm tự tại trong các đường hướng tầm tư. Này Bà-la-môn đối với bốn Thiền, thuộc tăng thượng tâm, hiện tại lạc trú, Ta có được không khó khăn, Ta có được không mệt nhọc, Ta có được không phí sức. Này Bà-la-môn, do đoạn diệt các lậu hoặc, ngay trong hiện tại, với thắng trí, Ta chứng ngộ, chứng đạt và an trú vô lậu tâm giải thoát, tuệ giải thoát.`, ref: "AN 4.35", url: "../an/an4.35.html#content" },

{ text: `Ai trong mọi chúng sanh,\nHiểu rõ được giải thoát,\nKhỏi cạm bẫy thần chết,\nVì hạnh phúc nhân thiên,\nTuyên bố về chánh lý,\nTuyên bố về Chánh pháp.\nQuần chúng thấy nghe vậy,\nLiền hoan hỷ tịnh tín,\nThiện xảo đạo, phi đạo,\nViệc nên làm đã làm,\nVô lậu bậc Giác ngộ,\nVới thân này thân cuối,\nNgài được gọi tôn xưng,\nBậc Ðại tuệ, Ðại nhân.`, ref: "AN 4.35", url: "../an/an4.35.html#content" },

{ text: `Ví như, này Bà-la-môn, bông sen xanh, hay bông sen hồng, hay bông sen trắng, sanh ra trong nước, lớn lên trong nước, vươn lên khỏi nước, và đứng thẳng không bị nước thấm ướt. Cũng vậy, này Bà-la-môn sanh ta trong đời, lớn lên trong đời, Ta sống chinh phục đời, không bị đời thấm ướt. Này Bà-la-môn, Ta là Phật, hãy như vậy thọ trì.`, ref: "AN 4.36", url: "../an/an4.36.html#content" },

{ text: `Tỷ-kheo an trú giới,\nSống chế ngự các căn,\nBiết tiết độ ăn uống,\nVà chú tâm cảnh giác,\nSống an trú như vậy,\nNgày đêm không mệt mỏi\nTu tập các thiện pháp,\nÐạt an ổn ách nạn,\nƯa thích không phóng dật,\nThấy sợ hãi phóng dật,\nKhông có thể thối đọa,\nTỷ-kheo gần Niết-bàn.`, ref: "AN 4.37", url: "../an/an4.37.html#content" },

{ text: `Này các Tỷ-kheo, có bốn định tu tập này. Thế nào là bốn? Có định tu tập, này các Tỷ-kheo, do tu tập, do làm cho sung mãn, đưa đến hiện tại lạc trú. Có định tu tập, này các Tỷ-kheo, do tu tập, do làm cho sung mãn, đưa đến chứng được tri kiến. Có định tu tập, này các Tỷ-kheo, do tu tập, do làm cho sung mãn, đưa đến chánh niệm tỉnh giác. Có định tu tập, này các Tỷ-kheo, được tu tập, được làm cho sung mãn, đưa đến đoạn tận các lậu hoặc.`, ref: "AN 4.41", url: "../an/an4.41.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là định tu tập, do tu tập, do làm cho sung mãn, đưa đến chánh niệm tỉnh giác? Ở đây, này các Tỷ-kheo, với vị Tỷ-kheo, thọ khởi lên được rõ biết, thọ an trú được rõ biết, thọ chấm dứt được rõ biết; tưởng khởi lên được rõ biết, tưởng an trú được rõ biết, tưởng chấm dứt được rõ biết; tầm khởi lên được rõ biết, tầm an trú được rõ biết, tầm chấm dứt được rõ biết. Này các Tỷ-kheo, đây gọi là định tu tập, do tu tập, do làm cho sung mãn, đưa đến chánh niệm tỉnh giác.`, ref: "AN 4.41", url: "../an/an4.41.html#content" },

{ text: `Bốn hạng người này, này các Tỷ-kheo, có mặt, hiện hữu ở đời. Thế nào là bốn? Kính trọng phẫn nộ, không kính trọng diệu pháp; kính trọng gièm pha, không kính trọng diệu pháp; kính trọng lợi dưỡng, không kính trọng diệu pháp; kính trọng cung kính, không kính trọng diệu pháp.`, ref: "AN 4.43", url: "../an/an4.43.html#content" },

{ text: `Bốn hạng người này, này các Tỷ-kheo, có mặt, hiện hữu ở đời. Thế nào là bốn? Kính trọng diệu pháp, không kính trọng phẫn nộ; kính trọng diệu pháp, không kính trọng gièm pha; kính trọng diệu pháp, không kính trọng lợi dưỡng; kính trọng diệu pháp, không kính trọng cung kính.`, ref: "AN 4.43", url: "../an/an4.43.html#content" },

{ text: `Các Tỷ-kheo kính trọng,\nPhẫn nộ và gièm pha,\nKính trọng các lợi dưỡng,\nKính trọng sự cung kính,\nVị ấy không lớn mạnh,\nTrong pháp đức Phật thuyết,\nAi hiện sống, đã sống,\nKính trọng Chánh diệu pháp,\nCác vị ấy lớn mạnh\nTrong pháp đức Phật thuyết.`, ref: "AN 4.43", url: "../an/an4.43.html#content" },

{ text: `Này Hiền giả, Ta tuyên bố rằng: “Tại chỗ nào không bị sanh, không bị già, không bị chết, không có từ bỏ (đời này), không có sanh khởi (đời khác), không có thể đi đến để thấy, để biết, để đạt đến chỗ tận cùng của thế giới”. Nhưng này Hiền giả, trong cái thân dài độ mấy tấc này, với những tưởng, những tư duy của nó, Ta tuyên bố về thế giới, về thế giới tập khởi, về thế giới đoạn diệt, về con đường đưa đến thế giới đoạn diệt.`, ref: "AN 4.45", url: "../an/an4.45.html#content" },

{ text: `Với đi, không bao giờ,\nÐạt tận cùng thế giới.\nNếu không, không đạt được,\nChỗ tận cùng thế giới,\nThời không có giải thoát,\nRa khỏi ngoài khổ đau.\nDo vậy, bậc có trí,\nHiểu biết rõ thế giới,\nÐi tận cùng thế giới,\nVới Phạm hạnh thành tựu,\nBậc đạt được an tịnh,\nBiết tận cùng thế giới,\nKhông mong cầu đời này,\nKhông mong cầu đời sau.`, ref: "AN 4.45", url: "../an/an4.45.html#content" },

{ text: `Này các Tỷ-kheo, có bốn sự việc này, rất xa, rất xa với nhau. Thế nào là bốn? Trời và đất, này các Tỷ-kheo, là sự việc thứ nhất rất xa, rất xa với nhau. Bờ biển bên này, này các Tỷ-kheo với bờ biển bên kia, là sự việc thứ hai rất xa, rất xa với nhau. Từ chỗ mặt trời mọc lên, này các Tỷ-kheo, đến chỗ mặt trời lặn xuống, là sự việc thứ ba rất xa, rất xa với nhau. Pháp của hạng người bất thiện, này các Tỷ-kheo, với pháp của hạng người thiện, là sự việc thứ tư rất xa, rất xa với nhau.`, ref: "AN 4.47", url: "../an/an4.47.html#content" },

{ text: `Nếu vị ấy không nói,\nChúng không biết vị ấy,\nNhư vậy bậc Hiền trí,\nLẫn lộn với kẻ ngu,\nNếu vị ấy nói lên,\nChúng biết đến vị ấy,\nKhi vị ấy thuyết giảng,\nCon đường đến bất tử,\nVậy hãy thuyết giảng lên,\nChói sáng chơn diệu pháp,\nHãy dâng cao ngọn cờ,\nNgọn cờ các ẩn sĩ,\nKhéo nói là ngọn cờ,\nCủa các bậc ẩn sĩ,\nVà pháp là ngọn cờ,\nCủa những bậc ẩn sĩ.`, ref: "AN 4.48", url: "../an/an4.48.html#content" },

{ text: `Này các Tỷ-kheo, có bốn tưởng điên đảo, tâm điên đảo, kiến điên đảo này. Thế nào là bốn? Trong vô thường, nghĩ là thường, này các Tỷ-kheo, đó là tưởng điên đảo, tâm điên đảo, kiến điên đảo. Trong khổ nghĩ là không khổ, này các Tỷ-kheo, đó là tưởng điên đảo, tâm điên đảo, kiến điên đảo. Trong vô ngã, nghĩ là ngã, này các Tỷ-kheo, đó là tưởng điên đảo, tâm điên đảo, kiến điên đảo. Trong không thanh tịnh, nghĩ là thanh tịnh, này các Tỷ-kheo, đó là tưởng điên đảo, tâm điên đảo, kiến điên đảo.`, ref: "AN 4.49", url: "../an/an4.49.html#content" },

{ text: `Có Sa-môn, Phạm chí,\nBị tham sân trói buộc,\nBị vô minh bao phủ,\nLoài người ưa sắc đẹp,\nUống rượu men rượu nấu,\nHưởng thụ pháp dâm dục,\nMê hoặc, họ chấp nhận,\nNhận lấy vàng và bạc,\nCác Sa-môn, Phạm chí,\nSinh sống theo tà mạng.\nPhật, bà con mặt trời\nNói đến uế nhiễm ấy,\nBị ô nhiễm bởi chúng,\nCác Sa-môn, Phạm chí,\nKhông cháy sang, chói sáng,\nÁnh sáng bụi ô nhiễm,\nBao phủ bởi tối tăm,\nNô lệ bởi ái dục,\nBị ái kéo, dắt dẫn,\nHọ làm đầy dẫy thêm,\nBãi tha ma ghê tởm,\nChúng lại phải tái sanh.`, ref: "AN 4.50", url: "../an/an4.50.html#content" },

{ text: `Biển lớn không hạn lượng,\nHồ lớn nhiều sợ hãi,\nLà kho tàng cất giữ,\nVô số lượng châu báu,\nCũng là chỗ trú ẩn,\nVô số các loại cá,\nLà chỗ các sóng lớn,\nQuy tụ chảy ra biển,\nCũng vậy người bố thí,\nÐồ ăn và đồ uống,\nVải mặc và giường nằm,\nChỗ ngồi và thảm nệm,\nBậc Hiền thí như vậy,\nPhước đức ùa chảy đến,\nNhư sông dẫn dòng nước,\nÙa chảy vào bể cả.`, ref: "AN 4.51", url: "../an/an4.51.html#content" },

{ text: `Này các Tỷ-kheo, Tỷ-kheo trong khi hưởng thọ y của ai... hưởng thọ đồ ăn khất thực của ai... hưởng thọ trú xứ của ai... hưởng thọ dược phẩm trị bệnh của ai, nếu vị ấy đạt đến và an trú vô lượng tâm định, như vậy là nguồn sanh phước vô lượng cho người bố thí, là nguồn sanh thiện đem lại an lạc, thuộc Thiên giới, là quả lạc dị thục, dẫn đến cõi Trời, đưa đến khả lạc, khả hỷ, khả ý, hạnh phúc, an lạc.`, ref: "AN 4.51", url: "../an/an4.51.html#content" },

{ text: `Này các Tỷ-kheo, vị Thánh đệ tử thành tựu bốn nguồn sanh phước, nguồn sanh thiện này, thời không dễ gì để nắm lấy một số lượng phước thiện, và nói rằng: “Có chừng ấy nguồn sanh phước, nguồn sanh thiện, đem lại an lạc, thuộc thiên giới, là quả lạc dị thục đem đến cõi trời, đưa đến khả lạc, khả hỷ, khả ý, hạnh phúc, an lạc”; vì rằng cả khối phước thiện lớn được xem là vô số vô lượng.`, ref: "AN 4.51", url: "../an/an4.51.html#content" },

{ text: `Ai tin tưởng Như Lai,\nBất động, khéo an trú,\nAi tin giới, hiền thiện,\nBậc Thánh khen, mến chuộng.\nAi tịnh tín chúng Tăng,\nVới cái nhìn chánh trực,\nNgười ấy được họ gọi,\nKhông phải là người nghèo.\nÐời sống người như vậy,\nKhông phải đời trống rỗng,\nDo vậy tín và giới,\nTịnh tín và thắng pháp,\nBậc trí chú tâm niệm,\nLời dạy của chư Phật.`, ref: "AN 4.52", url: "../an/an4.52.html#content" },

{ text: `Các Thánh nữ đệ tử khi bố thí đồ ăn, này Suppavàsà, bố thí bốn sự cho những người nhận. Thế nào là bốn? Cho thọ mạng, cho dung sắc, cho an lạc, cho sức mạnh. Sau khi cho thọ mạng, người cho được chia phần thọ mạng, thuộc cõi Trời hay cõi Người. Sau khi cho dung sắc, người cho được chia phần dung sắc, thuộc cõi Trời hay cõi Người. Sau khi cho an lạc, người cho được chia phần an lạc, hoặc thuộc cõi Trời, hoặc thuộc cõi Người. Sau khi cho sức mạnh, người cho được chia phần sức mạnh, thuộc cõi Trời, hay cõi Người. Này Suppavàsà, khi Thánh nữ đệ tử bố thí đồ ăn, bố thí bốn sự này cho những người nhận.`, ref: "AN 4.57", url: "../an/an4.57.html#content" },
{ text: `Những ai khéo chế ngự,\nSống bố thí người khác,\nAi tùy thời nhiệt thành,\nBố thí đồ ăn uống,\nÐem lại cho các vị,\nBốn sự kiện như sau,\nCho thọ mạng, dung sắc,\nCho an lạc, sức mạnh,\nVị bố thí thọ mạng,\nVị bố thí dung sắc,\nNgười bố thí an lạc,\nNgười bố thí sức mạnh,\nThọ mạng dài, danh xưng,\nDầu sanh tại chỗ nào.`, ref: "AN 4.59", url: "../an/an4.59.html#content" },

{ text: `Này Gia chủ, Thánh đệ tử ấy, sau khi biết được dục tham là uế nhiễm của tâm, từ bỏ dục tham, uế nhiễm của tâm; sau khi biết được sân hận là uế nhiễm của tâm, từ bỏ sân hận, uế nhiễm của tâm; sau khi biết được hôn trầm thụy miên là uế nhiễm của tâm, từ bỏ hôn trầm thụy miên, uế nhiễm của tâm; sau khi biết được trạo hối là uế nhiễm của tâm, từ bỏ trạo hối, uế nhiễm của tâm; sau khi biết được nghi là uế nhiễm của tâm, từ bỏ nghi, uế nhiễm của tâm; này Gia chủ, đây gọi là vị Thánh đệ tử có đại trí tuệ, có trí tuệ rộng lớn, bước vào giới vức minh kiến, đầy đủ trí tuệ. Ðây gọi là đầy đủ trí tuệ.`, ref: "AN 4.61", url: "../an/an4.61.html#content" },

{ text: `Những gia đình nào, này các Tỷ-kheo, các cha mẹ được các con đảnh lễ cúng dường ở trong nhà, những gia đình ấy được xem là giống như Phạm thiên. Những gia đình nào, này các Tỷ-kheo, các cha mẹ được các con đảnh lễ cúng dường ở trong nhà, những gia đình ấy được xem là giống như bậc Ðạo sư thời xưa. Những gia đình nào, này các Tỷ-kheo, các cha mẹ được các con đảnh lễ cúng dường ở trong nhà, những gia đình ấy, này các Tỷ-kheo, được xem là giống như chư Thiên thời trước. Những gia đình nào, này các Tỷ-kheo, các cha mẹ được các con đảnh lễ cúng dường ở trong nhà, những gia đình ấy được xem là đáng được cúng dường.`, ref: "AN 4.62", url: "../an/an4.62.html#content" },

{ text: `Phạm Thiên, này các Tỷ-kheo, là đồng nghĩa với mẹ cha; các bậc Ðạo sư thời xưa, này các Tỷ-kheo, là đồng nghĩa với mẹ cha; chư Thiên thuở xưa, này các Tỷ-kheo, là đồng nghĩa với mẹ cha; đáng được cung kính cúng dường, này các Tỷ-kheo, là đồng nghĩa với mẹ cha. Vì cớ sao? Này các Tỷ-kheo, vì mẹ cha giúp đỡ rất nhiều cho các con, nuôi dưỡng chúng lớn và giới thiệu chúng vào đời này.`, ref: "AN 4.62", url: "../an/an4.62.html#content" },

{ text: `Tham ái vật đẹp đẽ,\nThích thú sắc khả ái,\nBị cột bởi vô minh,\nCác hữu tình hạ liệt,\nCàng tăng trưởng trói buộc.\nCho đến kẻ có trí,\nLàm các việc bất thiện,\nSanh từ tham, sân, si,\nKhiến phiền muộn, khó chịu,\nLàm đau khổ sanh khởi,\nKẻ vô minh bao vây,\nKẻ mù không có mắt,\nTự tánh họ là vậy,\nHọ không thể nghĩ rằng,\nTa có thể như vậy.`, ref: "AN 4.66", url: "../an/an4.66.html#content" },

{ text: `Ðem đến hại mình, này các Tỷ-kheo, khi lợi dưỡng, cung kính, danh vọng khởi lên cho Devadatta; đem đến bất hạnh cho người, này các Tỷ-kheo, khi lợi dưỡng, cung kính, danh vọng khởi lên cho Devadatta! Ví như, này các Tỷ-kheo, một cây chuối khi sanh ra trái, đem đến hại mình; khi sanh ra trái, đem đến bất hạnh cho người khi sanh ra trái. Cũng vậy, này các Tỷ-kheo, đem đến hại mình khi lợi dưỡng, cung kính, danh vọng khởi lên cho Devadatta, đem đến bất hạnh cho người khi lợi dưỡng, cung kính, danh vọng khởi lên cho Devadatta. Ví như, này các Tỷ-kheo, cây tre đem đến hại mình khi sanh ra trái, đem đến bất hạnh cho người khi sanh ra trái. Cũng vậy, này các Tỷ-kheo, đem đến hại mình khi lợi dưỡng, cung kính, danh vọng khởi lên cho Devadatta.`, ref: "AN 4.68", url: "../an/an4.68.html#content" },


{ text: `Ở đây, này các Tỷ-kheo, bậc Chân nhân là người dầu có được hỏi, không nói lên lời không tán thán người khác; còn nói gì nếu không được hỏi! Nhưng nếu được hỏi, và phải trả lời, dè dặt và ngập ngừng, vị ấy không nói lên lời tán thán người khác. Cần phải được hiểu, này các Tỷ-kheo, vị này là bậc Chân nhân. Lại nữa, này các Tỷ-kheo, bậc Chân nhân là người dầu không được hỏi, cũng nói lên lời tán thán người khác; còn nói gì nếu được hỏi. Nếu được hỏi và phải trả lời, không dè dặt, không ngập ngừng, vị ấy nói lời tán thán người khác, đầy đủ và toàn bộ. Cần phải được hiểu, này các Tỷ-kheo, vị này là bậc Chân nhân.`, ref: "AN 4.73", url: "../an/an4.73.html#content" },

{ text: `Lại nữa, này các Tỷ-kheo, bậc Chân nhân là Người, nếu không được hỏi, vẫn nói lên lời không tán thán về mình; còn nói gì nếu được hỏi! Nếu được hỏi và phải trả lời, không dè dặt, không ngập ngừng, vị ấy nói lên lời không tán thán về mình, đầy đủ và toàn bộ. Cần phải được hiểu, này các Tỷ-kheo, vị này là bậc Chân nhân. Lại nữa, này các Tỷ-kheo, bậc Chân nhân dầu có được hỏi cũng không nói lên lời tán thán về mình; còn nói gì nếu không được hỏi! Nếu được hỏi và phải trả lời, dè dặt và ngập ngừng, vị ấy nói lên lời tán thán về mình, không đầy đủ; không toàn bộ. Cần phải được hiểu, này các Tỷ-kheo, vị này là bậc Chân nhân.`, ref: "AN 4.73", url: "../an/an4.73.html#content" },

{ text: `Ví như, này các Tỷ-kheo, người vợ trẻ, trong đêm hay ngày, được đưa về nhà chồng, nàng cảm thấy hết sức xấu hổ, sợ hãi trước mặt mẹ chồng, cha chồng, trước mặt chồng, cho đến trước mặt các người phục vụ, làm công. Sau một thời gian, do chung sống, do thân mật, nàng có thể nói với mẹ chồng, với cha chồng, với chồng: “Hãy đi đi, các người có biết được gì!”. Cũng vậy, này các Tỷ-kheo, ở đây có Tỷ-kheo, trong đêm hay ngày được xuất gia, từ bỏ gia đình sống không gia đình, cảm thấy hết sức xấu hổ, sợ hãi trước mặt các Tỷ-kheo, Tỷ-kheo-ni, nam cư sĩ, nữ cư sĩ, cho đến trước những người làm vườn và những Sa-di. Sau một thời gian, do chung sống, do thân mật, vị ấy có thể nói với sư A-xà-lê, với sư Giáo thọ: “Hãy đi đi, các người có thể biết được gì!”.`, ref: "AN 4.74", url: "../an/an4.74.html#content" },

{ text: `Có bốn điều này không thể nghĩ đến được, này các Tỷ-kheo, nếu nghĩ đến, thời người suy nghĩ có thể đi đến cuồng loạn và thống khổ. Thế nào là bốn? Phật giới của các đức Phật, này các Tỷ-kheo, không thể nghĩ đến được, nếu nghĩ đến, thời người suy nghĩ có thể đi đến cuồng loạn và thống khổ. Thiền giới của người ngồi Thiền, này các Tỷ-kheo, không thể nghĩ được, nếu nghĩ... thống khổ. Quả dị thục của nghiệp, này các Tỷ-kheo, không thể nghĩ đến được, nếu nghĩ đến... thống khổ. Tâm tư thế giới, này các Tỷ-kheo, không thể nghĩ đến được, nếu nghĩ đến thời có thể đi đến cuồng loạn và thống khổ.`, ref: "AN 4.77", url: "../an/an4.77.html#content" },
{ text: `Ví như, này các Tỷ-kheo, khi khăn bị cháy hay đầu bị cháy, và để dập tắt khăn và đầu, cần phải thực hiện tăng thượng ý muốn, tinh tấn, cố gắng, nỗ lực, tâm không thối chuyển, chánh niệm, tỉnh giác. Cũng vậy, này các Tỷ-kheo, người ấy, để chứng đắc các thiện pháp ấy, cần phải thực hiện tăng thượng ý muốn, tinh tấn, cố gắng, nỗ lực, tâm không thối chuyển, chánh niệm, tỉnh giác. Sau một thời gian, vị ấy thành người có được nội tâm chỉ và tăng thượng tuệ pháp quán. Tại đấy, này các Tỷ-kheo, hạng người này có được nội tâm chỉ, có được tăng thượng tuệ pháp quán, người ấy, này các Tỷ-kheo, sau khi an trú trong các thiện pháp ấy, cần phải chú tâm tu tập hơn nữa để đoạn diệt các lậu hoặc.`, ref: "AN 4.93", url: "../an/an4.93.html#content" },

{ text: `Tại đấy, này các Tỷ-kheo, hạng người này không chứng được nội tâm chỉ, không chứng được tăng thượng tuệ pháp quán. Người này, này các Tỷ-kheo, sau khi đi đến hạng người chứng nội tâm chỉ, chứng được tăng thượng tuệ pháp quán, người này cần phải nói như sau: “Thưa Hiền giả, tâm cần phải an lập thế nào? Tâm cần phải an trú thế nào? Tâm cần phải nhứt tâm thế nào? Tâm cần phải định tĩnh thế nào? Các hành cần phải thấy thế nào? Các hành cần phải biết thế nào? Các hành cần phải quán thế nào?” Người ấy trả lời cho vị này: “Như đã được thấy, như đã được biết, như vậy, này Hiền giả, tâm cần phải an lập; như vậy, tâm cần phải an trú. Như vậy, tâm cần phải nhứt tâm; như vậy, tâm cần phải định tĩnh; như vậy, các hành cần phải thấy; như vậy, các hành cần phải biết; như vậy, các hành cần phải quán”. Vị ấy, sau một thời gian chứng được nội tâm chỉ, chứng được tăng thượng tuệ pháp quán. Vị này, này các Tỷ-kheo, sau khi an trú trong các thiện pháp, cần phải tu tập chú tâm vào sự đoạn diệt các lậu hoặc.`, ref: "AN 4.94", url: "../an/an4.94.html#content" },

{ text: `Trong bốn trường hợp, này các Tỷ-kheo, cần phải không phóng dật. Thế nào là bốn? Hãy từ bỏ thân làm ác, này các Tỷ-kheo, hãy tu tập thân làm lành, và ở đây chớ có phóng dật. Hãy từ bỏ lời nói ác, này các Tỷ-kheo, hãy tu tập lời nói lành, và ở đây chớ có phóng dật. Hãy từ bỏ ý nghĩ ác, này các Tỷ-kheo, hãy tu tập ý nghĩ lành, và ở đây chớ có phóng dật. Hãy từ bỏ tà kiến, này các Tỷ-kheo, hãy tu tập chánh kiến, và ở đây chớ có phóng dật.`, ref: "AN 4.116", url: "../an/an4.116.html#content" },

{ text: `Khi nào, này các Tỷ-kheo, Tỷ-kheo đối với các pháp khiến cho tham đắm, tâm không tham đắm, tự ngã được ly tham; đối với các pháp khiến cho sân hận, tâm không sân hận, tự ngã được ly sân; đối với các pháp khiến cho si mê, tâm không si mê, tự ngã được ly si; đối với các pháp khiến cho say đắm, tâm không say đắm, tự ngã được ly đắm say; thời vị ấy không có sợ hãi, không có dao động, không có hốt hoảng, không rơi vào hoảng sợ, không có đi do nhân các Sa-môn có nói gì.`, ref: "AN 4.117", url: "../an/an4.117.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, có hạng người suy xét: “Nếu thân ta làm ác, lời nói ta ác, ý nghĩa ta ác, thời tự ngã có thể trách ta về phương diện giới: “Sao lại làm nghiệp ấy?”. Người ấy do sợ hãi tự trách, đoạn tận thân làm ác, tu tập thân làm lành, đoạn tận lời nói ác, tu tập lời nói lành, đoạn tận ý nghĩ ác, tu tập ý nghĩ lành; sống tự ngã trong sạch. Này các Tỷ-kheo, đây gọi là sợ hãi tự trách.`, ref: "AN 4.121", url: "../an/an4.121.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, có hạng người suy xét: “Nếu thân ta làm ác, lời nói ta ác, ý nghĩ ta ác, thời các người khác có thể trách ta về phương diện giới: “Sao lại làm nghiệp ấy?”. Người ấy do sợ hãi người khác trách, đoạn tận thân làm ác, tu tập thân làm lành, đoạn tận lời nói ác, tu tập lời nói lành, đoạn tận ý nghĩ ác, tu tập ý nghĩ lành; sống tự ngã trong sạch. Này các Tỷ-kheo, đây gọi là sợ hãi người khác trách.`, ref: "AN 4.121", url: "../an/an4.121.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, có hạng người suy nghĩ như sau: “Với ai thân làm ác, có ác dị thục trong tương lai, với ai lời nói ác ... với ai ý nghĩ ác, có ác dị thục trong tương lai. Làm thế nào cho ta sau khi thân hoại mạng chung, không có sanh tại cõi dữ, ác thú, đọa xứ, địa ngục?”. Người ấy vì sợ hãi ác thú, đoạn tận thân làm ác, tu tập thân làm lành; đoạn tận lời nói ác, tu tập lời nói lành; đoạn tận ý nghĩ ác, tu tập ý nghĩ lành; sống với tự ngã trong sạch. Này các Tỷ-kheo, đây gọi là sợ hãi ác thú.`, ref: "AN 4.121", url: "../an/an4.121.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, có thiện nam tử vì lòng tin xuất gia, từ bỏ gia đình, sống không gia đình. Vị ấy suy nghĩ như sau: “Ta bị sanh, già, chết, sầu, bi, khổ, ưu, não áp bức, bị khổ áp bức, bị khổ chi phối. Tuy vậy, ta mong có thể thấy được sự chấm dứt toàn bộ khổ uẩn này”. Khi được xuất gia như vậy, vị này buổi sáng đắp y, cầm y bát, đi vào làng hay thị trấn để khất thực, không phòng hộ thân, không phòng hộ lời, không phòng hộ tâm, niệm không an trú, các căn không chế ngự. Vị này thấy ở đây những phụ nữ mặc y phục không đoan chánh hay đắp y phục không đoan chánh. Khi thấy những phụ nữ mặc y phục không đoan chánh hay đắp y phục không đoan chánh, ái dục phá hoại tâm của vị ấy. Vị này, tâm bị ái dục phá hoại, từ bỏ học tập, trở về hoàn tục. Này các Tỷ-kheo, đây gọi là vị Tỷ-kheo bị sợ hãi bởi sự sợ hãi về cá dữ, từ bỏ học tập, trở về hoàn tục. Này các Tỷ-kheo, sợ hãi về cá dữ là đồng nghĩa với phụ nữ. Này các Tỷ-kheo, đây gọi là sợ hãi về cá dữ.`, ref: "AN 4.122", url: "../an/an4.122.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, có hạng người ly dục, ly ác pháp, chứng đạt và an trú Thiền thứ nhất. Ở đây, về các pháp thuộc sắc, thuộc thọ, thuộc tưởng, thuộc hành, thuộc thức, vị ấy tùy quán là vô thường, là khổ, là bệnh, là ung nhọt, là mũi tên, là bất hạnh, là bệnh hoạn, là hướng ngoại, là hoại diệt, là trống không, là vô ngã. Vị ấy, sau khi thân hoại mạng chung được sanh cộng trú với chư Thiên ở Tịnh cư Thiên. Sự sanh khởi này, này các Tỷ-kheo, không có chung cùng với các hàng phàm phu.`, ref: "AN 4.124", url: "../an/an4.124.html#content" },

{ text: `Này các Tỷ-kheo, quần chúng ưa thích chấp giữ, thích thú chấp giữ, hoan hỷ chấp giữ, khi pháp không chấp giữ được Như Lai thuyết giảng, họ khéo nghe, lắng tai, chánh trí an trú tâm. Này các Tỷ-kheo, khi Như Lai, bậc A-la-hán, Chánh Ðẳng Giác xuất hiện, đây là sự vi diệu chưa từng có thứ nhất xuất hiện.`, ref: "AN 4.128", url: "../an/an4.128.html#content" },

{ text: `Này các Tỷ-kheo, quần chúng ưa thích kiêu mạn, thích thú kiêu mạn, hoan hỷ kiêu mạn, khi pháp không kiêu mạn được Như Lai thuyết giảng, họ khéo nghe, lắng tai, chánh trí an trú tâm. Này các Tỷ-kheo, khi Như Lai, bậc A-la-hán, Chánh Ðẳng Giác xuất hiện, đây là sự vi diệu chưa từng có thứ hai xuất hiện.`, ref: "AN 4.128", url: "../an/an4.128.html#content" },

{ text: `Này các Tỷ-kheo, quần chúng ưa thích không an tịnh, thích thú không an tịnh, hoan hỷ không an tịnh, khi pháp an tịnh được Như Lai thuyết giảng, họ khéo nghe, lắng tai, chánh trí an trú tâm. Này các Tỷ-kheo, khi Như Lai, bậc A-la-hán, Chánh Ðẳng Giác xuất hiện, đây là sự vi diệu chưa từng có thứ ba xuất hiện.`, ref: "AN 4.128", url: "../an/an4.128.html#content" },

{ text: `Này các Tỷ-kheo, quần chúng đi đến vô minh, trở thành mù quáng, bị trói buộc che đậy, khi Như Lai thuyết pháp nhiếp phục vô minh, họ khéo nghe, lắng tai, chánh trí an trú tâm. Này các Tỷ-kheo, khi Như Lai, bậc A-la-hán, Chánh Ðẳng Giác xuất hiện, đây là sự vi diệu chưa từng có thứ tư xuất hiện.`, ref: "AN 4.128", url: "../an/an4.128.html#content" },

{ text: `Này các Tỷ-kheo, thế nào là thân viễn ly, tâm không viễn ly? Ở đây, này các Tỷ-kheo, các hạng người sống tại các núi non, khóm rừng, các trú xứ xa vắng; vị ấy nghĩ đến dục tầm, nghĩ đến sân tầm, nghĩ đến hại tầm. Như vậy, này các Tỷ-kheo, là hạng người thân viễn ly, nhưng tâm không viễn ly.`, ref: "AN 4.138", url: "../an/an4.138.html#content" },

{ text: `Này các Tỷ-kheo, thế nào là thân không viễn ly, nhưng tâm viễn ly? Ở đây, này các Tỷ-kheo, các hạng người không sống tại các núi non, khóm rừng, các trú xứ xa vắng; vị ấy tại đó nghĩ đến tầm xuất ly, nghĩ đến tầm vô sân, nghĩ đến tầm bất hại. Như vậy, này các Tỷ-kheo, là hạng người thân không viễn ly, nhưng tâm viễn ly.`, ref: "AN 4.138", url: "../an/an4.138.html#content" },

{ text: `Này các Tỷ-kheo, có bốn loại ánh sáng. Thế nào là bốn? Ánh sáng mặt trăng, ánh sáng mặt trời, ánh sáng ngọn lửa, ánh sáng trí tuệ. Này các Tỷ-kheo, có bốn loại ánh sáng này. Và này các Tỷ-kheo, loại tối thượng trong bốn loại ánh sáng là ánh sáng trí tuệ.`, ref: "AN 4.142", url: "../an/an4.142.html#content" },

{ text: `Có bốn thời gian này, này các Tỷ-kheo, nếu khéo tu tập, nếu khéo vận chuyển, tuần tự đưa đến sự đoạn diệt các lậu hoặc. Thế nào là bốn? Nghe pháp đúng thời, đàm luận về pháp đúng thời, chỉ đúng thời, quán đúng thời. Bốn thời gian này, này các Tỷ-kheo, nếu khéo tu tập, khéo vận chuyển, tuần tự đưa đến sự đoạn diệt các lậu hoặc.`, ref: "AN 4.147", url: "../an/an4.147.html#content" },

{ text: `Này các Tỷ-kheo, có hai loại bệnh này. Thế nào là hai? Bệnh về thân và bệnh về tâm. Này các Tỷ-kheo, Ta thấy có chúng sanh tự nhận mình là không thân bệnh được một năm, tự nhận mình là không thân bệnh được hai năm, được ba ... được bốn ... được năm ... được mười ... được hai mươi ... được ba mươi ... được bốn mươi ... tự nhận mình là không thân bệnh được năm mươi năm, tự nhận mình là không thân bệnh được một trăm năm. Các chúng sanh ấy, này các Tỷ-kheo, rất khó tìm được ở đời là những chúng sanh tự nhận mình là không tâm bệnh dầu chỉ trong một khoảnh khắc, trừ những vị đã đoạn trừ các lậu hoặc.`, ref: "AN 4.157", url: "../an/an4.157.html#content" },

{ text: `Này các Tỷ-kheo, có bốn loại bệnh này cho người xuất gia. Thế nào là bốn? Ở đây, này các Tỷ-kheo, người có dục lớn, bực bội tức tối, không tự bằng lòng với các đồ vật như y, đồ ăn khất thực, sàng tọa, dược phẩm trị bệnh. Người ấy vì nhiều dục lớn, bực bội tức tối, không tự bằng lòng với các vật dụng như y, đồ ăn khất thực, sàng tọa, dược phẩm trị bệnh, khởi lên thèm khát, ác dục, muốn được các điều không được tán thán, muốn được các lợi dưỡng, cung kính, danh vọng. Vị ấy nỗ lực, cố gắng, tinh tấn để được các điều không được tán thán, muốn được các lợi dưỡng, cung kính, danh vọng. Vị ấy sau khi tính toán, đi đến các gia đình; sau khi tính toán, ngồi xuống; sau khi tính toán, thuyết pháp; sau khi tính toán, ngưng nín tiểu tiện, đại tiện. Như vậy, này các Tỷ-kheo, là bốn chứng bệnh của người xuất gia.`, ref: "AN 4.157", url: "../an/an4.157.html#content" },

{ text: `Thưa các Hiền giả, Tỷ-kheo hay Tỷ-kheo-ni nào thấy trên tự thân có bốn pháp này, cần phải đi đến kết luận rằng: “Tôi thối đọa khỏi các thiện pháp “. Ðây được Thế Tôn gọi là thối đọa. Thế nào là bốn? Tham ái tăng thịnh, sân tăng thịnh, si tăng thịnh, đối với các vấn đề có mặt, không có mặt, không có tuệ nhãn soi thấu. Thưa các Hiền giả, Tỷ-kheo hay Tỷ-kheo-ni nào thấy trên tự thân có bốn pháp này, cần phải đi đến kết luận rằng: “Tôi thối đọa khỏi các thiện pháp “. Ðây được Thế Tôn gọi là thối đọa.`, ref: "AN 4.158", url: "../an/an4.158.html#content" },
{ text: `Này các Tỷ-kheo, các Trưởng lão Tỷ-kheo là những vị sống đầy đủ, lười biếng, dẫn đầu về đọa lạc, bỏ rơi gánh nặng sống viễn ly, không cố gắng tinh tấn để đạt được những gì chưa đạt được, để chứng đắc những gì chưa chứng đắc, để chứng ngộ những gì chưa chứng ngộ. Và những thế hệ sau tiếp nối theo tà kiến của họ. Thế hệ ấy cũng sống đầy đủ, lười biếng, dẫn đầu về đọa lạc, bỏ rơi gánh nặng sống viễn ly, không cố gắng tinh tấn để đạt được những gì chưa đạt được, để chứng đắc những gì chưa chứng đắc, để chứng ngộ những gì chưa chứng ngộ. Này các Tỷ-kheo, đây là pháp thứ tư đưa đến Diệu pháp hỗn loạn và biến mất.`, ref: "AN 4.160", url: "../an/an4.160.html#content" },

{ text: `Này các Tỷ-kheo, có bốn đạo hành này. Thế nào là bốn? Ðạo hành khổ, thắng trí chậm; Ðạo hành khổ, thắng trí nhanh; Ðạo hành lạc, thắng trí chậm; Ðạo hành lạc, thắng trí nhanh. Này các Tỷ-kheo, cố bốn đạo hành này.`, ref: "AN 4.161", url: "../an/an4.161.html#content" },

{ text: `Này các Tỷ-kheo, thế nào là đạo hành khổ, thắng trí chậm? Ở đây, có người bản tánh tham dục rất cường thịnh, luôn luôn cảm thọ khổ ưu do tham dục sanh; bản tánh sân rất cường thịnh, luôn luôn cảm thọ khổ ưu do sân hận sanh; bản tánh si rất cường thịnh, luôn luôn cảm thọ khổ ưu do si sanh. Với người ấy, năm căn này hiện ra rất mềm yếu, tín căn, tấn căn, niệm căn, định căn, tuệ căn. Do năm căn này mềm yếu, người ấy đạt được Vô gián định một cách chậm chạp để đoạn diệt các lậu hoặc. Này các Tỷ-kheo, đây gọi là đạo hành khổ, thắng trí chậm.`, ref: "AN 4.162", url: "../an/an4.162.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là đạo hành không kham nhẫn? Ở đây, này các Tỷ-kheo, có hạng người chưởi mắng lại kẻ đã chưởi mắng, sân hận lại với kẻ đã sân hận, gây lộn lại với kẻ đã gây lộn. Này các Tỷ-kheo, đây gọi là đạo hành không kham nhẫn.`, ref: "AN 4.164", url: "../an/an4.164.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là đạo hành kham nhẫn? Ở đây, này các Tỷ-kheo, có hạng người không nhiếc mắng lại kẻ đã nhiếc mắng, không sân hận lại kẻ đã sân hận, không gây lộn lại với kẻ đã gây lộn. Này các Tỷ-kheo, đây gọi là đạo hành kham nhẫn.`, ref: "AN 4.164", url: "../an/an4.164.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào là đạo hành nhiếp phục? Ở đây, này các Tỷ-kheo, Tỷ-kheo khi mắt thấy sắc, không nắm giữ tướng chung, không nắm giữ tướng riêng. Phàm do nhân duyên gì với nhãn căn này không được chế ngự, khiến cho tham ái, ưu bi, các ác bất thiện khởi lên, vị ấy chế ngự nguyên nhân ấy, hộ trì nhãn căn, sống với sự chế ngự nhãn căn. Khi tai nghe tiếng ... khi mũi ngửi hương ... khi lưỡi nếm vị ... khi thân cảm xúc ... khi ý biết pháp, không nắm giữ tướng chung, không nắm giữ tướng riêng. Phàm do nhân duyên gì ý căn này không được chế ngự, khiến cho tham ái, ưu bi, các ác bất thiện khởi lên, vị ấy chế ngự nguyên nhân ấy, thọ trì ý căn, sống với sự chế ngự ý căn. Này các Tỷ-kheo, đây gọi là đạo hành nhiếp phục.`, ref: "AN 4.164", url: "../an/an4.164.html#content" },

{ text: `Và này các Tỷ-kheo, thế nào gọi là đạo hành an tịnh? Ở đây, này các Tỷ-kheo, Tỷ-kheo không có chấp nhận dục tầm khởi lên, từ bỏ, tẩy sạch, làm cho an tịnh, chấm dứt, khiến đi đến không sanh hữu, không có chấp nhận sân tầm khởi lên ... không có chấp nhận hại tầm khởi lên ... không có chấp nhận các pháp ác bất thiện tầm khởi lên, từ bỏ, tẩy sạch, làm cho an tịnh, chấm dứt, khiến đi đến không sanh hữu. Này các Tỷ-kheo, đây gọi là đạo hành an tịnh.`, ref: "AN 4.164", url: "../an/an4.164.html#content" },

{ text: `Ở đây, này chư Hiền, Tỷ-kheo tu tập quán, có chỉ đi trước; do vị ấy tu tập quán có chỉ đi trước, con đường được sanh khởi. Vị ấy thực hành con đường ấy, tu tập, làm cho sung mãn. Do vị ấy thực hành con đường ấy, tu tập, làm cho sung mãn, các kiết sử được đoạn tận, các tùy miên được chấm dứt.`, ref: "AN 4.170", url: "../an/an4.170.html#content" },

{ text: `Ở đây, này chư Hiền, vị Tỷ-kheo tu tập chỉ, có quán đi trước. Do vị ấy tu tập chỉ có quán đi trước, con đường được sanh khởi. Vị ấy thực hành con đường ấy, tu tập, làm cho sung mãn. Do vị ấy thực hành con đường ấy, tu tập, làm cho sung mãn, các kiết sử được đoạn tận, các tùy miên được chấm dứt.`, ref: "AN 4.170", url: "../an/an4.170.html#content" },

{ text: `Ở đây, này chư Hiền, Tỷ-kheo tu tập cả hai chỉ quán gắn liền với nhau. Do vị ấy tu tập cả hai chỉ quán gắn liền với nhau, con đường được sanh khởi. Vị ấy thực hành con đường ấy, tu tập, làm cho sung mãn. Do vị ấy thực hành con đường ấy, tu tập, làm cho sung mãn, các kiết sử được đoạn tận, các tùy miên được chấm dứt.`, ref: "AN 4.170", url: "../an/an4.170.html#content" },

{ text: `Ở đây, này chư Hiền, Tỷ-kheo với các dao động đối với các pháp được hoàn toàn dứt sạch. Này các Hiền giả, đây là thời khi tâm của vị ấy an trú, an tọa, nhất tâm, định tĩnh. Với vị ấy, con đường sanh khởi. Vị ấy thực hành con đường ấy, tu tập, làm cho sung mãn. Do vị ấy thực hành con đường ấy, tu tập, làm cho sung mãn, các kiết sử được đoạn tận, các tùy miên được chấm dứt.`, ref: "AN 4.170", url: "../an/an4.170.html#content" },

{ text: `Này các Tỷ-kheo, Tỷ-kheo có lòng tin, nếu chơn chánh mong cầu, hãy mong cầu như sau: “Mong ta sẽ được như Sàriputta, Moggallàna”. Này các Tỷ-kheo, họ là cán cân, là đồ để đo lường các đệ tử Tỷ-kheo của ta, tức là Sàriputta, Moggallàna.`, ref: "AN 4.176", url: "../an/an4.176.html#content" },

{ text: `Này Ràhula, phàm có nội địa giới gì, phàm có ngoại địa giới gì, đều là địa giới này... phàm có nội thủy giới gì, phàm có ngoại thủy giới gì, đều là thủy giới này...., phàm có nội hỏa giới gì, phàm có ngoại hỏa giới gì, đều là hỏa giới này...., phàm có nội phong giới gì, phàm có ngoại phong giới gì, đều là phong giới này. Cần phải như thật thấy phong giới ấy với chánh trí tuệ rằng: “Cái này không phải của tôi, cái này không phải là tôi, cái này không phải là tự ngã của tôi”. Do thấy như thật (phong giới) này với chánh trí tuệ, vị ấy nhàm chán phong giới. Với trí tuệ, vị ấy tẩy sạch tâm.`, ref: "AN 4.177", url: "../an/an4.177.html#content" },

{ text: `Khi nào, này Ràhula, Tỷ-kheo đối với bốn giới này, không có tùy quán là tự ngã hay thuộc ngã sở, này Ràhula, vị này được gọi là Tỷ-kheo đã cắt dứt ái, đã giải tỏa các kiết sử, đã chơn chánh minh quán kiêu mạn, đã chấm dứt khổ đau.`, ref: "AN 4.177", url: "../an/an4.177.html#content" },

{ text: `Ở đây, này Hiền giả Ananda, chúng sanh không có như thật quán tri: “Các tưởng này dự phần vào thối đọa”, không có như thật quán tri: “Các tưởng này dự phần vào an trú”, không có như thật quán tri: “Các tưởng này dự phần vào thù thắng”, không có như thật quán tri: “Các tưởng này dự phần vào thể nhập”. Này Hiền giả Ananda, đây là nhân, đây là duyên, do vậy ở đây có hạng chúng sanh ngay trong hiện tại, không chứng nhập Niết-bàn.`, ref: "AN 4.179", url: "../an/an4.179.html#content" },

{ text: `Này Bà-la-môn, phàm nói lên điều thấy gì, các pháp bất thiện tăng trưởng, các pháp thiện tổn giảm, Ta nói rằng điều thấy như vậy không nên nói ra. Và này Bà-la-môn, phàm nói lên điều thấy gì, các pháp bất thiện tổn giảm, các pháp thiện tăng trưởng, Ta nói rằng điều thấy như vậy nên nói ra. Này Bà-la-môn, phàm nói ra điều nghe gì ... phàm nói ra điều cảm giác gì ... phàm nói ra điều thức tri gì ... các pháp bất thiện tăng trưởng, các pháp thiện tổn giảm, Ta nói rằng điều thức tri như vậy không nên nói ra. Và này Bà-la-môn, phàm nói ra điều thức tri gì, các pháp bất thiện tổn giảm, các pháp thiện tăng trưởng, Ta nói rằng điều thức tri như vậy nên nói ra.`, ref: "AN 4.183", url: "../an/an4.183.html#content" },

{ text: `Ở đây, này Bà-la-môn, có người không ly tham đối với các dục, không ly ham muốn, không ly luyến ái, không ly khát ái, không ly nhiệt não, không ly tham ái. Rồi một chứng bệnh trầm trọng khởi lên cho người ấy. Người ấy bị cảm thọ chứng bệnh trầm trọng ấy, suy nghĩ như sau: “Thật sự các dục khả ái sẽ bỏ ta”, hay “Ta sẽ từ bỏ các dục khả ái”. Người ấy sầu muộn, than vãn, khóc lóc, đập ngực, rơi vào bất tỉnh. Này Bà-la-môn, đây là người bản tánh bị chết, sợ hãi, rơi vào run sợ khi nghĩ đến chết.`, ref: "AN 4.184", url: "../an/an4.184.html#content" },

{ text: `Lại nữa, này Bà-la-môn, ở đây có người không ly tham đối với thân ... Rồi một chứng bệnh trầm trọng khởi lên cho người ấy. Người ấy bị cảm thọ bởi chứng bệnh trầm trọng ấy, suy nghĩ như sau: “Thật sự thân khả ái sẽ bỏ ta”, hay “Ta sẽ từ bỏ thân khả ái”. Người ấy sầu muộn, than vãn, khóc lóc, đập ngực, rơi vào bất tỉnh. Này Bà-la-môn, đây là người bản tánh bị chết, sợ hãi, rơi vào run sợ khi nghĩ đến chết.`, ref: "AN 4.184", url: "../an/an4.184.html#content" },

{ text: `Lại nữa, này Bà-la-môn, ở đây có hạng người không làm điều lành, không làm điều thiện, không che chở kẻ sợ hãi, làm điều ác, làm điều hung bạo, làm điều phạm pháp. Rồi một chứng bệnh trầm trọng khởi lên cho người ấy. Người ấy bị cảm thọ bởi chứng bệnh trầm trọng ấy, suy nghĩ như sau: “Thật sự ta không làm điều lành, không làm điều thiện, không che chở kẻ sợ hãi, làm điều ác, làm điều hung bạo, làm điều phạm pháp”. Tại sanh thú nào mà những người không làm điều lành, không làm điều thiện, không che chở kẻ sợ hãi, làm điều ác, làm điều hung bạo, làm điều phạm pháp, đi đến sau khi chết, ta đi đến sanh thú ấy. Người ấy sầu muộn, than vãn, khóc lóc, đập ngực, rơi vào bất tỉnh. Này Bà-la-môn, đây là người bản tánh bị chết, sợ hãi, rơi vào run sợ khi nghĩ đến chết`, ref: "AN 4.184", url: "../an/an4.184.html#content" },

{ text: `Ở đây, này các du sĩ, Bà-la-môn nói như sau: “Tất cả loài hữu tình không đáng bị sát hại”. Người Bà-la-môn nói như vậy là nói sự thật, không nói láo. Do vậy, vị ấy không nghĩ đến “Sa-môn”, không nghĩ đến “Bà-la-môn”, không nghĩ đến: “Ta hơn (các người khác)”, không nghĩ đến: “Ta bằng (các người khác)”, không nghĩ đến: “Ta là hạ liệt”. Lại nữa do thắng tri sự thật hàm chứa ở đấy, người ấy thực hành lòng thương tưởng, lòng từ mẫn đối với các loài hữu tình.`, ref: "AN 4.185", url: "../an/an4.185.html#content" },

{ text: `Lại nữa, này các du sĩ, Bà-la-môn nói như sau: “Mọi dục là vô thường, khổ, chịu sự biến hoại”. Người Bà-la-môn nói như vậy là nói sự thật, không nói láo. Do vậy, vị ấy không nghĩ đến “Sa-môn”, không nghĩ đến “Bà-la-môn”, không nghĩ đến: “Ta hơn (các người khác)”, không nghĩ đến: “Ta bằng (các người khác)”, không nghĩ đến: “Ta là hạ liệt”. Lại nữa do thắng tri sự thật hàm chứa ở đấy, (trong lời nói ấy), người ấy thực hành nhàm chán, ly tham, đoạn diệt đối với các dục.`, ref: "AN 4.185", url: "../an/an4.185.html#content" },

{ text: `Lại nữa, này các du sĩ, Bà-la-môn nói như sau: “Tất cả các sanh hữu là vô thường, khổ, chịu sự biến hoại”. Người Bà-la-môn nói như vậy là nói sự thật, không nói láo. Do vậy, vị ấy không nghĩ đến “Sa-môn”, không nghĩ đến “Bà-la-môn”, không nghĩ đến: “Ta hơn (các người khác)”, không nghĩ đến: “Ta bằng (các người khác)”, không nghĩ đến: “Ta là hạ liệt”. Lại nữa do thắng tri sự thật hàm chứa ở đấy, người ấy thực hiện nhàm chán, ly tham, đoạn diệt đối với các sanh hữu.`, ref: "AN 4.185", url: "../an/an4.185.html#content" },

{ text: `Lại nữa, này các du sĩ, người Bà-la-môn nói như sau: “Ta không là bất cứ ai, bất cứ thuộc ai, bất cứ là gì. Trong ấy, không có cái gì được gọi là của ta, bất cứ ở đâu, bất cứ là gì”. Người Bà-la-môn nói như vậy là nói sự thật, không nói láo. Do vậy, vị ấy không nghĩ đến “Sa-môn”, không nghĩ đến “Bà-la-môn”, không nghĩ đến: “Ta hơn (các người khác)”, không nghĩ đến: “Ta bằng (các người khác)”, không nghĩ đến: “Ta là hạ liệt”. Lại nữa do thắng tri sự thật hàm chứa ở đấy, (trong lời nói ấy) người ấy thực hành con đường không có sự vật gì.`, ref: "AN 4.185", url: "../an/an4.185.html#content" },

{ text: `Ở đây, này Tỷ-kheo, Bậc Hiền trí, Ðại tuệ, không có nghĩ tự làm hại mình, không có nghĩ tự làm hại người, không có nghĩ tự mình làm hại cả hai, có suy nghĩ điều gì thời suy nghĩ lợi mình, lợi người, lợi cả hai, lợi toàn thể thế giới. Như vậy, này Tỷ-kheo, là Bậc Hiền trí, Ðại tuệ.`, ref: "AN 4.186", url: "../an/an4.186.html#content" },

{ text: `Này Tỳ-kheo, chính bởi Tâm mà thế giới bị dẫn dắt; chính bởi Tâm mà thế giới bị lôi kéo; và thế giới đi theo sự làm chủ của Tâm khi nó đã khởi lên.`, ref: "AN 4.186", url: "../an/an4.186.html#content" },

{ text: `Ở đây, này Mallikà, có hạng nữ nhân phẫn nộ, não hại nhiều, tuy bị ít nói, liền nổi nóng, nổi giận, nổi sân, sừng sộ, gây hấn, biểu lộ phẫn nộ, sân hận, bất mãn. Người này không bố thí cho Sa-môn, Bà-la-môn món ăn vật uống, vải mặc, xe cộ, vòng hoa, hương, phấn sáp, giường nằm, trú xứ, đèn đuốc; tánh tình keo kiệt; thấy người khác được lợi dưỡng, cung kính, tôn trọng, tôn kính, đảnh lễ, cúng dường, thì ganh tỵ, tức tối, trói buộc bởi ganh tỵ. Người ấy, sau khi từ bỏ đời này, trở lui lại trạng thái này, tại đấy, tại đấy, tái sanh hạ liệt, dung sắc xấu, sắc đẹp xấu, hình dáng hạ liệt, nghèo khổ, tài sản ít, sở hữu ít, ảnh hưởng uy tín ít.`, ref: "AN 4.197", url: "../an/an4.197.html#content" },

{ text: `Ở đây, này Mallikà, có hạng nữ nhân không phẫn nộ, não hại không nhiều, tuy bị nói nhiều, không có nổi nóng, không có nổi giận, không nổi sân, không sừng sộ, không gây hấn, không biểu lộ phẫn nộ, không sân hận, không bất mãn. Người này bố thí cho Sa-môn, Bà-la-môn món ăn vật uống, vải mặc, xe cộ, vòng hoa, hương, phấn sáp, giường nằm, trú xứ, đèn đuốc; tánh tình không keo kiệt; thấy người khác được lợi dưỡng, cung kính, tôn trọng, tôn kính, đảnh lễ, cúng dường, không ganh tỵ, tức tối, trói buộc bởi ganh tỵ. Người ấy, sau khi từ bỏ đời này, trở lui lại trạng thái này, tại đấy, tái sanh dung sắc đẹp, sắc đẹp tốt, tịnh tín, thành tựu với dung sắc thù thắng, giàu sang, tài sản lớn, sở hữu lớn, uy tín ảnh hưởng lớn.`, ref: "AN 4.197", url: "../an/an4.197.html#content" },

{ text: `Ái, này các Tỷ-kheo, là lưới triền khiến cho lưu chuyển luân hồi được rộng ra, bám dính vào; chính do ái ấy, thế giới này bị hoại vong, trói buộc, rối loạn như một cuộn chỉ, rối ren như một ổ kén, quyện lại như cỏ mujia và lau sậy babbaja, không thể nào ra khỏi khổ xứ, ác thú, đọa xứ, sanh tử.`, ref: "AN 4.199", url: "../an/an4.199.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, có người tự mình đầy đủ lòng tin, còn khích lệ người khác có đầy đủ lòng tin; tự mình có xấu hổ và khích lệ người khác có xấu hổ; tự mình có sợ tội lỗi và khích lệ người khác có sợ tội lỗi; tự mình nghe nhiều và khích lệ người khác nghe nhiều; tự mình siêng năng tinh cần và khích lệ người khác siêng năng tinh cần; tự mình chánh niệm và khích lệ người khác chánh niệm; tự mình có trí tuệ và khích lệ người khác có trí tuệ. Người này, này các Tỷ-kheo, được gọi là gọi là bậc Chân nhân còn hơn cả bậc Chân nhân.`, ref: "AN 4.202", url: "../an/an4.202.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, có người tự mình từ bỏ sát sanh, còn khích lệ người khác từ bỏ sát sanh; tự mình từ bỏ lấy của không cho và khích lệ người khác từ bỏ lấy của không cho; tự mình từ bỏ tà hạnh trong các dục và khích lệ người khác từ bỏ tà hạnh trong các dục; tự mình từ bỏ nói láo và khích lệ người khác từ bỏ nói láo; tự mình từ bỏ nói hai lưỡi và khích lệ người khác từ bỏ nói hai lưỡi; tự mình từ bỏ nói lời thô ác và khích lệ người khác từ bỏ nói lời thô ác; tự mình từ bỏ nói lời phù phiếm và khích lệ người khác từ bỏ nói lời phù phiếm. Này các Tỷ-kheo, đây gọi là gọi là bậc Chân nhân còn hơn cả bậc Chân nhân.`, ref: "AN 4.203", url: "../an/an4.203.html#content" },

{ text: `Thành tựu với bốn pháp này, này các Tỷ-kheo, như vậy tương xứng bị rơi vào địa ngục. Thế nào là bốn? Thành tựu với thân làm ác, với lời nói ác, với ý nghĩ ác, với không biết ơn, không biết trả ơn. Thành tựu với bốn pháp này, này các Tỷ-kheo, như vậy tương xứng bị rơi vào địa ngục.\nThành tựu với bốn pháp này, này các Tỷ-kheo, như vậy tương xứng được sanh lên cõi Trời. Thế nào là bốn? Thành tựu với thân làm thiện, với lời nói thiện, với ý nghĩ thiện, biết ơn, biết trả ơn. Thành tựu với bốn pháp này, này các Tỷ-kheo, như vậy tương xứng được sanh lên cõi Trời.`, ref: "AN 4.213", url: "../an/an4.213.html#content" },

{ text: `Ở đây, này Ananda, kẻ ác Tỷ-kheo, do theo ác giới, theo ác pháp không trong sạch, sở hành đáng nghi ngờ, có hành động che giấu, không phải Sa-môn nhưng tự xưng là Sa-môn, không hành Phạm hạnh nhưng tự xưng là hành Phạm hạnh, nội tâm mục nát, đầy ứ dục vọng, một đống rác dơ bẩn. Vị ấy nghĩ như sau: “Nếu các Tỷ-kheo sẽ biết Ta là ác giới, theo ác pháp, không thanh tịnh ... một đống rác dơ bẩn; nếu họ hòa hợp, họ sẽ làm hại ta; nếu họ chia rẽ, họ sẽ không làm hại được ta”. Này Ananda, do thấy lợi ích thứ nhất này, ác Tỷ-kheo thích thú với phá hòa hợp Tăng.`, ref: "AN 4.243", url: "../an/an4.243.html#content" },

{ text: `Lại nữa, này Ananda, ác Tỷ-kheo có tà mạng, nuôi sống mình với tà mạng. Vị ấy suy nghĩ như sau: “Nếu các Tỷ-kheo sẽ biết Ta có tà mạng, nuôi sống mình với tà mạng; nếu họ hòa hợp, họ sẽ làm hại ta; nếu họ chia rẽ, họ sẽ không làm hại được ta”. Này Ananda, do thấy lợi ích thứ ba này, ác Tỷ-kheo thích thú với phá hòa hợp Tăng.`, ref: "AN 4.243", url: "../an/an4.243.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, các học pháp thắng hạnh được Ta đặt cho các đệ tử, để những ai ít lòng tin phát khởi lòng tin. Vì rằng, này các Tỷ-kheo, các học pháp thắng hạnh được Ta chế đặt cho các đệ tử, để những ai ít lòng tin phát khởi lòng tin, để những ai có lòng tin, được tăng trưởng lòng tin. Do vậy, một đệ tử sau khi chấp nhận và học tập trong các học pháp, đối với học pháp ấy là người sở hành không bị bể vụn, sở hành không cắt xén, sở hành không bị vết nhơ, sở hành không bị chấm đen. Như vậy, này các Tỷ-kheo, là lợi ích của học tập.`, ref: "AN 4.245", url: "../an/an4.245.html#content" },

{ text: `Lại nữa, này các Tỷ-kheo, các học pháp sở hành Phạm hạnh được Ta đặt cho các đệ tử, để chơn chánh đoạn diệt đau khổ một cách hoàn toàn. Vì rằng, này các Tỷ-kheo, các học pháp sở hành Phạm hạnh được Ta chế đặt cho các đệ tử, để chơn chánh đoạn diệt đau khổ một cách hoàn toàn. Do vậy, một đệ tử sau khi chấp nhận và học tập trong các học pháp, đối với học pháp ấy là người sở hành không bị bể vụn, sở hành không cắt xén, sở hành không bị vết nhơ, sở hành không bị chấm đen. Như vậy, này các Tỷ-kheo, là lợi ích của học tập.`, ref: "AN 4.245", url: "../an/an4.245.html#content" },

{ text: `Này các Tỷ-kheo, có bốn pháp phi Thánh cầu này. Thế nào là bốn? Ở đây, này các Tỷ-kheo, có người tự mình bị già, tầm cầu cái bị già; tự mình bị bệnh, tầm cầu cái bị bệnh; tự mình bị chết, tầm cầu cái bị chết; tự mình bị uế nhiễm, tầm cầu cái bị uế nhiễm. Này các Tỷ-kheo, có bốn pháp phi Thánh cầu này.`, ref: "AN 4.255", url: "../an/an4.255.html#content" },

{ text: `Này các Tỷ-kheo, có bốn pháp Thánh cầu này. Thế nào là bốn? Ở đây, này các Tỷ-kheo, có người tự mình bị già, sau khi biết sự nguy hại của bị già, tầm cầu cái không bị già, vô thượng an ổn khỏi các khổ ách, Niết-bàn; tự mình bị bệnh, sau khi biết sự nguy hại của bị bệnh, tầm cầu cái không bệnh, vô thượng an ổn khỏi các khổ ách, Niết-bàn; tự mình bị chết, sau khi biết sự nguy hại của bị chết, tầm cầu cái không chết, vô thượng an ổn khỏi các khổ ách, Niết-bàn; tự mình uế nhiễm, sau khi biết sự nguy hại của uế nhiễm, tầm cầu cái không bị uế nhiễm, vô thượng an ổn khỏi các khổ ách, Niết-bàn. Này các Tỷ-kheo, có bốn pháp Thánh cầu này.`, ref: "AN 4.255", url: "../an/an4.255.html#content" },

{ text: `Phàm những gia đình nào, này các Tỷ-kheo, đạt đến sự lớn mạnh trong các tài sản, được tồn tại lâu dài; tất cả đều do bốn sự kiện ấy hay là một trong những sự kiện này. Thế nào là bốn? Tìm những gì đã mất; sửa lại cái gì đã già yếu; ăn và uống không quá độ; đặt nữ nhân, nam nhân có giới trong địa vị tối thắng. Phàm những gia đình nào, này các Tỷ-kheo, đạt đến sự lớn mạnh trong các tài sản, được tồn tại lâu dài; tất cả đều do bốn sự kiện ấy hay là một trong những sự kiện này.`, ref: "AN 4.258", url: "../an/an4.258.html#content" },

{ text: `Thành tựu năm pháp này, này các Tỷ-kheo, Tỷ-kheo ngay trong hiện tại sống đau khổ, với tổn não, với ưu não, với nhiệt não, sau khi thân hoại mạng chung, được chờ đợi là ác thú. Thế nào là năm? Ở đây, này các Tỷ-kheo, Tỷ-kheo không có lòng tin, không có lòng hổ thẹn, không có lòng sợ hãi, biếng nhác, ác tuệ. Thành tựu với năm pháp này, này các Tỷ-kheo, ngay trong hiện tại sống đau khổ, với tổn não, với ưu não, với nhiệt não; sau khi thân hoại mạng chung, được chờ đợi là ác thú.`, ref: "AN 5.3", url: "../an/an5.3.html#content" },

{ text: `Thành tựu năm pháp này, này các Tỷ-kheo, Tỷ-kheo ngay trong hiện tại sống an lạc, không có tổn não, không ưu não, không có nhiệt não; sau khi thân hoại mạng chung, được chờ đợi là cõi lành. Thế nào là năm? Ở đây, này các Tỷ-kheo, Tỷ-kheo có lòng tin, có lòng hổ thẹn, có lòng sợ hãi, tinh cần tinh tấn, có trí tuệ. Thành tựu năm pháp này, này các Tỷ-kheo, Tỷ-kheo ngay trong hiện tại sống an lạc, không có tổn não, không có ưu não, không có nhiệt não; sau khi thân hoại mạng chung, được chờ đợi là cõi lành.`, ref: "AN 5.3", url: "../an/an5.3.html#content" },
{ text: `Không có sự bước vào bất thiện, này các Tỷ-kheo, cho đến khi nào có lòng hổ thẹn... lòng sợ hãi... tinh tấn... trí tuệ an trú vào các thiện pháp. Khi nào lòng hổ thẹn... lòng sợ hãi... tinh tấn... trí tuệ biến mất, này các Tỷ-kheo, không xấu hổ... không sợ hãi... biếng nhác... ác tuệ khởi lên và tồn tại, thời có sự bước vào bất thiện.`, ref: "AN 5.6", url: "../an/an5.6.html#content" },


{ text: `Này các Tỷ-kheo, cho đến khi nào vị Tỷ-kheo chưa gây được lòng tin đối với các thiện pháp, chưa gây được lòng hổ thẹn đối với các bất thiện pháp, chưa gây được lòng sợ hãi đối với các bất thiện pháp, chưa gây được tinh tấn đối với các thiện pháp; chưa gây được trí tuệ đối với các thiện pháp, cho đến khi ấy, này các Tỷ-kheo, Ta cần phải phòng hộ Tỷ-kheo ấy. Khi nào, này các Tỷ-kheo, Tỷ-kheo gây được lòng tin đối với các thiện pháp, gây được lòng hổ thẹn đối với các bất thiện pháp, gây được lòng sợ hãi đối với các bất thiện pháp, gây được lòng tinh tấn đối với các thiện pháp; gây được trí tuệ đối với các thiện pháp, thời khi ấy, này các Tỷ-kheo, Ta không còn săn sóc Tỷ-kheo ấy, nghĩ rằng: “Nay Tỷ-kheo ấy đã biết tự bảo vệ mình, không còn phóng dật nữa”.`, ref: "AN 5.7", url: "../an/an5.7.html#content" },

{ text: `Phần lớn, này các Tỷ-kheo, các loại hữu tình tìm được lạc thú trong các dục. Với thiện nam tử, này các Tỷ-kheo, đã bỏ một bên lưỡi liềm và đòn gánh, xuất gia, từ bỏ gia đình, sống không gia đình, vị ấy vừa đủ để được gọi: “Vị thiện nam tử vì lòng tin xuất gia”. Vì cớ sao?\nCác dục, này các Tỷ-kheo, được tìm thấy với tuổi trẻ, các dục này hay các dục khác. Và này các Tỷ-kheo, các dục hạ liệt, các dục trung đẳng, và các dục tối thắng, tất cả dục đều được chấp nhận là các dục.`, ref: "AN 5.7", url: "../an/an5.7.html#content" },

{ text: `Tỷ-kheo, này các Tỷ-kheo, không cung kính, không thận trọng, không sống tương hòa với các vị đồng Phạm hạnh, sẽ làm cho viên mãn thắng hạnh pháp, sự kiện này không xảy ra. Sau khi không làm cho viên mãn thắng hạnh pháp, vị ấy sẽ làm cho viên mãn hữu học pháp, sự kiện này không xảy ra. Không làm cho viên mãn hữu học pháp, vị ấy sẽ làm cho viên mãn các giới luật, sự kiện này không xảy ra. Sau khi không làm cho viên mãn các giới luật, vị ấy sẽ làm cho viên mãn chánh tri kiến, sự kiện này không xảy ra. Sau khi không làm cho viên mãn chánh tri kiến, vị ấy sẽ làm cho viên mãn chánh định, sự kiện này không xảy ra.`, ref: "AN 5.21", url: "../an/an5.21.html#content" },

{ text: `Tỷ-kheo, này các Tỷ-kheo, có cung kính, có thận trọng, sống tương hòa với các vị đồng Phạm hạnh sẽ làm cho viên mãn thắng hạnh pháp, sự kiện này có xảy ra. Sau khi làm cho viên mãn thắng hạnh pháp, vị ấy sẽ làm cho viên mãn hữu học pháp, sự kiện này có xảy ra. Sau khi làm cho viên mãn hữu học pháp, vị ấy sẽ làm cho viên mãn các giới luật, sự kiện này có xảy ra. Sau khi làm cho viên mãn các giới luật, vị ấy sẽ làm cho viên mãn chánh tri kiến, sự kiện này có xảy ra. Sau khi làm cho viên mãn chánh tri kiến, vị ấy sẽ làm cho viên mãn chánh định, sự kiện này có xảy ra.`, ref: "AN 5.21", url: "../an/an5.21.html#content" },

{ text: `Này các Tỷ-kheo, có năm uế nhiễm này của tâm, do các uế nhiễm ấy, tâm bị uế nhiễm, không nhu nhuyến, không dễ sử dụng, không sáng chói, bị bể vụn, không chơn chánh định tĩnh để đoạn diệt các lậu hoặc. Thế nào là năm? Tham dục, sân, hôn trầm thụy miên, trạo hối, nghi. Có năm uế nhiễm này của tâm, này các Tỷ-kheo, do năm uế nhiễm ấy, tâm bị uế nhiễm không được nhu nhuyến, không dễ sử dụng, không sáng chói, bị bể vụn, không chơn chánh, định tĩnh để đoạn diệt các lậu hoặc.`, ref: "AN 5.23", url: "../an/an5.23.html#content" },

{ text: `Và khi nào, này các Tỷ-kheo, tâm được giải thoát khỏi năm uế nhiễm này: tham dục, sân, hôn trầm thụy miên, trạo hối, nghi. Khi ấy tâm ấy được nhu nhuyến, dễ sử dụng, sáng chói, không bể vụn, chơn chánh định tĩnh để đoạn diệt các lậu hoặc. Tùy thuộc theo pháp gì cần phải được giác ngộ với thắng trí, tâm vị ấy hướng đến để được giác ngộ với thắng trí. Tại đây, tại đấy vị ấy có khả năng, có năng lực đạt đến pháp ấy, dầu thuộc loại xứ nào.`, ref: "AN 5.23", url: "../an/an5.23.html#content" },

{ text: `Ví như, này các Tỷ-kheo, một cây, với cành và lá bị phá hoại, thời đọt cây ấy không đi đến viên mãn, vỏ cây không đi đến viên mãn, giác cây không đi đến viên mãn, lõi cây không đi đến viên mãn. Cũng vậy, này các Tỷ-kheo, với người ác giới, với người phá giới, chánh định do vậy bị phá hoại. Khi chánh định không có mặt, với người chánh định bị phá hoại, như thật tri kiến nhân do vậy bị phá hoại. Khi như thật tri kiến không có mặt, với người như thật tri kiến bị phá hoại, nhàm chán, ly tham do vậy bị phá hoại. Khi nhàm chán, ly tham không có mặt, với người nhàm chán ly tham bị phá hoại, giải thoát tri kiến do vậy bị phá hoại.`, ref: "AN 5.24", url: "../an/an5.24.html#content" },

{ text: `Ví như, này các Tỷ-kheo, một cây, với cành và lá được đầy đủ, thời đọt cây ấy đi đến viên mãn, vỏ cây đi đến viên mãn, giác cây đi đến viên mãn, lõi cây đi đến viên mãn. Cũng vậy, này các Tỷ-kheo, với người có giới, với người giữ gìn giới, chánh định nhân vậy được đầy đủ. Do chánh định có mặt, với người chánh định được thành tựu, như thật tri kiến do vậy được thành tựu. Do như thật tri kiến có mặt, với người như thật tri kiến được thành tựu, nhàm chán, ly tham do vậy được thành tựu. Do nhàm chán, ly tham có mặt, với người nhàm chán, ly tham được thành tựu, giải thoát tri kiến do vậy được thành tựu.`, ref: "AN 5.24", url: "../an/an5.24.html#content" },

{ text: `Này các Tỷ-kheo, thông minh, thường niệm, hãy tu tập vô lượng định. Với ai thông minh, thường niệm, tu tập vô lượng định, tự mỗi người ấy khởi lên năm trí. Thế nào là năm? Ðịnh này hiện tại lạc và tương lai có quả dị thục lạc, trong mỗi người, trí (như vậy) khởi lên. Ðịnh này thuộc bậc Thánh, không thuộc vật chất, trong mỗi người, trí (như vậy) khởi lên. Ðịnh này không do người ác thực hiện, trong mỗi người, trí (như vậy) khởi lên. Ðịnh này an tịnh, thù diệu, đem đến khinh an, đạt được nhất tâm, không phải là sự chế ngự gò ép thường xuyên, trong mỗi người, trí (như vậy) khởi lên: “An tịnh, ta nhập định này. An tịnh, ta xuất khỏi định này”, trong mỗi người trí (như vậy) khởi lên.`, ref: "AN 5.27", url: "../an/an5.27.html#content" },

{ text: `Này các Tỷ-kheo, có năm lợi ích này của kinh hành. Thế nào là năm? Kham nhẫn được đường trường; kham nhẫn được tinh cần; ít bệnh tật; đưa đến tiêu hóa tốt đẹp các đồ được ăn, được uống, được nhai, được nếm; định chứng được trong khi kinh hành được tồn tại lâu dài. Những pháp này, này các Tỷ-kheo là năm lợi ích của kinh hành.`, ref: "AN 5.29", url: "../an/an5.29.html#content" },


{ text: `—Này Nàgita, những ai đã đến, và làm ồn ào như những hàng cá với đống cá lớn?\n—Các người ấy, bạch Thế Tôn, là các Ba-la-môn gia chủ ở Icchànangalam, đang đứng ở ngoài cổng vào, đem theo rất nhiều đồ ăn loại cứng và loại mềm cho Thế Tôn và chúng Tăng.\n—Này Nàgita, Ta không có liên hệ gì với danh vọng và danh vọng không có liên hệ gì với Ta. Này Nàgita, những ai tìm được không có khó khăn, tìm được không có mệt nhọc, tìm được không có phí sức, tìm được an ổn lạc, viễn ly lạc, an tịnh lạc, chánh giác lạc, mà Ta đã tìm được không có khó khăn, tìm được không có mệt nhọc, tìm được không có phí sức. Hãy để họ thọ hưởng lạc như phân ấy, thụy miên lạc, lợi dưỡng, cung kính, danh văn lạc.`, ref: "AN 5.30", url: "../an/an5.30.html#content" },

{ text: `Này Nàgita, với những ai nặng nề về ái lạc, này Nàgita, sự biến hoại, đổi khác, sầu bi khổ ưu não khởi lên. Ðấy là kết quả tất nhiên cho người ấy. Những ai chuyên chú tâm về tướng bất tịnh, này Nàgita, thời sự nhàm chán đối với tịnh tướng được an trú. Ðấy là kết quả tất nhiên cho người ấy. Ai sống tùy quán vô thường trong sáu xúc xứ, này Nàgita, thời sự nhàm chán đối với xúc được an trú. Ðấy là kết quả tất nhiên cho người ấy. Ai sống tùy quán sanh diệt đối với năm thủ uẩn, này Nàgita, thời sự nhàm chán đối với chấp thủ được an trú. Ðấy là kết quả tất nhiên cho người ấy.`, ref: "AN 5.30", url: "../an/an5.30.html#content" },

{ text: `Người có bố thí, này Sumanà, khi được làm người, vượt qua vị làm người không bố thí trên năm phương diện: Về nhân thọ mạng, về nhân sắc, về nhân lạc, về nhân danh xưng, về nhân tăng thượng. Người có bố thí, này Sumanà, khi được làm người, vượt qua vị làm người không bố thí trên năm phương diện này. Sự việc là như vậy, này Sumanà, là vừa đủ để bố thí, là vừa đủ để làm các công đức. Chúng là những giúp ích, những công đức cho chư Thiên. Chúng là những giúp ích, những công đức cho loài Người. Chúng là những giúp ích, những công đức cho những người xuất gia.`, ref: "AN 5.31", url: "../an/an5.31.html#content" },

{ text: `Như mặt trăng không uế,\nÐi giữa hư không giới,\nVới ánh sáng bừng chói,\nGiữa quần sao ở đời.\nCũng vậy, người đủ giới,\nHạng người có lòng tin,\nVới bố thí, bừng chói,\nGiữa xan tham ở đời.\nNhư mây mưa sấm sét,\nVòng hoa chóp trăm đầu,\nTràn đầy cả thung lũng,\nLan tràn cả đất bằng.\nCũng vậy, đầy tri kiến,\nÐệ tử bậc Chánh Giác,\nBậc trí vượt xan tham,\nTrên cả năm phương diện,\nThọ mạng và danh xưng,\nDung sắc và an lạc,\nVới tài sản sung mãn,\nChết hưởng hỷ lạc thiên.`, ref: "AN 5.31", url: "../an/an5.31.html#content" },

{ text: `Người bố thí, này Sìha, người thí chủ được quần chúng ái mộ và ưa thích. Này Sìha, người bố thí, người thí chủ được quần chúng ái mộ và ưa thích, đây quả bố thí thiết thực hiện tại. Lại nữa, này Sìha! Bậc thiện, bậc Chân nhân thân cận người bố thí, người thí chủ. Này Sìha, bậc Thiện, bậc Chân nhân, thân cận người bố thí, người thí chủ. Này Sìha, đây là quả bố thí thiết thực hiện tại. Lại nữa, này Sìha! Người bố thí, người thí chủ được đồn tốt đẹp truyền đi. Này Sìha, người bố thí, người thí chủ được tiếng đồn tốt đẹp truyền đi. Này Sìha, đây là quả bố thí thiết thực hiện tại.`, ref: "AN 5.34", url: "../an/an5.34.html#content" },

{ text: `Người bố thí, này Sìha, người thí chủ đi đến hội chúng nào, hoặc hội chúng Sát-đế-ly, hoặc hội chúng Bà-la-môn, hoặc hội chúng gia chủ, hoặc hội chúng Sa-môn. Vị ấy đi đến với tự tín, không có do dự hoang mang. Này Sìha, người bố thí, người thí đi đến hội chúng nào, hoặc hội chúng Sát Ðế Lỵ, hoặc hội chúng Bà-la-môn, hoặc hội chúng gia chủ, hoặc hội chúng Sa-môn; vị ấy đi đến với tự tín, không có do dự hoang mang. Này Sìha, đây là quả bố thí thiết thực hiện tại.`, ref: "AN 5.34", url: "../an/an5.34.html#content" },

{ text: `Này các Tỷ-kheo, có năm lợi ích này của bố thí. Thế nào là năm? Ðược nhiều người ái mộ, ưa thích; được bậc Thiện nhân, Chân nhân thân cận; tiếng đồn tốt đẹp được truyền đi; không có sai lệch pháp của người gia chủ; khi thân hoại mạng chung được sanh lên cõi lành, Thiên giới. Những pháp này, này các Tỷ-kheo, là lợi ích của bố thí.`, ref: "AN 5.35", url: "../an/an5.35.html#content" },
{ text: `Này các Tỷ-kheo, có năm bố thí đúng thời này. Thế nào là năm? Bố thí cho người đến, bố thí cho người đi, bố thí cho người đau bệnh, bố thí trong thời đói, phàm có những hoa quả gì mới gặt hái được, dành chúng đầu tiên để cúng dường các bậc giữ giới. Này các Tỷ-kheo, năm pháp này là năm bố thí đúng thời.`, ref: "AN 5.36", url: "../an/an5.36.html#content" },

{ text: `Người bố thí bữa ăn, này các Tỷ-kheo, người thí chủ đem lại cho người thọ lãnh năm điều. Thế nào là năm? Cho thọ mạng, cho dung sắc, cho an lạc, cho sức mạnh, cho biện tài. Cho thọ mạng, vị ấy được chia thọ mạng chư Thiên hay loài Người. Cho dung sắc, vị ấy được chia dung sắc chư Thiên hay loài Người. Cho an lạc, vị ấy được chia an lạc chư Thiên hay loài Người. Cho sức mạnh, vị ấy được chia sức mạnh chư Thiên hay loài Người. Cho biện tài, vị ấy được chia biện tài chư Thiên hay loài Người. Người bố thí bữa ăn, này các Tỷ-kheo, người thí chủ đem lại cho người thọ lãnh năm điều này.`, ref: "AN 5.37", url: "../an/an5.37.html#content" },

{ text: `Này các Tỷ-kheo, có năm lợi ích này cho thiện nam tử có lòng tin. Thế nào là năm? Các Thiện nhân, các Chân nhân, trước hết có lòng thương tưởng đến vị có lòng tin, không có như vậy đối với vị không có lòng tin; khi đến thăm, trước hết họ đến thăm vị có lòng tin, không có như vậy đối với vị không có lòng tin; khi chấp nhận, họ chấp nhận (các món ăn) trước hết từ những người có lòng tin, không từ những người không có lòng tin; họ thuyết pháp trước hết cho những người có lòng tin, không cho những người không có lòng tin; người có lòng tin, sau khi thân hoại mạng chung, được sanh lên cõi lành, cõi Trời. Những pháp này, này các Tỷ-kheo, là năm lợi ích cho thiện nam tử có lòng tin.`, ref: "AN 5.38", url: "../an/an5.38.html#content" },

{ text: `Ví như, này các Tỷ-kheo, trên khoảnh đất tốt, tại ngã tư đường, có cây bàng to lớn là chỗ nương tựa cho các loài chim chung quanh. Cũng vậy, này các Tỷ-kheo, thiện nam tử có lòng tin là chỗ nương tựa cho quần chúng, cho các Tỷ-kheo, Tỷ-kheo-ni, cho nam cư sĩ và cho nữ cư sĩ.`, ref: "AN 5.38", url: "../an/an5.38.html#content" },

{ text: `Như cây bàng to lớn,\nVới cành, lá, trái cây,\nVới thân, rễ, đầy trái,\nLàm chỗ trú loài chim.\nTại trú xứ thoải mái,\nCác con chim làm tổ,\nCần bóng mát, hứng mát,\nCần trái cây, ăn trái.\nCũng vậy, vị trì giới,\nNgười có lòng tịnh tín,\nKhiêm nhường và nhu thuận,\nHiền hòa, lời từ tốn,\nTánh tình thật dịu hiền,\nVị đoạn tham, đoạn sân,\nÐoạn si, không lậu hoặc,\nLà ruộng phước ở đời.\nHọ đến người như vậy,\nHọ thuyết pháp, người ấy\nÐoạn trừ mọi khổ đau,\nVị ấy ở tại đây,\nHiểu biết Chánh pháp ấy,\nViên bản nhập Niết-bàn,\nHoàn toàn không lậu hoặc.`, ref: "AN 5.38", url: "../an/an5.38.html#content" },

{ text: `Ai cho vật khả ý,\nNhận được điều khả ý,\nBố thí vật tối thượng,\nSẽ được quả tối thượng.\nNgười có vật thù diệu,\nNhận được điều thù diệu,\nNgười có vật tối thắng,\nNhận được điều tối thắng.\nNgười nào đem bố thí\nVật tối thượng, thù diệu,\nVà các vật tối thượng,\nNgười ấy thọ mạng dài,\nVà được cả danh xưng,\nTại chỗ vị ấy sanh.`, ref: "AN 5.44", url: "../an/an5.44.html#content" },

{ text: `Biển lớn không hạn lượng,\nHồ lớn nhiều sợ hãi,\nLà kho tàng cất giữ,\nVô số lượng châu báu,\nCũng là chỗ trú ẩn;\nVô số các loại cá,\nLà chỗ các sông lớn.\nQuy tựu chảy ra biển.\nCũng vậy người bố thí,\nÐồ ăn và đồ uống,\nVải mặc và giường nằm,\nChỗ ngồi và thảm nệm,\nBậc Hiền thí như vậy,\nPhước đức ùa chạy đến,\nNhư sông dẫn dòng nước,\nÙa chảy vào biển cả.`, ref: "AN 5.45", url: "../an/an5.45.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, vị Thánh đệ tử sống ở gia đình, tâm không bị cấu uế xan tham chi phối, bố thí rộng rãi, với bàn tay rộng mở, ưa thích từ bỏ, sẵn sàng để được yêu cầu, ưa thích phân phát vật bố thí. Này các Tỷ-kheo, đây gọi là thí tài.`, ref: "AN 5.47", url: "../an/an5.47.html#content" },

{ text: `Ai tin tưởng Như Lai,\nBất động, khéo an trí,\nAi gìn giữ thiện giới,\nThánh ái mộ tán thán.\nAi tịnh tín chúng Tăng,\nÐược thấy bậc Chánh trực,\nNgười ấy gọi không nghèo,\nMạng sống không trống không.\nDo vậy, tín và giới,\nTịnh tín thấy Chánh pháp,\nBậc trí tâm chuyên chú,\nNhớ đến lời Phật dạy.`, ref: "AN 5.47", url: "../an/an5.47.html#content" },

{ text: `Với kẻ phàm phu không học, này các Tỷ-kheo, phải bị già và già đến...  phải bị bệnh và bệnh đến... phải bị chết và chết đến... phải bị hoại diệt và hoại diệt đến... phải bị tiêu diệt và tiêu diệt đến; khi tiêu diệt đến, kẻ ấy không suy tư: “Không phải chỉ một mình ta phải bị tiêu diệt và tiêu diệt đến, nhưng đối với các loài hữu tình, có đến, có đi, có diệt, có sanh, tất cả loài hữu tình đều phải bị tiêu diệt và tiêu diệt đến. Và nếu phải bị tiêu diệt, và khi tiêu diệt đến, ta lại sầu, bi, than khóc, đập ngực, đi đến bất tỉnh, thời ăn uống không làm ta ưa thích; thân ta trở thành xấu xí; công việc không có xúc tiến, kẻ thù sẽ hoan hỷ, bạn bè sẽ lo buồn”. Kẻ ấy phải bị tiêu diệt, khi tiêu diệt đến, sầu, bi, than khóc, đập ngực, đi đến bất tỉnh. Này các Tỷ-kheo, đây gọi là kẻ phàm phu không học, bị mũi tên sầu muộn tẩm thuốc độc bắn trúng, kẻ ấy tự làm mình ưu não.
`, ref: "AN 5.48", url: "../an/an5.48.html#content" },

{ text: `Với lời thật khéo nói,\nVới bố thí chơn chánh,\nVới truyền thống khéo giữ,\nChỗ nào được lợi ích,\nChỗ ấy gắng tinh cần.\nNếu biết lợi không được,\nCả ta và người khác,\nKhông sầu, biết chịu đựng,\nMong vị ấy nghĩ rằng:\nNay ta phải làm gì?\nPhải kiên trì thế nào?`, ref: "AN 5.50", url: "../an/an5.50.html#content" },

{ text: `Dục tham, này các Tỷ-kheo, là chướng ngại triền cái bao phủ tâm, làm yếu ớt trí tuệ. Sân, này các Tỷ-kheo, là chướng ngại triền cái bao phủ tâm làm yếu ớt trí tuệ. Hôn trầm thụy miên, này các Tỷ-kheo, là chướng ngại, triền cái bao phủ tâm, làm yếu ớt trí tuệ. Trạo hối, này các Tỷ-kheo, là chướng ngại, triền cái bao phủ tâm, làm yếu ớt trí tuệ. Nghi, này các Tỷ-kheo, là chướng ngại, triền cái bao phủ tâm, làm yếu ớt trí tuệ. Những pháp này, này các Tỷ-kheo, là năm chướng ngại triền cái bao phủ tâm, làm yếu ớt trí tuệ.`, ref: "AN 5.51", url: "../an/an5.51.html#content" },


{ text: `Ví như, này các Tỷ-kheo, một con sông chảy, từ núi xuống, chảy thật xa, dòng chảy nhanh cuốn trôi mọi vật. Rồi có người lấy cày mở hai bên bờ sông. Như vậy, này các Tỷ-kheo, dòng sông ấy ở chặng giữa bị trở ngại, tràn rộng, bị chuyển hướng, không còn chảy ra xa, không còn chảy nhanh, không cuốn trôi mọi vật. Cũng vậy, này các Tỷ-kheo, Tỷ-kheo ấy không đoạn tận năm chướng ngại triền cái này bao phủ tâm, làm yếu ớt trí tuệ, không có sức mạnh và trí tuệ yếu kém, sẽ biết được lợi ích của mình, hay sẽ biết lợi ích của người, hay có thể biết lợi ích của cả hai, sẽ chứng ngộ được pháp thượng nhân, trí kiến thù thắng, xứng đáng bậc Thánh; sự kiện này không xảy ra.`, ref: "AN 5.51", url: "../an/an5.51.html#content" },


{ text: `Nói đến một đống bất thiện, này các Tỷ-kheo, nói một cách chơn chánh là nói đến năm triền cái. Thật vậy, này các Tỷ-kheo, toàn bộ đống bất thiện tức là năm triền cái. Thế nào là năm? Dục tham triền cái, sân triền cái, hôn trầm thụy miên triền cái, trạo hối triền cái, nghi triền cái. Nói đến một đống bất thiện, này các Tỷ-kheo, nói một cách chơn chánh là nói đến năm triền cái. Thật vậy, này các Tỷ-kheo, toàn bộ đống bất tiện này, này các Tỷ-kheo, tức là năm triền cái.`, ref: "AN 5.52", url: "../an/an5.52.html#content" },


{ text: `Này các Tỷ-kheo, nếu có ai nói rằng: “Là bẫy mồi toàn diện của Màra”, thời người ấy đã nói một cách chơn chánh về nữ nhân, thật là “một bẫy mồi hoàn toàn của Màra”.`, ref: "AN 5.55", url: "../an/an5.55.html#content" },

{ text: `Hãy nói chuyện với người,\nCó kiếm ở trong tay,\nNói chuyện với ác quỷ,\nHay ngồi thật gần kề.\nCon rắn có nọc độc,\nBị cắn liền mệnh chung,\nNhưng chớ có một mình,\nNói chuyện với nữ nhân.\nThất niệm, họ trói lại,\nVới nhìn, với nụ cười,\nVới xiêm áo hở hang,\nVới lời nói ngọt lịm,\nNgười ấy vẫn không thỏa,\nBất tỉnh bị mệnh chung.\nNăm dục trưởng dưỡng ấy,\nÐược thấy trong nữ sắc\nSắc, thanh, hương, vị, xúc,\nHấp dẫn và đẹp ý.\nBị thác nước dục vọng,\nTràn ngập và cuốn trôi,\nKẻ ngu si vô trí,\nKhông liễu tri các dục.\nLoài người khi mạng chung,\nSanh thú hữu, phi hữu,\nHọ phải bị dẫn đầu,\nTrong nhiều kiếp luân hồi.\nAi liễu tri các dục,\nSở hành không sợ hãi,\nHọ đến bờ bên kia,\nÐạt được lậu hoặc tận.`, ref: "AN 5.55", url: "../an/an5.55.html#content" },

{ text: `Này Tỷ-kheo, khi một người sống với các căn không được bảo vệ, với ăn uống không có tiết độ, không có chú tâm cảnh giác, không có quán nhìn các thiện pháp, không có trước đêm và sau đêm chuyên chú tu tập các pháp giác chi. Do vậy, thân Thầy cảm thấy như bị say ngọt, mắt Thầy không thấy rõ phương hướng, pháp không được Thầy nhớ đến. Hôn trầm thụy miên chinh phục tâm Thầy và an trú. Không có hoan hỷ, Thầy sống Phạm hạnh. Thầy có những nghi ngờ đối với Chánh pháp. Do vậy, này Tỷ-kheo, Thầy phải học tập như sau: “Ta sẽ bảo vệ các căn, có tiết độ trong ăn uống, chú tâm cảnh giác, quán nhìn các Thiện pháp, trước đêm và sau đêm ta sẽ sống chuyên chú tu tập các pháp giác chi”.`, ref: "AN 5.56", url: "../an/an5.56.html#content" },

{ text: `Này Tỷ-kheo, khi một người sống với các căn được bảo vệ, với ăn uống có tiết độ, có chú tâm cảnh giác, có quán nhìn các thiện pháp, trước đêm và sau đêm sống chuyên chú tu tập các pháp giác chi. Do vậy, thân không cảm thấy như bị say ngọt, các phương hướng được hiện rõ, và pháp được người ấy nhớ rõ. Hôn trầm thụy miên không còn chinh phục tâm của vị ấy. Với tâm hoan hỷ, vị ấy sống Phạm hạnh. Vị ấy không còn nghi ngờ đối với các thiện pháp. Vậy này các Tỷ-kheo, các Thầy cần phải học tập như sau: “Ta sẽ bảo vệ các căn, có tiết độ trong ăn uống, chuyên tâm cảnh giác quán nhìn các thiện pháp, trước đêm và sau đêm, ta sẽ sống chuyên chú tu tập các pháp giác chi”.`, ref: "AN 5.56", url: "../an/an5.56.html#content" },


{ text: `Bị bệnh và bị già,\nLại thêm phải bị chết,\nPháp yếu là như vậy,\nHữu tình là như vậy.\nPhàm phu sanh nhàm chán,\nThật không hợp cho Ta,\nNếu Ta cũng nhàm chán,\nÐối với các chúng sanh,\nCùng chung một số phận.\nTrong khi đời sống Ta,\nKhông khác gì đời họ,\nTa được sống như vậy,\nBiết pháp không sanh y,\nKiêu mạn trong không bệnh,\nTrong tuổi trẻ sinh mạng,\nTất cả Ta nhiếp phục\nPhát xuất từ an ổn,\nTa thấy hạnh viễn ly,\nTa phát tâm dõng mãnh,\nThấy được cảnh Niết-bàn.\nNay Ta không có thể,\nHưởng thọ các dục vọng,\nTa sẽ không thối đọa,\nChứng cứu cánh Phạm hạnh.`, ref: "AN 5.57", url: "../an/an5.57.html#content" },

{ text: `Có năm tưởng này, này các Tỷ-kheo, được tu tập, được làm cho sung mãn, đưa đến quả lớn, lợi ích lớn, thể nhập vào bất tử, đưa đến cứu cánh bất tử. Thế nào là năm? Tưởng bất tịnh, tưởng chết, tưởng nguy hại, tưởng ghê tởm các món ăn, tưởng không có hân hoan đối với tất cả thế giới. Năm tưởng này, này các Tỷ-kheo, được tu tập, được làm cho sung mãn, đưa đến quả lớn, lợi ích lớn, thể nhập vào bất tử, đưa đến cứu cánh bất tử.`, ref: "AN 5.61", url: "../an/an5.61.html#content" },

{ text: `Có năm tưởng này, này các Tỷ-kheo, được tu tập, được làm cho sung mãn, đưa đến quả lớn lợi ích, thể nhập vào bất tử, đưa đến cứu cánh bất tử. Thế nào là năm? Tưởng vô thường, tưởng vô ngã, tưởng chết, tưởng ghê tởm các món ăn, tưởng không có hân hoan đối với tất cả thế giới. Những pháp này là năm tưởng, này các Tỷ-kheo, được tu tập, được làm cho sung mãn, đưa đến quả lớn, lợi ích lớn, thể nhập vào bất tử, đưa đến cứu cánh bất tử.`, ref: "AN 5.62", url: "../an/an5.62.html#content" },

{ text: `Này các Tỷ-kheo, tăng trưởng với năm tăng trưởng, vị Thánh đệ tử tăng trưởng, với Thánh tăng trưởng đem lại kiên cố, đem lại thù thắng cho tự thân. Thế nào là năm? Tăng trưởng với lòng tin, tăng trưởng với giới, tăng trưởng với học hỏi, tăng trưởng với bố thí, tăng trưởng với trí tuệ. Tăng trưởng với năm tăng trưởng này, này các Tỷ-kheo, vị Thánh đệ tử tăng trưởng với Thánh tăng trưởng, đem lại kiên cố, đem lại thù thắng cho tự thân.`, ref: "AN 5.63", url: "../an/an5.63.html#content" },

{ text: `Năm pháp này, này các Tỷ-kheo, được tu tập, được làm cho sung mãn, đưa đến đoạn diệt các lậu hoặc. Thế nào là năm? Ở đây, này các Tỷ-kheo, vị Tỷ-kheo trú quán bất tịnh trên thân, với tưởng ghê tởm đối với các món ăn, với tưởng không hoan hỷ đối với tất cả thế giới, quán vô thường đối với tất cả hành, với tưởng về chết, nội tâm khéo an trú. Năm pháp này, này các Tỷ-kheo, được tu tập, được làm cho sung mãn, đưa đến đoạn diệt các lậu hoặc.`, ref: "AN 5.70", url: "../an/an5.70.html#content" },


{ text: `Ở đây, này các Tỷ-kheo, Tỷ-kheo thuyết pháp cho các người khác một cách rộng rãi như đã được nghe, như đã được học thông suốt. Vị ấy dùng trọn cả ngày để trình bày pháp cho các người khác, bỏ phế sống độc cư an tịnh, không nỗ lực chuyên chú vào nội tâm an chỉ. Này Tỷ-kheo, đấy gọi là Tỷ-kheo thuyết trình nhiều, nhưng không sống theo pháp.\nLại nữa, này các Tỷ-kheo, Tỷ-kheo đọc tụng pháp một cách rộng rãi như đã được nghe, như đã được học thuộc lòng. Vị ấy dùng trọn cả ngày để tụng đọc, bỏ phế sống độc cư an tịnh, không nỗ lực chuyên chú vào nội tâm an chỉ. Này Tỷ-kheo, đây gọi là Tỷ-kheo đọc tụng nhiều, nhưng không sống theo pháp.`, ref: "AN 5.73", url: "../an/an5.73.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, Tỷ-kheo với tâm tùy tầm tùy tứ, với ý tùy quán pháp như đã được nghe, như đã được học thuộc lòng. Vị ấy dùng trọn cả ngày suy tầm về pháp, bỏ phế sống độc cư an tịnh, không nỗ lực chuyên chú vào nội tâm an chỉ. Này Tỷ-kheo, đây gọi là Tỷ-kheo suy tầm nhiều, nhưng không sống theo pháp.\nỞ đây, này Tỷ-kheo, Tỷ-kheo học thuộc lòng pháp, tức là Khế kinh, Ứng tụng, Ký thuyết, Phúng tụng, Không hỏi tự nói, Như thị thuyết, Bổn sanh, Vị tằng hữu pháp, Trí giải hay Phương quảng. Vị ấy không dùng trọn cả ngày để học thuộc lòng pháp, không phế bỏ sống độc cư an tịnh, nỗ lực chuyên chú vào nội tâm an chỉ. Này Tỷ-kheo, như vậy Tỷ-kheo sống theo pháp.`, ref: "AN 5.73", url: "../an/an5.73.html#content" },

{ text: `Này Tỷ-kheo, điều gì bậc Ðạo Sư cần phải làm cho các đệ tử vì hạnh phúc, vì lòng thương tưởng, vì lòng từ khởi lên, các điều ấy, Ta đã làm cho các Thầy. Này Tỷ-kheo, đây là những gốc cây, đây là những căn nhà trống. Này Tỷ-kheo, hãy tu Thiền, chớ có phóng dật, chớ có để về sau sẽ phải hối tiếc. Ðấy là lời giáo giới của Ta cho các Thầy.`, ref: "AN 5.73", url: "../an/an5.73.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, Tỷ-kheo quán sát như sau: “Nay ta còn trẻ, niên thiếu, còn thanh niên, tóc đen nhánh, trong buổi thanh xuân, trong sơ kỳ tuổi đời. Nhưng rồi đến thời già sẽ xúc chạm thân này. Khi đã già yếu, và bị già chinh phục, thật không dễ gì để tác ý đến giáo pháp của các đức Phật, thật không dễ gì để sống tại các trú xứ rừng núi cao nguyên xa vắng. Trước khi trạng thái ấy đến với ta, không đáng ưa, không đáng thích, không khả ý, ta hãy hăng hái tinh cần trước khi thời ấy đến, để chứng đạt những gì chưa chứng đạt, chứng đắc những gì chưa chứng đắc, chứng ngộ những gì chưa chứng ngộ. Và nếu thành tựu trạng thái ấy, có bị già, ta sẽ sống được thoải mái”.\nNày các Tỷ-kheo, do quán thấy sợ hãi thứ nhất này về tương lai, như vậy là vừa đủ để Tỷ-kheo sống không phóng dật, nhiệt tâm, tinh cần, để chứng đạt những gì chưa chứng đạt, chứng đắc những gì chưa chứng đắc, chứng ngộ những gì chưa chứng ngộ.`, ref: "AN 5.78", url: "../an/an5.78.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, vị Tỷ-kheo quán sát như sau: “Nay ta ít bệnh, ít não, sự tiêu hóa được điều hòa, không lạnh quá, không nóng quá, trung bình, hợp với tinh tấn, nhưng rồi đến thời bệnh sẽ xúc chạm thân này. Khi đã bị bệnh và bị bệnh chinh phục, thật không dễ gì tác ý đến giáo pháp của các đức Phật, thật không dễ gì để sống tại các trú xứ rừng núi cao nguyên xa vắng. Trước khi trạng thái ấy đến với ta, không đáng ưa, không đáng thích, không khả ý, ta hãy hăng hái tinh cần trước khi thời ấy đến, để chứng đạt những gì chưa chứng đạt, chứng đắc những gì chưa chứng đắc, chứng ngộ những gì chưa chứng ngộ. Và nếu thành tựu trạng thái ấy, dầu có bị bệnh, ta sẽ sống được thoải mái”.\nNày các Tỷ-kheo, do quán thấy sợ hãi thứ hai này về tương lai, như vậy là vừa đủ để vị Tỷ-kheo sống không phóng dật, nhiệt tâm, tinh cần, để chứng đạt những gì chưa chứng đạt, chứng đắc những gì chưa chứng đắc, chứng ngộ những gì chưa chứng ngộ.`, ref: "AN 5.78", url: "../an/an5.78.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, vị Tỷ-kheo quán sát như sau: “Nay không có đói kém, được mùa, đồ ăn khất thực dễ kiếm được, thật dễ dàng để nuôi sống bằng khất thực nỗ lực. Nhưng rồi đến thời có nạn đói, mất mùa, đồ ăn khất thực nỗ lực được, không dễ gì nuôi sống bằng khất thực nỗ lực. Và những người bị nạn đói sẽ dời đến chỗ nào được nhiều đồ ăn; tại đấy, phải sống với quần chúng, phải sống với hỗn tạp. Khi phải sống với quần chúng, phải sống với hỗn tạp, thật không dễ gì để tác ý đến giáo pháp của các đức Phật, thật không dễ gì để sống tại các trú xứ rừng núi cao nguyên xa vắng. Trước khi trạng thái ấy đến với ta, không đáng ưa, không đáng thích, không khả ý, ta hãy hăng hái tinh cần trước khi thời ấy đến, để chứng đạt những gì chưa chứng đạt, chứng đắc những gì chưa chứng đắc, chứng ngộ những gì chưa chứng ngộ. Và nếu thành tựu trạng thái ấy, có bị đói kém, ta sẽ sống được thoải mái”.\nNày các Tỷ-kheo, do quán thấy sợ hãi thứ ba này về tương lai, như vậy là vừa đủ để vị Tỷ-kheo sống không phóng dật, nhiệt tâm, tinh cần, để chứng đạt những gì chưa chứng đạt, chứng đắc những gì chưa chứng đắc, chứng ngộ những gì chưa chứng ngộ.`, ref: "AN 5.78", url: "../an/an5.78.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, Tỷ-kheo quán sát như sau: “Nay các loài Người sống với nhau thuận hòa, hoan hỷ với nhau, không cãi lộn nhau, hòa hợp như nước với sữa, sống nhìn nhau với cặp mắt ái kính. Nhưng rồi đến thời có sự sợ hãi về nạn cướp rừng, dân chúng trong nước leo lên xe để đi trốn tại nơi nào có sự sợ hãi, dân chúng di động đến chỗ có sự an ổn. Tại đấy, phải sống với quần chúng, phải sống với hỗn tạp, thật không dễ với quần chúng, sống với hỗn tạp, thật không dễ gì để tác ý đến giáo pháp của các đức Phật, thật không dễ gì để sống tại các trú xứ rừng núi cao nguyên xa vắng.. Trước khi trạng thái ấy đến với ta, không đáng ưa, không đáng thích, không khả ý, ta phải hăng hái tinh cần trước khi thời ấy đến để chứng đạt những gì chưa chứng đạt, chứng đắc những gì chưa chứng đắc, chứng ngộ những gì chưa chứng ngộ. Và nếu thành tựu trạng thái ấy, có gặp sự sợ hãi, ta sẽ sống được thoải mái”.\nNày các Tỷ-kheo, do quán thấy sợ hãi thứ tư này về tương lai, như vậy là vừa đủ để Tỷ-kheo sống không phóng dật, nhiệt tâm, tinh cần, để chứng đạt những gì chưa chứng đạt, chứng đắc những gì chưa chứng đắc, chứng ngộ những gì chưa chứng ngộ.`, ref: "AN 5.78", url: "../an/an5.78.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, Tỷ-kheo quán sát như sau: “ Nay chúng Tăng hòa hợp, cùng nhau hoan hỷ, không tranh luận nhau, sống thoải mái cùng chung một lời dạy... nhưng rồi đến thời chúng Tăng chia rẽ. Khi chúng Tăng chia rẽ, thật không dễ gì để tác ý đến giáo pháp của các đức Phật. Thật không dễ gì để sống tại các trú xứ rừng núi, cao nguyên xa vắng. Trước khi trạng thái ấy đến với ta, không đáng ưa, không đáng thích, không khả ý, ta hãy hăng hái tinh cần trước khi thời ấy đến, để chứng đạt những gì chưa chứng đạt, chứng đắc những gì chưa chứng đắc, chứng ngộ những gì chưa chứng ngộ. Và nếu thành tựu trạng thái ấy, chúng Tăng có chia rẽ, ta sẽ sống được thoải mái”.\nNày các Tỷ-kheo, do quán thấy sợ hãi thứ năm này về tương lai, như vậy là vừa đủ để vị Tỷ-kheo sống không phóng dật, nhiệt tâm, tinh cần, để chứng đạt những gì chưa chứng đạt, chứng đắc những gì chưa chứng đắc, chứng ngộ những gì chưa chứng ngộ.`, ref: "AN 5.78", url: "../an/an5.78.html#content" },

{ text: `Này các Tỷ-kheo, các Tỷ-kheo trong tương lai sẽ tham muốn các y tốt đẹp. Do họ tham muốn các y tốt đẹp, họ sẽ từ bỏ các y nhặt nơi đống rác, họ sẽ từ bỏ các khu rừng, các vùng cao nguyên, các trú xứ xa vắng, họ sẽ đi đến các làng, thị trấn, kinh đô vua chúa và sống tại các chỗ ấy. Vì nhân y áo, họ sẽ rơi vào những hành vi tầm cầu không thích hợp. Này các Tỷ-kheo, đây là sợ hãi thứ nhất về tương lai, hiện nay chưa sanh khởi, nhưng sẽ sanh khởi trong tương lai. Các Thầy cần phải hoàn toàn rõ biết chúng. Sau khi hoàn toàn rõ biết, cần phải tinh tấn để đoạn trừ sợ hãi ấy.`, ref: "AN 5.80", url: "../an/an5.80.html#content" },

{ text: `Này các Tỷ-kheo, những Tỷ-kheo trong tương lai sẽ tham muốn các đồ ăn khất thực ngon lành. Do họ tham muốn các đồ ăn khất thực ngon lành, họ sẽ từ bỏ nếp sống khất thực, từ bỏ các khu rừng, các vùng cao nguyên, các trú xứ xa vắng. Họ sẽ đi vào các làng, thị trấn, kinh đô của vua và sinh sống tại đấy, tìm cầu các món ăn thượng vị, như với đầu lưỡi. Do nhân đồ ăn khất thực, họ sẽ rơi vào nhiều hành động tầm cầu không thích hợp. Này các Tỷ-kheo, đây là sợ hãi thứ hai về tương lai, hiện nay chưa sanh khởi, nhưng sẽ sanh khởi trong tương lai. Các Thầy cần phải hoàn toàn rõ biết chúng. Sau khi hoàn toàn rõ biết, cần phải tinh tấn để đoạn trừ sợ hãi ấy.`, ref: "AN 5.80", url: "../an/an5.80.html#content" },

{ text: `Này các Tỷ-kheo, những Tỷ-kheo trong tương lai sẽ tham muốn sàng tọa tốt đẹp. Do họ tham muốn các sàng tọa tốt đẹp, họ sẽ từ bỏ nếp sống dưới gốc cây, họ sẽ từ bỏ các khu rừng, các vùng cao nguyên, các trú xứ xa vắng. Họ sẽ đi vào các làng, thị trấn, kinh đô của vua và sinh sống tại đấy. Vì nhân sàng tọa, họ sẽ rơi vào nhiều hành động tầm cầu không thích hợp. Này các Tỷ-kheo, đây là sợ hãi thứ ba về tương lai, hiện nay chưa sanh khởi, nhưng sẽ sanh khởi trong tương lai. Các Thầy cần phải hoàn toàn rõ biết chúng. Sau khi hoàn toàn rõ biết, cần phải tinh tấn để đoạn trừ sợ hãi ấy.`, ref: "AN 5.80", url: "../an/an5.80.html#content" },

{ text: `Này các Tỷ-kheo, sẽ có những Tỷ-kheo trong tương lai sẽ sống liên hệ với Tỷ-kheo-ni, các chánh học nữ, các Sa-di-ni. Khi sống liên hệ với Tỷ-kheo-ni, chánh học nữ, Sa-di-ni, này các Tỷ-kheo, được chờ đợi là: Họ sẽ không thích thú sống Phạm hạnh, hay họ sẽ rơi vào một trong những tội lỗi ô nhiễm, sẽ từ bỏ học pháp và trở lui lại đời sống thế tục. Này các Tỷ-kheo, đây là sợ hãi thứ tư về tương lai, hiện nay chưa sanh khởi. Các Thầy cần phải hoàn toàn rõ biết chúng. Sau khi hoàn toàn rõ biết, cần phải tinh tấn để đoạn trừ sợ hãi ấy.`, ref: "AN 5.80", url: "../an/an5.80.html#content" },

{ text: `Này các Tỷ-kheo, sẽ có những Tỷ-kheo trong tương lai sống liên hệ với các người có hệ lụy đến khu vườn, với các Sa-di. Khi sống liên hệ với các người có hệ lụy đến khu vườn và với các Sa-di, này các Tỷ-kheo, được chờ đợi là họ sẽ sống và tận hưởng các vật liệu cất chứa, và họ sẽ làm các thô tướng đối với đất đai và đối với các sản phẩm trồng trọt. Này các Tỷ-kheo, đây là sợ hãi thứ năm về tương lai, hiện nay chưa sanh khởi, nhưng sẽ sanh khởi trong tương lai. Các Thầy cần phải hoàn toàn rõ biết chúng. Sau khi hoàn toàn rõ biết, các Thầy cần phải tinh tấn để đoạn tận sự sợ hãi ấy.`, ref: "AN 5.80", url: "../an/an5.80.html#content" },


{ text: `Thành tựu năm pháp này, này các Tỷ-kheo, Tỷ-kheo Trưởng lão đối với các vị đồng Phạm hạnh không được ái mộ, không được ưa thích, không được tôn trọng, không được làm gương để tu tập. Thế nào là năm? Bị tham ái bởi những gì khả ái, bị hiềm hận bởi những gì đáng hiềm hận, bị si mê bởi những gì đáng si mê, bị phẫn nộ bởi những gì đáng phẫn nộ, bị say đắm bởi những gì đáng say đắm. Thành tựu năm pháp này, này các Tỷ-kheo, Tỷ-kheo Trưởng Lão đối với các vị đồng Phạm hạnh không được ái mộ, không được ưa thích, không được tôn trọng, không được làm gương để tu tập.`, ref: "AN 5.81", url: "../an/an5.81.html#content" },

{ text: `Thành tựu năm pháp này, này các Tỷ-kheo, Tỷ-kheo Trưởng lão đối với các vị đồng Phạm hạnh được ái mộ, được ưa thích, được tôn trọng, được làm gương để tu tập. Thế nào là năm? Không bị tham bởi những gì khả ái, không bị hiềm hận bởi những gì đáng hiềm hận, không bị si mê bởi những gì đáng si mê, không bị phẫn nộ bởi những gì đáng phẫn nộ, không bị say đắm bởi những gì đáng say đắm. Thành tựu năm pháp này, này các Tỷ-kheo, Tỷ-kheo Trưởng Lão đối với các vị đồng Phạm hạnh được ái mộ, được ưa thích, được tôn trọng, được làm gương để tu tập.`, ref: "AN 5.81", url: "../an/an5.81.html#content" },

{ text: `Thành tựu năm pháp này, này các Tỷ-kheo, một Tỷ-kheo Trưởng lão đối với các vị đồng Phạm hạnh không được ái mộ, không được ưa thích, không được tôn trọng, không được làm gương để tu tập. Thế nào là năm? Lừa đảo, siểm nịnh (hư đàm), hiện tướng (gợi ý), gièm pha, lấy lợi cầu lợi. Thành tựu năm pháp này, này các Tỷ-kheo, một Tỷ-kheo Trưởng lão đối với các vị đồng Phạm hạnh không được ái mộ, không được ưa thích, không được tôn trọng, không được làm gương để tu tập.`, ref: "AN 5.83", url: "../an/an5.83.html#content" },

{ text: `Thành tựu năm pháp này, này các Tỷ-kheo, một Tỷ-kheo Trưởng lão đối với các vị đồng Phạm hạnh được ái mộ, được ưa thích, được tôn trọng, được làm gương để tu tập. Thế nào là năm? Có lòng tin, có hổ thẹn, có biết sợ, tinh cần, tinh tấn và có tuệ. Thành tựu năm pháp này, này các Tỷ-kheo, một Tỷ-kheo Trưởng lão đối với các vị đồng Phạm hạnh được ái mộ, được ưa thích, được tôn trọng, được làm gương để tu tập.`, ref: "AN 5.84", url: "../an/an5.84.html#content" },

{ text: `Thành tựu năm pháp, này các Tỷ-kheo, một Tỷ-kheo Trưởng lão đối với các vị đồng Phạm hạnh được ái mộ, được ưa thích, được tôn trọng, được làm gương để tu tập. Thế nào là năm? Có giới, sống được bảo vệ với sự bảo vệ của giới bổn, đầy đủ oai nghi chánh hạnh, thấy sự sợ hãi trong các tội nhỏ nhiệm, chấp nhận và học tập các học pháp, nghe nhiều, thọ trì điều được nghe, tích tập điều được nghe. Các pháp nào sơ thiện, trung thiện, hậu thiện, có nghĩa, có văn, đề cao đời sống Phạm hạnh hoàn toàn đầy đủ thanh tịnh, những pháp ấy, vị ấy đã nghe nhiều, đã nắm giữ, đã ghi nhớ nhờ đọc nhiều lần, chuyên ý quán sát, khéo thành tựu nhờ chánh kiến; thiện ngôn dùng lời thiện ngôn, lời nói tao nhã, ý nghĩa minh bạch, giọng nói không bập bẹ, phều phào, giải thích nghĩa lý minh xác, chứng được không khó khăn, chứng được không mệt nhọc, chứng được không phí sức bốn Thiền, thuộc tăng thượng tâm, đem đến hiện tại lạc trú. Do đoạn tận các lậu hoặc, vị ấy tự mình với thắng trí chứng ngộ, chứng đạt và an trú ngay trong hiện tại vô lậu tâm giải thoát, tuệ giải thoát.\nThành tựu năm pháp này, này các Tỷ-kheo, một Tỷ-kheo Trưởng lão đối với các vị đồng Phạm hạnh được ái mộ, được ưa thích, được tôn trọng, được làm gương để tu tập.`, ref: "AN 5.87", url: "../an/an5.87.html#content" },

{ text: `Năm pháp này, này các Tỷ-kheo, khiến Tỷ-kheo hữu học thối chuyển. Thế nào là năm? Ưa công việc, ưa đàm luận, ưa ngủ, ưa có quần chúng, không quán sát tâm như đã được giải thoát. Năm pháp này, này các Tỷ-kheo, khiến Tỷ-kheo hữu học thối chuyển.`, ref: "AN 5.89", url: "../an/an5.89.html#content" },

{ text: `Năm pháp này, này các Tỷ-kheo, không khiến Tỷ-kheo hữu học thối chuyển. Thế nào là năm? Không ưa công việc, không ưa đàm luận, không ưa ngủ, không ưa có quần chúng, quán sát tâm như đã được giải thoát. Năm pháp này, này các Tỷ-kheo, không khiến Tỷ-kheo hữu học thối chuyển.`, ref: "AN 5.89", url: "../an/an5.89.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, vị Tỷ-kheo hữu học có nhiều công việc, có nhiều việc phải làm, khéo léo trong công việc phải làm, từ bỏ độc cư Thiền tịnh, không chuyên chú vào nội tâm tịnh chỉ. Ðây là pháp thứ nhất khiến Tỷ-kheo hữu học thối chuyển. Lại nữa, này các Tỷ-kheo, Tỷ-kheo hữu học suốt ngày làm những công việc nhỏ nhặt, từ bỏ độc cư Thiền tịnh, không có chuyên chú vào nội tâm tịnh chỉ. Ðây là pháp thứ hai khiến vị Tỷ-kheo hữu học thối chuyển. Lại nữa, này các Tỷ-kheo, Tỷ-kheo hữu học sống liên hệ nhiều với các vị tại gia và xuất gia, hệ lụy với các sự việc tại gia không thích đáng, từ bỏ độc cư Thiền tịnh, không chuyên chú vào nội tâm tịnh chỉ. Ðây là pháp thứ ba khiến Tỷ-kheo hữu học thối chuyển.`, ref: "AN 5.90", url: "../an/an5.90.html#content" },

{ text: `Ở đây, này các Tỷ-kheo, vị Tỷ-kheo hữu học đối với các câu chuyện nghiêm trang, khai tâm, như câu chuyện về ít dục, câu chuyện về tri túc, câu chuyện về viễn ly, câu chuyện về không hội họp, câu chuyện về tinh cần tinh tấn, câu chuyện về giới, câu chuyện về định, câu chuyện về tuệ, câu chuyện về giải thoát, câu chuyện về giải thoát tri kiến. Các câu chuyện ấy có được không khó khăn, có được không mệt nhọc, có được không phí sức, không từ bỏ độc cư Thiền tịnh, chuyên chú vào nội tâm tịnh chỉ. Ðây là pháp thứ năm, này các Tỷ-kheo, không đưa đến thối chuyển cho vị Tỷ-kheo hữu học.`, ref: "AN 5.90", url: "../an/an5.90.html#content" },
{ text: `Thành tựu năm pháp, này các Tỷ-kheo, vị Tỷ-kheo thực hành Niệm hơi thở vô hơi thở ra, không bao lâu thể nhập vào bất động. Thế nào là năm? Ở đây, này các Tỷ-kheo, Tỷ-kheo muốn không có nhiều, công việc không có nhiều, nuôi sống dễ dàng, khéo tri túc với những nhu yếu ở đời, ăn uống ít, không chuyên lo về bao tử; ít thụy miên, chuyên chú trong giác tỉnh; nghe nhiều, thọ trì nhiều, tích lũy điều đã nghe; các pháp nào sơ thiện, trung thiện, hậu thiện, có nghĩa, có văn, tán thán Phạm hạnh hoàn toàn viên mãn thanh tịnh, các pháp ấy, Tỷ-kheo đã nghe nhiều, đã nắm giữ, đã ghi nhớ nhờ đọc nhiều lần, chuyên ý quán sát, khéo thành tựu nhờ chánh kiến; quán sát tâm như đã được giải thoát. Thành tựu năm pháp này, này các Tỷ-kheo, Tỷ-kheo thực hành Niệm hơi thở vô hơi thở ra, không bao lâu thể nhập vào bất động.`, ref: "AN 5.96", url: "../an/an5.96.html#content" },

{ text: `Con sư tử, này các Tỷ-kheo, là đồng nghĩa với bậc A-la-hán Chánh Ðẳng Giác. Khi Như Lai thuyết pháp cho hội chúng, tức là rống tiếng rống con sư tử. Này các Tỷ-kheo, nếu Như Lai thuyết pháp cho các vị Tỷ-kheo, Như Lai thuyết pháp hết sức cẩn thận, chu đáo, không phải không cẩn thận, chu đáo. Nếu Như Lai thuyết pháp cho các vị Tỷ-kheo Ni, Như Lai thuyết pháp hết sức cẩn thận, chu đáo, không phải không cẩn thận, chu đáo. Nếu Như Lai thuyết pháp cho các hàng nam cư sĩ, Như Lai thuyết pháp hết sức cẩn thận, chu đáo, không phải không cẩn thận, chu đáo. Nếu Như Lai thuyết pháp cho các hàng nữ cư sĩ, Như Lai thuyết pháp hết sức cẩn thận, chu đáo, không phải không cẩn thận, chu đáo. Nếu Như Lai thuyết pháp cho các hàng phàm phu , cho các người bắt chim hay xin ăn, Như Lai thuyết pháp hết sức cẩn thận, chu đáo, không phải không cẩn thận, chu đáo. Vì cớ sao? Vì Như Lai là bậc tôn trọng Pháp, này các Tỷ-kheo, là bậc tôn kính Pháp.`, ref: "AN 5.99", url: "../an/an5.99.html#content" },


{ text: `Ở đây, này các Tỷ-kheo, Tỷ-kheo có lòng tin, có giới, có nghe nhiều, có tinh cần tinh tấn, có trí tuệ. Cái gì làm cho kẻ không có lòng tin sợ hãi, này các Tỷ-kheo, cái ấy không làm cho người có lòng tin sợ hãi. Do vậy, pháp này là pháp làm cho bậc Hữu học không sợ hãi. Cái gì làm cho kẻ ác giới sợ hãi, này các Tỷ kheo, cái ấy không làm cho người có giới sợ hãi. Do vậy, pháp này là pháp làm cho bậc Hữu học không sợ hãi. Cái gì làm cho kẻ ít nghe sợ hãi, này các Tỷ-kheo, cái ấy không làm cho người nghe nhiều sợ hãi. Do vậy, pháp này là pháp làm cho bậc Hữu học không sợ hãi. Cái gì làm cho kẻ biếng nhác sợ hãi, này các Tỷ-kheo, cái ấy không làm cho kẻ tinh cần tinh tấn sợ hãi. Do vậy, pháp này là pháp làm cho bậc Hữu học không sợ hãi. Cái gì làm cho kẻ ác tuệ sợ hãi, này các Tỷ-kheo, cái ấy không làm cho người có trí tuệ sợ hãi. Do vậy, pháp này là pháp làm cho bậc Hữu học không sợ hãi.`, ref: "AN 5.101", url: "../an/an5.101.html#content" },


{ text: `Này các Tỷ-kheo, có năm an ổn trú này, Thế nào là năm? Ở đây, này các Tỷ-kheo, Tỷ-kheo an trú từ thân nghiệp đối với các đồng Phạm hạnh, cả trước mặt và sau lưng; an trú từ khẩu nghiệp đối với các đồng Phạm hạnh, trước mặt và sau lưng; an trú từ ý nghiệp đối với các đồng Phạm hạnh, trước mặt và sau lưng; đối với các giới không bị bể vụn, không bị sứt mẻ, không bị nhiễm ô, không bị uế nhiễm, đem lại giải thoát, được người trí tán thán, không bị chấp thủ, đưa đến Thiền định, vị ấy sống thành tựu các giới như vậy đối với các đồng Phạm hạnh, trước mặt và sau lưng, và đối với tri kiến này, thuộc bậc Thánh đưa đến xuất ly, được người thực hành chân chánh đoạn diệt khổ đau, vị ấy sống thành tựu tri kiến như vậy đối với các đồng Phạm hạnh, trước mặt và sau lưng. Năm pháp này, này các Tỷ-kheo, là năm an ổn trú.`, ref: "AN 5.105", url: "../an/an5.105.html#content" },

{ text: `Thành tựu năm pháp, này các Tỷ-kheo, Tỷ-kheo thân cận các gia đình, được các gia đình ái mộ, thích ý, kính trọng, noi gương để tu tập. Thế nào là năm? Vị ấy không thân mật với người không thân tín, không can thiệp vào việc không có thẩm quyền, không ra vào với các phần tử chống đối, không nói riêng một bên tai, không xin quá nhiều. Thành tựu năm pháp, này các Tỷ-kheo, Tỷ-kheo thân cận các gia đình, được các gia đình ái mộ, thích ý, kính trọng, noi gương để tu tập.`, ref: "AN 5.111", url: "../an/an5.111.html#content" },

{ text: `Thành tựu năm pháp, này các Tỷ-kheo, Tỷ-kheo không có thể đạt đến và an trú chánh định. Thế nào là năm? Ở đây, này các Tỷ-kheo, Tỷ-kheo không kham nhẫn các sắc, không kham nhẫn các tiếng, không kham nhẫn các hương, không kham nhẫn các vị, không kham nhẫn các xúc. Thành tựu năm pháp, này các Tỷ-kheo, Tỷ-kheo không có thể đạt đến và an trú chánh định.`, ref: "AN 5.113", url: "../an/an5.113.html#content" },

{ text: `Thành tựu năm pháp, này các Tỷ-kheo, Tỷ-kheo có thể đạt đến và an trú chánh định. Thế nào là năm? Ở đây, này các Tỷ-kheo, Tỷ-kheo kham nhẫn các sắc, kham nhẫn các tiếng, kham nhẫn các hương, kham nhẫn các vị, kham nhẫn các xúc. Thành tựu năm pháp, này các Tỷ-kheo, Tỷ-kheo có thể đạt đến và an trú chánh định.`, ref: "AN 5.113", url: "../an/an5.113.html#content" },

{ text: `Năm pháp này, này các Tỷ-kheo, gia tăng tuổi thọ. Thế nào là năm? Làm việc thích đáng, biết vừa phải trong việc thích đáng, ăn các đồ ăn tiêu hóa, du hành phải thời, và sống Phạm hạnh. Năm pháp này, này các Tỷ-kheo, gia tăng tuổi thọ.`, ref: "AN 5.125", url: "../an/an5.125.html#content" },

{ text: `Thành tựu năm pháp này, vị Tỷ-kheo không đủ điều kiện để sống biệt lập chúng Tăng. Thế nào là năm? Ở đây, này các Tỷ-kheo, Tỷ-kheo không tự vừa đủ với y nhận được chỗ này chỗ kia; không tự vừa đủ với đồ ăn khất thực nhận được chỗ này chỗ kia; không tự vừa đủ với sàng tọa nhận được chỗ này chỗ kia; không tự vừa đủ với dược phẩm trị bệnh nhận được chỗ này chỗ kia; và sống với nhiều tư duy về dục. Thành tựu năm pháp này, này các Tỷ-kheo, một Tỷ-kheo không đủ điều kiện để sống biệt lập chúng Tăng.`, ref: "AN 5.127", url: "../an/an5.127.html#content" },

{ text: `Thành tựu năm pháp này, này các Tỷ-kheo, một Tỷ-kheo đủ điều kiện để sống biệt lập với chúng Tăng. Thế nào là năm? Ở đây, này các Tỷ-kheo, Tỷ-kheo tự vừa đủ với y nhận được chỗ này chỗ kia; tự vừa đủ với đồ ăn khất thực nhận được chỗ này chỗ này; tự vừa đủ với sàng tọa nhận được chỗ này chỗ kia; tự vừa đủ với dược phẩm nhận được chỗ này chỗ kia; sống nhiều tư duy về viễn ly. Thành tựu năm pháp này, này các Tỷ-kheo, Tỷ-kheo đủ điều kiện để sống biệt lập với chúng Tăng.`, ref: "AN 5.127", url: "../an/an5.127.html#content" },

{ text: `Có năm điều khổ này cho Sa-môn. Thế nào là năm? Ở đây, này các Tỷ-kheo không tự vừa đủ với y nhận được chỗ này chỗ kia; không tự vừa đủ với đồ ăn khất thực nhận được chỗ này chỗ kia; không tự vừa đủ với sàng tọa nhận được chỗ này chỗ kia; không tự vừa đủ với dược phẩm trị bệnh nhận được chỗ này chỗ kia; sống không vui thích trong Phạm hạnh. Này các Tỷ-kheo, có năm điều khổ này cho Sa-môn.`, ref: "AN 5.128", url: "../an/an5.128.html#content" },

{ text: `Có năm an lạc này, này các Tỷ-kheo, cho Sa-môn. Thế nào là năm? Ở đây, này các Tỷ-kheo, Tỷ-kheo tự vừa đủ với y nhận được chỗ này chỗ kia; tự vừa đủ với đồ ăn khất thực nhận được chỗ này chỗ kia; tự vừa đủ với sàng tọa nhận được chỗ này chỗ kia; tự vừa đủ với dược phẩm trị bệnh nhận được chỗ này chỗ kia; sống vui thích trong Phạm hạnh. Này các Tỷ-kheo, có năm an lạc này cho vị Sa-môn.`, ref: "AN 5.128", url: "../an/an5.128.html#content" },

{ text: `Này các Tỷ-kheo, có năm điều tổn thất này. Thế nào là năm? Tổn thất bà con, tổn thất tài sản, tổn thất tật bệnh, tổn thất giới, tổn thất tri kiến. Này các Tỷ-kheo, không do nhân tổn thất bà con, hay không do nhân tổn thất tài sản, hay không do nhân tổn thất bệnh hoạn mà các loài hữu tình sau khi thân hoại mạng chung sanh vào cõi dữ, ác thú, đọa xứ, địa ngục. Này các Tỷ-kheo, chính do nhân tổn thất giới, hay tổn thất tri kiến mà các loài hữu tình sau khi thân hoại mạng chung sanh vào cõi dữ, ác thú, địa ngục. Này các Tỷ-kheo, có năm tổn thất này.`, ref: "AN 5.130", url: "../an/an5.130.html#content" },

{ text: `Này các Licchavì, sự hiện hữu của năm châu báu khó tìm được ở đời. Và thế nào là năm? Sự hiện hữu của Như Lai, bậc A-la-hán, Chánh Ðẳng Giác khó tìm được ở đời. Hạng người có thể thuyết giảng Pháp và Luật do Như Lai tuyên bố khó tìm được ở đời. Người hiểu được lời thuyết giảng về Pháp là Luật do Như Lai tuyên bố khó tìm được ở đời. Người đem thực hành các pháp và tùy pháp được hiểu từ lời thuyết giảng về Pháp và Luật do Như Lai tuyên bố khó tìm được ở đời. Người biết ơn, và nhớ ơn khó tìm được ở đời.`, ref: "AN 5.143", url: "../an/an5.143.html#content" },

{ text: `Thành tựu năm pháp này, này các Tỷ-kheo, Tỷ-kheo không đáng được làm bạn. Thế nào là năm? Bảo làm việc đồng áng; ưa thích kiện tụng; chống đối các Tỷ-kheo lãnh đạo; sống đời sống không có mục đích, kéo dài đời sống như vậy; không có khả năng thỉnh thoảng trình bày, khích lệ, làm cho phấn khởi, làm cho hoan hỷ với một bài thuyết pháp. Thành tựu năm pháp này, này các Tỷ-kheo, Tỷ-kheo không đáng được làm bạn.`, ref: "AN 5.146", url: "../an/an5.146.html#content" },

{ text: `Thành tựu năm pháp này, này các Tỷ-kheo, Tỷ-kheo đáng được làm một người bạn. Thế nào là năm? Không bảo làm việc đồng áng; không ưa thích kiện tụng; không chống đối các Tỷ-kheo lãnh đạo; không sống đời sống không có mục đích, không kéo dài đời sống như vậy; có khả năng thỉnh thoảng trình bày, khích lệ, làm cho phấn khởi, làm cho hoan hỷ với một bài thuyết pháp. Thành tựu năm pháp này, này các Tỷ-kheo, Tỷ-kheo đáng được làm bạn.`, ref: "AN 5.146", url: "../an/an5.146.html#content" },

{ text: `Có năm loại bố thí này, này các Tỷ-kheo, không xứng bậc Chân nhân. Thế nào là năm? Bố thí không cung kính, bố thí không suy nghĩ, bố thí không tự tay mình, bố thí đồ quăng bỏ, bố thí không nghĩ đến tương lai. Các pháp này, này các Tỷ-kheo, là năm loại bố thí không xứng bậc Chân nhân. Năm loại bố thí này, này các Tỷ-kheo, là loại bố thí xứng bậc Chân nhân. Thế nào là năm? Bố thí có cung kính, bố thí có suy nghĩ, bố thí tự tay mình, bố thí đồ không quăng bỏ, bố thí có nghĩ đến tương lai. Các pháp này, này các Tỷ-kheo, là năm loại bố thí xứng bậc Chân nhân.`, ref: "AN 5.147", url: "../an/an5.147.html#content" },

{ text: `Này các Tỷ-kheo, có năm loại bố thí này xứng bậc Chân nhân. Thế nào là năm? Bố thí có lòng tin, bố thí có kính trọng, bố thí đúng thời, bố thí với tâm không gượng ép, bố thí không làm thương tổn mình và người. Này các Tỷ-kheo, có năm loại bố thí xứng bậc Chân nhân này.`, ref: "AN 5.148", url: "../an/an5.148.html#content" },

{ text: `Này các Tỷ-kheo, sau khi bố thí với lòng tin chỗ nào, chỗ nào, quả dị thục của sự bố thí ấy đem lại kết quả: Người ấy được giàu sang, đại phú, tài sản sung mãn, đẹp trai, dễ ngó, có thành tín và thành tựu dung sắc thù thắng như hoa sen. Và này các Tỷ-kheo, sau khi bố thí có cung kính, chỗ nào, chỗ nào, quả dị thục của sự bố thí ấy đem lại kết quả: Người ấy được giàu sang, đại phú, tài sản sung mãn; và các con trai, các bà vợ, các người nô tỳ, các người đưa tin, các người làm công, những người ấy đều sẵn sàng vâng theo người ấy, họ lóng tai và phục vụ với tâm hiểu biết.`, ref: "AN 5.148", url: "../an/an5.148.html#content" },

{ text: `Và này các Tỷ-kheo, sau khi bố thí đúng thời, chỗ nào, chỗ nào, quả dị thục của sự bố thí ấy đem lại kết quả: Người ấy được giàu sang, đại phú, tài sản sung mãn; và các vật dụng đến với người ấy đúng thời và sung túc. Và này các Tỷ-kheo, sau khi bố thí không làm thương tổn mình và người, chỗ nào, chỗ nào, quả dị thục của sự bố thí ấy đem lại kết quả: Người ấy được giàu sang, đại phú, tài sản sung mãn; và không một tai nạn nào từ đâu đến, đến với tài sản của người ấy, hoặc từ lửa, từ nước, từ vua, từ ăn trộm, từ các người thù địch hay từ các người thừa tự.`, ref: "AN 5.148", url: "../an/an5.148.html#content" },

{ text: `Này Ananda, thật không dễ gì để thuyết pháp cho các người khác. Ðể thuyết pháp cho các người khác, này Ananda, sau khi nội tâm an trú được năm pháp, mới nên thuyết pháp cho các người khác. Thế nào là năm? “Ta sẽ thuyết pháp tuần tự”, thuyết pháp cho người khác cần phải suy nghĩ như vậy. “Ta sẽ thuyết với mắt nhìn vào pháp môn”, thuyết pháp cho người khác cần phải suy nghĩ như vậy. “Ta sẽ thuyết vì lòng từ mẫn”, thuyết pháp cho người khác cần phải suy nghĩ như vậy. “Ta sẽ thuyết pháp, không phải vì tài vật”, thuyết pháp cho người khác cần phải suy nghĩ như vậy. “Ta sẽ thuyết pháp, không làm thương tổn cho mình và cho người”. Thuyết pháp cho người khác cần phải suy nghĩ như vậy. Này Ananda, thật không dễ gì để thuyết pháp cho các người khác. Ðể thuyết pháp cho các người khác, này Ananda, sau nội tâm an trú được năm pháp, mới nên thuyết pháp cho các người khác.`, ref: "AN 5.159", url: "../an/an5.159.html#content" },

{ text: `Năm pháp này khởi lên, này các Tỷ-kheo, thật khó trừ khử. Thế nào là năm? Tham khởi lên, thật khó trừ khử; sân khởi lên, thật khó trừ khử; si khởi lên, thật khó trừ khử; ham nói khởi lên, thật khó trừ khử; tâm lang thang thật khó trừ khử. Năm pháp này đã khởi lên, này các Tỷ-kheo, thật khó trừ khử.`, ref: "AN 5.160", url: "../an/an5.160.html#content" },

{ text: `Này các Hiền giả, khi Tỷ-kheo buộc tội muốn buộc tội người khác, hãy an trú nội tâm năm pháp rồi hãy buộc tội. Thế nào là năm? “Tôi sẽ nói đúng thời, không phải phi thời”; “Tôi sẽ nói chơn thật, không phải phi chơn thật”; “Tôi sẽ nói nhu hòa, không phải thô bạo”; “Tôi sẽ nói lời liên hệ đến lợi ích, không phải lời không liên hệ đến lợi ích”; “Tôi sẽ nói với từ tâm, không phải với sân tâm”. Này các Hiền giả, khi vị Tỷ-kheo buộc tội muốn buộc tội người khác, hãy an trú nội tâm năm pháp rồi hãy buộc tội người khác.`, ref: "AN 5.167", url: "../an/an5.167.html#content" },

{ text: `Thế Tôn nói với Gia chủ Anàthapindika đang ngồi xuống một bên: - Này Gia chủ, Ông đã cung cấp cho chúng Tỷ-kheo các vật dụng cần thiết như y, đồ ăn khất thực, sàng tọa, dược phẩm trị bệnh. Nhưng Ông chớ có bằng lòng với ý nghĩ: “Chúng ta đã cung cấp cho chúng Tỷ-kheo các vật dụng cần thiết như y, đồ ăn khất thực, sàng tọa, dược phẩm trị bệnh”. Do vậy, này Gia chủ, Ông cần phải học tập như sau: “Với phương tiện nào chúng ta thỉnh thoảng đạt được và an trú hỷ do viễn ly sanh”. Như vậy, này Gia chủ, Ông cần phải học tập.`, ref: "AN 5.176", url: "../an/an5.176.html#content" },

{ text: `Này Sàriputta, trong khi Thánh đệ tử đạt được và an trú hỷ do viễn ly sanh, trong thời gian ấy, năm sự kiện không xảy ra cho người ấy: Khổ và ưu liên hệ đến dục trong thời gian ấy không xảy ra cho người ấy. Lạc và hỷ liên hệ đến dục trong thời gian ấy không xảy ra cho người ấy. Khổ và ưu liên hệ đến bất thiện trong thời gian ấy không xảy ra cho người ấy. Lạc và hỷ liên hệ đến bất thiện trong thời gian ấy không xảy ra cho người ấy. Khổ và ưu liên hệ đến thiện, trong thời gian ấy không xảy ra cho người ấy. Này Sàriputta, trong khi vị Thánh đệ tử đạt đến và an trú hỷ do viễn ly sanh, trong thời gian ấy, năm sự kiện này không xảy ra cho người ấy.`, ref: "AN 5.176", url: "../an/an5.176.html#content" },

{ text: `Có năm nghề buôn bán này, này các Tỷ-kheo, một nam cư sĩ không nên làm. Thế nào là năm? Buôn bán đao kiếm, buôn bán người, buôn bán thịt, buôn bán rượu, buôn bán thuốc độc. Có năm nghề buôn bán này, này các Tỷ-kheo, một nam cư sĩ không nên làm.`, ref: "AN 5.177", url: "../an/an5.177.html#content" },

{ text: `Ví như này các Tỷ-kheo, từ con bò có sữa, từ sữa có lạc, từ lạc có sanh tô, từ sanh tô có thục tô, từ thục tô có đề hồ. Ðây được gọi là đệ nhất. Cũng vậy, này các Tỷ-kheo, trong năm hạng người sống ở rừng, này các Tỷ-kheo, hạng sống ở rừng vì ít dục, vì biết đủ, vì đoạn giảm, vì viễn ly, vì cầu thiện hành này sống ở rừng. Hạng người này trong năm hạng người ấy là đệ nhất, là tối thắng, là thượng thủ, là tối thượng, là tối diệu.`, ref: "AN 5.181", url: "../an/an5.181.html#content" },

{ text: `Ở đây, này Kimbila, khi Như Lai nhập diệt, các Tỷ-kheo, Tỷ-kheo-ni, nam cư sĩ, nữ cư sĩ sống không tôn trọng, không vâng lời bậc Ðạo sư; sống không tôn trọng, không vâng lời Pháp; sống không tôn trọng, không vâng lời chúng Tăng; sống không tôn trọng, không vâng lời học pháp; sống không tôn trọng, không vâng lời lẫn nhau. Do nhân này, do duyên này, này Kimbila, khi Như Lai nhập diệt, diệu pháp không được an trú lâu ngày. Ở đây, này Kimbila, khi Như Lai nhập diệt, các Tỷ-kheo, Tỷ-kheo-ni, nam cư sĩ, nữ cư sĩ sống tôn trọng và vâng lời bậc Ðạo sư; sống tôn trọng và vâng lời Pháp; sống tôn trọng và vâng lời chúng Tăng; sống tôn trọng và vâng lời học pháp; sống tôn trọng và vâng lời lẫn nhau. Ðây là nhân, đây là duyên, này Kimbila, khi Như Lai nhập diệt, diệu pháp được tồn tại lâu dài.`, ref: "AN 5.201", url: "../an/an5.201.html#content" },

{ text: `Này các Tỷ-kheo, nghe pháp có năm lợi ích này. Thế nào là năm? Ðược nghe điều chưa nghe, làm cho trong sạch điều được nghe, đoạn trừ nghi, làm cho tri kiến chánh trực, làm cho tâm tịnh tín. Này các Tỷ-kheo, nghe pháp có năm lợi ích này.`, ref: "AN 5.202", url: "../an/an5.202.html#content" },

{ text: `Này các Tỷ-kheo, có năm nguy hại này đối với người thất niệm, không tỉnh giác rơi vào giấc ngủ. Thế nào là năm? Ngủ một cách khổ sở; thức dậy một cách khổ sở; thấy ác mộng; chư Thiên không phòng hộ; bất tịnh chảy ra, mộng tinh, di tinh. Này các Tỷ-kheo, có năm nguy hại này đối với người thất niệm, không tỉnh giác rơi vào giấc ngủ. Này các Tỷ-kheo, có năm lợi ích này đối với người trú niệm, tỉnh giác rơi vào giấc ngủ. Thế nào là năm? Ngủ một các ngon lành; thức dậy một cách ngon lành; không thấy ác mộng; chư Thiên phòng hộ; bất tịnh không chảy ra. Này các Tỷ-kheo, có năm lợi ích này đối với người trú niệm, tỉnh giác rơi vào giấc ngủ.`, ref: "AN 5.210", url: "../an/an5.210.html#content" },

{ text: `Tỷ-kheo nào, này các Tỷ-kheo, mắng nhiếc, mạ lỵ, các vị tu Phạm hạnh, phỉ báng bậc Thánh, vị ấy được chờ đợi năm sự nguy hại. Thế nào là năm? Phạm tội bị tẩn xuất, chặt đứt con đường hướng thượng; hay phạm một tội nhiễm; hay cảm xúc bệnh hoạn trầm trọng; khi mạng chung tâm bị mê loạn; sau khi thân hoại mạng chung, sanh vào cõi dữ, ác thú, đọa xứ, địa ngục. Tỷ-kheo nào, này các Tỷ-kheo, mắng nhiếc, mạ lỵ, các vị tu Phạm hạnh, phỉ báng bậc Thánh, vị ấy được chờ đợi năm sự nguy hại này.`, ref: "AN 5.211", url: "../an/an5.211.html#content" },

{ text: `Tỷ-kheo nào, này các Tỷ-kheo, là người gây ra cãi cọ, là người gây ra tranh luận, là người gây ra đấu tranh, là người gây ra các cuộc đấu khẩu, là người gây ra kiện tụng trong Tăng chúng. Vị ấy được chờ đợi năm sự nguy hại. Thế nào là năm? Không chứng điều chưa chứng được; thối thất điều đã chứng được; tiếng ác đồn khắp; khi mạng chung, tâm bị mê loạn; sau khi thân hoại mạng chung, sanh vào cõi dữ, ác thú, đọa xứ, địa ngục. Tỷ-kheo nào, này các Tỷ-kheo, là người gây ra cãi cọ, là người gây ra tranh luận, là người gây ra đấu tranh, là người gây ra đấu khẩu, là người gây ra kiện tụng trong Tăng chúng. Vị ấy được chờ đợi năm sự nguy hại này.`, ref: "AN 5.212", url: "../an/an5.212.html#content" },

{ text: `Có năm nguy hại này cho người nói nhiều. Thế nào là năm? Nói láo; nói lời hai lưỡi; nói lời độc ác; nói lời phù phiếm; sau khi thân hoại hạng chung, sanh vào cõi dữ, ác thú, đọa xứ, địa ngục. Này các Tỷ-kheo, có năm nguy hại này cho người nói nhiều.`, ref: "AN 5.214", url: "../an/an5.214.html#content" },

{ text: `Có năm nguy hại này cho người không kham nhẫn. Thế nào là năm? Quần chúng không ái mộ, không ưa thích; nhiều người hận thù; nhiều người tránh né; khi mạng chung, tâm bị mê loạn; sau khi thân hoại mạng chung; sanh vào cõi dữ, ác thú, đọa xứ, địa ngục. Này các Tỷ-kheo, có năm nguy hại này cho người không kham nhẫn.`, ref: "AN 5.215", url: "../an/an5.215.html#content" },

{ text: `Này các Tỷ-kheo, có năm lợi ích này cho người có kham nhẫn. Thế nào là năm? Quần chúng ái mộ, ưa thích; không có người hận thù; không có nhiều người tránh né; khi mạng chung, tâm không bị mê loạn; sau khi thân hoại mạng chung, được sanh vào thiện thú, Thiên giới, cõi đời này. Này các Tỷ-kheo, có năm lợi ích này cho người có kham nhẫn.`, ref: "AN 5.215", url: "../an/an5.215.html#content" },

{ text: `Có năm nguy hại này, này các Tỷ-kheo, cho kẻ không tịnh tín. Thế nào là năm? Những tư tưởng bất tín không được tịnh tín; một số tư tưởng đã tịnh tín có thể đổi khác; không làm theo lời dạy của bậc Ðạo Sư; thế hệ tiếp bắt chước tà kiến; tâm không được tịnh tín. Này các Tỷ-kheo, có năm nguy hại này, cho người không có tịnh tín.`, ref: "AN 5.218", url: "../an/an5.218.html#content" },

{ text: `Có năm lợi ích này, này các Tỷ-kheo, cho người có tịnh tín. Thế nào là năm? Những tư tưởng bất tín được tịnh tín; những tư tưởng tịnh tín được tăng trưởng; lời dạy của bậc Ðạo Sư được làm theo; thế hệ tiếp bắt chước theo tri kiến; tâm được tịnh tín. Này các Tỷ-kheo, có năm lợi ích này, cho người có tịnh tín.`, ref: "AN 5.218", url: "../an/an5.218.html#content" },

{ text: `Có năm nguy hại này, này các Tỷ-kheo, nếu sống quá lâu tại một chỗ. Thế nào là năm? Ðồ dùng nhiều, cất chứa nhiều đồ dùng; nhiều dược phẩm, cất chứa nhiều dược phẩm; nhiều việc làm, nhiều công việc phải làm, không khéo léo trong những công việc gì phải làm; sống lẫn lộn với gia chủ và xuất gia, tùy thuận trong sự liên hệ với gia chủ; và khi ra đi bỏ trú xứ ấy, ra đi với sự luyến tiếc. Này các Tỷ-kheo, đó là năm nguy hại nếu sống quá lâu tại một chỗ.`, ref: "AN 5.223", url: "../an/an5.223.html#content" },

{ text: `Có năm lợi ích này, này các Tỷ-kheo, nếu sống đồng đều tại mỗi chỗ. Thế nào là năm? Ðồ dùng không nhiều, không cất chứa nhiều đồ dùng; dược phẩm không nhiều, không cất chứa nhiều dược phẩm; không có nhiều việc làm, không nhiều công việc phải làm, khéo léo trong những công việc phải làm; không sống lẫn lộn với gia chủ và xuất gia, không tùy thuận trong sự liên hệ với gia chủ; và khi ra đi bỏ trú xứ ấy, ra đi không với sự luyến tiếc. Này các Tỷ-kheo, đó là năm lợi ích nếu sống đồng đều tại một chỗ.`, ref: "AN 5.223", url: "../an/an5.223.html#content" },

{ text: `Có năm nguy hại này, này các Tỷ-kheo, nếu sống quá lâu tại một chỗ. Thế nào là năm? Xan tham đối với trú xứ; xan tham đối với gia đình; xan tham đối với đồ vật cúng dường; xan tham đối với công đức; xan tham đối với pháp. Có năm nguy hại này, này các Tỷ-kheo, nếu sống quá lâu tại một chỗ.`, ref: "AN 5.224", url: "../an/an5.224.html#content" },

{ text: `Có năm nguy hại này, này các Tỷ-kheo, cho người viếng thăm gia đình. Thế nào là năm? Phạm lỗi không mời mà đến; phạm lỗi ngồi một mình; phạm lỗi ngồi chỗ kín đáo; phạm lỗi thuyết pháp cho nữ nhân hơn năm, sáu chữ; sống với nhiều suy tư về dục. Này các Tỷ-kheo, có năm nguy hại này cho người viếng thăm gia đình.`, ref: "AN 5.225", url: "../an/an5.225.html#content" },

{ text: `Có năm nguy hại này, này các Tỷ-kheo, đối với vị Tỷ-kheo sống liên hệ quá nhiều với các gia đình. Thế nào là năm? Luôn luôn thấy nữ nhân; do thấy, nên có liên hệ; do có liên hệ nên có sự thân mật; do có sự thân mật nên có cơ hội (để tư thông); khi tâm đã có tư thông, thời được chờ đợi như sau: Sẽ không có hoan hỷ sống Phạm hạnh; hay sẽ rơi vào trong một tội nhiễm ô; hay từ bỏ học giới; trở lui lại đời sống thế tục. Này các Tỷ-kheo, đây là năm nguy hại đối với vị Tỷ-kheo sống liên hệ quá nhiều với các gia đình.`, ref: "AN 5.226", url: "../an/an5.226.html#content" },

{ text: `Thành tựu năm pháp này, này các Tỷ-kheo, vị Tỷ-kheo trú tại chỗ trở thành không đáng được làm gương để tu tập. Thế nào là năm? Không đầy đủ về uy nghi, không đầy đủ về trách nhiệm; không nghe nhiều, không thọ trì điều được nghe; không biết sống đoạn giảm, không ưa thích sống Thiền tịnh; lời nói không hiền thiện, không là người nói lời hiền thiện; ác tuệ, đần độn, câm điếc. Thành tựu năm pháp này, này các Tỷ-kheo, vị Tỷ-kheo trú tại chỗ trở thành không đáng được làm gương để tu tập.`, ref: "AN 5.231", url: "../an/an5.231.html#content" },

{ text: `Thành tựu năm pháp này, này các Tỷ-kheo, vị Tỷ-kheo trú tại chỗ trở thành đáng được làm gương để tu tập. Thế nào là năm? Ðầy đủ về uy nghi, đầy đủ về trách nhiệm; nghe nhiều, thọ trì điều được nghe; biết sống đoạn giảm, ưa thích Thiền tịnh; lời nói hiền thiện, là người nói lời hiền thiện; có trí tuệ, không đần độn, không câm điếc. Thành tựu năm pháp này, này các Tỷ-kheo, vị Tỷ-kheo trú tại chỗ trở thành đáng được làm gương để tu tập.`, ref: "AN 5.231", url: "../an/an5.231.html#content" },

{ text: `Thành tựu năm pháp này, này các Tỷ-kheo, vị Tỷ-kheo trú tại chỗ có lòng từ mẫn đối với các gia chủ. Thế nào là năm? Khích lệ tăng thượng giới; khiến chúng sống theo gương pháp; khi đến thăm người bệnh, an trú niệm cho người bệnh như sau: “Các vị hãy an trú niệm vào hướng đến quả A-la-hán”; khi đại chúng Tỷ-kheo đi đến từ nhiều địa phương khác nhau, vị ấy nói với các gia chủ đi đến như sau: “Nay đại chúng Tỷ-kheo đã đến từ nhiều địa phương khác nhau. Các vị hãy làm các phước đức. Nay là thời làm các phước đức”; họ có cúng dường các món ăn gì, hoặc thô hoặc tế, tự mình thọ dụng, không làm cho của tín thí rơi rớt. Thành tựu năm pháp này, này các Tỷ-kheo, vị Tỷ-kheo trú tại chỗ có lòng từ mẫn đối với các gia chủ.`, ref: "AN 5.235", url: "../an/an5.235.html#content" },

{ text: `Thành tựu sáu pháp, này các Tỷ-kheo, Tỷ-kheo đáng được cung kính, đáng được tôn trọng, đáng được cúng dường, đáng được chắp tay, là phước điền vô thượng ở đời. Thế nào là sáu? Ở đây, này các Tỷ-kheo, Tỷ-kheo khi mắt thấy sắc, không có ưa thích, không có ghét bỏ, trú xả, chánh niệm tỉnh giác; khi tai nghe tiếng... khi mũi ngửi hương... khi lưỡi nếm vị... khi thân cảm xúc... khi ý biết pháp, không có ưa thích, không có ghét bỏ, trú xả, chánh niệm tỉnh giác. Thành tựu sáu pháp này, này các Tỷ-kheo, Tỷ-kheo đáng được cung kính, đáng được tôn trọng, đáng được cúng dường, đáng được chắp tay, là vô thượng phước điền ở đời.`, ref: "AN 6.1", url: "../an/an6.1.html#content" },
            ],
            dhp: [
                { text: "Đang Cập Nhật", ref: "Kinh Pháp Cú 273", url: "../dhp/dhp273.html" }
            ],
            kp: [
                { text: "Đang Cập Nhật", ref: "Tiểu Tụng", url: "../kp/kp.html" }
            ],
            ud: [
                { text: "Đang Cập Nhật", ref: "Ud 8.5", url: "../ud/ud8.5.html" }
            ],
            iti: [
                { text: "Đang Cập Nhật", ref: "Iti 22", url: "../iti/iti22.html" }
            ],
            snp: [
                { text: "Đang Cập Nhật", ref: "Sutta Nipata 812", url: "../snp/snp812.html" }
            ],
            thag: [
                { text: "Đang Cập Nhật", ref: "Trưởng Lão Tăng Kệ", url: "../thag/thag.html" }
            ],
            thig: [
                { text: "Đang Cập Nhật", ref: "Thig 5.4", url: "../thig/thig5.4.html" }
            ]
        };

        // Gộp dữ liệu (Giữ nguyên)
        let allQuotes = [];
        Object.keys(quotesData).forEach(key => {
            allQuotes = allQuotes.concat(quotesData[key]);
        });
        quotesData['all'] = allQuotes;

        let currentCategory = 'all';
        const quoteContentEl = document.getElementById('quote-content');
        const refContainerEl = document.getElementById('reference-container');

        function getRandomQuote(category) {
            const list = quotesData[category] || quotesData['all'];
            if (!list || list.length === 0) return { text: "Chưa có dữ liệu.", ref: "", url: "#" };
            return list[Math.floor(Math.random() * list.length)];
        }

        function renderQuote() {
            quoteContentEl.classList.add('fade-out');
            
            setTimeout(() => {
                const q = getRandomQuote(currentCategory);
                
                // 1. Cập nhật nội dung quote
                quoteContentEl.textContent = q.text;
                
                // 2. TẠO VÀ CẬP NHẬT LINK
                // Xóa nội dung cũ
                refContainerEl.innerHTML = ''; 
                
                // Tạo thẻ <a>
                const linkEl = document.createElement('a');
                linkEl.id = 'quote-link';
                linkEl.href = q.url;
                linkEl.textContent = q.ref;
                linkEl.target = "_blank"; // Mở link trong tab mới
                
                // Chèn thẻ <a> vào container
                refContainerEl.appendChild(linkEl);
                
                quoteContentEl.classList.remove('fade-out');
            }, 300);
        }

        // --- XỬ LÝ SỰ KIỆN (Giữ nguyên) ---

        // Nút New Quote
        document.getElementById('new-quote-btn').addEventListener('click', renderQuote);

        // Nút Copy
        const copyBtn = document.getElementById('copy-btn');
        const copyTextEl = document.getElementById('copy-text');

        copyBtn.addEventListener('click', () => {
            // Lấy text của link để sao chép cả tham chiếu
            const refText = document.getElementById('quote-link').textContent;
            const fullText = `"${quoteContentEl.textContent}"\n— ${refText}`;
            
            navigator.clipboard.writeText(fullText).then(() => {
                const originalText = copyTextEl.textContent;
                copyTextEl.textContent = "Đã chép!";
                copyBtn.style.borderColor = "#4caf50";
                
                setTimeout(() => {
                    copyTextEl.textContent = originalText;
                    copyBtn.style.borderColor = ""; 
                }, 2000);
            });
        });

        // Bộ lọc
        document.querySelectorAll('.filter-btn').forEach(btn => {
            btn.addEventListener('click', (e) => {
                document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
                e.target.classList.add('active');
                currentCategory = e.target.dataset.id;
                renderQuote();
            });
        });

        // Dark Mode
        const themeToggle = document.getElementById('theme-toggle');
        if (localStorage.getItem('theme') === 'dark') {
            document.body.classList.add('dark');
            themeToggle.textContent = '🌙';
        }
        themeToggle.addEventListener('click', () => {
            document.body.classList.toggle('dark');
            if (document.body.classList.contains('dark')) {
                themeToggle.textContent = '🌙';
                localStorage.setItem('theme', 'dark');
            } else {
                themeToggle.textContent = '☀️';
                localStorage.setItem('theme', 'light');
            }
        });

        renderQuote();